-- ============================================
-- Card Usage Tips Migration Script
-- ============================================
-- Description: Migrate all card_usage_tips from local to production
-- Uses bank + name subquery to handle different card_id between environments
-- Last Updated: 2025-12-26
-- Total Records: 628
-- ============================================

START TRANSACTION;

-- Clear existing tips (optional - uncomment if you want to replace all)
-- DELETE FROM card_usage_tips;

-- Insert all tips using bank + name subquery for card_id

COMMIT;

-- Verification
SELECT c.bank, c.name, COUNT(*) as tips_count FROM card_usage_tips t JOIN credit_cards c ON t.card_id = c.id GROUP BY c.bank, c.name ORDER BY c.bank, c.name;
