INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'AVOID', '{"en": "High Interest Rate Warning", "es": "Advertencia de tasa de interés alta", "fr": "Avertissement taux d''intérêt élevé", "ja": "高金利に注意", "ko": "높은 이자율 주의", "zh": "高利率警告"}', '{"en": "Avoid carrying a balance; the charge card has a steep 30% APR on unpaid balances.", "es": "Evita mantener un saldo; la tarjeta tiene una TAE del 30% sobre saldos impagos.", "fr": "Évitez de garder un solde; la carte a un TAP élevé de 30% sur les soldes impayés.", "ja": "残高を残さないようにしましょう。未払い残高には30%の高金利がかかります。", "ko": "잔액을 남기지 마세요. 미지급 잔액에 30%의 높은 연이율이 적용됩니다.", "zh": "避免留有余额；该签账卡对未付余额收取高达30%的年利率。"}', 'warning', 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'BEST_USE', '{"en": "Air Canada Purchases", "es": "Compras en Air Canada", "fr": "Achats Air Canada", "ja": "エアカナダでの購入", "ko": "에어캐나다 구매", "zh": "加航消费"}', '{"en": "Get 2 Aeroplan points per $1 spent on Air Canada and Air Canada Vacations, maximizing travel rewards.", "es": "Obtén 2 puntos Aeroplan por cada $1 en Air Canada y Air Canada Vacations, maximizando recompensas de viaje.", "fr": "Obtenez 2 points Aeroplan par dollar chez Air Canada et Air Canada Vacations, maximisant les récompenses voyage.", "ja": "エアカナダとAir Canada Vacationsで$1につき2 Aeroplanポイントを獲得し、旅行リワードを最大化。", "ko": "에어캐나다 및 Air Canada Vacations에서 $1당 2 Aeroplan 포인트 적립, 여행 리워드 극대화.", "zh": "在加拿大航空和Air Canada Vacations消费每$1可获得2 Aeroplan积分，最大化旅行奖励。"}', 'travel', 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'BEST_USE', '{"en": "Maximize Dining Rewards", "es": "Maximiza las recompensas de comida", "fr": "Maximiser les récompenses repas", "ja": "外食リワードを最大化", "ko": "다이닝 리워드 극대화", "zh": "最大化餐饮奖励"}', '{"en": "Earn 1.5 Aeroplan points per $1 spent on dining and food delivery, ideal for frequent diners.", "es": "Gana 1.5 puntos Aeroplan por cada $1 gastado en restaurantes y delivery, ideal para quienes comen fuera frecuentemente.", "fr": "Gagnez 1,5 point Aeroplan par dollar dépensé en restauration et livraison, idéal pour les amateurs de restaurants.", "ja": "外食やフードデリバリーで$1につき1.5 Aeroplanポイントを獲得。外食が多い方に最適。", "ko": "식당 및 배달 음식에서 $1당 1.5 Aeroplan 포인트 적립. 자주 외식하는 분에게 적합.", "zh": "餐饮和外卖消费每$1可获得1.5 Aeroplan积分，非常适合经常外出就餐的用户。"}', 'dining', 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'INSURANCE', '{"en": "Comprehensive Travel Insurance", "es": "Seguro de viaje completo", "fr": "Assurance voyage complète", "ja": "充実の旅行保険", "ko": "종합 여행 보험", "zh": "全面旅行保险"}', '{"en": "Benefit from extensive travel insurance, including lost baggage and trip accident coverage.", "es": "Benefíciate de un seguro de viaje completo, incluyendo equipaje perdido y cobertura de accidentes de viaje.", "fr": "Bénéficiez d''une assurance voyage complète, incluant la perte de bagages et l''assurance accident de voyage.", "ja": "手荷物紛失や旅行事故補償を含む充実の旅行保険を利用できます。", "ko": "수하물 분실 및 여행 사고 보장을 포함한 종합 여행 보험 혜택.", "zh": "享受全面的旅行保险，包括行李丢失和旅行意外保险。"}', 'insurance', 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'REDEMPTION', '{"en": "Optimal Point Redemption", "es": "Canje óptimo de puntos", "fr": "Échange optimal de points", "ja": "最適なポイント交換", "ko": "최적의 포인트 교환", "zh": "最佳积分兑换"}', '{"en": "Redeem Aeroplan points for flights to get the best value, ideally above 1.29 cents per point.", "es": "Canjea puntos Aeroplan por vuelos para obtener el mejor valor, idealmente por encima de 1.29 centavos por punto.", "fr": "Échangez les points Aeroplan contre des vols pour la meilleure valeur, idéalement au-dessus de 1,29 cent par point.", "ja": "Aeroplanポイントをフライトに交換すると最高の価値を得られます。理想的には1ポイント1.29セント以上。", "ko": "Aeroplan 포인트를 항공권으로 교환하면 최고의 가치를 얻을 수 있습니다. 포인트당 1.29센트 이상이 이상적.", "zh": "将Aeroplan积分兑换机票可获得最佳价值，理想情况下每积分价值超过1.29美分。"}', 'travel', 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'STACKING', '{"en": "Combine with Other Cards", "es": "Combinar con otras tarjetas", "fr": "Combiner avec d''autres cartes", "ja": "他のカードと組み合わせる", "ko": "다른 카드와 조합", "zh": "与其他卡组合使用"}', '{"en": "Consider pairing with a card that offers higher rewards on everyday purchases for better overall value.", "es": "Considera combinarlo con una tarjeta que ofrezca mayores recompensas en compras diarias para mejor valor general.", "fr": "Envisagez de combiner avec une carte offrant plus de récompenses sur les achats quotidiens pour une meilleure valeur globale.", "ja": "日常の買い物でより高いリワードを提供するカードとの併用を検討し、全体的な価値を高めましょう。", "ko": "일상 구매에서 더 높은 리워드를 제공하는 카드와 함께 사용하여 전체 가치를 높이세요.", "zh": "考虑搭配一张日常消费返现更高的卡，以获得更好的整体价值。"}', 'default', 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Card'), 'TRAVEL_BENEFIT', '{"en": "Free Checked Bags", "es": "Equipaje facturado gratis", "fr": "Bagages enregistrés gratuits", "ja": "無料受託手荷物", "ko": "무료 수하물", "zh": "免费托运行李"}', '{"en": "Enjoy a free first checked bag for yourself and up to 8 companions on Air Canada flights.", "es": "Disfruta de una primera maleta facturada gratis para ti y hasta 8 acompañantes en vuelos de Air Canada.", "fr": "Profitez d''un premier bagage enregistré gratuit pour vous et jusqu''à 8 compagnons sur les vols Air Canada.", "ja": "エアカナダ便で、ご自身と最大8名の同伴者の最初の受託手荷物が無料。", "ko": "에어캐나다 항공편에서 본인과 최대 8명의 동반자에게 첫 번째 수하물 무료.", "zh": "在加航航班上，您和最多8位同伴可享受免费托运首件行李。"}', 'travel', 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'AVOID', '{"en": "High Annual Fee", "es": "Cuota anual alta", "fr": "Frais annuels élevés", "ja": "高額な年会費", "ko": "높은 연회비", "zh": "高额年费"}', '{"en": "The $599 annual fee ($199 per additional card) requires frequent Air Canada travel to justify. Calculate your expected benefits before applying.", "es": "La cuota anual de $599 ($199 por tarjeta adicional) requiere viajes frecuentes con Air Canada para justificarse. Calcula tus beneficios antes de solicitar.", "fr": "Les frais annuels de 599 $ (199 $ par carte supplémentaire) nécessitent des voyages fréquents avec Air Canada. Calculez vos avantages avant de postuler.", "ja": "年会費$599（追加カード$199）はエアカナダ頻繁利用者向け。申請前に期待される特典を計算してください。", "ko": "연회비 $599 (추가 카드 $199)는 에어캐나다 자주 이용해야 본전. 신청 전 예상 혜택을 계산하세요.", "zh": "$599年费（附属卡每张$199）需要经常乘坐加航才能值回票价。申请前请计算预期收益。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'AVOID', '{"en": "2026 Program Changes", "es": "Cambios en 2026", "fr": "Changements 2026", "ja": "2026年の変更", "ko": "2026년 프로그램 변경", "zh": "2026年计划变更"}', '{"en": "Note: Aeroplan benefits are shifting to revenue-based earning in 2026. Consider this when evaluating long-term value of the card.", "es": "Nota: Aeroplan cambia a acumulación basada en ingresos en 2026. Considera esto al evaluar el valor a largo plazo.", "fr": "Note: Aeroplan passe à un système basé sur les revenus en 2026. Considérez ceci pour évaluer la valeur à long terme.", "ja": "注意：Aeroplanは2026年に収益ベースの獲得に移行します。カードの長期的な価値を評価する際はご注意ください。", "ko": "참고: Aeroplan이 2026년 수익 기반 적립으로 전환됩니다. 장기 가치 평가 시 고려하세요.", "zh": "注意：Aeroplan将于2026年转为收入型积分模式。评估卡片长期价值时请考虑这一点。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'BEST_USE', '{"en": "Maximize Air Canada Purchases", "es": "Maximiza compras en Air Canada", "fr": "Maximiser les achats Air Canada", "ja": "エアカナダ購入を最大化", "ko": "에어캐나다 구매 극대화", "zh": "最大化加航消费"}', '{"en": "Earn 3x Aeroplan points per $1 on Air Canada and Air Canada Vacations purchases - the highest earning rate among all Aeroplan cards.", "es": "Gana 3x puntos Aeroplan por $1 en Air Canada y Air Canada Vacations - la tasa más alta entre todas las tarjetas Aeroplan.", "fr": "Gagnez 3x points Aeroplan par dollar sur Air Canada et Air Canada Vacations - le taux le plus élevé parmi toutes les cartes Aeroplan.", "ja": "エアカナダとAir Canada Vacationsで$1につき3倍のAeroplanポイント獲得——全Aeroplanカード中最高の還元率。", "ko": "에어캐나다 및 Air Canada Vacations에서 $1당 3배 Aeroplan 포인트 적립 - 모든 Aeroplan 카드 중 최고 적립률.", "zh": "在加拿大航空和Air Canada Vacations消费每$1可获3倍Aeroplan积分——所有Aeroplan卡中最高的积分倍率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'BEST_USE', '{"en": "Dining Rewards", "es": "Recompensas de comida", "fr": "Récompenses restauration", "ja": "外食リワード", "ko": "다이닝 리워드", "zh": "餐饮奖励"}', '{"en": "Earn 2x Aeroplan points per $1 spent at restaurants and food delivery services.", "es": "Gana 2x puntos Aeroplan por $1 en restaurantes y servicios de delivery.", "fr": "Gagnez 2x points Aeroplan par dollar dans les restaurants et services de livraison.", "ja": "レストランやフードデリバリーで$1につき2倍のAeroplanポイントを獲得。", "ko": "레스토랑 및 음식 배달에서 $1당 2배 Aeroplan 포인트 적립.", "zh": "在餐厅和外卖服务消费每$1可获2倍Aeroplan积分。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'INSURANCE', '{"en": "$5M Emergency Medical", "es": "$5M seguro médico", "fr": "5 M$ assurance médicale", "ja": "500万ドル緊急医療保険", "ko": "$500만 응급 의료 보험", "zh": "500万紧急医疗保险"}', '{"en": "Get up to $5 million emergency medical coverage for the first 15 days of your trip (for cardholders under 65 years old).", "es": "Obtén hasta $5 millones en cobertura médica de emergencia para los primeros 15 días del viaje (menores de 65 años).", "fr": "Bénéficiez d''une couverture médicale d''urgence jusqu''à 5 M$ pour les 15 premiers jours (titulaires de moins de 65 ans).", "ja": "旅行開始から15日間、最高500万ドルの緊急医療保険（65歳未満のカード会員対象）。", "ko": "여행 첫 15일간 최대 $500만 응급 의료 보장 (65세 미만 카드 소지자).", "zh": "旅行前15天可获最高500万美元紧急医疗保险（65岁以下持卡人适用）。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'INSURANCE', '{"en": "Trip Protection Coverage", "es": "Protección de viaje", "fr": "Protection voyage", "ja": "旅行保護補償", "ko": "여행 보호 보장", "zh": "旅行保障"}', '{"en": "Includes trip cancellation/interruption up to $1,500 per person, flight delay coverage up to $1,000, and $500,000 accidental death insurance.", "es": "Incluye cancelación/interrupción hasta $1,500 por persona, cobertura por retraso hasta $1,000 y $500,000 seguro de muerte accidental.", "fr": "Comprend annulation/interruption jusqu''à 1 500 $/personne, retard de vol jusqu''à 1 000 $, et 500 000 $ assurance décès accidentel.", "ja": "旅行キャンセル/中断保険（1人$1,500まで）、フライト遅延保険（$1,000まで）、事故死亡保険$500,000を含む。", "ko": "여행 취소/중단 보험 1인당 $1,500, 항공편 지연 $1,000, 사고 사망 보험 $500,000 포함.", "zh": "包括每人最高$1,500的行程取消/中断保险、最高$1,000的航班延误保险，以及$500,000意外身故保险。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'REDEMPTION', '{"en": "Use eUpgrade Credits", "es": "Usar créditos eUpgrade", "fr": "Utiliser les crédits eUpgrade", "ja": "eUpgradeクレジットを使う", "ko": "eUpgrade 크레딧 사용", "zh": "使用eUpgrade升舱券"}', '{"en": "Use eUpgrade credits to upgrade to Business Class on Air Canada flights. Cardholders receive eUpgrade credits as part of their elite status benefits.", "es": "Usa créditos eUpgrade para ascender a Clase Ejecutiva en vuelos de Air Canada. Los titulares reciben créditos eUpgrade.", "fr": "Utilisez les crédits eUpgrade pour passer en classe Affaires sur les vols Air Canada. Les titulaires reçoivent des crédits eUpgrade.", "ja": "eUpgradeクレジットを使用してエアカナダ便でビジネスクラスにアップグレード。カード会員はeUpgradeクレジットを受け取れます。", "ko": "eUpgrade 크레딧으로 에어캐나다 비즈니스 클래스로 업그레이드하세요. 카드 소지자는 eUpgrade 크레딧을 받습니다.", "zh": "使用eUpgrade升舱券在加航航班上升级到商务舱。持卡人可获得eUpgrade升舱券作为精英会员权益。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'REDEMPTION', '{"en": "Annual Companion Pass", "es": "Pase de Acompañante Anual", "fr": "Pass Accompagnateur Annuel", "ja": "年間コンパニオンパス", "ko": "연간 동반자 패스", "zh": "年度同行票"}', '{"en": "Earn a Worldwide Companion Pass after spending $25,000 annually. The companion pays only taxes and fees ($99-$599 base fare) for a round-trip ticket.", "es": "Obtén un Pase de Acompañante Mundial después de gastar $25,000 al año. El acompañante solo paga impuestos (tarifa base $99-$599).", "fr": "Obtenez un Pass Accompagnateur Mondial après 25 000 $ de dépenses annuelles. L''accompagnateur ne paie que les taxes (tarif de base 99-599 $).", "ja": "年間$25,000利用でワールドワイドコンパニオンパスを獲得。同伴者は税金のみ（基本運賃$99-$599）で往復航空券を取得。", "ko": "연간 $25,000 사용 시 월드와이드 동반자 패스 획득. 동반자는 세금만 지불 (기본 요금 $99-$599).", "zh": "年消费满$25,000可获得全球同行票。同行人只需支付税费（$99-$599基础票价）即可获得往返机票。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'STACKING', '{"en": "Pair with Cobalt Card", "es": "Combinar con tarjeta Cobalt", "fr": "Combiner avec la carte Cobalt", "ja": "Cobaltカードと組み合わせ", "ko": "Cobalt 카드와 조합", "zh": "搭配Cobalt卡使用"}', '{"en": "Use this card for Air Canada and dining. Pair with AMEX Cobalt for groceries (5x MR) and other everyday spending to maximize overall rewards.", "es": "Usa esta tarjeta para Air Canada y comida. Combina con Cobalt para supermercado (5x MR) y gastos diarios para maximizar recompensas.", "fr": "Utilisez cette carte pour Air Canada et restaurants. Combinez avec Cobalt pour l''épicerie (5x MR) et les dépenses quotidiennes.", "ja": "このカードはエアカナダと外食に。Cobaltと組み合わせて食料品（5x MR）や日常消費で全体リワードを最大化。", "ko": "에어캐나다와 식당에 이 카드 사용. Cobalt와 조합하여 식료품 (5x MR) 및 일상 지출 리워드 극대화.", "zh": "用此卡消费加航和餐饮。搭配AMEX Cobalt用于超市（5倍MR积分）和其他日常消费，最大化整体奖励。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'TRAVEL_BENEFIT', '{"en": "Unlimited Lounge Access", "es": "Acceso ilimitado a salas VIP", "fr": "Accès illimité aux salons", "ja": "無制限ラウンジアクセス", "ko": "무제한 라운지 이용", "zh": "无限贵宾室使用"}', '{"en": "Enjoy unlimited access to Maple Leaf Lounges across North America when flying Air Canada, regardless of cabin class.", "es": "Disfruta acceso ilimitado a las salas Maple Leaf en Norteamérica volando con Air Canada, sin importar la clase.", "fr": "Profitez d''un accès illimité aux salons Feuille d''Érable en Amérique du Nord sur les vols Air Canada, quelle que soit la classe.", "ja": "エアカナダ搭乗時、客室クラスに関係なく北米のメープルリーフラウンジを無制限で利用可能。", "ko": "에어캐나다 탑승 시 좌석 등급과 관계없이 북미 전역 메이플 리프 라운지 무제한 이용.", "zh": "乘坐加航时可无限次使用北美各地的枫叶贵宾室，不限舱位等级。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'TRAVEL_BENEFIT', '{"en": "Priority Services", "es": "Servicios prioritarios", "fr": "Services prioritaires", "ja": "優先サービス", "ko": "우선 서비스", "zh": "优先服务"}', '{"en": "Get Priority Zone 2 boarding, priority check-in, and a free first checked bag for you and up to 8 companions on Air Canada flights.", "es": "Obtén embarque prioritario Zona 2, check-in prioritario y primera maleta gratis para ti y hasta 8 acompañantes en Air Canada.", "fr": "Bénéficiez de l''embarquement Zone 2, enregistrement prioritaire et premier bagage gratuit pour vous et jusqu''à 8 accompagnateurs.", "ja": "優先搭乗ゾーン2、優先チェックイン、ご本人と最大8名の同伴者の無料受託手荷物1個をエアカナダ便で利用可能。", "ko": "에어캐나다에서 우선 탑승 존 2, 우선 체크인, 본인과 최대 8명의 동반자 첫 번째 수하물 무료.", "zh": "享受优先登机区2、优先值机，以及您和最多8位同伴在加航航班上的首件免费托运行李。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Aeroplan Reserve Card'), 'TRAVEL_BENEFIT', '{"en": "$100 NEXUS Credit", "es": "Crédito NEXUS de $100", "fr": "Crédit NEXUS de 100 $", "ja": "$100 NEXUSクレジット", "ko": "$100 NEXUS 크레딧", "zh": "$100 NEXUS抵扣"}', '{"en": "Receive a $100 credit towards NEXUS application or renewal fees, helping you speed through Canada-US border crossings.", "es": "Recibe un crédito de $100 para la solicitud o renovación de NEXUS, ayudándote a cruzar rápido la frontera Canadá-EE.UU.", "fr": "Recevez un crédit de 100 $ pour les frais de demande ou renouvellement NEXUS, accélérant vos passages à la frontière Canada-USA.", "ja": "NEXUS申請または更新費用に$100クレジット。カナダ・米国国境通過がスムーズに。", "ko": "NEXUS 신청 또는 갱신 비용에 $100 크레딧 제공. 캐나다-미국 국경 통과 시간 단축.", "zh": "获得$100 NEXUS申请或续费抵扣，帮助您快速通过加美边境。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'AVOID', '{"en": "Monthly Spending Cap", "es": "Límite mensual de gasto", "fr": "Plafond mensuel", "ja": "月間上限額", "ko": "월 지출 한도", "zh": "月消费上限"}', '{"en": "The 5x earning on groceries/dining is capped at $2,500/month. Above that, you only earn 1x. Plan large purchases accordingly.", "es": "El 5x en supermercado/comida tiene límite de $2,500/mes. Más allá ganas 1x. Planifica compras grandes.", "fr": "Le 5x sur épicerie/restaurants est plafonné à 2 500 $/mois. Au-delà, vous gagnez 1x. Planifiez vos gros achats.", "ja": "食料品・外食の5倍は月$2,500が上限。超過分は1倍のみ。大きな買い物は計画的に。", "ko": "식료품/다이닝 5배는 월 $2,500 한도. 초과분은 1배만 적립. 대량 구매는 계획적으로.", "zh": "超市/餐饮5倍积分上限为每月$2,500。超出部分只获1倍积分。请合理规划大额消费。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'AVOID', '{"en": "No Trip Cancellation Insurance", "es": "Sin seguro de cancelación", "fr": "Pas d''assurance annulation", "ja": "旅行キャンセル保険なし", "ko": "여행 취소 보험 없음", "zh": "无旅行取消保险"}', '{"en": "This card does not include trip cancellation/interruption insurance. Consider a premium travel card for those benefits.", "es": "Esta tarjeta no incluye seguro de cancelación/interrupción. Considera una tarjeta de viaje premium.", "fr": "Cette carte n''inclut pas l''assurance annulation/interruption de voyage. Envisagez une carte voyage premium.", "ja": "この カードには旅行キャンセル/中断保険がありません。必要な場合はプレミアムカードを検討。", "ko": "이 카드는 여행 취소/중단 보험이 없습니다. 해당 혜택이 필요하면 프리미엄 카드를 고려하세요.", "zh": "此卡不包含旅行取消/中断保险。如需此权益，请考虑高端旅行卡。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'BEST_USE', '{"en": "Groceries & Dining 5x", "es": "Supermercado y comida 5x", "fr": "Épicerie et restaurants 5x", "ja": "食料品・外食5倍", "ko": "식료품 & 다이닝 5배", "zh": "超市和餐饮5倍积分"}', '{"en": "Earn 5x MR points per $1 on groceries and dining (up to $2,500/month, then 1x). The best everyday earning rate in Canada.", "es": "Gana 5x puntos MR por $1 en supermercado y comida (hasta $2,500/mes, luego 1x). La mejor tasa diaria en Canadá.", "fr": "Gagnez 5x points MR par dollar en épicerie et restaurants (jusqu''à 2 500 $/mois, puis 1x). Le meilleur taux au Canada.", "ja": "食料品・外食で$1につき5倍MRポイント（月$2,500まで、以降1倍）。カナダ最高の日常還元率。", "ko": "식료품 및 다이닝에서 $1당 5배 MR 포인트 (월 $2,500까지, 이후 1배). 캐나다 최고의 일상 적립률.", "zh": "超市和餐饮消费每$1可获5倍MR积分（每月上限$2,500，超出后1倍）。加拿大最高的日常消费积分率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'BEST_USE', '{"en": "Streaming Services 3x", "es": "Servicios de streaming 3x", "fr": "Services de streaming 3x", "ja": "ストリーミング3倍", "ko": "스트리밍 서비스 3배", "zh": "流媒体服务3倍积分"}', '{"en": "Earn 3x MR points on streaming subscriptions including Netflix, Spotify, Apple TV+, Disney+, and more.", "es": "Gana 3x puntos MR en suscripciones de streaming como Netflix, Spotify, Apple TV+, Disney+.", "fr": "Gagnez 3x points MR sur les abonnements streaming : Netflix, Spotify, Apple TV+, Disney+, etc.", "ja": "Netflix、Spotify、Apple TV+、Disney+などのストリーミングで3倍MRポイント。", "ko": "Netflix, Spotify, Apple TV+, Disney+ 등 스트리밍에서 3배 MR 포인트.", "zh": "流媒体订阅服务可获3倍MR积分，包括Netflix、Spotify、Apple TV+、Disney+等。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'BEST_USE', '{"en": "Gas & Transit 2x", "es": "Gasolina y transporte 2x", "fr": "Essence et transport 2x", "ja": "ガソリン・交通2倍", "ko": "주유 & 교통 2배", "zh": "加油和交通2倍积分"}', '{"en": "Earn 2x MR points on gas, public transit, and ride-sharing services like Uber and Lyft.", "es": "Gana 2x puntos MR en gasolina, transporte público y servicios como Uber y Lyft.", "fr": "Gagnez 2x points MR sur l''essence, le transport en commun et les services comme Uber et Lyft.", "ja": "ガソリン、公共交通、UberやLyftなどで2倍MRポイント。", "ko": "주유, 대중교통, Uber/Lyft 등에서 2배 MR 포인트.", "zh": "加油、公共交通和网约车服务（如Uber、Lyft）可获2倍MR积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'INSURANCE', '{"en": "$5M Emergency Medical", "es": "$5M seguro médico", "fr": "5 M$ assurance médicale", "ja": "500万ドル緊急医療保険", "ko": "$500만 응급 의료 보험", "zh": "500万紧急医疗保险"}', '{"en": "Get up to $5 million emergency medical coverage when traveling (for cardholders under 65). Also includes car rental insurance up to 48 days.", "es": "Cobertura médica de emergencia hasta $5M viajando (menores de 65). Incluye seguro de auto rentado hasta 48 días.", "fr": "Couverture médicale d''urgence jusqu''à 5 M$ en voyage (moins de 65 ans). Inclut aussi l''assurance location auto jusqu''à 48 jours.", "ja": "旅行中最高500万ドルの緊急医療保険（65歳未満）。48日までのレンタカー保険も含む。", "ko": "여행 중 최대 $500만 응급 의료 보장 (65세 미만). 48일까지 렌터카 보험 포함.", "zh": "旅行时可获最高500万美元紧急医疗保险（65岁以下）。还包括最长48天的租车保险。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'INSURANCE', '{"en": "Mobile Device Protection", "es": "Protección de dispositivo móvil", "fr": "Protection appareil mobile", "ja": "モバイル機器保護", "ko": "모바일 기기 보호", "zh": "手机保护计划"}', '{"en": "Get up to $1,000 coverage for your mobile phone against damage or theft when you pay your monthly bill with this card.", "es": "Cobertura hasta $1,000 para tu teléfono contra daños o robo al pagar la factura mensual con esta tarjeta.", "fr": "Couverture jusqu''à 1 000 $ pour votre téléphone contre dommages ou vol si vous payez la facture avec cette carte.", "ja": "この カードで月額料金を支払うと、携帯電話の破損・盗難に最大$1,000の補償。", "ko": "이 카드로 월 요금 결제 시 휴대폰 손상/도난에 최대 $1,000 보장.", "zh": "用此卡支付月费账单后，手机损坏或被盗可获最高$1,000保障。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'PERK', '{"en": "Free Supplementary Cards", "es": "Tarjetas adicionales gratis", "fr": "Cartes supplémentaires gratuites", "ja": "追加カード無料", "ko": "무료 추가 카드", "zh": "免费附属卡"}', '{"en": "Add supplementary cards for family members at no extra cost. All spending earns points to your account.", "es": "Agrega tarjetas adicionales para familiares sin costo extra. Todos los gastos acumulan puntos.", "fr": "Ajoutez des cartes supplémentaires pour la famille sans frais. Toutes les dépenses accumulent des points.", "ja": "家族用の追加カードを無料で発行可能。全ての利用がポイント対象。", "ko": "가족용 추가 카드 무료 발급. 모든 지출이 포인트 적립 대상.", "zh": "可免费为家人添加附属卡。所有消费积分都累积到您的账户。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'PERK', '{"en": "Referral Bonus", "es": "Bono de referencia", "fr": "Bonus de parrainage", "ja": "紹介ボーナス", "ko": "추천 보너스", "zh": "推荐奖励"}', '{"en": "Earn 5,000 MR points for each successful referral, up to 75,000 points per year. Great way to offset the annual fee.", "es": "Gana 5,000 puntos MR por cada referencia exitosa, hasta 75,000 puntos/año. Ideal para compensar la cuota anual.", "fr": "Gagnez 5 000 points MR par parrainage réussi, jusqu''à 75 000 points/an. Idéal pour compenser les frais annuels.", "ja": "紹介成功ごとに5,000 MRポイント獲得、年間最大75,000ポイント。年会費の相殺に最適。", "ko": "추천 성공당 5,000 MR 포인트, 연간 최대 75,000 포인트. 연회비 상쇄에 좋음.", "zh": "每成功推荐一人可获5,000 MR积分，每年最高75,000积分。抵消年费的好方法。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'REDEMPTION', '{"en": "Transfer to Airline Partners", "es": "Transferir a aerolíneas socias", "fr": "Transférer aux partenaires aériens", "ja": "航空パートナーへ移行", "ko": "항공사 파트너로 전환", "zh": "转移至航空伙伴"}', '{"en": "Transfer MR points 1:1 to Aeroplan, British Airways Avios, and Hilton. Access airlines in all three major alliances for maximum flexibility.", "es": "Transfiere puntos MR 1:1 a Aeroplan, British Airways Avios y Hilton. Acceso a las tres alianzas principales.", "fr": "Transférez les points MR 1:1 vers Aeroplan, British Airways Avios et Hilton. Accès aux trois grandes alliances.", "ja": "MRポイントをAeroplan、英国航空Avios、ヒルトンへ1:1で移行。3大アライアンス全てにアクセス可能。", "ko": "MR 포인트를 Aeroplan, 브리티시 에어웨이 Avios, 힐튼으로 1:1 전환. 3대 항공 동맹 모두 이용 가능.", "zh": "MR积分可1:1转移至Aeroplan、英航Avios和希尔顿。可使用三大航空联盟航司，灵活度最高。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'REDEMPTION', '{"en": "Fixed Points Travel", "es": "Viaje con puntos fijos", "fr": "Voyage à points fixes", "ja": "固定ポイント旅行", "ko": "고정 포인트 여행", "zh": "固定积分旅行"}', '{"en": "Redeem at 1 cent per point through Amex Travel for hotels and flights. Best for quick redemptions without transfer delays.", "es": "Canjea a 1 centavo por punto en Amex Travel para hoteles y vuelos. Ideal para canjes rápidos.", "fr": "Échangez à 1 cent par point via Amex Travel pour hôtels et vols. Idéal pour les échanges rapides.", "ja": "Amex Travelで1ポイント1セントで交換。ホテルや航空券を素早く予約したい時に最適。", "ko": "Amex Travel에서 포인트당 1센트로 호텔 및 항공권 교환. 빠른 교환에 적합.", "zh": "通过Amex Travel兑换酒店和机票，每积分价值1美分。适合快速兑换，无需等待积分转移。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Cobalt Card'), 'STACKING', '{"en": "Pair with Aeroplan Cards", "es": "Combinar con tarjetas Aeroplan", "fr": "Combiner avec les cartes Aeroplan", "ja": "Aeroplanカードと組み合わせ", "ko": "Aeroplan 카드와 조합", "zh": "搭配Aeroplan卡使用"}', '{"en": "Use Cobalt for groceries/dining (5x), pair with Aeroplan Reserve for Air Canada bookings (3x) to maximize across all spending categories.", "es": "Usa Cobalt para supermercado/comida (5x), combina con Aeroplan Reserve para Air Canada (3x).", "fr": "Utilisez Cobalt pour épicerie/restaurants (5x), combinez avec Aeroplan Reserve pour Air Canada (3x).", "ja": "Cobaltは食料品・外食に（5倍）、Aeroplan Reserveはエアカナダ予約に（3倍）で全カテゴリ最大化。", "ko": "Cobalt는 식료품/다이닝 (5배), Aeroplan Reserve는 에어캐나다 (3배)로 전 카테고리 극대화.", "zh": "用Cobalt消费超市/餐饮（5倍），搭配Aeroplan Reserve用于加航购票（3倍），全面最大化积分。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'AVOID', '{"en": "Avoid Fixed Points Redemption", "es": "Evitar canje de puntos fijos", "fr": "Éviter l''échange à points fixes", "ja": "固定ポイント交換を避ける", "ko": "고정 포인트 교환 피하기", "zh": "避免固定积分兑换"}', '{"en": "Don''t redeem points at 1 cent per point through Amex Travel. Transfer to airline partners for 1.5-2+ cents per point value instead.", "es": "No canjees a 1 centavo/punto en Amex Travel. Transfiere a aerolíneas para 1.5-2+ centavos/punto.", "fr": "N''échangez pas à 1 cent/point via Amex Travel. Transférez aux partenaires aériens pour 1,5-2+ cents/point.", "ja": "Amex Travelで1ポイント1セント交換は避けて。航空パートナーへ移行で1.5-2+セント/ポイントの価値に。", "ko": "Amex Travel에서 포인트당 1센트로 교환하지 마세요. 항공사 파트너로 전환하면 1.5-2+ 센트/포인트 가치.", "zh": "不要通过Amex Travel以每积分1美分兑换。转移至航空伙伴可获得每积分1.5-2+美分的价值。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'AVOID', '{"en": "Don''t Miss Travel Credit", "es": "No olvides el crédito de viaje", "fr": "N''oubliez pas le crédit voyage", "ja": "旅行クレジットを忘れずに", "ko": "여행 크레딧 잊지 마세요", "zh": "别忘记使用旅行抵用金"}', '{"en": "Use your $100 annual travel credit before your card anniversary. It doesn''t roll over - book anything on Amex Travel to use it.", "es": "Usa tu crédito de $100 antes del aniversario de la tarjeta. No se acumula - reserva en Amex Travel.", "fr": "Utilisez vos 100 $ de crédit voyage avant l''anniversaire de la carte. Non cumulable - réservez sur Amex Travel.", "ja": "カード更新前に年間$100旅行クレジットを使用。繰り越し不可 - Amex Travelで何でも予約して使い切る。", "ko": "카드 기념일 전에 연간 $100 여행 크레딧 사용. 이월 안 됨 - Amex Travel에서 예약하여 사용.", "zh": "在卡周年日前使用$100年度旅行抵用金。不能累积到下一年 - 在Amex Travel预订任何内容即可使用。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'BEST_USE', '{"en": "Gas, Grocery & Drugstore 2x", "es": "Gasolina, supermercado y farmacia 2x", "fr": "Essence, épicerie et pharmacie 2x", "ja": "ガソリン・食料品・薬局2倍", "ko": "주유, 식료품, 약국 2배", "zh": "加油、超市、药店2倍积分"}', '{"en": "Earn 2x MR points on gas, groceries, and drugstores. No monthly cap on these bonus categories.", "es": "Gana 2x puntos MR en gasolina, supermercado y farmacias. Sin límite mensual en estas categorías.", "fr": "Gagnez 2x points MR sur essence, épicerie et pharmacies. Aucun plafond mensuel sur ces catégories.", "ja": "ガソリン、食料品、薬局で2倍MRポイント。これらのボーナスカテゴリに月間上限なし。", "ko": "주유, 식료품, 약국에서 2배 MR 포인트. 이 보너스 카테고리에 월 한도 없음.", "zh": "加油、超市和药店消费可获2倍MR积分。这些奖励类别无月度上限。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'BEST_USE', '{"en": "Travel Purchases 2x", "es": "Compras de viaje 2x", "fr": "Achats voyage 2x", "ja": "旅行購入2倍", "ko": "여행 구매 2배", "zh": "旅行消费2倍积分"}', '{"en": "Earn 2x MR points on travel purchases including flights, hotels, and car rentals. Book through Amex Travel for an extra 1x (total 3x).", "es": "Gana 2x puntos MR en compras de viaje. Reserva por Amex Travel para 1x extra (total 3x).", "fr": "Gagnez 2x points MR sur les achats voyage. Réservez via Amex Travel pour 1x supplémentaire (total 3x).", "ja": "旅行購入で2倍MRポイント。Amex Travel経由で追加1倍（合計3倍）。", "ko": "여행 구매에서 2배 MR 포인트. Amex Travel 예약 시 추가 1배 (총 3배).", "zh": "旅行消费（机票、酒店、租车）可获2倍MR积分。通过Amex Travel预订可额外获得1倍（共3倍）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'INSURANCE', '{"en": "$5M Emergency Medical (15 days)", "es": "$5M seguro médico (15 días)", "fr": "5 M$ assurance médicale (15 jours)", "ja": "500万ドル緊急医療(15日)", "ko": "$500만 응급 의료 (15일)", "zh": "500万紧急医疗保险(15天)"}', '{"en": "Up to $5 million emergency medical coverage for first 15 days of travel (for cardholders under 65). Includes trip cancellation up to $6,000.", "es": "Cobertura médica de emergencia hasta $5M para los primeros 15 días (menores de 65). Incluye cancelación hasta $6,000.", "fr": "Couverture médicale d''urgence jusqu''à 5 M$ pour les 15 premiers jours (moins de 65 ans). Inclut annulation voyage jusqu''à 6 000 $.", "ja": "旅行最初の15日間、最高500万ドルの緊急医療保険（65歳未満）。旅行キャンセル最高$6,000も含む。", "ko": "여행 첫 15일간 최대 $500만 응급 의료 보장 (65세 미만). 여행 취소 최대 $6,000 포함.", "zh": "旅行前15天可获最高500万美元紧急医疗保险（65岁以下）。还包括最高$6,000旅行取消保险。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'INSURANCE', '{"en": "Car Rental Insurance (48 days)", "es": "Seguro de auto rentado (48 días)", "fr": "Assurance location auto (48 jours)", "ja": "レンタカー保険(48日)", "ko": "렌터카 보험 (48일)", "zh": "租车保险(48天)"}', '{"en": "Comprehensive car rental insurance for up to 48 consecutive days. Covers vehicles with MSRP up to $85,000. Decline the rental company''s CDW to save.", "es": "Seguro de auto rentado hasta 48 días consecutivos. Cubre vehículos MSRP hasta $85,000. Rechaza el CDW de la rentadora.", "fr": "Assurance location auto complète jusqu''à 48 jours consécutifs. Couvre véhicules PDSF jusqu''à 85 000 $. Refusez le CDW du loueur.", "ja": "最長48日間連続のレンタカー保険。希望小売価格$85,000までの車両対象。レンタル会社のCDWを断って節約。", "ko": "최대 48일 연속 렌터카 보험. MSRP $85,000까지 차량 보장. 렌터카 회사 CDW 거절로 절약.", "zh": "连续48天租车综合保险。覆盖建议零售价$85,000以内的车辆。可拒绝租车公司的CDW以节省费用。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'PERK', '{"en": "Referral Bonus", "es": "Bono de referencia", "fr": "Bonus de parrainage", "ja": "紹介ボーナス", "ko": "추천 보너스", "zh": "推荐奖励"}', '{"en": "Earn 7,500 MR points for each successful referral, up to 112,500 points per year. One of the most generous referral programs among Canadian cards.", "es": "Gana 7,500 puntos MR por referencia exitosa, hasta 112,500 puntos/año. Uno de los mejores programas de referencia en Canadá.", "fr": "Gagnez 7 500 points MR par parrainage réussi, jusqu''à 112 500 points/an. Un des meilleurs programmes de parrainage au Canada.", "ja": "紹介成功ごとに7,500 MRポイント、年間最大112,500ポイント。カナダで最も寛大な紹介プログラムの一つ。", "ko": "추천 성공당 7,500 MR 포인트, 연간 최대 112,500 포인트. 캐나다에서 가장 후한 추천 프로그램 중 하나.", "zh": "每成功推荐一人可获7,500 MR积分，每年最高112,500积分。加拿大最慷慨的推荐计划之一。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'PERK', '{"en": "The Hotel Collection Benefits", "es": "Beneficios Hotel Collection", "fr": "Avantages Hotel Collection", "ja": "Hotel Collectionの特典", "ko": "Hotel Collection 혜택", "zh": "Hotel Collection酒店权益"}', '{"en": "Book through The Hotel Collection for up to $100 USD hotel credit and room upgrades when available at select luxury properties.", "es": "Reserva por Hotel Collection para hasta $100 USD de crédito y upgrades en hoteles de lujo selectos.", "fr": "Réservez via Hotel Collection pour jusqu''à 100 $ USD de crédit hôtel et surclassements dans certains hôtels de luxe.", "ja": "Hotel Collection経由で予約すると、最大$100 USDのホテルクレジットと客室アップグレード（空き状況次第）。", "ko": "Hotel Collection 예약 시 최대 $100 USD 호텔 크레딧 및 객실 업그레이드 (가능 시).", "zh": "通过Hotel Collection预订精选豪华酒店，可获最高$100美元酒店抵用金及客房升级（视情况）。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'REDEMPTION', '{"en": "Transfer to Airline Partners", "es": "Transferir a aerolíneas socias", "fr": "Transférer aux partenaires aériens", "ja": "航空パートナーへ移行", "ko": "항공사 파트너로 전환", "zh": "转移至航空伙伴"}', '{"en": "Transfer MR points to Aeroplan, British Airways Avios, Air France KLM, Delta, and more. Access all three major airline alliances for maximum flexibility.", "es": "Transfiere puntos MR a Aeroplan, British Airways, Air France KLM, Delta y más. Acceso a las tres alianzas.", "fr": "Transférez les points MR vers Aeroplan, British Airways, Air France KLM, Delta, etc. Accès aux trois grandes alliances.", "ja": "MRポイントをAeroplan、英国航空、エールフランスKLM、デルタなどへ移行。3大アライアンス全てにアクセス。", "ko": "MR 포인트를 Aeroplan, 브리티시 에어웨이, 에어프랑스 KLM, 델타 등으로 전환. 3대 항공 동맹 이용 가능.", "zh": "MR积分可转移至Aeroplan、英航Avios、法航荷航、达美等。可使用三大航空联盟，灵活度最高。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'STACKING', '{"en": "Gift Card Strategy", "es": "Estrategia de tarjetas regalo", "fr": "Stratégie cartes-cadeaux", "ja": "ギフトカード戦略", "ko": "기프트 카드 전략", "zh": "礼品卡策略"}', '{"en": "Buy gift cards at grocery stores to earn 2x on purchases that would normally earn 1x (electronics, furniture, etc.). Great way to maximize points.", "es": "Compra tarjetas regalo en supermercados para ganar 2x en compras que normalmente ganan 1x. Gran forma de maximizar puntos.", "fr": "Achetez des cartes-cadeaux en épicerie pour gagner 2x sur des achats normalement à 1x. Excellente façon de maximiser les points.", "ja": "食料品店でギフトカードを購入し、通常1倍の買い物（電子機器、家具等）を2倍に。ポイント最大化の秘訣。", "ko": "식료품점에서 기프트 카드 구매로 일반 1배 적립 품목(전자제품, 가구 등)을 2배로. 포인트 극대화 방법.", "zh": "在超市购买礼品卡，原本1倍积分的消费（电子产品、家具等）可变成2倍。最大化积分的好方法。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'TRAVEL_BENEFIT', '{"en": "$100 Annual Travel Credit", "es": "$100 crédito de viaje anual", "fr": "100 $ crédit voyage annuel", "ja": "年間$100旅行クレジット", "ko": "연간 $100 여행 크레딧", "zh": "每年$100旅行抵用金"}', '{"en": "Receive $100 annual travel credit when booking through Amex Travel. Effectively reduces the annual fee from $250 to $150.", "es": "Recibe $100 de crédito de viaje anual al reservar por Amex Travel. Reduce la cuota anual de $250 a $150.", "fr": "Recevez 100 $ de crédit voyage annuel via Amex Travel. Réduit effectivement les frais annuels de 250 $ à 150 $.", "ja": "Amex Travel経由で年間$100の旅行クレジット。実質年会費$250→$150に。", "ko": "Amex Travel 예약 시 연간 $100 여행 크레딧. 실질 연회비 $250→$150.", "zh": "通过Amex Travel预订可获$100年度旅行抵用金。实际年费从$250降至$150。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'TRAVEL_BENEFIT', '{"en": "4 Plaza Premium Lounge Passes", "es": "4 pases Plaza Premium", "fr": "4 accès Plaza Premium", "ja": "Plaza Premium 4回利用", "ko": "Plaza Premium 라운지 4회", "zh": "4次Plaza Premium贵宾室"}', '{"en": "Get 4 complimentary Plaza Premium lounge visits per year. Also includes Priority Pass membership with pay-per-visit access to 1,400+ lounges.", "es": "4 visitas gratuitas a Plaza Premium por año. Incluye membresía Priority Pass con acceso de pago a 1,400+ salas.", "fr": "4 visites gratuites Plaza Premium par an. Inclut aussi Priority Pass avec accès payant à 1 400+ salons.", "ja": "年4回無料Plaza Premiumラウンジ利用。Priority Passも付帯、1,400+ラウンジに有料アクセス可能。", "ko": "연 4회 무료 Plaza Premium 라운지. Priority Pass 회원 자격으로 1,400+ 라운지 유료 이용 가능.", "zh": "每年4次免费Plaza Premium贵宾室使用权。还包括Priority Pass会员资格，可付费使用1,400+个贵宾室。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Gold Rewards Card'), 'TRAVEL_BENEFIT', '{"en": "$50 NEXUS Credit", "es": "$50 crédito NEXUS", "fr": "50 $ crédit NEXUS", "ja": "$50 NEXUSクレジット", "ko": "$50 NEXUS 크레딧", "zh": "$50 NEXUS申请费抵用"}', '{"en": "Receive $50 statement credit for NEXUS application or renewal fee once every 4 years. NEXUS provides expedited border crossing between Canada and US.", "es": "Recibe $50 de crédito NEXUS cada 4 años. NEXUS permite cruce fronterizo rápido entre Canadá y EE.UU.", "fr": "Recevez 50 $ de crédit pour NEXUS tous les 4 ans. NEXUS permet un passage frontalier accéléré Canada-USA.", "ja": "4年ごとに$50のNEXUSクレジット。NEXUSでカナダ・米国間の国境通過を迅速化。", "ko": "4년마다 $50 NEXUS 크레딧. NEXUS로 캐나다-미국 국경 신속 통과.", "zh": "每4年可获$50 NEXUS申请或续费抵用金。NEXUS可快速通关加拿大和美国边境。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'AVOID', '{"en": "Don''t Waste Your Credits", "es": "No desperdicies tus créditos", "fr": "N''oubliez pas vos crédits", "ja": "クレジットを無駄にしない", "ko": "크레딧을 낭비하지 마세요", "zh": "别浪费抵用金"}', '{"en": "Use your $200 travel credit (anniversary year) and $200 dining credit (calendar year) before they expire. That''s $400 in annual value.", "es": "Usa tus $200 crédito viaje y $200 crédito comida antes de que expiren. $400 de valor anual.", "fr": "Utilisez vos 200 $ crédit voyage et 200 $ crédit restaurant avant expiration. 400 $ de valeur annuelle.", "ja": "$200旅行クレジット（カード更新年）と$200ダイニングクレジット（暦年）を期限前に使用。年間$400の価値。", "ko": "$200 여행 크레딧 (카드 기념일)과 $200 다이닝 크레딧 (달력 연도) 만료 전 사용. 연간 $400 가치.", "zh": "在过期前使用$200旅行抵用金（卡周年）和$200餐饮抵用金（日历年）。每年$400的价值。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'AVOID', '{"en": "Avoid Fixed Points Redemption", "es": "Evitar canje de puntos fijos", "fr": "Éviter l''échange à points fixes", "ja": "固定ポイント交換を避ける", "ko": "고정 포인트 교환 피하기", "zh": "避免固定积分兑换"}', '{"en": "Don''t redeem points at 1 cent per point through Amex Travel. Transfer to airline partners for 1.5-2+ cents per point value.", "es": "No canjees a 1 centavo/punto en Amex Travel. Transfiere a aerolíneas para 1.5-2+ centavos/punto.", "fr": "N''échangez pas à 1 cent/point via Amex Travel. Transférez aux partenaires aériens pour 1,5-2+ cents/point.", "ja": "Amex Travelで1ポイント1セント交換は避けて。航空パートナーへ移行で1.5-2+セント/ポイントの価値に。", "ko": "Amex Travel에서 포인트당 1센트로 교환하지 마세요. 항공사 파트너로 전환하면 1.5-2+ 센트/포인트 가치.", "zh": "不要通过Amex Travel以每积分1美分兑换。转移至航空伙伴可获得每积分1.5-2+美分的价值。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'BEST_USE', '{"en": "Travel & Dining 2x", "es": "Viaje y comida 2x", "fr": "Voyage et restaurants 2x", "ja": "旅行・外食2倍", "ko": "여행 & 다이닝 2배", "zh": "旅行和餐饮2倍积分"}', '{"en": "Earn 2x MR points on all travel and dining purchases. Use for flights, hotels, restaurants, and food delivery.", "es": "Gana 2x puntos MR en todas las compras de viaje y comida. Vuelos, hoteles, restaurantes y delivery.", "fr": "Gagnez 2x points MR sur tous les achats voyage et restaurants. Vols, hôtels, restaurants et livraison.", "ja": "旅行・外食の全ての購入で2倍MRポイント。航空券、ホテル、レストラン、デリバリーに。", "ko": "모든 여행 및 다이닝 구매에서 2배 MR 포인트. 항공권, 호텔, 레스토랑, 배달에 적용.", "zh": "所有旅行和餐饮消费可获2倍MR积分。适用于机票、酒店、餐厅和外卖。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'BEST_USE', '{"en": "Referral Bonus 15,000 pts", "es": "Bono referencia 15,000 pts", "fr": "Bonus parrainage 15 000 pts", "ja": "紹介ボーナス15,000ポイント", "ko": "추천 보너스 15,000 포인트", "zh": "推荐奖励15,000积分"}', '{"en": "Earn 15,000 MR points for each successful referral, up to 225,000 points per year. The highest referral bonus among Canadian cards.", "es": "Gana 15,000 puntos MR por referencia exitosa, hasta 225,000 puntos/año. El mayor bono de referencia en Canadá.", "fr": "Gagnez 15 000 points MR par parrainage réussi, jusqu''à 225 000 points/an. Le plus haut bonus de parrainage au Canada.", "ja": "紹介成功ごとに15,000 MRポイント、年間最大225,000ポイント。カナダ最高の紹介ボーナス。", "ko": "추천 성공당 15,000 MR 포인트, 연간 최대 225,000 포인트. 캐나다 최고의 추천 보너스.", "zh": "每成功推荐一人可获15,000 MR积分，每年最高225,000积分。加拿大最高的推荐奖励。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'INSURANCE', '{"en": "$5M Emergency Medical (15 days)", "es": "$5M seguro médico (15 días)", "fr": "5 M$ assurance médicale (15 jours)", "ja": "500万ドル緊急医療(15日)", "ko": "$500만 응급 의료 (15일)", "zh": "500万紧急医疗保险(15天)"}', '{"en": "Up to $5 million emergency medical coverage for first 15 days of travel (under 65). Includes $2,500 trip cancellation and $1,000 flight delay.", "es": "Cobertura médica de emergencia hasta $5M para los primeros 15 días (menores de 65). Incluye cancelación $2,500 y retraso $1,000.", "fr": "Couverture médicale d''urgence jusqu''à 5 M$ pour les 15 premiers jours (moins de 65 ans). Inclut annulation 2 500 $ et retard vol 1 000 $.", "ja": "旅行最初の15日間、最高500万ドルの緊急医療保険（65歳未満）。旅行キャンセル$2,500、航空遅延$1,000も含む。", "ko": "여행 첫 15일간 최대 $500만 응급 의료 보장 (65세 미만). 여행 취소 $2,500, 항공 지연 $1,000 포함.", "zh": "旅行前15天可获最高500万美元紧急医疗保险（65岁以下）。还包括$2,500旅行取消和$1,000航班延误。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'PERK', '{"en": "Fine Hotels & Resorts", "es": "Fine Hotels & Resorts", "fr": "Fine Hotels & Resorts", "ja": "Fine Hotels & Resorts", "ko": "Fine Hotels & Resorts", "zh": "Fine Hotels & Resorts"}', '{"en": "Book luxury hotels with guaranteed room upgrades, daily breakfast, $100 USD property credit, and 4 PM late checkout.", "es": "Reserva hoteles de lujo con upgrade garantizado, desayuno diario, crédito $100 USD y late checkout 4 PM.", "fr": "Réservez des hôtels de luxe avec upgrade garanti, petit-déjeuner, crédit 100 $ USD et départ 16h.", "ja": "高級ホテル予約で客室アップグレード保証、毎日の朝食、$100 USDクレジット、16時レイトチェックアウト。", "ko": "럭셔리 호텔 예약 시 객실 업그레이드 보장, 매일 조식, $100 USD 크레딧, 오후 4시 레이트 체크아웃.", "zh": "预订豪华酒店可享保证房间升级、每日早餐、$100美元酒店消费额度和下午4点延迟退房。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'PERK', '{"en": "Platinum Concierge Service", "es": "Servicio Concierge Platinum", "fr": "Service Conciergerie Platinum", "ja": "プラチナコンシェルジュ", "ko": "플래티넘 컨시어지 서비스", "zh": "白金礼宾服务"}', '{"en": "24/7 concierge service for travel bookings, restaurant reservations, event tickets, and special requests.", "es": "Servicio concierge 24/7 para reservas de viaje, restaurantes, boletos y solicitudes especiales.", "fr": "Service conciergerie 24/7 pour réservations voyage, restaurants, billets et demandes spéciales.", "ja": "24時間コンシェルジュサービス。旅行予約、レストラン予約、イベントチケット、特別リクエストに対応。", "ko": "24시간 컨시어지 서비스. 여행 예약, 레스토랑 예약, 이벤트 티켓, 특별 요청 지원.", "zh": "24/7礼宾服务，可协助旅行预订、餐厅预约、活动门票和特殊需求。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'REDEMPTION', '{"en": "Transfer to Airline Partners", "es": "Transferir a aerolíneas socias", "fr": "Transférer aux partenaires aériens", "ja": "航空パートナーへ移行", "ko": "항공사 파트너로 전환", "zh": "转移至航空伙伴"}', '{"en": "Transfer MR points 1:1 to Aeroplan, British Airways Avios. Access Star Alliance, oneworld, and SkyTeam airlines for maximum flexibility.", "es": "Transfiere puntos MR 1:1 a Aeroplan, British Airways. Acceso a Star Alliance, oneworld y SkyTeam.", "fr": "Transférez les points MR 1:1 vers Aeroplan, British Airways. Accès à Star Alliance, oneworld et SkyTeam.", "ja": "MRポイントをAeroplan、英国航空へ1:1で移行。スターアライアンス、ワンワールド、スカイチーム全てにアクセス。", "ko": "MR 포인트를 Aeroplan, 브리티시 에어웨이로 1:1 전환. 스타얼라이언스, 원월드, 스카이팀 이용 가능.", "zh": "MR积分可1:1转移至Aeroplan、英航Avios。可使用星空联盟、寰宇一家和天合联盟航司，灵活度最高。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'STACKING', '{"en": "Meet Spending with Chexy", "es": "Cumplir gastos con Chexy", "fr": "Atteindre les dépenses avec Chexy", "ja": "Chexyで消費要件達成", "ko": "Chexy로 지출 요건 충족", "zh": "用Chexy完成消费要求"}', '{"en": "Use Chexy (1.75% fee) to pay rent/bills with your card. Great for meeting the $10,000 minimum spend for welcome bonus.", "es": "Usa Chexy (1.75% de comisión) para pagar renta/facturas. Ideal para cumplir los $10,000 de gasto mínimo.", "fr": "Utilisez Chexy (frais 1,75 %) pour payer loyer/factures. Idéal pour atteindre les 10 000 $ de dépenses minimum.", "ja": "Chexy（1.75%手数料）で家賃/請求書をカード払い。$10,000の最低利用達成に最適。", "ko": "Chexy (1.75% 수수료)로 월세/청구서 카드 결제. $10,000 최소 지출 충족에 적합.", "zh": "使用Chexy（1.75%手续费）用卡支付房租/账单。适合完成$10,000开户消费要求。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'TRAVEL_BENEFIT', '{"en": "Unlimited Lounge Access", "es": "Acceso ilimitado a salas VIP", "fr": "Accès illimité aux salons", "ja": "無制限ラウンジアクセス", "ko": "무제한 라운지 이용", "zh": "无限次贵宾室使用"}', '{"en": "Unlimited access to 1,300+ lounges worldwide including Centurion Lounges (can bring 2 guests free) and Priority Pass lounges.", "es": "Acceso ilimitado a 1,300+ salas incluyendo Centurion Lounges (2 invitados gratis) y Priority Pass.", "fr": "Accès illimité à plus de 1 300 salons dont Centurion Lounges (2 invités gratuits) et Priority Pass.", "ja": "Centurion Lounge（ゲスト2名無料）、Priority Passなど1,300+ラウンジへ無制限アクセス。", "ko": "Centurion Lounge (게스트 2명 무료), Priority Pass 등 1,300+ 라운지 무제한 이용.", "zh": "全球1,300+个贵宾室无限次使用，包括Centurion Lounge（可免费带2位客人）和Priority Pass贵宾室。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'TRAVEL_BENEFIT', '{"en": "$200 Annual Travel Credit", "es": "$200 crédito de viaje anual", "fr": "200 $ crédit voyage annuel", "ja": "年間$200旅行クレジット", "ko": "연간 $200 여행 크레딧", "zh": "每年$200旅行抵用金"}', '{"en": "Receive $200 annual travel credit (anniversary year) when booking through Amex Travel. Helps offset the $799 annual fee.", "es": "Recibe $200 de crédito de viaje anual al reservar por Amex Travel. Ayuda a compensar la cuota de $799.", "fr": "Recevez 200 $ de crédit voyage annuel via Amex Travel. Aide à compenser les frais de 799 $.", "ja": "Amex Travel経由で年間$200の旅行クレジット。$799の年会費相殺に。", "ko": "Amex Travel 예약 시 연간 $200 여행 크레딧. $799 연회비 상쇄에 도움.", "zh": "每年可获$200旅行抵用金（卡周年），通过Amex Travel预订使用。帮助抵消$799年费。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'TRAVEL_BENEFIT', '{"en": "$200 Annual Dining Credit", "es": "$200 crédito de comida anual", "fr": "200 $ crédit restaurant annuel", "ja": "年間$200ダイニングクレジット", "ko": "연간 $200 다이닝 크레딧", "zh": "每年$200餐饮抵用金"}', '{"en": "Receive $200 annual dining credit (calendar year) at participating restaurants. Combined with travel credit, reduces effective fee to $399.", "es": "Recibe $200 de crédito de comida anual en restaurantes participantes. Con crédito de viaje, cuota efectiva $399.", "fr": "Recevez 200 $ de crédit restaurant annuel dans les restaurants participants. Avec le crédit voyage, frais effectifs de 399 $.", "ja": "参加レストランで年間$200のダイニングクレジット。旅行クレジットと合わせて実質年会費$399に。", "ko": "참여 레스토랑에서 연간 $200 다이닝 크레딧. 여행 크레딧과 합쳐 실질 연회비 $399.", "zh": "每年可获$200餐饮抵用金（日历年），在参与餐厅使用。与旅行抵用金合计，实际年费降至$399。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'Platinum Card'), 'TRAVEL_BENEFIT', '{"en": "Marriott & Hilton Gold Status", "es": "Estatus Gold Marriott & Hilton", "fr": "Statut Gold Marriott & Hilton", "ja": "Marriott & Hilton ゴールド会員", "ko": "Marriott & Hilton 골드 회원", "zh": "万豪和希尔顿金卡会籍"}', '{"en": "Complimentary Marriott Bonvoy Gold Elite and Hilton Honors Gold status. Enjoy room upgrades, late checkout, and bonus points.", "es": "Estatus Marriott Bonvoy Gold Elite y Hilton Honors Gold gratis. Upgrades, late checkout y puntos extra.", "fr": "Statut Marriott Bonvoy Gold Elite et Hilton Honors Gold gratuits. Upgrades, départ tardif et points bonus.", "ja": "Marriott Bonvoy Gold EliteとHilton Honors Gold会員資格が無料。客室アップグレード、レイトチェックアウト、ボーナスポイント。", "ko": "Marriott Bonvoy Gold Elite, Hilton Honors Gold 무료 제공. 객실 업그레이드, 레이트 체크아웃, 보너스 포인트.", "zh": "免费获得万豪Bonvoy金卡会籍和希尔顿荣誉金卡会籍。享受房间升级、延迟退房和额外积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'AVOID', '{"en": "Superstores Don''t Qualify", "es": "Supermercados grandes no califican", "fr": "Les grandes surfaces ne comptent pas", "ja": "大型店舗は対象外", "ko": "대형마트 제외", "zh": "大型超市不算"}', '{"en": "Superstores, wholesale clubs (Costco), and general merchandise retailers don''t qualify for 2% gas/grocery. Use at stand-alone stores.", "es": "Supermercados grandes, clubes (Costco) y minoristas generales no califican para el 2%. Usa en tiendas independientes.", "fr": "Les grandes surfaces, clubs entrepôts (Costco) et détaillants généraux ne comptent pas pour le 2 %. Utilisez dans les magasins autonomes.", "ja": "大型店舗、会員制倉庫店（Costco）、総合小売店は2%対象外。独立店舗で使用を。", "ko": "대형마트, 창고형매장(Costco), 종합소매점은 2% 대상 제외. 독립 매장에서 사용.", "zh": "大型超市、会员店（Costco）和综合零售店不适用2%加油/超市返现。请在独立商店使用。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'BEST_USE', '{"en": "Gas & Grocery 2%", "es": "Gasolina y supermercado 2%", "fr": "Essence et épicerie 2 %", "ja": "ガソリン・食料品2%", "ko": "주유 & 식료품 2%", "zh": "加油和超市2%返现"}', '{"en": "Earn 2% cash back at stand-alone gas stations and grocery stores (up to $15,000/year combined, then 1.25%).", "es": "Gana 2% en gasolineras y supermercados independientes (hasta $15,000/año combinado, luego 1.25%).", "fr": "Gagnez 2 % sur les stations-service et épiceries autonomes (jusqu''à 15 000 $/an combiné, puis 1,25 %).", "ja": "独立したガソリンスタンドと食料品店で2%還元（年間$15,000まで、以降1.25%）。", "ko": "독립 주유소와 식료품점에서 2% 캐시백 (연간 $15,000까지, 이후 1.25%).", "zh": "独立加油站和超市可获2%返现（每年合计最高$15,000消费，之后1.25%）。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'BEST_USE', '{"en": "No Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 없음", "zh": "无年费"}', '{"en": "Keep this card forever with no annual fee. Great as a simple everyday cashback card for gas and groceries.", "es": "Mantén esta tarjeta para siempre sin cuota anual. Ideal como tarjeta simple para gasolina y supermercado.", "fr": "Gardez cette carte pour toujours sans frais annuels. Idéale comme carte simple pour essence et épicerie.", "ja": "年会費無料で永久に保持可能。ガソリンと食料品の日常使いに最適なシンプルなカード。", "ko": "연회비 없이 영구 보유 가능. 주유와 식료품용 간단한 일상 캐시백 카드로 적합.", "zh": "永久无年费。适合作为日常加油和超市消费的简单返现卡。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'BEST_USE', '{"en": "1.25% on Everything Else", "es": "1.25% en todo lo demás", "fr": "1,25 % sur tout le reste", "ja": "その他全て1.25%", "ko": "기타 모든 구매 1.25%", "zh": "其他消费1.25%返现"}', '{"en": "Earn 1.25% cash back on all other purchases with no caps. Higher than most no-fee cards'' base rate.", "es": "Gana 1.25% en todas las demás compras sin límite. Más alto que la mayoría de las tarjetas sin cuota.", "fr": "Gagnez 1,25 % sur tous les autres achats sans plafond. Plus élevé que la plupart des cartes sans frais.", "ja": "他の全購入で1.25%還元、上限なし。無料カードの中では高いベース還元率。", "ko": "다른 모든 구매에서 1.25% 캐시백, 한도 없음. 대부분의 무료 카드보다 높은 기본 적립률.", "zh": "其他所有消费可获1.25%返现，无上限。高于大多数无年费卡的基础返现率。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'INSURANCE', '{"en": "Purchase & Warranty Protection", "es": "Protección de compra y garantía", "fr": "Protection achat et garantie", "ja": "購入・保証保護", "ko": "구매 및 보증 보호", "zh": "购物和保修保障"}', '{"en": "90-day purchase protection (up to $1,000/occurrence) for theft or damage, plus extended warranty adds 1 extra year to manufacturer warranty.", "es": "Protección de compra 90 días (hasta $1,000/evento), más garantía extendida de 1 año sobre la garantía del fabricante.", "fr": "Protection achat 90 jours (jusqu''à 1 000 $/événement), plus garantie prolongée d''1 an sur la garantie du fabricant.", "ja": "90日間の購入保護（$1,000/件まで）、盗難・損傷対応、メーカー保証に1年延長保証を追加。", "ko": "90일 구매 보호 (사건당 최대 $1,000) 도난/손상 대비, 제조사 보증에 1년 연장 보증 추가.", "zh": "90天购物保障（每次最高$1,000）防盗窃或损坏，延长保修在原厂保修基础上增加1年。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'INSURANCE', '{"en": "Travel Accident Insurance", "es": "Seguro de accidente de viaje", "fr": "Assurance accident voyage", "ja": "旅行傷害保険", "ko": "여행 상해 보험", "zh": "旅行意外险"}', '{"en": "Up to $100,000 accidental death and dismemberment coverage when you charge travel tickets (plane, train, bus) to your card.", "es": "Hasta $100,000 de cobertura por muerte accidental y desmembramiento al pagar boletos de viaje con esta tarjeta.", "fr": "Jusqu''à 100 000 $ de couverture décès et mutilation accidentels lorsque vous payez vos billets de voyage avec cette carte.", "ja": "このカードで交通チケット（飛行機、電車、バス）を購入すると、最大$10万の傷害死亡・後遺障害補償。", "ko": "이 카드로 여행 티켓 (비행기, 기차, 버스) 구매 시 최대 $10만 상해사망 및 후유장해 보장.", "zh": "用此卡购买机票、火车票或巴士票可获最高$10万意外死亡和伤残保障。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'PERK', '{"en": "Front of the Line Access", "es": "Acceso prioritario", "fr": "Accès prioritaire", "ja": "優先アクセス", "ko": "우선 접근권", "zh": "优先购票权"}', '{"en": "Get presale and reserved tickets to concerts, theatre, movie screenings, and culinary events before the general public.", "es": "Obtén boletos de preventa y reservados para conciertos, teatro, proyecciones y eventos culinarios antes que el público.", "fr": "Accédez aux préventes et billets réservés pour concerts, théâtre, projections et événements culinaires avant le public.", "ja": "コンサート、劇場、映画上映、グルメイベントの先行販売・予約チケットを一般より早く入手。", "ko": "콘서트, 공연, 영화 시사회, 미식 이벤트의 선판매 및 예약 티켓을 일반 대중보다 먼저 구매.", "zh": "比公众提前获得演唱会、剧院、电影首映和美食活动的预售票和预留票。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash'), 'STACKING', '{"en": "Pair with Other Cards", "es": "Combinar con otras tarjetas", "fr": "Combiner avec d''autres cartes", "ja": "他のカードと併用", "ko": "다른 카드와 조합", "zh": "搭配其他卡使用"}', '{"en": "Use SimplyCash for gas/grocery (2%), pair with Cobalt for dining (5x) or other category cards for maximum rewards.", "es": "Usa SimplyCash para gasolina/supermercado (2%), combina con Cobalt para comida (5x) para maximizar.", "fr": "Utilisez SimplyCash pour essence/épicerie (2 %), combinez avec Cobalt pour restaurants (5x) pour maximiser.", "ja": "SimplyCashはガソリン/食料品に（2%）、Cobaltは外食に（5倍）と使い分けて最大化。", "ko": "SimplyCash는 주유/식료품 (2%), Cobalt는 다이닝 (5배)로 조합하여 극대화.", "zh": "SimplyCash用于加油/超市（2%），搭配Cobalt用于餐饮（5倍），或其他类别卡最大化收益。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'AVOID', '{"en": "Superstores Don''t Qualify", "es": "Supermercados grandes no califican", "fr": "Les grandes surfaces ne comptent pas", "ja": "大型店舗は対象外", "ko": "대형마트 제외", "zh": "大型超市不算"}', '{"en": "Superstores, wholesale clubs (Costco), and general merchandise retailers don''t qualify for 4% gas/grocery. Use at stand-alone stores.", "es": "Supermercados grandes, clubes (Costco) y minoristas generales no califican para el 4%. Usa en tiendas independientes.", "fr": "Les grandes surfaces, clubs entrepôts (Costco) et détaillants généraux ne comptent pas pour le 4 %. Utilisez dans les magasins autonomes.", "ja": "大型店舗、会員制倉庫店（Costco）、総合小売店は4%対象外。独立店舗で使用を。", "ko": "대형마트, 창고형매장(Costco), 종합소매점은 4% 대상 제외. 독립 매장에서 사용.", "zh": "大型超市、会员店（Costco）和综合零售店不适用4%加油/超市返现。请在独立商店使用。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'AVOID', '{"en": "Don''t Forget Month 13", "es": "No olvides el mes 13", "fr": "N''oubliez pas le mois 13", "ja": "13ヶ月目を忘れずに", "ko": "13개월차 잊지 마세요", "zh": "别忘记第13个月"}', '{"en": "Remember to make a purchase in month 13 to get your $50 statement credit. Set a reminder on your phone.", "es": "Recuerda hacer una compra en el mes 13 para obtener tu crédito de $50. Pon un recordatorio.", "fr": "N''oubliez pas de faire un achat au mois 13 pour obtenir votre crédit de 50 $. Programmez un rappel.", "ja": "13ヶ月目に購入して$50クレジットを忘れずに。スマホにリマインダーを設定。", "ko": "13개월차에 구매하여 $50 크레딧 받기를 잊지 마세요. 휴대폰에 알림 설정.", "zh": "记得在第13个月消费以获得$50账单抵扣。在手机上设置提醒。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'BEST_USE', '{"en": "Gas & Grocery 4%", "es": "Gasolina y supermercado 4%", "fr": "Essence et épicerie 4 %", "ja": "ガソリン・食料品4%", "ko": "주유 & 식료품 4%", "zh": "加油和超市4%返现"}', '{"en": "Earn 4% cash back at stand-alone gas stations and grocery stores (up to $30,000/year combined, then 2%). One of the highest gas/grocery rates in Canada.", "es": "Gana 4% en gasolineras y supermercados independientes (hasta $30,000/año combinado, luego 2%). Una de las tasas más altas en Canadá.", "fr": "Gagnez 4 % sur stations-service et épiceries autonomes (jusqu''à 30 000 $/an combiné, puis 2 %). L''un des meilleurs taux au Canada.", "ja": "独立したガソリンスタンドと食料品店で4%還元（年間$30,000まで、以降2%）。カナダ最高レベルのガソリン/食料品還元率。", "ko": "독립 주유소와 식료품점에서 4% 캐시백 (연간 $30,000까지, 이후 2%). 캐나다 최고 수준의 주유/식료품 적립률.", "zh": "独立加油站和超市可获4%返现（每年合计最高$30,000消费，之后2%）。加拿大最高的加油/超市返现率之一。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'BEST_USE', '{"en": "2% on Everything Else", "es": "2% en todo lo demás", "fr": "2 % sur tout le reste", "ja": "その他全て2%", "ko": "기타 모든 구매 2%", "zh": "其他消费2%返现"}', '{"en": "Earn 2% cash back on all other purchases with no caps. Excellent flat-rate cashback for everyday spending.", "es": "Gana 2% en todas las demás compras sin límite. Excelente tasa fija para gastos diarios.", "fr": "Gagnez 2 % sur tous les autres achats sans plafond. Excellent taux fixe pour les dépenses quotidiennes.", "ja": "他の全購入で2%還元、上限なし。日常消費に優秀なフラットレート。", "ko": "다른 모든 구매에서 2% 캐시백, 한도 없음. 일상 지출에 훌륭한 고정 적립률.", "zh": "其他所有消费可获2%返现，无上限。日常消费的优秀固定返现率。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'INSURANCE', '{"en": "Mobile Device Insurance", "es": "Seguro de dispositivo móvil", "fr": "Assurance appareil mobile", "ja": "モバイル端末保険", "ko": "모바일 기기 보험", "zh": "手机设备保险"}', '{"en": "Up to $1,000 coverage for theft, loss, or accidental damage of your mobile device for 2 years when purchased with this card.", "es": "Hasta $1,000 de cobertura por robo, pérdida o daño accidental de tu dispositivo móvil durante 2 años.", "fr": "Jusqu''à 1 000 $ de couverture pour vol, perte ou dommage accidentel de votre appareil mobile pendant 2 ans.", "ja": "このカードで購入したモバイル端末の盗難・紛失・偶発的損傷に対し、2年間最大$1,000の補償。", "ko": "이 카드로 구매한 모바일 기기의 도난, 분실, 우발적 손상에 대해 2년간 최대 $1,000 보장.", "zh": "用此卡购买手机可享2年保障，盗窃、丢失或意外损坏最高赔付$1,000。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'INSURANCE', '{"en": "Travel Insurance Package", "es": "Paquete de seguro de viaje", "fr": "Forfait assurance voyage", "ja": "旅行保険パッケージ", "ko": "여행 보험 패키지", "zh": "旅行保险套餐"}', '{"en": "Includes $5M emergency medical (15 days, under 65), $100K travel accident, car rental insurance up to $85K MSRP, and flight delay coverage.", "es": "Incluye $5M seguro médico de emergencia (15 días, menores de 65), $100K accidente de viaje, seguro de auto alquiler y retraso de vuelo.", "fr": "Inclut 5 M$ d''assurance médicale d''urgence (15 jours, moins de 65 ans), 100 K$ accident voyage, assurance auto location et retard de vol.", "ja": "緊急医療$500万（15日間、65歳未満）、旅行傷害$10万、レンタカー保険、フライト遅延補償を含む。", "ko": "긴급 의료 $500만 (15일, 65세 미만), 여행 상해 $10만, 렌터카 보험, 항공편 지연 보장 포함.", "zh": "包含$500万紧急医疗险（15天内，65岁以下）、$10万旅行意外险、最高$8.5万租车险和航班延误保障。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'INSURANCE', '{"en": "Purchase & Warranty Protection", "es": "Protección de compra y garantía", "fr": "Protection achat et garantie", "ja": "購入・保証保護", "ko": "구매 및 보증 보호", "zh": "购物和保修保障"}', '{"en": "90-day purchase protection (up to $1,000/occurrence) for theft or damage, plus extended warranty adds 1 extra year (up to $10,000/item).", "es": "Protección de compra 90 días (hasta $1,000/evento), más garantía extendida de 1 año (hasta $10,000/artículo).", "fr": "Protection achat 90 jours (jusqu''à 1 000 $/événement), plus garantie prolongée d''1 an (jusqu''à 10 000 $/article).", "ja": "90日間の購入保護（$1,000/件まで）、盗難・損傷対応、延長保証で1年追加（$10,000/品まで）。", "ko": "90일 구매 보호 (사건당 최대 $1,000) 도난/손상 대비, 연장 보증 1년 추가 (품목당 최대 $10,000).", "zh": "90天购物保障（每次最高$1,000）防盗窃或损坏，延长保修增加1年（每件最高$10,000）。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'PERK', '{"en": "$50 Month 13 Credit", "es": "$50 crédito mes 13", "fr": "50 $ crédit mois 13", "ja": "13ヶ月目$50クレジット", "ko": "13개월차 $50 크레딧", "zh": "第13个月$50抵扣"}', '{"en": "Make any purchase in month 13 to receive a $50 statement credit. Helps offset the $119.88 annual fee.", "es": "Haz una compra en el mes 13 para recibir $50 de crédito. Ayuda a compensar la cuota de $119.88.", "fr": "Faites un achat au mois 13 pour recevoir 50 $ de crédit. Aide à compenser les frais de 119,88 $.", "ja": "13ヶ月目に購入すると$50のステートメントクレジット。$119.88の年会費相殺に。", "ko": "13개월차에 구매하면 $50 명세서 크레딧. $119.88 연회비 상쇄에 도움.", "zh": "第13个月消费可获$50账单抵扣。帮助抵消$119.88年费。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'AMEX' AND name = 'SimplyCash Preferred'), 'STACKING', '{"en": "Best Cashback Combo", "es": "Mejor combo cashback", "fr": "Meilleure combo cashback", "ja": "最高のキャッシュバック組み合わせ", "ko": "최고의 캐시백 조합", "zh": "最佳返现组合"}', '{"en": "Use SimplyCash Preferred for gas/grocery (4%) + dining cards for restaurants. Best pure cashback setup for Canadian families.", "es": "Usa SimplyCash Preferred para gasolina/supermercado (4%) + tarjetas de comida. Mejor setup cashback para familias canadienses.", "fr": "Utilisez SimplyCash Preferred pour essence/épicerie (4 %) + cartes restaurant. Meilleur setup cashback pour familles canadiennes.", "ja": "SimplyCash Preferredはガソリン/食料品に（4%）+ 外食カードはレストランに。カナダの家族に最適なキャッシュバック構成。", "ko": "SimplyCash Preferred는 주유/식료품 (4%) + 다이닝 카드는 레스토랑에. 캐나다 가정에 최적의 캐시백 조합.", "zh": "SimplyCash Preferred用于加油/超市（4%）+ 餐饮卡用于餐厅。加拿大家庭最佳纯返现组合。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'AVOID', '{"en": "Non-Partner Gas Stations", "es": "Gasolineras no asociadas", "fr": "Stations non-partenaires", "ja": "非提携ガソリンスタンド", "ko": "비제휴 주유소", "zh": "非合作加油站"}', '{"en": "Only Shell earns 3x. Other gas stations like Petro-Canada, Esso earn base rate only (1x). Use Shell for fuel.", "es": "Solo Shell gana 3x. Petro-Canada, Esso = tasa base (1x). Usa Shell.", "fr": "Seul Shell donne 3x. Petro-Canada, Esso = taux de base (1x). Utilisez Shell.", "ja": "Shellのみ3倍。Petro-Canada、Essoは基本レート（1倍）。給油はShellで。", "ko": "Shell만 3배. Petro-Canada, Esso는 기본 적립(1배). 주유는 Shell에서.", "zh": "只有Shell可获3倍积分。Petro-Canada、Esso等其他加油站只有基础倍率（1倍）。加油请去Shell。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'AVOID', '{"en": "Foreign Transaction Fee", "es": "Cargo transacción extranjera", "fr": "Frais transaction étrangère", "ja": "海外取引手数料", "ko": "해외 거래 수수료", "zh": "外币交易费"}', '{"en": "2.5% foreign transaction fee applies. For international travel, consider using a no-FX fee card like Scotiabank Passport Visa.", "es": "2.5% de cargo por transacciones extranjeras. Para viajes, usa una tarjeta sin cargo FX como Scotiabank Passport.", "fr": "Frais de 2,5 % sur transactions étrangères. Pour voyages, utilisez une carte sans frais comme Scotiabank Passport.", "ja": "海外取引に2.5%の手数料。海外旅行にはScotiabank Passport Visaなど外貨手数料無料カードを。", "ko": "해외 거래 2.5% 수수료. 해외여행 시 Scotiabank Passport Visa 같은 FX 무료 카드 사용 권장.", "zh": "海外交易收取2.5%手续费。国际旅行建议使用无外汇费卡如Scotiabank Passport Visa。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'BEST_USE', '{"en": "Shell Gas 3x", "es": "Shell gasolina 3x", "fr": "Shell essence 3x", "ja": "Shellガソリン3倍", "ko": "Shell 주유 3배", "zh": "Shell加油3倍"}', '{"en": "Earn 3 miles per $12 at Shell and other AIR MILES partners. Plus get 7¢/L off V-Power and 2¢/L off regular fuel at Shell.", "es": "Gana 3 millas por $12 en Shell y socios AIR MILES. Además 7¢/L en V-Power y 2¢/L en combustible regular.", "fr": "Gagnez 3 milles par 12 $ chez Shell et partenaires AIR MILES. Plus 7¢/L sur V-Power et 2¢/L sur carburant régulier.", "ja": "ShellなどのAIR MILESパートナーで$12ごとに3マイル。V-Powerは7¢/L、通常燃料は2¢/Lの割引も。", "ko": "Shell 및 AIR MILES 파트너에서 $12당 3마일. V-Power 리터당 7¢, 일반 연료 2¢ 할인.", "zh": "在Shell等AIR MILES合作伙伴每消费$12获3积分。还可在Shell享V-Power每升优惠7分、普通油品优惠2分。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'BEST_USE', '{"en": "Grocery & Costco 2x", "es": "Supermercado & Costco 2x", "fr": "Épicerie & Costco 2x", "ja": "食料品・Costco 2倍", "ko": "식료품 & Costco 2배", "zh": "超市/Costco 2倍"}', '{"en": "Earn 2 miles per $12 at grocery stores, wholesale clubs (Costco), and liquor retailers. Works at Costco where Amex is not accepted.", "es": "Gana 2 millas por $12 en supermercados, clubes mayoristas (Costco) y licorerías. Funciona en Costco donde Amex no es aceptada.", "fr": "Gagnez 2 milles par 12 $ à l''épicerie, clubs entrepôts (Costco) et SAQ. Fonctionne chez Costco où Amex n''est pas accepté.", "ja": "食料品店、倉庫店（Costco）、酒類店で$12ごとに2マイル。Amexが使えないCostcoでも利用可能。", "ko": "식료품점, 창고형매장(Costco), 주류 판매점에서 $12당 2마일. Amex가 안 되는 Costco에서 사용 가능.", "zh": "超市、仓储店（Costco）和酒类零售店每消费$12获2积分。在Costco使用（Amex不被接受的地方）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'INSURANCE', '{"en": "Travel Medical $5M", "es": "Seguro médico viaje $5M", "fr": "Assurance médicale voyage 5 M$", "ja": "旅行医療$500万", "ko": "여행 의료 $500만", "zh": "旅行医疗险$500万"}', '{"en": "Up to $5 million emergency medical coverage for trips up to 15 days outside your province. Purchase travel tickets with this card.", "es": "Hasta $5M de cobertura médica de emergencia para viajes de hasta 15 días fuera de tu provincia.", "fr": "Jusqu''à 5 M$ de couverture médicale d''urgence pour voyages jusqu''à 15 jours hors province. Payez vos billets avec cette carte.", "ja": "州外旅行15日間まで最大$500万の緊急医療補償。このカードで航空券を購入すること。", "ko": "지방 외 여행 최대 15일간 $500만 긴급 의료 보장. 이 카드로 항공권 구매 시 적용.", "zh": "省外旅行最多15天可享最高$500万紧急医疗保障。用此卡购买机票即可生效。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'INSURANCE', '{"en": "Trip & Rental Car Coverage", "es": "Seguro viaje y auto alquiler", "fr": "Assurance voyage et auto", "ja": "旅行・レンタカー保険", "ko": "여행 및 렌터카 보험", "zh": "行程和租车保险"}', '{"en": "Includes trip cancellation/interruption, flight/baggage delay, hotel burglary, and rental car collision damage waiver coverage.", "es": "Incluye cancelación/interrupción de viaje, retraso vuelo/equipaje, robo hotel y seguro colisión auto alquiler.", "fr": "Inclut annulation/interruption de voyage, retard vol/bagages, vol hôtel et assurance collision auto location.", "ja": "旅行キャンセル/中断、フライト/手荷物遅延、ホテル盗難、レンタカー衝突損害免除を含む。", "ko": "여행 취소/중단, 항공편/수하물 지연, 호텔 도난, 렌터카 충돌 손해 면책 포함.", "zh": "包含行程取消/中断、航班/行李延误、酒店盗窃和租车碰撞损失免责保险。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'PERK', '{"en": "Instacart+ Membership", "es": "Membresía Instacart+", "fr": "Adhésion Instacart+", "ja": "Instacart+会員", "ko": "Instacart+ 멤버십", "zh": "Instacart+会员"}', '{"en": "Get 6 months free Instacart+ membership plus $10/month Instacart credit when you sign up with your BMO card.", "es": "Obtén 6 meses de Instacart+ gratis más $10/mes de crédito Instacart al registrarte con tu tarjeta BMO.", "fr": "Obtenez 6 mois d''Instacart+ gratuit plus 10 $/mois de crédit Instacart en vous inscrivant avec votre carte BMO.", "ja": "BMOカードで登録すると6ヶ月のInstacart+無料会員と月$10のInstacartクレジット。", "ko": "BMO 카드로 가입 시 6개월 무료 Instacart+ 멤버십과 월 $10 Instacart 크레딧.", "zh": "用BMO卡注册可获6个月免费Instacart+会员，每月$10 Instacart抵扣。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'PERK', '{"en": "Car Rental Discounts", "es": "Descuentos alquiler auto", "fr": "Rabais location auto", "ja": "レンタカー割引", "ko": "렌터카 할인", "zh": "租车优惠"}', '{"en": "Preferential rates at National Car Rental and Alamo Rent A Car. Access to over 1 million Wi-Fi hotspots globally.", "es": "Tarifas preferenciales en National y Alamo. Acceso a más de 1 millón de hotspots Wi-Fi globalmente.", "fr": "Tarifs préférentiels chez National et Alamo. Accès à plus d''1 million de hotspots Wi-Fi dans le monde.", "ja": "National Car RentalとAlamoで優待料金。世界100万以上のWi-Fiホットスポットにアクセス。", "ko": "National Car Rental과 Alamo에서 우대 요금. 전 세계 100만+ Wi-Fi 핫스팟 이용.", "zh": "National Car Rental和Alamo Rent A Car优惠价。全球超过100万Wi-Fi热点接入。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'REDEMPTION', '{"en": "25% Flight Discount", "es": "25% descuento vuelo", "fr": "25 % rabais vol", "ja": "フライト25%割引", "ko": "항공권 25% 할인", "zh": "机票兑换75折"}', '{"en": "Get 25% off one AIR MILES Dream reward flight per year. Best value when redeeming for flights instead of merchandise.", "es": "Obtén 25% de descuento en un vuelo Dream AIR MILES por año. Mejor valor para vuelos que para mercancía.", "fr": "Obtenez 25 % de rabais sur un vol Dream AIR MILES par an. Meilleure valeur pour les vols plutôt que la marchandise.", "ja": "年1回のAIR MILES Dreamリワードフライトが25%オフ。商品より航空券の方がお得。", "ko": "연 1회 AIR MILES Dream 리워드 항공권 25% 할인. 상품보다 항공권 교환이 더 가치 있음.", "zh": "每年一次AIR MILES Dream机票兑换可享75折。兑换机票比商品更划算。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'REDEMPTION', '{"en": "Cash vs Dream Miles", "es": "Cash vs Dream Millas", "fr": "Cash vs Dream Milles", "ja": "Cash vs Dreamマイル", "ko": "Cash vs Dream 마일", "zh": "Cash vs Dream积分选择"}', '{"en": "Choose Dream Miles for flights (best value with 25% discount). Cash Miles work like cashback at 95 miles = $10 at participating stores.", "es": "Elige Dream Miles para vuelos (mejor valor con 25%). Cash Miles = 95 millas = $10 en tiendas participantes.", "fr": "Choisissez Dream Miles pour vols (meilleure valeur avec 25 %). Cash Miles = remise 95 milles = 10 $ en magasin.", "ja": "フライトはDream Miles（25%割引で最高価値）。Cash Milesは95マイル=$10で現金同様に使用可能。", "ko": "항공권은 Dream Miles (25% 할인으로 최고 가치). Cash Miles는 95마일=$10로 현금처럼 사용.", "zh": "机票选Dream Miles（享25%折扣最划算）。Cash Miles像返现，95积分=$10可在合作店使用。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'STACKING', '{"en": "AIR MILES Ecosystem", "es": "Ecosistema AIR MILES", "fr": "Écosystème AIR MILES", "ja": "AIR MILESエコシステム", "ko": "AIR MILES 생태계", "zh": "AIR MILES生态系统"}', '{"en": "Stack miles by using AIR MILES collector card at partners + this credit card. Double-dip at Shell, Sobeys, Metro, Safeway, and more.", "es": "Acumula millas usando la tarjeta colector + esta tarjeta. Doble ganancia en Shell, Sobeys, Metro, Safeway.", "fr": "Cumulez les milles avec la carte collecteur + cette carte crédit. Double gain chez Shell, Sobeys, Metro, Safeway.", "ja": "AIR MILESコレクターカードとこのカードを併用でマイル二重取り。Shell、Sobeys、Metro、Safewayで。", "ko": "AIR MILES 수집 카드와 이 카드 동시 사용으로 마일 적립. Shell, Sobeys, Metro, Safeway에서 이중 적립.", "zh": "在合作伙伴处同时使用AIR MILES会员卡和此信用卡叠加积分。Shell、Sobeys、Metro、Safeway等可双重积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'TRAVEL_BENEFIT', '{"en": "DragonPass Lounge Access", "es": "Acceso lounge DragonPass", "fr": "Accès salon DragonPass", "ja": "DragonPassラウンジ", "ko": "DragonPass 라운지", "zh": "DragonPass贵宾厅"}', '{"en": "Free Mastercard Travel Pass (DragonPass) membership. Access airport lounges worldwide for US$32 per visit.", "es": "Membresía gratis Mastercard Travel Pass (DragonPass). Acceso a lounges por US$32 por visita.", "fr": "Adhésion gratuite Mastercard Travel Pass (DragonPass). Accès aux salons d''aéroport pour 32 $ US/visite.", "ja": "Mastercard Travel Pass（DragonPass）会員資格無料。世界の空港ラウンジがUS$32/回で利用可能。", "ko": "Mastercard Travel Pass (DragonPass) 무료 회원. 전 세계 공항 라운지 US$32/회 이용.", "zh": "免费Mastercard Travel Pass（DragonPass）会员。全球机场贵宾厅每次US$32。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Air Miles World Elite Mastercard'), 'TRAVEL_BENEFIT', '{"en": "Automatic Onyx Status", "es": "Estatus Onyx automático", "fr": "Statut Onyx automatique", "ja": "自動Onyxステータス", "ko": "자동 Onyx 자격", "zh": "自动Onyx身份"}', '{"en": "Get AIR MILES Onyx status automatically. Enjoy exclusive benefits like bonus miles offers and priority customer service.", "es": "Obtén estatus Onyx AIR MILES automáticamente. Disfruta ofertas de millas bonus y servicio prioritario.", "fr": "Obtenez automatiquement le statut Onyx AIR MILES. Profitez d''offres de milles bonus et service prioritaire.", "ja": "AIR MILES Onyxステータスを自動取得。ボーナスマイルオファーや優先カスタマーサービスなどの特典。", "ko": "AIR MILES Onyx 자격 자동 부여. 보너스 마일 오퍼와 우선 고객 서비스 등 혜택.", "zh": "自动获得AIR MILES Onyx身份。享受专属福利如额外积分优惠和优先客服。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'AVOID', '{"en": "Foreign Transaction Fee", "es": "Cargo transacción extranjera", "fr": "Frais transaction étrangère", "ja": "海外取引手数料", "ko": "해외 거래 수수료", "zh": "外币交易费"}', '{"en": "2.5% foreign transaction fee applies. For international purchases, use a no-FX fee card like Scotiabank Passport Visa.", "es": "2.5% de cargo por transacciones extranjeras. Para compras internacionales, usa una tarjeta sin cargo FX.", "fr": "Frais de 2,5 % sur transactions étrangères. Pour achats internationaux, utilisez une carte sans frais FX.", "ja": "海外取引に2.5%の手数料。海外購入にはScotiabank Passport Visaなど外貨手数料無料カードを。", "ko": "해외 거래 2.5% 수수료. 해외 구매 시 FX 무료 카드 사용 권장.", "zh": "海外交易收取2.5%手续费。国际消费建议使用无外汇费卡如Scotiabank Passport Visa。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'AVOID', '{"en": "Category Spending Caps", "es": "Límites por categoría", "fr": "Plafonds par catégorie", "ja": "カテゴリ上限", "ko": "카테고리 한도", "zh": "类别消费上限"}', '{"en": "Travel 5x capped at $15,000/year; Dining/Entertainment/Recurring 3x capped at $10,000/category/year. Track spending to avoid caps.", "es": "Viaje 5x limitado a $15,000/año; comida/entretenimiento/recurrente 3x limitado a $10,000/categoría/año.", "fr": "Voyage 5x plafonné à 15 000 $/an ; resto/divertissement/récurrent 3x plafonné à 10 000 $/catégorie/an.", "ja": "旅行5倍は年間$15,000まで；飲食/エンタメ/固定費3倍は各カテゴリ年$10,000まで。上限に注意。", "ko": "여행 5배는 연간 $15,000까지; 식당/엔터/고정비 3배는 각 카테고리 연 $10,000까지. 한도 주의.", "zh": "旅行5倍上限$15,000/年；餐饮/娱乐/固定账单3倍上限各$10,000/年。跟踪消费避免超限。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'BEST_USE', '{"en": "Travel 5x Points", "es": "Viaje 5x puntos", "fr": "Voyage 5x points", "ja": "旅行5倍ポイント", "ko": "여행 5배 포인트", "zh": "旅行5倍积分"}', '{"en": "Earn 5x BMO Rewards points on travel purchases up to $15,000/year. Book flights, hotels, car rentals, and cruises to maximize earnings.", "es": "Gana 5x puntos BMO Rewards en viajes hasta $15,000/año. Reserva vuelos, hoteles, autos y cruceros.", "fr": "Gagnez 5x points BMO Rewards sur les voyages jusqu''à 15 000 $/an. Réservez vols, hôtels, locations et croisières.", "ja": "旅行購入で5倍BMO Rewardsポイント（年間$15,000まで）。航空券、ホテル、レンタカー、クルーズの予約に。", "ko": "여행 구매 시 5배 BMO Rewards 포인트 (연간 $15,000까지). 항공권, 호텔, 렌터카, 크루즈 예약 시.", "zh": "旅行消费每年最高$15,000可获5倍BMO Rewards积分。预订机票、酒店、租车和邮轮最大化收益。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'BEST_USE', '{"en": "Dining & Entertainment 3x", "es": "Restaurante & Entretenimiento 3x", "fr": "Restaurant & Divertissement 3x", "ja": "飲食・エンタメ3倍", "ko": "식당 & 엔터테인먼트 3배", "zh": "餐饮娱乐3倍"}', '{"en": "Earn 3x points on dining, entertainment, and recurring bills (up to $10,000/category/year). Works at Costco unlike Amex cards.", "es": "Gana 3x puntos en comida, entretenimiento y facturas recurrentes ($10,000/categoría/año). Funciona en Costco.", "fr": "Gagnez 3x points sur resto, divertissement et factures récurrentes (10 000 $/catégorie/an). Fonctionne chez Costco.", "ja": "飲食、エンタメ、固定費で3倍ポイント（カテゴリ毎年$10,000まで）。AmexがだめなCostcoでも利用可能。", "ko": "식당, 엔터테인먼트, 고정 청구서 3배 포인트 (카테고리당 연 $10,000). Costco에서도 사용 가능 (Amex 불가).", "zh": "餐饮、娱乐和固定账单消费获3倍积分（每类别年度上限$10,000）。在Costco可用（Amex不行）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'INSURANCE', '{"en": "Travel Medical $5M", "es": "Seguro médico viaje $5M", "fr": "Assurance médicale voyage 5 M$", "ja": "旅行医療$500万", "ko": "여행 의료 $500만", "zh": "旅行医疗险$500万"}', '{"en": "Up to $5 million emergency medical coverage for trips up to 21 days (age 64 and under). Book travel with this card to activate.", "es": "Hasta $5M de cobertura médica de emergencia para viajes hasta 21 días (64 años o menos). Paga el viaje con esta tarjeta.", "fr": "Jusqu''à 5 M$ de couverture médicale d''urgence pour voyages jusqu''à 21 jours (64 ans et moins). Payez le voyage avec cette carte.", "ja": "21日間まで最大$500万の緊急医療補償（64歳以下）。このカードで旅行を予約して有効化。", "ko": "최대 21일 여행에 $500만 긴급 의료 보장 (64세 이하). 이 카드로 여행 예약 시 활성화.", "zh": "省外/国外旅行最多21天可享最高$500万紧急医疗保障（64岁及以下）。用此卡预订旅行激活。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'INSURANCE', '{"en": "Trip & Rental Car Coverage", "es": "Seguro viaje y auto alquiler", "fr": "Assurance voyage et auto", "ja": "旅行・レンタカー保険", "ko": "여행 및 렌터카 보험", "zh": "行程和租车保险"}', '{"en": "Trip cancellation ($1,500) + interruption ($2,000) + flight delay ($500) + rental car CDW up to $65,000 MSRP for 48 days.", "es": "Cancelación viaje ($1,500) + interrupción ($2,000) + retraso vuelo ($500) + CDW auto hasta $65,000 MSRP por 48 días.", "fr": "Annulation voyage (1 500 $) + interruption (2 000 $) + retard vol (500 $) + CDW location auto jusqu''à 65 000 $ PDSF pour 48 jours.", "ja": "旅行キャンセル（$1,500）+ 中断（$2,000）+ フライト遅延（$500）+ レンタカーCDW（MSRP $65,000まで、48日間）。", "ko": "여행 취소 ($1,500) + 중단 ($2,000) + 항공편 지연 ($500) + 렌터카 CDW ($65,000 MSRP까지, 48일).", "zh": "行程取消（$1,500）+ 中断（$2,000）+ 航班延误（$500）+ 租车CDW（MSRP $65,000以内，48天）。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'PERK', '{"en": "Fee Rebate with BMO Premium", "es": "Reembolso con BMO Premium", "fr": "Remboursement avec BMO Premium", "ja": "BMO Premiumで年会費リベート", "ko": "BMO Premium으로 연회비 환급", "zh": "BMO Premium账户免年费"}', '{"en": "Get the $150 annual fee rebated every year by holding a BMO Premium Chequing Account. Effectively makes the card free.", "es": "Obtén el reembolso de los $150 anuales con una cuenta BMO Premium Chequing. La tarjeta es efectivamente gratis.", "fr": "Obtenez le remboursement des frais annuels de 150 $ avec un compte BMO Premium. La carte devient gratuite.", "ja": "BMO Premium Chequing Accountで年会費$150が毎年リベート。実質無料のカードに。", "ko": "BMO Premium Chequing Account로 연회비 $150 매년 환급. 사실상 무료 카드.", "zh": "持有BMO Premium Chequing Account可每年返还$150年费。实际上让这张卡免费。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'PERK', '{"en": "Instacart+ Membership", "es": "Membresía Instacart+", "fr": "Adhésion Instacart+", "ja": "Instacart+会員", "ko": "Instacart+ 멤버십", "zh": "Instacart+会员"}', '{"en": "Get 6 months free Instacart+ membership plus $10/month Instacart credit. Enroll your card to activate this benefit.", "es": "Obtén 6 meses de Instacart+ gratis más $10/mes de crédito Instacart. Registra tu tarjeta para activar.", "fr": "Obtenez 6 mois d''Instacart+ gratuit plus 10 $/mois de crédit Instacart. Inscrivez votre carte pour activer.", "ja": "6ヶ月のInstacart+無料会員と月$10のInstacartクレジット。カードを登録して有効化。", "ko": "6개월 무료 Instacart+ 멤버십과 월 $10 Instacart 크레딧. 카드 등록으로 활성화.", "zh": "获得6个月免费Instacart+会员，每月$10 Instacart抵扣。注册您的卡以激活此福利。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'REDEMPTION', '{"en": "BMO Travel Portal", "es": "Portal de viaje BMO", "fr": "Portail voyage BMO", "ja": "BMOトラベルポータル", "ko": "BMO 여행 포털", "zh": "BMO旅行门户"}', '{"en": "Redeem 150 pts = $1 for travel via BMO Rewards portal (0.67cpp). No blackout dates on airline redemptions.", "es": "Canjea 150 pts = $1 en viajes via portal BMO (0.67cpp). Sin fechas bloqueadas en vuelos.", "fr": "Échangez 150 pts = 1 $ pour voyages via le portail BMO (0,67 ¢/pt). Aucune date bloquée pour vols.", "ja": "BMOポータルで150ポイント=$1で旅行に交換（0.67cpp）。航空券に日付制限なし。", "ko": "BMO 포털에서 150포인트=$1로 여행 교환 (0.67cpp). 항공권 교환 시 블랙아웃 날짜 없음.", "zh": "在BMO Rewards门户兑换旅行：150积分=$1（0.67分/点）。航空兑换无日期限制。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'STACKING', '{"en": "Maximize First Year", "es": "Maximizar primer año", "fr": "Maximiser la 1re année", "ja": "初年度を最大化", "ko": "첫해 최대화", "zh": "最大化首年价值"}', '{"en": "Stack first year benefits: waived $150 fee + up to 100K bonus points + NEXUS credit + Instacart perks = $1,600+ value.", "es": "Acumula beneficios del primer año: $150 exento + 100K pts bonus + NEXUS + Instacart = $1,600+ en valor.", "fr": "Cumulez les avantages 1re année : 150 $ remis + 100K pts bonus + crédit NEXUS + Instacart = 1 600 $+ de valeur.", "ja": "初年度特典を重ねる：$150免除 + 最大10万ボーナス + NEXUSクレジット + Instacart = $1,600+の価値。", "ko": "첫해 혜택 중첩: $150 면제 + 최대 10만 보너스 + NEXUS 크레딧 + Instacart = $1,600+ 가치.", "zh": "叠加首年福利：免$150年费 + 最高10万积分 + NEXUS抵扣 + Instacart福利 = 价值超$1,600。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'TRAVEL_BENEFIT', '{"en": "4 Free Lounge Visits", "es": "4 visitas lounge gratis", "fr": "4 visites salon gratuites", "ja": "4回無料ラウンジ", "ko": "4회 무료 라운지", "zh": "4次免费贵宾厅"}', '{"en": "Get 4 complimentary airport lounge visits per year via Mastercard Travel Pass (DragonPass). Use before expensive flights.", "es": "Obtén 4 visitas gratuitas a lounges via Mastercard Travel Pass (DragonPass). Usa antes de vuelos caros.", "fr": "Obtenez 4 visites gratuites aux salons via Mastercard Travel Pass (DragonPass). Utilisez avant les vols coûteux.", "ja": "Mastercard Travel Pass（DragonPass）で年4回無料ラウンジ利用。高額フライト前に活用。", "ko": "Mastercard Travel Pass (DragonPass)로 연 4회 무료 라운지. 비싼 항공편 전에 활용.", "zh": "每年4次免费机场贵宾厅（通过Mastercard Travel Pass/DragonPass）。在贵价航班前使用。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Ascend World Elite Mastercard'), 'TRAVEL_BENEFIT', '{"en": "NEXUS Statement Credit", "es": "Crédito NEXUS", "fr": "Crédit NEXUS", "ja": "NEXUS申請費クレジット", "ko": "NEXUS 신청비 크레딧", "zh": "NEXUS申请费抵扣"}', '{"en": "Get up to $200 credit for NEXUS application fee in your first year. Speeds up US/Canada border crossings for 5 years.", "es": "Obtén hasta $200 de crédito para NEXUS el primer año. Acelera cruces fronterizos EE.UU./Canadá por 5 años.", "fr": "Obtenez jusqu''à 200 $ de crédit pour frais NEXUS la première année. Accélère les passages frontaliers pour 5 ans.", "ja": "初年度NEXUS申請費最大$200クレジット。米加国境通過が5年間スムーズに。", "ko": "첫해 NEXUS 신청비 최대 $200 크레딧. 미국/캐나다 국경 통과 5년간 신속화.", "zh": "首年可获最高$200 NEXUS申请费抵扣。加快美加边境通关，有效期5年。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'AVOID', '{"en": "Costco/Walmart Coding", "es": "Código Costco/Walmart", "fr": "Code Costco/Walmart", "ja": "Costco/Walmartコード", "ko": "Costco/Walmart 코드", "zh": "Costco/Walmart编码"}', '{"en": "Costco and Walmart may not code as grocery (warehouse/retail instead). Test with small purchase first or use at dedicated grocers.", "es": "Costco y Walmart pueden no codificar como supermercado. Prueba con compra pequeña o usa tiendas dedicadas.", "fr": "Costco et Walmart peuvent ne pas être codés épicerie. Testez avec petit achat ou utilisez épiceries dédiées.", "ja": "CostcoやWalmartは食料品としてコード化されない場合あり。小額でテストするか専門店で使用。", "ko": "Costco와 Walmart는 식료품으로 인식 안 될 수 있음. 소액 테스트 또는 전문 식료품점 사용.", "zh": "Costco和Walmart可能不被识别为超市（而是仓储/零售）。先小额测试或在专门超市使用。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'AVOID', '{"en": "Low Base Rate", "es": "Tasa base baja", "fr": "Taux de base faible", "ja": "基本還元率が低い", "ko": "기본 적립률 낮음", "zh": "基础返现较低"}', '{"en": "Only 0.5% on non-category spending. Use a flat-rate 1.5-2% card for general purchases outside grocery/bills.", "es": "Solo 0.5% fuera de categorías. Usa una tarjeta de tasa fija 1.5-2% para compras generales.", "fr": "Seulement 0,5 % hors catégories. Utilisez une carte à taux fixe 1,5-2 % pour achats généraux.", "ja": "カテゴリ外は0.5%のみ。一般購入には1.5-2%フラットレートカードを使用。", "ko": "카테고리 외 0.5%만. 일반 구매는 1.5-2% 정률 카드 사용.", "zh": "非类别消费仅0.5%。一般消费建议用1.5-2%的固定返现卡。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'BEST_USE', '{"en": "Grocery 3% Cash Back", "es": "Supermercado 3% reembolso", "fr": "Épicerie 3 % remise", "ja": "食料品3%キャッシュバック", "ko": "식료품 3% 캐시백", "zh": "超市3%返现"}', '{"en": "Earn 3% cash back on groceries up to $500/month ($15/month max). Use at dedicated grocery stores for best results.", "es": "Gana 3% en supermercados hasta $500/mes ($15/mes máx). Usa en tiendas de comestibles dedicadas.", "fr": "Gagnez 3 % sur l''épicerie jusqu''à 500 $/mois (max 15 $/mois). Utilisez dans les épiceries dédiées.", "ja": "食料品で月$500まで3%還元（月最大$15）。専門スーパーで使用が最適。", "ko": "식료품 월 $500까지 3% 캐시백 (월 최대 $15). 전문 식료품점에서 사용.", "zh": "超市消费每月最高$500享3%返现（月最高$15）。在专门的超市使用效果最佳。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'BEST_USE', '{"en": "Recurring Bills 1%", "es": "Facturas recurrentes 1%", "fr": "Factures récurrentes 1 %", "ja": "固定費1%", "ko": "고정 청구서 1%", "zh": "固定账单1%"}', '{"en": "Earn 1% on recurring bill payments up to $500/month. Set up auto-pay for phone, internet, streaming, and insurance.", "es": "Gana 1% en facturas recurrentes hasta $500/mes. Configura pago automático para teléfono, internet, streaming.", "fr": "Gagnez 1 % sur factures récurrentes jusqu''à 500 $/mois. Configurez paiement auto pour téléphone, internet, streaming.", "ja": "固定費で月$500まで1%還元。電話、インターネット、ストリーミングの自動支払いを設定。", "ko": "고정 청구서 월 $500까지 1% 캐시백. 휴대폰, 인터넷, 스트리밍 자동 결제 설정.", "zh": "固定账单每月最高$500享1%返现。设置手机、网络、流媒体和保险自动付款。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'INSURANCE', '{"en": "Extended Warranty", "es": "Garantía extendida", "fr": "Garantie prolongée", "ja": "延長保証", "ko": "연장 보증", "zh": "延长保修"}', '{"en": "Doubles manufacturer warranty up to 1 additional year. Use for electronics and appliances to extend coverage.", "es": "Duplica garantía del fabricante hasta 1 año adicional. Usa para electrónicos y electrodomésticos.", "fr": "Double la garantie fabricant jusqu''à 1 an supplémentaire. Utilisez pour électronique et électroménagers.", "ja": "メーカー保証を最大1年延長。電子機器や家電購入時に使用。", "ko": "제조사 보증 최대 1년 연장. 전자제품과 가전제품 구매 시 사용.", "zh": "制造商保修延长最多1年。购买电子产品和家电时使用以延长保障。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Coverage against accidental damage or theft within 90 days of purchase. Keep receipts for claims.", "es": "Cobertura contra daños accidentales o robo dentro de 90 días. Guarda los recibos.", "fr": "Couverture contre dommages accidentels ou vol dans les 90 jours. Conservez les reçus.", "ja": "購入後90日以内の偶発的損傷または盗難をカバー。請求用にレシートを保管。", "ko": "구매 후 90일 이내 우발적 손상 또는 도난 보장. 청구를 위해 영수증 보관.", "zh": "购买后90天内的意外损坏或盗窃保障。保留收据以便索赔。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'PERK', '{"en": "No Annual Fee", "es": "Sin cuota anual", "fr": "Aucuns frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "无年费"}', '{"en": "No annual fee and no minimum income requirement. Great starter card or everyday grocery card to keep long-term.", "es": "Sin cuota anual ni ingreso mínimo. Excelente tarjeta inicial o para supermercado diario a largo plazo.", "fr": "Aucuns frais annuels ni revenu minimum requis. Excellente carte de départ ou pour épicerie quotidienne.", "ja": "年会費無料、最低収入要件なし。入門カードや長期保有の食料品カードに最適。", "ko": "연회비 무료, 최소 소득 요건 없음. 입문 카드나 장기 보유 식료품 카드로 적합.", "zh": "无年费且无最低收入要求。适合作为入门卡或长期持有的日常超市卡。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'PERK', '{"en": "Balance Transfer 0.99%", "es": "Transferencia saldo 0.99%", "fr": "Transfert solde 0,99 %", "ja": "残高移行0.99%", "ko": "잔액 이체 0.99%", "zh": "余额转账0.99%"}', '{"en": "Transfer balances from other cards at 0.99% interest rate for 9 months. Good option to pay down high-interest debt.", "es": "Transfiere saldos al 0.99% por 9 meses. Buena opción para pagar deudas de alto interés.", "fr": "Transférez des soldes à 0,99 % pendant 9 mois. Bonne option pour rembourser les dettes à taux élevé.", "ja": "他カードから0.99%で9ヶ月残高移行可能。高金利債務返済に良いオプション。", "ko": "다른 카드에서 0.99% 이자로 9개월 잔액 이체. 고금리 부채 상환에 좋은 옵션.", "zh": "从其他卡转移余额，9个月内享0.99%利率。偿还高息债务的好选择。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack Mastercard'), 'STACKING', '{"en": "Pair with Premium Card", "es": "Combinar con tarjeta premium", "fr": "Combiner avec carte premium", "ja": "プレミアムカードと併用", "ko": "프리미엄 카드와 함께 사용", "zh": "搭配高端卡"}', '{"en": "Use this for grocery 3% and pair with a travel/dining card for other categories. Keep this card long-term for credit history.", "es": "Usa para supermercado 3% y combina con tarjeta de viaje/comida. Mantén a largo plazo para historial crediticio.", "fr": "Utilisez pour épicerie 3 % et combinez avec carte voyage/resto. Gardez à long terme pour historique de crédit.", "ja": "食料品3%に使い、旅行/飲食カードと併用。クレジット履歴のため長期保有。", "ko": "식료품 3%에 사용하고 여행/식당 카드와 병행. 신용 기록을 위해 장기 보유.", "zh": "用此卡享超市3%，搭配旅行/餐饮卡用于其他类别。长期持有此卡有助于信用记录。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'AVOID', '{"en": "Foreign Transaction Fee", "es": "Cargo transacción extranjera", "fr": "Frais transaction étrangère", "ja": "海外取引手数料", "ko": "해외 거래 수수료", "zh": "外币交易费"}', '{"en": "2.5% foreign transaction fee applies. For international purchases, use a no-FX fee card like Scotiabank Passport.", "es": "2.5% de cargo por transacciones extranjeras. Para compras internacionales, usa tarjeta sin cargo FX.", "fr": "Frais de 2,5 % sur transactions étrangères. Pour achats internationaux, utilisez une carte sans frais FX.", "ja": "海外取引に2.5%の手数料。海外購入には外貨手数料無料カードを使用。", "ko": "해외 거래 2.5% 수수료. 해외 구매 시 FX 무료 카드 사용 권장.", "zh": "海外交易收取2.5%手续费。国际消费建议使用无外汇费卡如Scotiabank Passport。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'AVOID', '{"en": "Monthly Spending Caps", "es": "Límites mensuales", "fr": "Plafonds mensuels", "ja": "月間上限", "ko": "월 한도", "zh": "月消费上限"}', '{"en": "Grocery $500, transit $300, gas $300, recurring $500 per month. Track spending to maximize and avoid exceeding caps.", "es": "Supermercado $500, transporte $300, gas $300, recurrente $500 por mes. Rastrea gastos.", "fr": "Épicerie 500 $, transport 300 $, essence 300 $, récurrent 500 $ par mois. Suivez les dépenses.", "ja": "食料品$500、交通$300、ガソリン$300、固定費$500が月上限。支出を追跡して最大化。", "ko": "식료품 $500, 대중교통 $300, 주유 $300, 고정비 $500 월 한도. 지출 추적으로 최대화.", "zh": "超市$500、公交$300、加油$300、固定账单$500月上限。跟踪消费以最大化收益。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'BEST_USE', '{"en": "Grocery 5% Cash Back", "es": "Supermercado 5% reembolso", "fr": "Épicerie 5 % remise", "ja": "食料品5%キャッシュバック", "ko": "식료품 5% 캐시백", "zh": "超市5%返现"}', '{"en": "Earn 5% cash back on groceries up to $500/month ($25/month max). Best grocery rate among no-FX-fee cards.", "es": "Gana 5% en supermercados hasta $500/mes ($25/mes máx). Mejor tasa de supermercado entre tarjetas sin cargo FX.", "fr": "Gagnez 5 % sur l''épicerie jusqu''à 500 $/mois (max 25 $/mois). Meilleur taux épicerie parmi cartes sans frais FX.", "ja": "食料品で月$500まで5%還元（月最大$25）。FX手数料無料カード中最高の食料品還元率。", "ko": "식료품 월 $500까지 5% 캐시백 (월 최대 $25). FX 무료 카드 중 최고 식료품 적립률.", "zh": "超市消费每月最高$500享5%返现（月最高$25）。无外汇费卡中最高的超市返现率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'BEST_USE', '{"en": "Transit 4% Cash Back", "es": "Transporte 4% reembolso", "fr": "Transport 4 % remise", "ja": "交通4%キャッシュバック", "ko": "대중교통 4% 캐시백", "zh": "公交4%返现"}', '{"en": "Earn 4% on transit up to $300/month ($12/month max). Includes TTC, GO Transit, Uber, Lyft, and ride-sharing.", "es": "Gana 4% en transporte hasta $300/mes ($12/mes máx). Incluye TTC, GO Transit, Uber, Lyft.", "fr": "Gagnez 4 % sur transport jusqu''à 300 $/mois (max 12 $/mois). Inclut TTC, GO Transit, Uber, Lyft.", "ja": "交通で月$300まで4%還元（月最大$12）。TTC、GO Transit、Uber、Lyft含む。", "ko": "대중교통 월 $300까지 4% 캐시백 (월 최대 $12). TTC, GO Transit, Uber, Lyft 포함.", "zh": "公交消费每月最高$300享4%返现（月最高$12）。包括TTC、GO Transit、Uber、Lyft等。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'BEST_USE', '{"en": "Gas & EV Charging 3%", "es": "Gasolina & Carga EV 3%", "fr": "Essence & Recharge VÉ 3 %", "ja": "ガソリン・EV充電3%", "ko": "주유 & EV 충전 3%", "zh": "加油和电动车充电3%"}', '{"en": "Earn 3% on gas and EV charging up to $300/month ($9/month max). Works at all gas stations and charging networks.", "es": "Gana 3% en gasolina y carga EV hasta $300/mes ($9/mes máx). Funciona en todas las gasolineras y redes de carga.", "fr": "Gagnez 3 % sur essence et recharge VÉ jusqu''à 300 $/mois (max 9 $/mois). Fonctionne partout.", "ja": "ガソリンとEV充電で月$300まで3%還元（月最大$9）。全ガソリンスタンドと充電網で利用可。", "ko": "주유와 EV 충전 월 $300까지 3% 캐시백 (월 최대 $9). 모든 주유소와 충전 네트워크 적용.", "zh": "加油和电动车充电每月最高$300享3%返现（月最高$9）。适用于所有加油站和充电网络。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'BEST_USE', '{"en": "Recurring Bills 2%", "es": "Facturas recurrentes 2%", "fr": "Factures récurrentes 2 %", "ja": "固定費2%", "ko": "고정 청구서 2%", "zh": "固定账单2%"}', '{"en": "Earn 2% on recurring bills up to $500/month ($10/month max). Set up phone, internet, streaming, insurance auto-pay.", "es": "Gana 2% en facturas recurrentes hasta $500/mes ($10/mes máx). Configura pago automático.", "fr": "Gagnez 2 % sur factures récurrentes jusqu''à 500 $/mois (max 10 $/mois). Configurez paiement auto.", "ja": "固定費で月$500まで2%還元（月最大$10）。電話、ネット、ストリーミング、保険の自動支払い設定。", "ko": "고정 청구서 월 $500까지 2% 캐시백 (월 최대 $10). 휴대폰, 인터넷, 스트리밍, 보험 자동 결제 설정.", "zh": "固定账单每月最高$500享2%返现（月最高$10）。设置手机、网络、流媒体、保险自动扣款。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'INSURANCE', '{"en": "Rental Car CDW Coverage", "es": "Seguro colisión alquiler", "fr": "Assurance collision location", "ja": "レンタカーCDW", "ko": "렌터카 CDW", "zh": "租车碰撞险"}', '{"en": "Collision damage waiver for rental cars up to $65,000 MSRP for 48 days. Decline the rental company CDW to save money.", "es": "Seguro colisión para autos hasta $65,000 MSRP por 48 días. Rechaza el CDW de la empresa para ahorrar.", "fr": "Assurance collision pour location jusqu''à 65 000 $ PDSF pour 48 jours. Refusez CDW du loueur pour économiser.", "ja": "MSRP $65,000までのレンタカーCDW（48日間）。レンタル会社のCDWを断って節約。", "ko": "MSRP $65,000까지 렌터카 CDW (48일). 렌터카 회사 CDW 거절해서 비용 절감.", "zh": "租车碰撞损失免责（MSRP $65,000以内，48天）。拒绝租车公司CDW以省钱。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'INSURANCE', '{"en": "Travel Medical $5M", "es": "Seguro médico viaje $5M", "fr": "Assurance médicale voyage 5 M$", "ja": "旅行医療$500万", "ko": "여행 의료 $500만", "zh": "旅行医疗险$500万"}', '{"en": "Up to $5 million emergency medical coverage for trips up to 21 days. Book travel with this card to activate coverage.", "es": "Hasta $5M de cobertura médica de emergencia para viajes hasta 21 días. Paga el viaje con esta tarjeta.", "fr": "Jusqu''à 5 M$ de couverture médicale d''urgence pour voyages jusqu''à 21 jours. Payez le voyage avec cette carte.", "ja": "21日間まで最大$500万の緊急医療補償。このカードで旅行を予約して有効化。", "ko": "최대 21일 여행에 $500만 긴급 의료 보장. 이 카드로 여행 예약 시 활성화.", "zh": "最多21天旅行可享最高$500万紧急医疗保障。用此卡预订旅行以激活保障。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'PERK', '{"en": "Instacart+ Membership", "es": "Membresía Instacart+", "fr": "Adhésion Instacart+", "ja": "Instacart+会員", "ko": "Instacart+ 멤버십", "zh": "Instacart+会员"}', '{"en": "Get 6 months free Instacart+ membership plus $10/month Instacart credit. Enroll your card to activate.", "es": "Obtén 6 meses de Instacart+ gratis más $10/mes de crédito Instacart. Registra tu tarjeta.", "fr": "Obtenez 6 mois d''Instacart+ gratuit plus 10 $/mois de crédit Instacart. Inscrivez votre carte.", "ja": "6ヶ月のInstacart+無料会員と月$10のInstacartクレジット。カードを登録して有効化。", "ko": "6개월 무료 Instacart+ 멤버십과 월 $10 Instacart 크레딧. 카드 등록으로 활성화.", "zh": "获得6个月免费Instacart+会员，每月$10 Instacart抵扣。注册您的卡以激活。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'STACKING', '{"en": "Maximize Welcome Bonus", "es": "Maximizar bono bienvenida", "fr": "Maximiser bonus bienvenue", "ja": "入会ボーナス最大化", "ko": "가입 보너스 최대화", "zh": "最大化开卡奖励"}', '{"en": "Spend $2,000/month for 12 months to earn $40/month ($480 total). Combine with category bonuses for max $56/month return.", "es": "Gasta $2,000/mes por 12 meses para ganar $40/mes ($480 total). Combina con bonos de categoría.", "fr": "Dépensez 2 000 $/mois pendant 12 mois pour 40 $/mois (480 $ total). Combinez avec bonus catégorie.", "ja": "12ヶ月間毎月$2,000利用で月$40（合計$480）。カテゴリボーナスと組み合わせて月最大$56還元。", "ko": "12개월간 매월 $2,000 사용으로 월 $40 ($480 총). 카테고리 보너스와 조합해 월 최대 $56 적립.", "zh": "每月消费$2,000连续12个月，每月获$40（共$480）。结合类别奖励每月最高返$56。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'CashBack World Elite Mastercard'), 'TRAVEL_BENEFIT', '{"en": "4 Free Lounge Visits", "es": "4 visitas lounge gratis", "fr": "4 visites salon gratuites", "ja": "4回無料ラウンジ", "ko": "4회 무료 라운지", "zh": "4次免费贵宾厅"}', '{"en": "Get 4 complimentary airport lounge visits per year via Mastercard Travel Pass (DragonPass). Plan trips around lounge access.", "es": "Obtén 4 visitas gratuitas a lounges via Mastercard Travel Pass (DragonPass). Planifica viajes.", "fr": "Obtenez 4 visites gratuites aux salons via Mastercard Travel Pass (DragonPass). Planifiez vos voyages.", "ja": "Mastercard Travel Pass（DragonPass）で年4回無料ラウンジ。ラウンジに合わせて旅行計画。", "ko": "Mastercard Travel Pass (DragonPass)로 연 4회 무료 라운지. 라운지에 맞춰 여행 계획.", "zh": "每年4次免费机场贵宾厅（通过Mastercard Travel Pass/DragonPass）。根据贵宾厅规划行程。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'AVOID', '{"en": "Foreign Transaction Fee", "es": "Cargo transacción extranjera", "fr": "Frais transaction étrangère", "ja": "海外取引手数料", "ko": "해외 거래 수수료", "zh": "外币交易费"}', '{"en": "2.5% foreign transaction fee applies. For international purchases, use a no-FX fee card instead.", "es": "2.5% de cargo por transacciones extranjeras. Para compras internacionales, usa tarjeta sin cargo FX.", "fr": "Frais de 2,5 % sur transactions étrangères. Pour achats internationaux, utilisez une carte sans frais FX.", "ja": "海外取引に2.5%の手数料。海外購入には外貨手数料無料カードを使用。", "ko": "해외 거래 2.5% 수수료. 해외 구매 시 FX 무료 카드 사용 권장.", "zh": "海外交易收取2.5%手续费。国际消费建议使用无外汇费卡。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'AVOID', '{"en": "Costco/Walmart Exclusion", "es": "Exclusión Costco/Walmart", "fr": "Exclusion Costco/Walmart", "ja": "Costco/Walmart除外", "ko": "Costco/Walmart 제외", "zh": "Costco/Walmart不算超市"}', '{"en": "Grocery 5x excludes wholesale (Costco) and general retailers (Walmart). Only dedicated grocery stores qualify.", "es": "Supermercado 5x excluye mayoristas (Costco) y minoristas generales (Walmart). Solo tiendas de comestibles dedicadas.", "fr": "Épicerie 5x exclut entrepôts (Costco) et détaillants généraux (Walmart). Seulement épiceries dédiées.", "ja": "食料品5倍は卸売店（Costco）や総合小売店（Walmart）を除外。専門スーパーのみ対象。", "ko": "식료품 5배는 도매점(Costco)과 일반 소매점(Walmart) 제외. 전문 식료품점만 해당.", "zh": "超市5倍积分不包括仓储店（Costco）和综合零售商（Walmart）。仅限专门超市。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'BEST_USE', '{"en": "Dining & Grocery 5x", "es": "Restaurante & Supermercado 5x", "fr": "Restaurant & Épicerie 5x", "ja": "飲食・食料品5倍", "ko": "식당 & 식료품 5배", "zh": "餐饮超市5倍"}', '{"en": "Earn 5x points on dining and groceries (up to 30,000 pts/year each). Includes restaurants, delivery, and meal kits.", "es": "Gana 5x puntos en comida y supermercado (hasta 30,000 pts/año cada uno). Incluye restaurantes, delivery y kits.", "fr": "Gagnez 5x points sur resto et épicerie (max 30 000 pts/an chacun). Inclut restos, livraison et kits repas.", "ja": "飲食と食料品で5倍ポイント（各年間最大30,000ポイント）。レストラン、デリバリー、ミールキット含む。", "ko": "식당과 식료품 5배 포인트 (각 연간 최대 30,000). 레스토랑, 배달, 밀키트 포함.", "zh": "餐饮和超市消费获5倍积分（每类别年上限30,000积分）。包括餐厅、外卖和餐食套装。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'BEST_USE', '{"en": "Gas & Transit 5x", "es": "Gasolina & Transporte 5x", "fr": "Essence & Transport 5x", "ja": "ガソリン・交通5倍", "ko": "주유 & 대중교통 5배", "zh": "加油公交5倍"}', '{"en": "Earn 5x points on gas and transit (up to 100,000 pts/year each). Higher annual cap than dining/grocery categories.", "es": "Gana 5x puntos en gasolina y transporte (hasta 100,000 pts/año cada uno). Límite más alto que comida/supermercado.", "fr": "Gagnez 5x points sur essence et transport (max 100 000 pts/an chacun). Plafond plus élevé que resto/épicerie.", "ja": "ガソリンと交通で5倍ポイント（各年間最大100,000ポイント）。飲食/食料品より年間上限が高い。", "ko": "주유와 대중교통 5배 포인트 (각 연간 최대 100,000). 식당/식료품보다 연간 한도 높음.", "zh": "加油和公交消费获5倍积分（每类别年上限100,000积分）。比餐饮/超市类别年度上限更高。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'INSURANCE', '{"en": "Mobile Device Insurance", "es": "Seguro dispositivo móvil", "fr": "Assurance appareil mobile", "ja": "モバイル端末保険", "ko": "모바일 기기 보험", "zh": "手机保险"}', '{"en": "Coverage up to $1,000 for mobile device damage or theft. Pay your monthly phone bill with this card to activate.", "es": "Cobertura hasta $1,000 por daño o robo de dispositivo. Paga tu factura de teléfono con esta tarjeta.", "fr": "Couverture jusqu''à 1 000 $ pour dommage ou vol d''appareil. Payez votre facture téléphone avec cette carte.", "ja": "モバイル端末の損傷・盗難に最大$1,000補償。このカードで月額料金を支払って有効化。", "ko": "모바일 기기 손상 또는 도난에 최대 $1,000 보장. 이 카드로 월 휴대폰 요금 결제 시 활성화.", "zh": "手机损坏或盗窃最高$1,000保障。用此卡支付每月话费以激活。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'PERK', '{"en": "$20/Month Streaming Credit", "es": "Crédito streaming $20/mes", "fr": "Crédit streaming 20 $/mois", "ja": "月$20ストリーミングクレジット", "ko": "월 $20 스트리밍 크레딧", "zh": "每月$20流媒体抵扣"}', '{"en": "Get $20/month statement credit for streaming services in your first year ($240 total). Covers Netflix, Spotify, Disney+, etc.", "es": "Obtén $20/mes de crédito streaming en tu primer año ($240 total). Cubre Netflix, Spotify, Disney+, etc.", "fr": "Obtenez 20 $/mois de crédit streaming la 1re année (240 $ total). Netflix, Spotify, Disney+, etc.", "ja": "初年度月$20のストリーミングクレジット（計$240）。Netflix、Spotify、Disney+などに使用可能。", "ko": "첫해 매월 $20 스트리밍 크레딧 (총 $240). Netflix, Spotify, Disney+ 등 적용.", "zh": "首年每月获$20流媒体账单抵扣（共$240）。可用于Netflix、Spotify、Disney+等。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'PERK', '{"en": "$50 Annual Lifestyle Credit", "es": "Crédito anual $50", "fr": "Crédit annuel 50 $", "ja": "年間$50ライフスタイルクレジット", "ko": "연간 $50 라이프스타일 크레딧", "zh": "$50年度生活抵扣"}', '{"en": "Receive $50 statement credit automatically on your account anniversary each year. Helps offset the $120 annual fee.", "es": "Recibe $50 de crédito automáticamente en tu aniversario cada año. Ayuda a compensar los $120 de cuota anual.", "fr": "Recevez 50 $ de crédit automatiquement à chaque anniversaire du compte. Aide à compenser les 120 $ de frais.", "ja": "毎年アカウント記念日に$50クレジットを自動受取。$120の年会費を相殺。", "ko": "매년 계좌 기념일에 자동으로 $50 크레딧. $120 연회비 상쇄에 도움.", "zh": "每年账户周年日自动获得$50账单抵扣。帮助抵消$120年费。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'PERK', '{"en": "10% Bonus with Authorized User", "es": "Bono 10% con usuario autorizado", "fr": "Bonus 10 % avec utilisateur autorisé", "ja": "家族カードで10%ボーナス", "ko": "추가 카드로 10% 보너스", "zh": "副卡10%积分加成"}', '{"en": "Add an authorized user to earn 10% more points on all purchases. Turns 5x into 5.5x and 1x into 1.1x.", "es": "Agrega un usuario autorizado para ganar 10% más puntos. 5x se convierte en 5.5x y 1x en 1.1x.", "fr": "Ajoutez un utilisateur autorisé pour 10 % plus de points. 5x devient 5,5x et 1x devient 1,1x.", "ja": "家族カードを追加すると全購入で10%ボーナス。5倍→5.5倍、1倍→1.1倍に。", "ko": "추가 사용자 등록 시 모든 구매에 10% 추가 적립. 5배→5.5배, 1배→1.1배.", "zh": "添加副卡用户可让所有消费多获10%积分。5倍变5.5倍，1倍变1.1倍。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'PERK', '{"en": "Instacart+ Membership", "es": "Membresía Instacart+", "fr": "Adhésion Instacart+", "ja": "Instacart+会員", "ko": "Instacart+ 멤버십", "zh": "Instacart+会员"}', '{"en": "Get 6 months free Instacart+ membership plus $10/month Instacart credit. Enroll your card to activate.", "es": "Obtén 6 meses de Instacart+ gratis más $10/mes de crédito. Registra tu tarjeta.", "fr": "Obtenez 6 mois d''Instacart+ gratuit plus 10 $/mois de crédit. Inscrivez votre carte.", "ja": "6ヶ月のInstacart+無料会員と月$10クレジット。カードを登録して有効化。", "ko": "6개월 무료 Instacart+ 멤버십과 월 $10 크레딧. 카드 등록으로 활성화.", "zh": "获得6个月免费Instacart+会员，每月$10 Instacart抵扣。注册您的卡以激活。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'BMO' AND name = 'Eclipse Visa Infinite'), 'REDEMPTION', '{"en": "BMO Travel Portal 0.67cpp", "es": "Portal viaje BMO 0.67cpp", "fr": "Portail voyage BMO 0,67 ¢/pt", "ja": "BMOトラベル0.67cpp", "ko": "BMO 여행 포털 0.67cpp", "zh": "BMO旅行门户0.67分/点"}', '{"en": "Redeem 150 pts = $1 for travel via BMO Rewards portal (0.67cpp). Better than statement credit at 200 pts = $1 (0.5cpp).", "es": "Canjea 150 pts = $1 en viajes via BMO (0.67cpp). Mejor que crédito de estado de cuenta 200 pts = $1 (0.5cpp).", "fr": "Échangez 150 pts = 1 $ pour voyages via BMO (0,67 ¢/pt). Mieux que crédit relevé 200 pts = 1 $ (0,5 ¢/pt).", "ja": "BMOポータルで150ポイント=$1で旅行交換（0.67cpp）。明細クレジット200pt=$1（0.5cpp）より良い。", "ko": "BMO 포털에서 150포인트=$1로 여행 교환 (0.67cpp). 명세서 크레딧 200pt=$1 (0.5cpp)보다 좋음.", "zh": "在BMO Rewards门户兑换旅行：150积分=$1（0.67分/点）。优于账单抵扣200积分=$1（0.5分/点）。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'AVOID', '{"en": "Lower Grocery Rate", "es": "Tasa supermercado menor", "fr": "Taux épicerie plus bas", "ja": "食料品還元率が低い", "ko": "식료품 적립률 낮음", "zh": "超市返现较低"}', '{"en": "Only 1.5% on groceries vs 3% on World Elite. If you spend $500+/month on groceries and meet income requirements, consider upgrading.", "es": "Solo 1.5% en supermercados vs 3% World Elite. Si gasta $500+/mes y califica, considere actualizar.", "fr": "Seulement 1,5 % sur l''épicerie vs 3 % World Elite. Si vous dépensez 500 $+/mois et qualifiez, considérez une mise à niveau.", "ja": "食料品は1.5%のみ、World Eliteは3%。月$500以上食料品に支出し収入要件を満たすならアップグレードを検討。", "ko": "식료품 1.5%만, World Elite는 3%. 월 $500 이상 식료품 지출 및 소득 요건 충족 시 업그레이드 고려.", "zh": "超市仅1.5%，而World Elite为3%。如果超市月消费$500+且满足收入要求，考虑升级。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'AVOID', '{"en": "Low Base Rate", "es": "Tasa base baja", "fr": "Taux de base faible", "ja": "基本還元率が低い", "ko": "기본 적립률 낮음", "zh": "基础返现较低"}', '{"en": "Only 0.5% on non-category spending. Use a flat-rate 1.5-2% card for purchases outside CT stores, grocery, and gas.", "es": "Solo 0.5% fuera de categorías. Use una tarjeta 1.5-2% para compras fuera de CT, supermercado y gasolina.", "fr": "Seulement 0,5 % hors catégories. Utilisez une carte à taux fixe 1,5-2 % pour les achats hors CT, épicerie et essence.", "ja": "カテゴリ外は0.5%のみ。CT店舗、食料品、ガソリン以外は1.5-2%フラットレートカードを使用。", "ko": "카테고리 외 0.5%만. CT 매장, 식료품, 주유 외 구매는 1.5-2% 정률 카드 사용.", "zh": "非类别消费仅0.5%。CT门店、超市、加油以外的消费建议用1.5-2%的固定返现卡。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'AVOID', '{"en": "No Roadside Assistance", "es": "Sin asistencia vial", "fr": "Pas d''assistance routière", "ja": "ロードサービスなし", "ko": "로드 어시스턴스 없음", "zh": "无道路救援"}', '{"en": "Unlike the World Elite version, this card does NOT include free Roadside Assistance. Purchase separately if needed.", "es": "A diferencia de World Elite, esta tarjeta NO incluye asistencia vial. Compre por separado si es necesario.", "fr": "Contrairement à la World Elite, cette carte N''inclut PAS l''assistance routière. Achetez séparément si nécessaire.", "ja": "World Elite版と異なり、このカードには無料ロードサービスが含まれません。必要な場合は別途購入。", "ko": "World Elite 버전과 달리 이 카드에는 무료 로드 어시스턴스가 포함되지 않음. 필요시 별도 구매.", "zh": "与World Elite版本不同，此卡不包含免费道路救援。如需要请单独购买。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'BEST_USE', '{"en": "4% at CT Family Stores", "es": "4% en tiendas CT", "fr": "4 % aux magasins CT", "ja": "CTグループ店舗4%", "ko": "CT 패밀리 매장 4%", "zh": "CT系列门店4%"}', '{"en": "Earn 4% CT Money at Canadian Tire, Sport Chek, and Mark''s stores. Same earn rate as the World Elite version!", "es": "Gana 4% CT Money en Canadian Tire, Sport Chek y Mark''s. ¡Misma tasa que la versión World Elite!", "fr": "Gagnez 4 % en Argent CT chez Canadian Tire, Sport Chek et Mark''s. Même taux que la version World Elite!", "ja": "Canadian Tire、Sport Chek、Mark''s店舗で4% CT Money獲得。World Elite版と同じ獲得率！", "ko": "Canadian Tire, Sport Chek, Mark''s 매장에서 4% CT Money 적립. World Elite 버전과 동일한 적립률!", "zh": "在Canadian Tire、Sport Chek、Mark''s店铺消费可获4% CT Money。与World Elite版本相同的返还率！"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'BEST_USE', '{"en": "1.5% Groceries", "es": "Supermercado 1.5%", "fr": "Épicerie 1,5 %", "ja": "食料品1.5%", "ko": "식료품 1.5%", "zh": "超市1.5%"}', '{"en": "Earn 1.5% CT Money on groceries up to $12,000/year. Costco and Walmart do not qualify for this bonus rate.", "es": "Gana 1.5% CT Money en supermercados hasta $12,000/año. Costco y Walmart no califican.", "fr": "Gagnez 1,5 % en Argent CT sur l''épicerie jusqu''à 12 000 $/an. Costco et Walmart non admissibles.", "ja": "食料品で年間$12,000まで1.5% CT Money獲得。CostcoとWalmartは対象外。", "ko": "식료품 연간 $12,000까지 1.5% CT Money 적립. Costco와 Walmart는 제외.", "zh": "超市消费年最高$12,000享1.5% CT Money。Costco和Walmart不适用此优惠费率。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'BEST_USE', '{"en": "Gas+ Fuel Savings", "es": "Ahorro Gas+", "fr": "Économies Gas+", "ja": "Gas+燃料節約", "ko": "Gas+ 연료 절약", "zh": "Gas+加油优惠"}', '{"en": "Earn 5 cents per litre in CT Money at Gas+ and Essence+ locations. About 1.5% equivalent value at current gas prices.", "es": "Gana 5¢/L en CT Money en Gas+ y Essence+. Aproximadamente 1.5% de valor a precios actuales.", "fr": "Gagnez 5 ¢/L en Argent CT chez Gas+ et Essence+. Environ 1,5 % de valeur aux prix actuels.", "ja": "Gas+とEssence+で1リットルあたり5セントのCT Money獲得。現在のガス価格で約1.5%相当。", "ko": "Gas+와 Essence+에서 리터당 5센트 CT Money 적립. 현재 유가 기준 약 1.5% 가치.", "zh": "在Gas+和Essence+加油站每升节省5分CT Money。按当前油价约相当于1.5%返还。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Basic coverage against accidental damage or theft for 90 days after purchase. Keep receipts for potential claims.", "es": "Cobertura básica contra daños accidentales o robo por 90 días. Guarde los recibos.", "fr": "Couverture de base contre dommages accidentels ou vol pendant 90 jours. Conservez les reçus.", "ja": "購入後90日間の基本的な偶発的損傷または盗難カバー。請求用にレシートを保管。", "ko": "구매 후 90일 동안 기본적인 우발적 손상 또는 도난 보장. 청구를 위해 영수증 보관.", "zh": "购买后90天内的基本意外损坏或盗窃保障。保留收据以便可能的索赔。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'PERK', '{"en": "Pay Bills with Card", "es": "Pagar facturas con tarjeta", "fr": "Payer factures par carte", "ja": "カードで請求書支払い", "ko": "카드로 청구서 결제", "zh": "信用卡付账单"}', '{"en": "Pay utility bills (hydro, property tax, rent) that normally don''t accept credit cards through CTFS portal. Earn 0.5% CT Money with no extra fee!", "es": "Paga facturas (electricidad, impuestos, alquiler) que no aceptan tarjetas vía portal CTFS. ¡Gana 0.5% sin cargo!", "fr": "Payez les factures (hydro, taxes, loyer) qui n''acceptent pas les cartes via le portail CTFS. Gagnez 0,5 % sans frais!", "ja": "通常クレジットカードを受け付けない請求書（電気、固定資産税、家賃）をCTFSポータルで支払い。手数料なしで0.5% CT Money獲得！", "ko": "일반적으로 신용카드를 받지 않는 공과금(전기, 재산세, 임대료)을 CTFS 포털로 결제. 추가 수수료 없이 0.5% CT Money 적립!", "zh": "通过CTFS门户用信用卡支付通常不接受信用卡的账单（电费、房产税、房租）。赚取0.5% CT Money，无额外费用！"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'PERK', '{"en": "No Fee, No Income Req", "es": "Sin cuota ni ingreso mín", "fr": "Sans frais ni revenu min", "ja": "年会費・収入要件なし", "ko": "연회비·소득요건 없음", "zh": "无年费无收入要求"}', '{"en": "No annual fee and no minimum income requirement. Great starter card or alternative if you don''t qualify for World Elite.", "es": "Sin cuota anual ni ingreso mínimo. Gran tarjeta inicial o alternativa si no califica para World Elite.", "fr": "Aucuns frais annuels ni revenu minimum. Excellente carte de départ si vous ne qualifiez pas pour World Elite.", "ja": "年会費・最低収入要件なし。World Eliteの資格がない場合に最適な入門カードまたは代替カード。", "ko": "연회비 무료, 최소 소득 요건 없음. World Elite 자격이 안 되면 좋은 입문 카드 또는 대안.", "zh": "无年费且无最低收入要求。如果不符合World Elite资格，是很好的入门卡或替代选择。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'REDEMPTION', '{"en": "CT Money Flexibility", "es": "Flexibilidad CT Money", "fr": "Flexibilité Argent CT", "ja": "CT Money柔軟性", "ko": "CT Money 유연성", "zh": "CT Money灵活使用"}', '{"en": "Redeem CT Money at Canadian Tire, Sport Chek, Mark''s, and online. $1 CT Money = $1 value. No minimums to redeem.", "es": "Canjea CT Money en Canadian Tire, Sport Chek, Mark''s y en línea. $1 CT Money = $1. Sin mínimos.", "fr": "Échangez l''Argent CT chez Canadian Tire, Sport Chek, Mark''s et en ligne. 1 $ = 1 $. Aucun minimum.", "ja": "Canadian Tire、Sport Chek、Mark''s、オンラインでCT Moneyを交換。$1 CT Money = $1の価値。最低交換額なし。", "ko": "Canadian Tire, Sport Chek, Mark''s 및 온라인에서 CT Money 사용. $1 CT Money = $1 가치. 최소 금액 없음.", "zh": "在Canadian Tire、Sport Chek、Mark''s及在线兑换CT Money。$1 CT Money = $1价值。无最低兑换限制。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle Mastercard'), 'STACKING', '{"en": "Bonus Days Events", "es": "Eventos Días Bonus", "fr": "Événements Jours Bonus", "ja": "ボーナスデーイベント", "ko": "보너스 데이 이벤트", "zh": "奖励日活动"}', '{"en": "Watch for Bonus Days at Canadian Tire (20-30x CT Money events). Your 4% card rate stacks on top of promotional multipliers!", "es": "Busque eventos Bonus Days en Canadian Tire (20-30x CT Money). ¡Su 4% se suma a los multiplicadores promocionales!", "fr": "Surveillez les Jours Bonus chez Canadian Tire (20-30x Argent CT). Votre taux de 4 % s''ajoute aux multiplicateurs!", "ja": "Canadian TireのBonus Days（20-30倍CT Moneyイベント）をチェック。4%カードレートがプロモ倍率に上乗せ！", "ko": "Canadian Tire Bonus Days (20-30배 CT Money 이벤트) 확인. 4% 카드 적립률이 프로모션 배율에 추가!", "zh": "留意Canadian Tire的Bonus Days（20-30倍CT Money活动）。4%卡片返还可与促销倍数叠加！"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'AVOID', '{"en": "Costco/Walmart Excluded", "es": "Costco/Walmart excluidos", "fr": "Costco/Walmart exclus", "ja": "Costco/Walmart対象外", "ko": "Costco/Walmart 제외", "zh": "Costco/Walmart不适用"}', '{"en": "Costco and Walmart grocery purchases do NOT qualify for the 3% grocery rate. Only 1% base rate applies at these stores.", "es": "Compras de supermercado en Costco y Walmart NO califican para 3%. Solo aplica 1% base.", "fr": "Les achats d''épicerie chez Costco et Walmart NE qualifient PAS pour le 3 %. Seulement 1 % de base.", "ja": "CostcoとWalmartの食料品購入は3%の対象外。これらの店舗では1%の基本レートのみ適用。", "ko": "Costco와 Walmart 식료품 구매는 3% 적립 대상 아님. 이 매장에서는 1% 기본 적립만 적용.", "zh": "Costco和Walmart的杂货购买不符合3%超市返还。这些店只能获得1%基础返还。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'AVOID', '{"en": "Income Requirement", "es": "Requisito de ingresos", "fr": "Exigence de revenu", "ja": "収入要件", "ko": "소득 요건", "zh": "收入要求"}', '{"en": "World Elite tier requires $80,000 personal income or $150,000 household. If you don''t meet this, apply for the regular Triangle Mastercard instead.", "es": "El nivel World Elite requiere $80,000 personal o $150,000 familiar. Si no califica, solicite la Triangle Mastercard regular.", "fr": "Le niveau World Elite exige 80 000 $ personnel ou 150 000 $ familial. Sinon, demandez la Triangle Mastercard régulière.", "ja": "World Eliteは個人収入$80,000または世帯収入$150,000が必要。該当しない場合は通常のTriangle Mastercardを申請。", "ko": "World Elite 등급은 개인 소득 $80,000 또는 가구 소득 $150,000 필요. 해당 안 되면 일반 Triangle Mastercard 신청.", "zh": "World Elite级别需个人收入$80,000或家庭收入$150,000。如不满足，请申请普通Triangle Mastercard。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'BEST_USE', '{"en": "4% at CT Family Stores", "es": "4% en tiendas CT", "fr": "4 % aux magasins CT", "ja": "CTグループ店舗4%", "ko": "CT 패밀리 매장 4%", "zh": "CT系列门店4%"}', '{"en": "Earn 4% CT Money at Canadian Tire, Sport Chek, Mark''s, Atmosphere, Party City, and participating Sports Experts stores.", "es": "Gana 4% CT Money en Canadian Tire, Sport Chek, Mark''s, Atmosphere, Party City y tiendas Sports Experts participantes.", "fr": "Gagnez 4 % en Argent CT chez Canadian Tire, Sport Chek, Mark''s, Atmosphere, Party City et Sports Experts participants.", "ja": "Canadian Tire、Sport Chek、Mark''s、Atmosphere、Party City、参加Sports Experts店舗で4% CT Money獲得。", "ko": "Canadian Tire, Sport Chek, Mark''s, Atmosphere, Party City 및 참여 Sports Experts 매장에서 4% CT Money 적립.", "zh": "在Canadian Tire、Sport Chek、Mark''s、Atmosphere、Party City及参与活动的Sports Experts店铺消费可获4% CT Money。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'BEST_USE', '{"en": "3% Groceries", "es": "Supermercado 3%", "fr": "Épicerie 3 %", "ja": "食料品3%", "ko": "식료품 3%", "zh": "超市3%"}', '{"en": "Earn 3% CT Money on groceries up to $12,000/year. Use at dedicated grocery stores. Costco and Walmart do not qualify.", "es": "Gana 3% CT Money en supermercados hasta $12,000/año. Costco y Walmart no califican.", "fr": "Gagnez 3 % en Argent CT sur l''épicerie jusqu''à 12 000 $/an. Costco et Walmart non admissibles.", "ja": "食料品で年間$12,000まで3% CT Money獲得。CostcoとWalmartは対象外。", "ko": "식료품 연간 $12,000까지 3% CT Money 적립. Costco와 Walmart는 제외.", "zh": "超市消费年最高$12,000享3% CT Money。在专门超市使用。Costco和Walmart不适用。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'BEST_USE', '{"en": "Gas+ Fuel Savings", "es": "Ahorro Gas+", "fr": "Économies Gas+", "ja": "Gas+燃料節約", "ko": "Gas+ 연료 절약", "zh": "Gas+加油优惠"}', '{"en": "Earn 5 cents/L on regular fuel and 7 cents/L on premium fuel at Gas+ and Essence+ locations. About 2% equivalent value.", "es": "Gana 5¢/L en combustible regular y 7¢/L en premium en Gas+ y Essence+. Aproximadamente 2% de valor.", "fr": "Gagnez 5 ¢/L sur l''essence ordinaire et 7 ¢/L sur le super à Gas+ et Essence+. Environ 2 % de valeur.", "ja": "Gas+とEssence+でレギュラー5セント/L、プレミアム7セント/L獲得。約2%相当の価値。", "ko": "Gas+와 Essence+에서 일반 연료 5센트/L, 프리미엄 연료 7센트/L 적립. 약 2% 가치.", "zh": "在Gas+和Essence+加油站普通油每升节省5分，高级油每升节省7分。相当于约2%返还。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Coverage against accidental damage or theft for 90 days after purchase. Covers items up to $1,000 per claim.", "es": "Cobertura contra daños accidentales o robo por 90 días. Hasta $1,000 por reclamo.", "fr": "Couverture contre dommages accidentels ou vol pendant 90 jours. Jusqu''à 1 000 $ par réclamation.", "ja": "購入後90日間の偶発的損傷または盗難をカバー。請求ごとに最大$1,000。", "ko": "구매 후 90일 동안 우발적 손상 또는 도난 보장. 청구당 최대 $1,000.", "zh": "购买后90天内意外损坏或盗窃保障。每次索赔最高$1,000。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'INSURANCE', '{"en": "Extended Warranty", "es": "Garantía extendida", "fr": "Garantie prolongée", "ja": "延長保証", "ko": "연장 보증", "zh": "延长保修"}', '{"en": "Doubles manufacturer warranty up to 1 additional year. Use for electronics, appliances, and tools purchased at Canadian Tire.", "es": "Duplica garantía del fabricante hasta 1 año. Ideal para electrónicos y herramientas de Canadian Tire.", "fr": "Double la garantie fabricant jusqu''à 1 an. Idéal pour électronique et outils achetés chez Canadian Tire.", "ja": "メーカー保証を最大1年延長。Canadian Tireで購入した電子機器、家電、工具に最適。", "ko": "제조사 보증 최대 1년 연장. Canadian Tire에서 구입한 전자제품, 가전, 공구에 적합.", "zh": "制造商保修延长最多1年。适用于在Canadian Tire购买的电子产品、电器和工具。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'PERK', '{"en": "Free Roadside Assistance", "es": "Asistencia vial gratuita", "fr": "Assistance routière gratuite", "ja": "無料ロードサービス", "ko": "무료 로드 어시스턴스", "zh": "免费道路救援"}', '{"en": "Includes Roadside Assistance Gold Plan free (worth ~$100/year). Covers towing, flat tire, battery boost, and lockout services.", "es": "Incluye Plan Gold de asistencia vial gratis (~$100/año). Cubre remolque, neumático pinchado, arranque de batería y cerrajería.", "fr": "Comprend l''assistance routière Gold gratuite (~100 $/an). Couvre remorquage, pneu crevé, survoltage et déverrouillage.", "ja": "無料のロードサービスGoldプラン付き（年間約$100相当）。牽引、パンク、バッテリー充電、ロックアウトサービスを含む。", "ko": "무료 로드 어시스턴스 Gold Plan 포함 (연간 ~$100 가치). 견인, 펑크, 배터리 점프, 잠금 서비스 포함.", "zh": "含免费道路救援Gold Plan（价值约$100/年）。包括拖车、换胎、电池启动和开锁服务。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'PERK', '{"en": "Pay Bills with Card", "es": "Pagar facturas con tarjeta", "fr": "Payer factures par carte", "ja": "カードで請求書支払い", "ko": "카드로 청구서 결제", "zh": "信用卡付账单"}', '{"en": "Pay utility bills (hydro, property tax, etc.) that normally don''t accept credit cards through CTFS portal at 1% CT Money. No extra fee!", "es": "Paga facturas de servicios (electricidad, impuestos) que no aceptan tarjetas vía portal CTFS al 1% CT Money. ¡Sin cargo!", "fr": "Payez les factures (hydro, taxes foncières) qui n''acceptent pas les cartes via le portail CTFS à 1 % Argent CT. Sans frais!", "ja": "通常クレジットカードを受け付けない請求書（電気、固定資産税など）をCTFSポータルで支払い、1% CT Money獲得。手数料なし！", "ko": "일반적으로 신용카드를 받지 않는 공과금(전기, 재산세 등)을 CTFS 포털로 결제하고 1% CT Money 적립. 추가 수수료 없음!", "zh": "通过CTFS门户用信用卡支付通常不接受信用卡的账单（电费、房产税等），赚取1% CT Money。无额外费用！"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'PERK', '{"en": "No Annual Fee", "es": "Sin cuota anual", "fr": "Aucuns frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "无年费"}', '{"en": "No annual fee despite being a World Elite card. Requires $80,000 personal or $150,000 household income to qualify.", "es": "Sin cuota anual a pesar de ser World Elite. Requiere ingreso personal $80,000 o familiar $150,000.", "fr": "Aucuns frais annuels malgré le statut World Elite. Exige 80 000 $ personnel ou 150 000 $ revenu familial.", "ja": "World Eliteカードながら年会費無料。個人収入$80,000または世帯収入$150,000が必要。", "ko": "World Elite 카드이지만 연회비 무료. 개인 소득 $80,000 또는 가구 소득 $150,000 필요.", "zh": "虽是World Elite卡但无年费。需个人收入$80,000或家庭收入$150,000才能申请。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'REDEMPTION', '{"en": "CT Money Flexibility", "es": "Flexibilidad CT Money", "fr": "Flexibilité Argent CT", "ja": "CT Money柔軟性", "ko": "CT Money 유연성", "zh": "CT Money灵活使用"}', '{"en": "Redeem CT Money at Canadian Tire, Sport Chek, Mark''s, Atmosphere, and online. $1 CT Money = $1 value. No minimums to redeem.", "es": "Canjea CT Money en Canadian Tire, Sport Chek, Mark''s, Atmosphere y en línea. $1 CT Money = $1. Sin mínimos.", "fr": "Échangez l''Argent CT chez Canadian Tire, Sport Chek, Mark''s, Atmosphere et en ligne. 1 $ Argent CT = 1 $. Aucun minimum.", "ja": "Canadian Tire、Sport Chek、Mark''s、Atmosphere、オンラインでCT Moneyを交換。$1 CT Money = $1の価値。最低交換額なし。", "ko": "Canadian Tire, Sport Chek, Mark''s, Atmosphere 및 온라인에서 CT Money 사용. $1 CT Money = $1 가치. 최소 금액 없음.", "zh": "在Canadian Tire、Sport Chek、Mark''s、Atmosphere及在线兑换CT Money。$1 CT Money = $1价值。无最低兑换限制。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Canadian Tire' AND name = 'Triangle World Elite Mastercard'), 'STACKING', '{"en": "Bonus Days Events", "es": "Eventos Días Bonus", "fr": "Événements Jours Bonus", "ja": "ボーナスデーイベント", "ko": "보너스 데이 이벤트", "zh": "奖励日活动"}', '{"en": "Watch for Bonus Days at Canadian Tire (20-30x CT Money events). Stack with your 4% card rate for massive returns on big purchases.", "es": "Busque eventos Bonus Days en Canadian Tire (20-30x CT Money). Combine con su 4% para máximos retornos.", "fr": "Surveillez les Jours Bonus chez Canadian Tire (20-30x Argent CT). Combinez avec votre taux de 4 % pour maximiser les retours.", "ja": "Canadian TireのBonus Days（20-30倍CT Moneyイベント）をチェック。4%カードレートと組み合わせて大きなリターンを。", "ko": "Canadian Tire Bonus Days (20-30배 CT Money 이벤트) 확인. 4% 카드 적립률과 결합하여 높은 수익 달성.", "zh": "留意Canadian Tire的Bonus Days（20-30倍CT Money活动）。与4%卡片返还叠加，大额消费可获超高回报。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'AVOID', '{"en": "$40K Annual Cap", "es": "Límite $40K/año", "fr": "Plafond 40K $/an", "ja": "年間$4万上限", "ko": "연간 $4만 한도", "zh": "年消费$4万上限"}', '{"en": "Bonus 1.5x earning only applies to first $40,000 in annual spending. After cap, you earn just 1 pt/$1 base rate.", "es": "El bono 1.5x solo aplica a los primeros $40,000/año. Después gana solo 1 pt/$1 base.", "fr": "Le bonus 1,5x s''applique seulement aux premiers 40 000 $/an. Après, vous gagnez 1 pt/1 $ de base.", "ja": "1.5倍ボーナスは年間$40,000までのみ適用。上限後は基本1ポイント/$1のみ。", "ko": "1.5배 보너스는 연간 $40,000까지만 적용. 한도 초과 후 기본 1 포인트/$1만 적립.", "zh": "1.5倍奖励仅适用于年消费$40,000以内。超过上限后只能获得基础1倍积分。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'AVOID', '{"en": "Categories Change Monthly", "es": "Categorías cambian mensualmente", "fr": "Catégories changent mensuellement", "ja": "カテゴリは毎月変化", "ko": "카테고리 매월 변경", "zh": "类别每月变化"}', '{"en": "Your top 3 categories are recalculated each month. If spending patterns vary, you may not consistently earn 1.5x in the same categories.", "es": "Tus 3 categorías principales se recalculan cada mes. Si tus patrones varían, no siempre ganarás 1.5x.", "fr": "Vos 3 catégories principales sont recalculées chaque mois. Si vos habitudes varient, vous ne gagnerez pas toujours 1,5x.", "ja": "トップ3カテゴリは毎月再計算。消費パターンが変わると同じカテゴリで1.5倍を維持できない場合も。", "ko": "상위 3개 카테고리는 매월 재계산. 소비 패턴이 변하면 동일 카테고리에서 1.5배를 지속적으로 적립하지 못할 수 있음.", "zh": "前3类别每月重新计算。如果消费模式变化，可能无法在相同类别持续获得1.5倍。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'AVOID', '{"en": "Lower Point Value", "es": "Valor de puntos menor", "fr": "Valeur de points plus basse", "ja": "ポイント価値が低い", "ko": "포인트 가치 낮음", "zh": "积分价值较低"}', '{"en": "Cashback redemption is 0.67¢/pt (1.5x = effective 1%). Cards like CIBC Dividend (4% grocery) may be better for fixed high-spend categories.", "es": "El canje en efectivo es 0.67¢/pt (1.5x = 1% efectivo). CIBC Dividend (4% supermercado) puede ser mejor para categorías fijas.", "fr": "L''échange en argent est 0,67 ¢/pt (1,5x = 1 % effectif). CIBC Dividend (4 % épicerie) peut être mieux pour catégories fixes.", "ja": "キャッシュバック交換は0.67¢/pt（1.5倍 = 実質1%）。固定カテゴリにはCIBC Dividend（食料品4%）などが良い場合も。", "ko": "캐시백 사용은 0.67¢/pt (1.5배 = 실질 1%). 고정 고소비 카테고리에는 CIBC Dividend (식료품 4%)가 더 나을 수 있음.", "zh": "返现兑换价值0.67分/积分（1.5倍 = 实际1%）。CIBC Dividend等卡（超市4%）可能更适合固定高消费类别。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'BEST_USE', '{"en": "Auto 1.5x Top 3 Categories", "es": "Auto 1.5x top 3 categorías", "fr": "Auto 1,5x top 3 catégories", "ja": "自動1.5倍トップ3カテゴリ", "ko": "자동 1.5배 상위 3 카테고리", "zh": "自动1.5倍前3类别"}', '{"en": "Automatically earn 1.5 pts/$1 on your top 3 spending categories each month. No need to choose - the card adapts to your habits!", "es": "Gana automáticamente 1.5 pts/$1 en tus 3 principales categorías cada mes. ¡No necesitas elegir - la tarjeta se adapta!", "fr": "Gagnez automatiquement 1,5 pts/1 $ sur vos 3 principales catégories chaque mois. Pas besoin de choisir - la carte s''adapte!", "ja": "毎月自動的にトップ3カテゴリで1.5ポイント/$1獲得。選択不要、カードがあなたの習慣に適応！", "ko": "매월 상위 3개 소비 카테고리에서 자동으로 1.5 포인트/$1 적립. 선택 불필요, 카드가 습관에 적응!", "zh": "每月自动在消费最高的3个类别获得1.5倍积分。无需选择，卡片自动适应你的消费习惯！"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'BEST_USE', '{"en": "12 Dynamic Categories", "es": "12 categorías dinámicas", "fr": "12 catégories dynamiques", "ja": "12の動的カテゴリ", "ko": "12개 동적 카테고리", "zh": "12个动态类别"}', '{"en": "Categories include: Groceries, Dining, Gas, Entertainment, Hotels, Home Improvement, Health, Transit, Utilities, Retail, Online Shopping, Travel.", "es": "Categorías: Supermercado, Restaurantes, Gasolina, Entretenimiento, Hoteles, Hogar, Salud, Transporte, Servicios, Retail, Compras online, Viajes.", "fr": "Catégories : Épicerie, Restaurants, Essence, Divertissement, Hôtels, Rénovation, Santé, Transport, Services, Détail, Achats en ligne, Voyage.", "ja": "カテゴリ：食料品、飲食、ガス、エンタメ、ホテル、ホームセンター、健康、交通、光熱費、小売、オンライン、旅行。", "ko": "카테고리: 식료품, 식당, 주유, 엔터테인먼트, 호텔, 홈 인테리어, 건강, 교통, 공과금, 리테일, 온라인 쇼핑, 여행.", "zh": "类别包括：超市、餐饮、加油、娱乐、酒店、家居装修、健康、交通、水电费、零售、网购、旅行。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'BEST_USE', '{"en": "2x via CIBCbyExpedia", "es": "2x vía CIBCbyExpedia", "fr": "2x via CIBCbyExpedia", "ja": "CIBCbyExpedia経由2倍", "ko": "CIBCbyExpedia 2배", "zh": "CIBCbyExpedia 2倍"}', '{"en": "Earn 2 pts/$1 (double rate) when booking travel through CIBCbyExpedia.com portal. Best for flights and hotels.", "es": "Gana 2 pts/$1 al reservar viajes en CIBCbyExpedia.com. Ideal para vuelos y hoteles.", "fr": "Gagnez 2 pts/1 $ en réservant via CIBCbyExpedia.com. Idéal pour vols et hôtels.", "ja": "CIBCbyExpedia.comで予約すると2ポイント/$1獲得。航空券やホテルに最適。", "ko": "CIBCbyExpedia.com에서 여행 예약 시 2 포인트/$1 적립. 항공권과 호텔에 최적.", "zh": "通过CIBCbyExpedia.com预订旅行可获2倍积分。适合预订机票和酒店。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Coverage against accidental damage or theft for 90 days after purchase. Keep receipts for potential claims.", "es": "Cobertura contra daños accidentales o robo por 90 días. Guarde los recibos.", "fr": "Couverture contre dommages accidentels ou vol pendant 90 jours. Conservez les reçus.", "ja": "購入後90日間の偶発的損傷または盗難をカバー。請求用にレシートを保管。", "ko": "구매 후 90일 동안 우발적 손상 또는 도난 보장. 청구를 위해 영수증 보관.", "zh": "购买后90天内的意外损坏或盗窃保障。保留收据以便索赔。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'PERK', '{"en": "No Annual Fee", "es": "Sin cuota anual", "fr": "Aucuns frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "无年费"}', '{"en": "No annual fee with minimum $15,000 household income requirement. Great everyday card for flexible spenders.", "es": "Sin cuota anual con ingreso familiar mínimo $15,000. Gran tarjeta diaria para gastos flexibles.", "fr": "Aucuns frais annuels avec revenu familial minimum de 15 000 $. Excellente carte quotidienne.", "ja": "年会費無料、世帯収入$15,000以上が条件。柔軟な消費者向けの日常カード。", "ko": "연회비 무료, 최소 가구 소득 $15,000 요건. 유연한 소비자를 위한 일상 카드.", "zh": "无年费，最低家庭收入要求$15,000。适合灵活消费者的日常卡。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'PERK', '{"en": "Roadside Assistance", "es": "Asistencia vial", "fr": "Assistance routière", "ja": "ロードサービス", "ko": "로드 어시스턴스", "zh": "道路救援"}', '{"en": "Includes Roadside Assistance coverage (worth ~$50/year). Covers towing, battery boost, flat tire, and lockout services.", "es": "Incluye asistencia vial (~$50/año). Cubre remolque, arranque de batería, neumático pinchado y cerrajería.", "fr": "Comprend l''assistance routière (~50 $/an). Couvre remorquage, survoltage, crevaison et déverrouillage.", "ja": "ロードサービス付き（年間約$50相当）。牽引、バッテリー充電、パンク、ロックアウトサービスを含む。", "ko": "로드 어시스턴스 포함 (연간 ~$50 가치). 견인, 배터리 점프, 펑크, 잠금 서비스 포함.", "zh": "含道路救援服务（价值约$50/年）。包括拖车、电池启动、换胎和开锁服务。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 사용", "zh": "灵活兑换"}', '{"en": "1,500 pts = $10 cashback (0.67¢/pt) or 1,200 pts = $10 toward CIBC products (0.83¢/pt). Use for statement credit or CIBC banking products.", "es": "1,500 pts = $10 reembolso (0.67¢/pt) o 1,200 pts = $10 productos CIBC (0.83¢/pt). Crédito o productos bancarios.", "fr": "1 500 pts = 10 $ remise (0,67 ¢/pt) ou 1 200 pts = 10 $ produits CIBC (0,83 ¢/pt). Crédit ou produits bancaires.", "ja": "1,500ポイント = $10キャッシュバック（0.67¢/pt）または1,200ポイント = $10 CIBC商品（0.83¢/pt）。", "ko": "1,500 포인트 = $10 캐시백 (0.67¢/pt) 또는 1,200 포인트 = $10 CIBC 상품 (0.83¢/pt).", "zh": "1,500积分 = $10返现（0.67分/积分）或1,200积分 = $10 CIBC产品（0.83分/积分）。可用于账单抵扣或CIBC银行产品。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Adapta Mastercard'), 'STACKING', '{"en": "Pair with Category Cards", "es": "Combinar con tarjetas de categoría", "fr": "Combiner avec cartes catégorie", "ja": "カテゴリカードと併用", "ko": "카테고리 카드와 함께 사용", "zh": "搭配类别卡"}', '{"en": "Use Adapta for varied spending and pair with fixed-category cards (e.g., 4% grocery card) for your highest consistent spend categories.", "es": "Usa Adapta para gastos variados y combina con tarjetas de categoría fija (ej: 4% supermercado) para tus gastos regulares.", "fr": "Utilisez Adapta pour dépenses variées et combinez avec cartes à catégories fixes (ex: 4 % épicerie) pour vos dépenses régulières.", "ja": "Adaptaは多様な支出に使い、固定カテゴリカード（4%食料品など）と組み合わせて一貫した高額支出カテゴリに。", "ko": "Adapta는 다양한 지출에 사용하고, 고정 카테고리 카드(예: 4% 식료품)와 함께 일관된 고액 지출 카테고리에 사용.", "zh": "用Adapta处理多变消费，搭配固定类别卡（如4%超市卡）用于最高固定消费类别。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'AVOID', '{"en": "Low Base Rate", "es": "Tasa base baja", "fr": "Taux de base faible", "ja": "基本還元率が低い", "ko": "기본 적립률 낮음", "zh": "基础返还率较低"}', '{"en": "Only 1 pt per $1.50 (~0.67x) on non-category spending. Use a 1.5-2% flat rate card for purchases outside gas, grocery, EV, and Air Canada.", "es": "Solo 1 pt por $1.50 (~0.67x) fuera de categorías. Usa una tarjeta 1.5-2% para compras fuera de gasolina, supermercado, VE y Air Canada.", "fr": "Seulement 1 pt par 1,50 $ (~0,67x) hors catégories. Utilisez une carte à taux fixe 1,5-2 % pour autres achats.", "ja": "カテゴリ外は$1.50につき1ポイントのみ（約0.67倍）。ガス、食料品、EV、Air Canada以外は1.5-2%フラットレートカードを使用。", "ko": "카테고리 외 $1.50당 1 포인트만 (~0.67배). 주유, 식료품, EV, Air Canada 외 구매는 1.5-2% 정률 카드 사용.", "zh": "非类别消费只有每$1.50获1积分（约0.67倍）。加油、超市、充电、Air Canada以外的消费建议用1.5-2%固定返还卡。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'AVOID', '{"en": "No Premium Perks", "es": "Sin beneficios premium", "fr": "Pas d''avantages premium", "ja": "プレミアム特典なし", "ko": "프리미엄 혜택 없음", "zh": "无高端权益"}', '{"en": "No free checked bags, no lounge access, no travel insurance. Upgrade to Aeroplan Visa Infinite for these perks ($139/year).", "es": "Sin equipaje gratis, acceso a salas VIP ni seguro de viaje. Actualiza a Aeroplan Visa Infinite para estos beneficios ($139/año).", "fr": "Pas de bagages gratuits, accès salon ou assurance voyage. Passez au Visa Infinite Aeroplan pour ces avantages (139 $/an).", "ja": "無料預け荷物、ラウンジアクセス、旅行保険なし。これらの特典にはAeroplan Visa Infinite（年$139）にアップグレード。", "ko": "무료 위탁 수하물, 라운지 이용, 여행 보험 없음. 이러한 혜택은 Aeroplan Visa Infinite로 업그레이드 (연 $139).", "zh": "无免费托运行李、无贵宾厅、无旅行保险。如需这些权益请升级到Aeroplan Visa Infinite（年费$139）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'BEST_USE', '{"en": "1x on Gas, Grocery, EV", "es": "1x gasolina, super, VE", "fr": "1x essence, épicerie, VÉ", "ja": "ガス/食料品/EV 1倍", "ko": "주유/식료품/EV 1배", "zh": "加油/超市/充电1倍"}', '{"en": "Earn 1 Aeroplan point per $1 on gas, groceries, and EV charging. Best categories for daily use on this no-fee card.", "es": "Gana 1 punto Aeroplan por $1 en gasolina, supermercado y carga VE. Mejores categorías para uso diario.", "fr": "Gagnez 1 point Aeroplan par 1 $ sur essence, épicerie et recharge VÉ. Meilleures catégories pour usage quotidien.", "ja": "ガス、食料品、EV充電で$1につき1 Aeroplanポイント獲得。年会費無料カードの日常利用に最適。", "ko": "주유, 식료품, EV 충전에서 $1당 1 Aeroplan 포인트 적립. 연회비 무료 카드의 일상 사용에 최적.", "zh": "加油、超市和电动车充电每消费$1获1 Aeroplan积分。无年费卡日常消费的最佳类别。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'BEST_USE', '{"en": "1x on Air Canada", "es": "1x Air Canada", "fr": "1x Air Canada", "ja": "Air Canada 1倍", "ko": "Air Canada 1배", "zh": "Air Canada 1倍"}', '{"en": "Earn 1 Aeroplan point per $1 on Air Canada purchases. Use this card for booking flights directly with Air Canada.", "es": "Gana 1 punto Aeroplan por $1 en Air Canada. Usa esta tarjeta para reservar vuelos con Air Canada.", "fr": "Gagnez 1 point Aeroplan par 1 $ chez Air Canada. Utilisez cette carte pour réserver des vols Air Canada.", "ja": "Air Canadaで$1につき1 Aerolanポイント獲得。Air Canadaでの航空券予約にこのカードを使用。", "ko": "Air Canada에서 $1당 1 Aeroplan 포인트 적립. Air Canada에서 직접 항공편 예약 시 이 카드 사용.", "zh": "Air Canada消费每$1获1 Aeroplan积分。用此卡直接在Air Canada预订机票。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Basic purchase protection against accidental damage or theft for 90 days after purchase.", "es": "Protección básica contra daños accidentales o robo por 90 días después de la compra.", "fr": "Protection de base contre dommages accidentels ou vol pendant 90 jours après l''achat.", "ja": "購入後90日間の基本的な偶発的損傷または盗難保護。", "ko": "구매 후 90일 동안 우발적 손상 또는 도난에 대한 기본 보호.", "zh": "购买后90天内基本的意外损坏或盗窃保障。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'PERK', '{"en": "No Annual Fee", "es": "Sin cuota anual", "fr": "Aucuns frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "无年费"}', '{"en": "No annual fee - the entry-level way to earn Aeroplan points. Great to keep long-term for credit history and ongoing earning.", "es": "Sin cuota anual - forma básica de ganar puntos Aeroplan. Ideal para mantener a largo plazo.", "fr": "Sans frais annuels - façon d''entrée de gamme pour gagner des points Aeroplan. Idéal à garder à long terme.", "ja": "年会費無料 - Aeroplanポイントを貯める入門カード。クレジット履歴と継続的な獲得のため長期保有に最適。", "ko": "연회비 무료 - Aeroplan 포인트를 적립하는 입문 카드. 신용 기록과 지속적인 적립을 위해 장기 보유에 적합.", "zh": "无年费 - 入门级Aeroplan积分卡。适合长期持有以积累信用记录和持续赚取积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'PERK', '{"en": "5,000 pts Anniversary Bonus", "es": "Bono aniversario 5,000 pts", "fr": "Bonus anniversaire 5 000 pts", "ja": "5,000ポイント周年ボーナス", "ko": "5,000 포인트 기념 보너스", "zh": "5,000积分周年奖励"}', '{"en": "Earn 5,000 Aeroplan points anniversary bonus when you spend $10,000 in your first 12 months. Worth ~$80 in flights!", "es": "Gana 5,000 puntos Aeroplan de bono aniversario al gastar $10,000 en 12 meses. ¡Valor ~$80 en vuelos!", "fr": "Gagnez 5 000 points Aeroplan en bonus anniversaire si vous dépensez 10 000 $ en 12 mois. Valeur ~80 $ en vols!", "ja": "初年度$10,000利用で5,000 Aeroplanポイント周年ボーナス獲得。フライトで約$80の価値！", "ko": "첫 12개월 $10,000 사용 시 5,000 Aeroplan 포인트 기념 보너스 적립. 항공권 ~$80 가치!", "zh": "首年消费$10,000可获5,000 Aeroplan积分周年奖励。价值约$80机票！"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'REDEMPTION', '{"en": "Aeroplan Flight Rewards", "es": "Vuelos Aeroplan", "fr": "Vols Aeroplan", "ja": "Aeroplan航空券", "ko": "Aeroplan 항공권", "zh": "Aeroplan机票兑换"}', '{"en": "Redeem points for flights on Air Canada and Star Alliance partners. Points worth ~1.6-2 cents each on flight redemptions.", "es": "Canjea puntos por vuelos en Air Canada y socios Star Alliance. Puntos valen ~1.6-2 centavos cada uno.", "fr": "Échangez des points pour des vols Air Canada et partenaires Star Alliance. Points valent ~1,6-2 ¢ chacun.", "ja": "Air CanadaとスターアライアンスパートナーのフライトにポイントTを交換。フライト交換で1ポイント約1.6-2セントの価値。", "ko": "Air Canada 및 스타 얼라이언스 파트너 항공편에 포인트 사용. 항공권 사용 시 포인트당 ~1.6-2센트 가치.", "zh": "用积分兑换Air Canada和星空联盟伙伴航班。机票兑换时积分价值约1.6-2分/点。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'REDEMPTION', '{"en": "Points + Cash Option", "es": "Opción Puntos + Efectivo", "fr": "Option Points + Argent", "ja": "ポイント+現金オプション", "ko": "포인트 + 현금 옵션", "zh": "积分+现金选项"}', '{"en": "Use Points + Cash to book flights even when you don''t have enough points. Pay partial cash to top up your point balance.", "es": "Usa Puntos + Efectivo para reservar aunque no tengas suficientes puntos. Paga parcialmente en efectivo.", "fr": "Utilisez Points + Argent pour réserver même sans assez de points. Payez en partie comptant pour compléter.", "ja": "ポイントが足りなくてもPoints + Cashでフライト予約可能。現金で一部支払いしてポイントを補充。", "ko": "포인트가 부족해도 Points + Cash로 항공편 예약 가능. 현금으로 일부 결제하여 포인트 보충.", "zh": "即使积分不够也可用积分+现金预订航班。用部分现金补足积分余额。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'STACKING', '{"en": "Pair with Premium Card", "es": "Combinar con tarjeta premium", "fr": "Combiner avec carte premium", "ja": "プレミアムカードと併用", "ko": "프리미엄 카드와 함께 사용", "zh": "搭配高端卡"}', '{"en": "Use this for gas/grocery earning, and pair with AMEX Aeroplan or TD Aeroplan Infinite for travel perks and higher earning rates.", "es": "Usa para gasolina/supermercado y combina con AMEX Aeroplan o TD Aeroplan Infinite para beneficios de viaje.", "fr": "Utilisez pour essence/épicerie et combinez avec AMEX Aeroplan ou TD Aeroplan Infinite pour avantages voyage.", "ja": "ガス/食料品の獲得に使用し、旅行特典と高い獲得率にはAMEX AeroplanまたはTD Aeroplan Infiniteと併用。", "ko": "주유/식료품 적립에 사용하고, 여행 혜택과 더 높은 적립률을 위해 AMEX Aeroplan 또는 TD Aeroplan Infinite와 함께 사용.", "zh": "用此卡赚取加油/超市积分，搭配AMEX Aeroplan或TD Aeroplan Infinite获得旅行权益和更高返还率。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Card'), 'STACKING', '{"en": "Earn & Fly with Aeroplan", "es": "Gana & Vuela con Aeroplan", "fr": "Gagnez & Volez Aeroplan", "ja": "Aeroplanで貯めて飛ぶ", "ko": "Aeroplan으로 적립 & 비행", "zh": "赚积分飞Aeroplan"}', '{"en": "Double-dip by showing Aeroplan membership when flying Air Canada, then earn card points on the purchase. Points combine in one account.", "es": "Gana doble mostrando tu membresía Aeroplan al volar Air Canada, luego gana puntos de la tarjeta. Los puntos se combinan.", "fr": "Double gain en montrant votre carte Aeroplan sur Air Canada, puis gagnez des points carte. Les points se combinent.", "ja": "Air Canada搭乗時にAeroplan会員カードを提示してダブル獲得、さらにカードポイントも獲得。ポイントは1つのアカウントに統合。", "ko": "Air Canada 탑승 시 Aeroplan 멤버십을 보여주고 카드 포인트도 적립. 포인트가 하나의 계정에 통합.", "zh": "乘坐Air Canada时出示Aeroplan会员卡可双重赚取积分，再用此卡消费赚取卡片积分。所有积分汇入同一账户。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'AVOID', '{"en": "$139 Fee After Year 1", "es": "$139 después del año 1", "fr": "139 $ après 1re année", "ja": "2年目以降$139年会費", "ko": "1년 후 $139 연회비", "zh": "第二年起$139年费"}', '{"en": "$139 annual fee kicks in after first year. Make sure you use the free checked bag (worth $140+) and spend enough to justify the fee.", "es": "Cuota de $139 después del primer año. Usa el equipaje gratis ($140+) y gasta suficiente para justificar la cuota.", "fr": "Frais de 139 $ après la 1re année. Utilisez le bagage gratuit (140 $+) et dépensez assez pour justifier les frais.", "ja": "2年目以降$139の年会費が発生。無料預け荷物（$140以上の価値）を活用し、年会費を正当化する消費を。", "ko": "첫해 후 $139 연회비 발생. 무료 위탁 수하물 ($140+ 가치) 활용하고 연회비를 정당화할 만큼 사용.", "zh": "首年后需支付$139年费。确保使用免费托运行李（价值$140+）并足够消费以抵消年费。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'AVOID', '{"en": "2026 Elite Status Changes", "es": "Cambios Élite 2026", "fr": "Changements Élite 2026", "ja": "2026年エリート変更", "ko": "2026 엘리트 상태 변경", "zh": "2026精英状态变更"}', '{"en": "Starting January 2026, Air Canada is changing Aeroplan Elite Status benefits for CIBC cards. Check latest terms before applying.", "es": "A partir de enero 2026, Air Canada cambia beneficios de Élite Aeroplan para tarjetas CIBC. Verifique términos antes de aplicar.", "fr": "À partir de janvier 2026, Air Canada modifie les avantages Élite Aeroplan pour cartes CIBC. Vérifiez les termes avant d''appliquer.", "ja": "2026年1月よりAir CanadaはCIBCカードのAeroplanエリート特典を変更。申請前に最新条件を確認。", "ko": "2026년 1월부터 Air Canada가 CIBC 카드의 Aeroplan 엘리트 상태 혜택 변경. 신청 전 최신 조건 확인.", "zh": "2026年1月起，Air Canada将更改CIBC卡的Aeroplan精英状态权益。申请前请查看最新条款。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'BEST_USE', '{"en": "1.5x on Gas, Grocery, AC", "es": "1.5x gasolina, super, AC", "fr": "1,5x essence, épicerie, AC", "ja": "ガス/食料品/AC 1.5倍", "ko": "주유/식료품/AC 1.5배", "zh": "加油/超市/AC 1.5倍"}', '{"en": "Earn 1.5 Aeroplan points per $1 on gas, groceries, and Air Canada purchases. Use for all everyday spending in these categories.", "es": "Gana 1.5 puntos Aeroplan por $1 en gasolina, supermercado y Air Canada. Usa para gastos diarios.", "fr": "Gagnez 1,5 point Aeroplan par 1 $ sur essence, épicerie et Air Canada. Utilisez pour dépenses quotidiennes.", "ja": "ガス、食料品、Air Canadaで$1につき1.5 Aeroplanポイント獲得。日常消費に最適。", "ko": "주유, 식료품, Air Canada에서 $1당 1.5 Aeroplan 포인트 적립. 일상 지출에 사용.", "zh": "加油、超市和Air Canada消费每$1获1.5 Aeroplan积分。日常消费首选这些类别。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'INSURANCE', '{"en": "Travel Insurance", "es": "Seguro de viaje", "fr": "Assurance voyage", "ja": "旅行保険", "ko": "여행 보험", "zh": "旅行保险"}', '{"en": "Includes trip cancellation/interruption, baggage delay, flight delay, and emergency medical coverage when you pay for travel with the card.", "es": "Incluye cancelación/interrupción de viaje, retraso de equipaje, retraso de vuelo y cobertura médica de emergencia.", "fr": "Comprend annulation/interruption voyage, retard bagages, retard vol et couverture médicale d''urgence.", "ja": "カードで旅行代金を支払うと、旅行キャンセル/中断、手荷物遅延、フライト遅延、緊急医療保障が含まれます。", "ko": "카드로 여행 결제 시 여행 취소/중단, 수하물 지연, 항공편 지연, 긴급 의료 보장 포함.", "zh": "用卡支付旅行时包含行程取消/中断、行李延误、航班延误和紧急医疗保障。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Purchase protection for 90 days against damage/theft. Extended warranty doubles manufacturer warranty up to 1 year.", "es": "Protección de compras 90 días contra daños/robo. Garantía extendida duplica garantía del fabricante hasta 1 año.", "fr": "Protection achats 90 jours contre dommages/vol. Garantie prolongée double la garantie fabricant jusqu''à 1 an.", "ja": "90日間の購入保護（損傷/盗難）。延長保証でメーカー保証を最大1年延長。", "ko": "90일 구매 보호 (손상/도난). 연장 보증으로 제조사 보증 최대 1년 연장.", "zh": "90天购物保障防损坏/盗窃。延长保修将制造商保修延长最多1年。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "First Year Free", "es": "Primer año gratis", "fr": "1re année gratuite", "ja": "初年度無料", "ko": "첫해 무료", "zh": "首年免年费"}', '{"en": "First year annual fee waived ($139 value). Also $50 rebate per authorized user (up to 3). Total up to $289 in fee savings!", "es": "Cuota anual primer año gratis ($139). $50 por usuario autorizado (máx 3). ¡Hasta $289 en ahorros!", "fr": "Frais annuels 1re année gratuits (139 $). 50 $ par utilisateur autorisé (max 3). Jusqu''à 289 $ d''économies!", "ja": "初年度年会費無料（$139相当）。追加カード1枚$50返金（最大3枚）。最大$289節約！", "ko": "첫해 연회비 무료 ($139 가치). 추가 사용자당 $50 환급 (최대 3명). 총 최대 $289 절약!", "zh": "首年免$139年费。附属卡每张返还$50（最多3张）。总计最高节省$289！"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "25K Anniversary Bonus", "es": "Bono aniversario 25K", "fr": "Bonus anniversaire 25K", "ja": "25K周年ボーナス", "ko": "25K 기념 보너스", "zh": "25K周年奖励"}', '{"en": "Earn 25,000 Aeroplan points anniversary bonus when you spend $12,000 in your first 12 months. Worth ~$400 in flights!", "es": "Gana 25,000 puntos aniversario al gastar $12,000 en 12 meses. ¡Valor ~$400 en vuelos!", "fr": "Gagnez 25 000 points anniversaire si vous dépensez 12 000 $ en 12 mois. Valeur ~400 $ en vols!", "ja": "初年度$12,000利用で25,000ポイント周年ボーナス獲得。フライトで約$400の価値！", "ko": "첫 12개월 $12,000 사용 시 25,000 포인트 기념 보너스 적립. 항공권 ~$400 가치!", "zh": "首年消费$12,000可获25,000 Aeroplan积分周年奖励。价值约$400机票！"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'REDEMPTION', '{"en": "Aeroplan Flight Rewards", "es": "Vuelos Aeroplan", "fr": "Vols Aeroplan", "ja": "Aeroplan航空券", "ko": "Aeroplan 항공권", "zh": "Aeroplan机票兑换"}', '{"en": "Redeem for flights on Air Canada and 40+ Star Alliance partners. Points worth ~1.6-2 cents each. Use Points + Cash if short.", "es": "Canjea por vuelos en Air Canada y 40+ socios Star Alliance. Puntos valen ~1.6-2¢. Usa Points + Cash si faltan.", "fr": "Échangez pour vols Air Canada et 40+ partenaires Star Alliance. Points valent ~1,6-2 ¢. Utilisez Points + Argent si insuffisant.", "ja": "Air Canadaと40以上のスターアライアンスパートナーのフライトに交換。ポイントは約1.6-2セント/pt。Points + Cashも利用可能。", "ko": "Air Canada 및 40개 이상의 스타 얼라이언스 파트너 항공편에 사용. 포인트당 ~1.6-2센트 가치. 부족 시 Points + Cash 사용.", "zh": "可兑换Air Canada和40+星空联盟伙伴航班。积分价值约1.6-2分/点。积分不足时可用Points + Cash。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'STACKING', '{"en": "Pair with AMEX Aeroplan", "es": "Combinar con AMEX Aeroplan", "fr": "Combiner avec AMEX Aeroplan", "ja": "AMEX Aeroplanと併用", "ko": "AMEX Aeroplan과 함께 사용", "zh": "搭配AMEX Aeroplan"}', '{"en": "Use this CIBC card for grocery/gas (1.5x) and free checked bags. Pair with AMEX Aeroplan for dining (2x) and travel (3x).", "es": "Usa esta CIBC para supermercado/gasolina (1.5x) y equipaje gratis. Combina con AMEX Aeroplan para comida (2x) y viaje (3x).", "fr": "Utilisez cette carte CIBC pour épicerie/essence (1,5x) et bagages gratuits. Combinez avec AMEX Aeroplan pour resto (2x) et voyage (3x).", "ja": "このCIBCカードを食料品/ガス（1.5倍）と無料荷物に使用。AMEX Aeroplanを飲食（2倍）と旅行（3倍）に併用。", "ko": "이 CIBC 카드를 식료품/주유 (1.5배) 및 무료 수하물에 사용. AMEX Aeroplan을 식당 (2배) 및 여행 (3배)에 함께 사용.", "zh": "用此CIBC卡赚取超市/加油（1.5倍）和免费托运行李。搭配AMEX Aeroplan赚取餐饮（2倍）和旅行（3倍）。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'STACKING', '{"en": "Earn & Fly with Aeroplan", "es": "Gana & Vuela con Aeroplan", "fr": "Gagnez & Volez Aeroplan", "ja": "Aeroplanで貯めて飛ぶ", "ko": "Aeroplan으로 적립 & 비행", "zh": "赚积分飞Aeroplan"}', '{"en": "Triple-dip: Show Aeroplan membership when flying + earn card points on purchase + get free checked bag. All points combine!", "es": "Triple ganancia: muestra Aeroplan al volar + gana puntos de tarjeta + equipaje gratis. ¡Todos los puntos se combinan!", "fr": "Triple gain : montrez Aeroplan en vol + gagnez points carte + bagage gratuit. Tous les points se combinent!", "ja": "トリプル獲得：搭乗時Aeroplan提示 + カードポイント獲得 + 無料預け荷物。全ポイント統合！", "ko": "트리플 적립: 탑승 시 Aeroplan 제시 + 카드 포인트 적립 + 무료 위탁 수하물. 모든 포인트 통합!", "zh": "三重赚取：飞行时出示Aeroplan会员卡 + 消费获卡片积分 + 免费托运行李。所有积分合并！"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aeroplan Visa Infinite'), 'TRAVEL_BENEFIT', '{"en": "Free Checked Bag", "es": "Equipaje facturado gratis", "fr": "Bagage enregistré gratuit", "ja": "無料預け荷物", "ko": "무료 위탁 수하물", "zh": "免费托运行李"}', '{"en": "Get first checked bag free on Air Canada flights for you and up to 8 companions on same booking. Worth $70+ per round trip!", "es": "Primera maleta gratis en Air Canada para ti y hasta 8 acompañantes. ¡Valor $70+ por viaje redondo!", "fr": "Premier bagage gratuit sur Air Canada pour vous et jusqu''à 8 compagnons. Valeur 70 $+ par aller-retour!", "ja": "Air Canadaで最初の預け荷物無料、同伴者8名まで対象。往復$70以上の価値！", "ko": "Air Canada에서 본인과 동반자 최대 8명까지 첫 번째 위탁 수하물 무료. 왕복 $70+ 가치!", "zh": "乘坐Air Canada时您和同行最多8人可免费托运首件行李。往返价值$70+！"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'AVOID', '{"en": "$139 Annual Fee", "es": "$139 cuota anual", "fr": "139 $ frais annuels", "ja": "$139年会費", "ko": "$139 연회비", "zh": "$139年费"}', '{"en": "$139 annual fee applies. Make sure you use the 4 lounge visits ($160+ value) and NEXUS discount ($160) to offset the fee.", "es": "Cuota anual $139. Usa las 4 visitas a salas VIP ($160+) y descuento NEXUS ($160) para compensar.", "fr": "Frais annuels de 139 $. Utilisez les 4 visites salon (160 $+) et le rabais NEXUS (160 $) pour compenser.", "ja": "年会費$139。4回ラウンジ訪問（$160以上）とNEXUS割引（$160）で相殺を。", "ko": "연회비 $139. 4회 라운지 방문 ($160+ 가치)과 NEXUS 할인 ($160)으로 연회비 상쇄.", "zh": "年费$139。确保使用4次贵宾厅（$160+价值）和NEXUS折扣（$160）来抵消年费。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'AVOID', '{"en": "Lower Point Value", "es": "Valor de puntos menor", "fr": "Valeur points plus basse", "ja": "ポイント価値が低い", "ko": "포인트 가치 낮음", "zh": "积分价值较低"}', '{"en": "Aventura points worth ~1 cent each, less than Aeroplan (~1.6-2 cents). If you fly often, consider Aeroplan cards instead.", "es": "Puntos Aventura valen ~1¢ cada uno, menos que Aeroplan (~1.6-2¢). Si vuela seguido, considere Aeroplan.", "fr": "Points Aventura valent ~1 ¢ chacun, moins que Aeroplan (~1,6-2 ¢). Si vous voyagez souvent, considérez Aeroplan.", "ja": "Aventuraポイントは1ポイント約1セント、Aeroplan（約1.6-2セント）より低い。頻繁に飛ぶならAeroplanカードを検討。", "ko": "Aventura 포인트는 약 1센트, Aeroplan (약 1.6-2센트)보다 낮음. 자주 비행하면 Aeroplan 카드 고려.", "zh": "Aventura积分每点约1分钱，低于Aeroplan（约1.6-2分钱）。如果经常飞行，考虑Aeroplan卡。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'BEST_USE', '{"en": "2x via CIBC Rewards", "es": "2x vía CIBC Rewards", "fr": "2x via CIBC Rewards", "ja": "CIBC Rewards経由2倍", "ko": "CIBC Rewards 2배", "zh": "CIBC Rewards 2倍"}', '{"en": "Earn 2 Aventura points per $1 when booking travel through CIBC Rewards Centre. Best rate for flights, hotels, and car rentals.", "es": "Gana 2 puntos Aventura por $1 reservando en CIBC Rewards Centre. Mejor tasa para vuelos, hoteles y autos.", "fr": "Gagnez 2 points Aventura par 1 $ via CIBC Rewards Centre. Meilleur taux pour vols, hôtels et locations.", "ja": "CIBC Rewards Centre経由で$1につき2 Aventuraポイント獲得。航空券、ホテル、レンタカーに最適。", "ko": "CIBC Rewards Centre에서 예약 시 $1당 2 Aventura 포인트 적립. 항공권, 호텔, 렌터카에 최적.", "zh": "通过CIBC Rewards Centre预订旅行每$1获2 Aventura积分。机票、酒店、租车的最佳返还率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'BEST_USE', '{"en": "1.5x Gas, Grocery, Pharmacy", "es": "1.5x gasolina, super, farmacia", "fr": "1,5x essence, épicerie, pharma", "ja": "ガス/食料品/薬局 1.5倍", "ko": "주유/식료품/약국 1.5배", "zh": "加油/超市/药房 1.5倍"}', '{"en": "Earn 1.5 Aventura points per $1 on gas, EV charging, groceries, and drugstores. Great for everyday spending.", "es": "Gana 1.5 puntos Aventura por $1 en gasolina, carga VE, supermercado y farmacias. Ideal para gastos diarios.", "fr": "Gagnez 1,5 points Aventura par 1 $ sur essence, recharge VÉ, épicerie et pharmacies. Idéal pour dépenses quotidiennes.", "ja": "ガス、EV充電、食料品、薬局で$1につき1.5 Aventuraポイント獲得。日常消費に最適。", "ko": "주유, EV 충전, 식료품, 약국에서 $1당 1.5 Aventura 포인트 적립. 일상 지출에 적합.", "zh": "加油、电动车充电、超市和药店每$1获1.5 Aventura积分。日常消费首选。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'INSURANCE', '{"en": "Travel Insurance", "es": "Seguro de viaje", "fr": "Assurance voyage", "ja": "旅行保険", "ko": "여행 보험", "zh": "旅行保险"}', '{"en": "Includes trip cancellation/interruption, emergency medical, baggage delay, and flight delay coverage when paying with the card.", "es": "Incluye cancelación/interrupción, emergencia médica, retraso equipaje y vuelo al pagar con la tarjeta.", "fr": "Comprend annulation/interruption voyage, urgence médicale, retard bagages et vol en payant avec la carte.", "ja": "カード支払いで旅行キャンセル/中断、緊急医療、手荷物遅延、フライト遅延保障が含まれます。", "ko": "카드로 결제 시 여행 취소/중단, 긴급 의료, 수하물 지연, 항공편 지연 보장 포함.", "zh": "用卡支付时包含行程取消/中断、紧急医疗、行李延误和航班延误保障。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Purchase protection for 90 days against damage/theft. Extended warranty doubles manufacturer warranty up to 1 year.", "es": "Protección de compras 90 días contra daños/robo. Garantía extendida duplica garantía del fabricante hasta 1 año.", "fr": "Protection achats 90 jours contre dommages/vol. Garantie prolongée double la garantie fabricant jusqu''à 1 an.", "ja": "90日間の購入保護（損傷/盗難）。延長保証でメーカー保証を最大1年延長。", "ko": "90일 구매 보호 (손상/도난). 연장 보증으로 제조사 보증 최대 1년 연장.", "zh": "90天购物保障防损坏/盗窃。延长保修将制造商保修延长最多1年。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'PERK', '{"en": "$160 NEXUS Discount", "es": "Descuento NEXUS $160", "fr": "Rabais NEXUS 160 $", "ja": "NEXUS$160割引", "ko": "NEXUS $160 할인", "zh": "$160 NEXUS折扣"}', '{"en": "Get $160 statement credit for NEXUS application fee. NEXUS gives you expedited border crossing between Canada and US.", "es": "Crédito de $160 para solicitud NEXUS. NEXUS permite cruce rápido de frontera Canadá-EE.UU.", "fr": "Crédit de 160 $ pour frais NEXUS. NEXUS permet passage accéléré à la frontière Canada-É.-U.", "ja": "NEXUS申請費用に$160クレジット。NEXUSでカナダ・米国国境を迅速通過。", "ko": "NEXUS 신청비 $160 크레딧. NEXUS로 캐나다-미국 국경 신속 통과.", "zh": "NEXUS申请费可获$160账单抵扣。NEXUS让您快速通过加美边境。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'REDEMPTION', '{"en": "Flexible Travel Redemption", "es": "Canje de viaje flexible", "fr": "Échange voyage flexible", "ja": "柔軟な旅行交換", "ko": "유연한 여행 사용", "zh": "灵活旅行兑换"}', '{"en": "Redeem Aventura points for flights, hotels, car rentals, and vacation packages via CIBC Rewards Centre. ~1 cent per point value.", "es": "Canjea puntos Aventura por vuelos, hoteles, autos y paquetes vía CIBC Rewards Centre. ~1¢ por punto.", "fr": "Échangez points Aventura pour vols, hôtels, locations et forfaits via CIBC Rewards Centre. ~1 ¢ par point.", "ja": "CIBC Rewards CentreでAventuraポイントを航空券、ホテル、レンタカー、旅行パッケージに交換。1ポイント約1セント。", "ko": "CIBC Rewards Centre에서 Aventura 포인트를 항공권, 호텔, 렌터카, 여행 패키지에 사용. 포인트당 ~1센트 가치.", "zh": "通过CIBC Rewards Centre用Aventura积分兑换机票、酒店、租车和度假套餐。每点约1分钱价值。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'STACKING', '{"en": "Book via CIBC Rewards", "es": "Reserve vía CIBC Rewards", "fr": "Réservez via CIBC Rewards", "ja": "CIBC Rewardsで予約", "ko": "CIBC Rewards로 예약", "zh": "通过CIBC Rewards预订"}', '{"en": "Always book travel through CIBC Rewards Centre to get 2x instead of 1x. Compare prices - sometimes it matches or beats online rates.", "es": "Reserve siempre vía CIBC Rewards Centre para 2x en vez de 1x. Compare precios - a veces iguala o supera tarifas online.", "fr": "Réservez toujours via CIBC Rewards Centre pour 2x au lieu de 1x. Comparez les prix - parfois égaux ou meilleurs en ligne.", "ja": "CIBC Rewards Centreで旅行を予約して1xではなく2x獲得。価格比較を - オンライン料金と同等または有利な場合も。", "ko": "CIBC Rewards Centre에서 여행 예약하여 1x 대신 2x 적립. 가격 비교 - 때때로 온라인 요금과 같거나 더 좋을 수 있음.", "zh": "始终通过CIBC Rewards Centre预订旅行以获得2倍而非1倍积分。比较价格 - 有时可匹配或优于在线价格。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'STACKING', '{"en": "Pair with Cashback Card", "es": "Combinar con tarjeta cashback", "fr": "Combiner avec carte remise", "ja": "キャッシュバックカードと併用", "ko": "캐시백 카드와 함께 사용", "zh": "搭配返现卡"}', '{"en": "Use Aventura for travel (2x) and lounge access. Pair with a 4-5% grocery card for higher everyday returns on food spending.", "es": "Usa Aventura para viaje (2x) y salas VIP. Combina con tarjeta 4-5% supermercado para mejores retornos diarios.", "fr": "Utilisez Aventura pour voyage (2x) et salons. Combinez avec carte épicerie 4-5 % pour meilleurs retours quotidiens.", "ja": "Aventuraを旅行（2倍）とラウンジに使用。4-5%食料品カードと併用して日常の食品支出で高いリターンを。", "ko": "Aventura를 여행 (2배) 및 라운지에 사용. 4-5% 식료품 카드와 함께 사용하여 일상 식품 지출에 높은 수익.", "zh": "用Aventura赚取旅行（2倍）和贵宾厅。搭配4-5%超市卡获得更高的日常食品消费回报。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite'), 'TRAVEL_BENEFIT', '{"en": "4 Lounge Visits/Year", "es": "4 visitas salas VIP/año", "fr": "4 visites salon/an", "ja": "年4回ラウンジ", "ko": "연 4회 라운지", "zh": "每年4次贵宾厅"}', '{"en": "Get 4 complimentary airport lounge visits per year via Priority Pass or Mastercard Airport Experiences. Worth ~$40+ per visit.", "es": "4 visitas a salas VIP gratis por año vía Priority Pass o Mastercard Airport Experiences. Valor ~$40+ por visita.", "fr": "4 visites salon gratuites par an via Priority Pass ou Mastercard Airport Experiences. Valeur ~40 $+ par visite.", "ja": "Priority PassまたはMastercard Airport Experiencesで年4回空港ラウンジ無料。1回あたり約$40以上の価値。", "ko": "Priority Pass 또는 Mastercard Airport Experiences로 연 4회 무료 공항 라운지. 방문당 ~$40+ 가치.", "zh": "每年通过Priority Pass或Mastercard Airport Experiences享受4次免费机场贵宾厅。每次价值约$40+。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'AVOID', '{"en": "High Fee Requires Travel Use", "es": "Cuota alta requiere viajes", "fr": "Frais élevés exigent voyages", "ja": "高い年会費には旅行利用が必要", "ko": "높은 연회비는 여행 사용 필요", "zh": "高年费需旅行消费"}', '{"en": "The $499 annual fee is steep. After $200 travel credit, you pay $299 net. You need to use lounge visits, insurance, and earn significant points to justify the cost.", "es": "La cuota anual de $499 es alta. Después del crédito de $200, pagas $299 neto. Necesitas usar salas VIP y seguro para justificar el costo.", "fr": "Les frais annuels de 499 $ sont élevés. Après le crédit de 200 $, vous payez 299 $ net. Utilisez les salons et l''assurance pour justifier le coût.", "ja": "$499の年会費は高い。$200旅行クレジット後、正味$299支払い。ラウンジ、保険を活用し、十分なポイントを獲得してコストを正当化する必要あり。", "ko": "$499 연회비는 높습니다. $200 여행 크레딧 후 순 $299 지불. 라운지 방문, 보험을 활용하고 충분한 포인트를 적립해야 비용이 정당화됩니다.", "zh": "$499年费较高。扣除$200旅行抵扣后净付$299。需要使用贵宾厅、保险并赚取大量积分才能值回票价。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'BEST_USE', '{"en": "3x via CIBC Rewards", "es": "3x vía CIBC Rewards", "fr": "3x via CIBC Rewards", "ja": "CIBC Rewards経由3倍", "ko": "CIBC Rewards 3배", "zh": "CIBC Rewards 3倍"}', '{"en": "Earn 3 Aventura points per $1 when booking travel through CIBC Rewards Centre. Best-in-class rate for flights, hotels, and car rentals.", "es": "Gana 3 puntos Aventura por $1 reservando en CIBC Rewards Centre. Tasa premium para vuelos, hoteles y autos.", "fr": "Gagnez 3 points Aventura par 1 $ via CIBC Rewards Centre. Taux de première classe pour vols, hôtels et locations.", "ja": "CIBC Rewards Centre経由で$1につき3 Aventuraポイント獲得。航空券、ホテル、レンタカーに最高クラス。", "ko": "CIBC Rewards Centre에서 예약 시 $1당 3 Aventura 포인트 적립. 항공권, 호텔, 렌터카에 최상위 적립률.", "zh": "通过CIBC Rewards Centre预订旅行每$1获3 Aventura积分。机票、酒店、租车的顶级返还率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'BEST_USE', '{"en": "2x on Everyday Spending", "es": "2x en gastos diarios", "fr": "2x sur dépenses courantes", "ja": "日常消費 2倍", "ko": "일상 지출 2배", "zh": "日常消费 2倍"}', '{"en": "Earn 2 Aventura points per $1 on gas, EV charging, groceries, dining, and drugstores. Premium rate for all everyday categories.", "es": "Gana 2 puntos Aventura por $1 en gasolina, carga VE, supermercado, restaurantes y farmacias. Tasa premium en todas las categorías.", "fr": "Gagnez 2 points Aventura par 1 $ sur essence, recharge VÉ, épicerie, restaurants et pharmacies. Taux premium pour toutes catégories.", "ja": "ガス、EV充電、食料品、ダイニング、薬局で$1につき2 Aventuraポイント獲得。全日常カテゴリでプレミアムレート。", "ko": "주유, EV 충전, 식료품, 식당, 약국에서 $1당 2 Aventura 포인트 적립. 모든 일상 카테고리에서 프리미엄 적립률.", "zh": "加油、电动车充电、超市、餐饮和药店每$1获2 Aventura积分。所有日常类别的高端返还率。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'BEST_USE', '{"en": "Always Book via CIBC", "es": "Siempre reservar vía CIBC", "fr": "Toujours réserver via CIBC", "ja": "常にCIBC経由で予約", "ko": "항상 CIBC 경유 예약", "zh": "始终通过CIBC预订"}', '{"en": "Always book travel through CIBC Rewards Centre to get 3x points AND access the $200 travel credit. Booking elsewhere means 1.25x base rate only.", "es": "Siempre reserva vía CIBC Rewards Centre para 3x puntos Y acceso al crédito de $200. Reservar en otro lugar = solo tasa base 1.25x.", "fr": "Réservez toujours via CIBC Rewards Centre pour 3x points ET accès au crédit de 200 $. Réserver ailleurs = taux de base 1,25x seulement.", "ja": "常にCIBC Rewards Centre経由で予約し、3倍ポイントと$200旅行クレジットを獲得。他で予約すると1.25倍の基本レートのみ。", "ko": "항상 CIBC Rewards Centre에서 예약하여 3배 포인트 및 $200 여행 크레딧 이용. 다른 곳에서 예약하면 1.25배 기본 적립률만 적용.", "zh": "始终通过CIBC Rewards Centre预订旅行以获得3倍积分和$200旅行抵扣。在其他地方预订只能获得1.25倍基础积分。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'INSURANCE', '{"en": "Premium Travel Insurance", "es": "Seguro de viaje premium", "fr": "Assurance voyage premium", "ja": "プレミアム旅行保険", "ko": "프리미엄 여행 보험", "zh": "高端旅行保险"}', '{"en": "Includes up to 25 days emergency medical ($5M), trip cancellation ($2,500), delayed baggage ($1,000), and rental car collision. Among the best insurance packages.", "es": "Incluye hasta 25 días de emergencia médica ($5M), cancelación ($2,500), equipaje retrasado ($1,000) y colisión de alquiler. Uno de los mejores paquetes.", "fr": "Inclut jusqu''à 25 jours d''urgence médicale (5 M$), annulation (2 500 $), bagages retardés (1 000 $) et collision auto. L''un des meilleurs forfaits.", "ja": "最大25日間の緊急医療($500万)、旅行キャンセル($2,500)、手荷物遅延($1,000)、レンタカー衝突保険付き。最高クラスの保険パッケージ。", "ko": "최대 25일 응급 의료($500만), 여행 취소($2,500), 수하물 지연($1,000), 렌터카 충돌 보험 포함. 최고 수준의 보험 패키지.", "zh": "包含最多25天紧急医疗($500万)、行程取消($2,500)、行李延误($1,000)和租车碰撞险。顶级保险套餐。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'PERK', '{"en": "$200 Annual Travel Credit", "es": "Crédito viaje $200/año", "fr": "Crédit voyage 200 $/an", "ja": "年間$200旅行クレジット", "ko": "연간 $200 여행 크레딧", "zh": "每年$200旅行抵扣"}', '{"en": "Receive $200 annual travel credit when booking through CIBC Rewards Centre. Offsets a significant portion of the $499 annual fee.", "es": "Recibe $200 de crédito de viaje anual al reservar vía CIBC Rewards Centre. Compensa parte de la cuota anual de $499.", "fr": "Recevez 200 $ de crédit voyage annuel en réservant via CIBC Rewards Centre. Compense une partie des frais annuels de 499 $.", "ja": "CIBC Rewards Centre経由予約で年間$200旅行クレジット獲得。$499年会費の大部分を相殺。", "ko": "CIBC Rewards Centre에서 예약 시 연간 $200 여행 크레딧 제공. $499 연회비의 상당 부분 상쇄.", "zh": "通过CIBC Rewards Centre预订可获得每年$200旅行抵扣。抵消$499年费的很大一部分。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'PERK', '{"en": "$200 NEXUS Rebate", "es": "Reembolso NEXUS $200", "fr": "Remboursement NEXUS 200 $", "ja": "$200 NEXUS払戻", "ko": "$200 NEXUS 환급", "zh": "$200 NEXUS返款"}', '{"en": "Get up to $200 rebate on NEXUS application fee ($120 CAD) and Global Entry ($120 USD). Covers trusted traveler program costs for faster border crossings.", "es": "Obtén hasta $200 de reembolso en NEXUS ($120 CAD) y Global Entry ($120 USD). Cubre programas de viajero de confianza.", "fr": "Obtenez jusqu''à 200 $ de remboursement sur NEXUS (120 $ CAD) et Global Entry (120 $ USD). Couvre les programmes de voyageur de confiance.", "ja": "NEXUS申請料($120 CAD)とGlobal Entry($120 USD)で最大$200リベート。信頼旅行者プログラム費用をカバー。", "ko": "NEXUS 신청비($120 CAD) 및 Global Entry($120 USD)에 최대 $200 환급. 신뢰 여행자 프로그램 비용 지원.", "zh": "NEXUS申请费($120 CAD)和Global Entry($120 USD)最高返还$200。覆盖可信旅客计划费用，享受快速通关。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'PERK', '{"en": "Mobile Device Protection", "es": "Protección dispositivo móvil", "fr": "Protection appareil mobile", "ja": "モバイルデバイス保護", "ko": "모바일 기기 보호", "zh": "手机保护"}', '{"en": "Covers damage or theft of your mobile phone up to $1,000 per claim when you pay your monthly bill with this card. $50 deductible.", "es": "Cubre daños o robo de tu teléfono hasta $1,000 por reclamo al pagar tu factura mensual con esta tarjeta. Deducible de $50.", "fr": "Couvre les dommages ou le vol de votre téléphone jusqu''à 1 000 $ par réclamation si vous payez votre facture avec cette carte. Franchise 50 $.", "ja": "このカードで月額料金を支払うと、携帯電話の破損や盗難を請求あたり最大$1,000までカバー。$50控除。", "ko": "이 카드로 월 요금을 결제하면 휴대폰 손상 또는 도난 시 청구당 최대 $1,000 보장. $50 공제.", "zh": "使用此卡支付每月账单后，手机损坏或被盗可获最高$1,000赔付。$50免赔额。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'REDEMPTION', '{"en": "Flexible Redemption Options", "es": "Opciones de canje flexibles", "fr": "Options échange flexibles", "ja": "柔軟な交換オプション", "ko": "유연한 교환 옵션", "zh": "灵活兑换选项"}', '{"en": "Redeem Aventura points for any travel (1 pt = 1 cent via CIBC), statement credits, gift cards, or merchandise. No blackout dates on CIBC Rewards bookings.", "es": "Canjea puntos Aventura por viajes (1 pt = 1 centavo vía CIBC), créditos, tarjetas regalo o mercancía. Sin fechas restringidas.", "fr": "Échangez les points Aventura contre voyages (1 pt = 1 cent via CIBC), crédits, cartes-cadeaux ou marchandises. Aucune date d''interdiction.", "ja": "Aventuraポイントを旅行(CIBC経由で1pt=1セント)、明細クレジット、ギフトカード、商品に交換。ブラックアウト日なし。", "ko": "Aventura 포인트를 여행(CIBC 경유 1pt = 1센트), 명세서 크레딧, 기프트 카드, 상품으로 교환. 블랙아웃 날짜 없음.", "zh": "Aventura积分可兑换任意旅行(1积分=1分通过CIBC)、账单抵扣、礼品卡或商品。CIBC Rewards预订无黑日期。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'STACKING', '{"en": "Pair with Infinite for Family", "es": "Combinar con Infinite", "fr": "Combiner avec Infinite", "ja": "Infiniteとペアで家族用", "ko": "Infinite와 가족용 조합", "zh": "搭配Infinite家庭卡"}', '{"en": "Add the lower-fee Aventura Infinite ($139) for family members. Points combine in one account with 10 free Priority Pass lounge visits total for the household.", "es": "Agrega la Aventura Infinite ($139) más económica para familiares. Los puntos se combinan con 10 visitas de sala Priority Pass en total.", "fr": "Ajoutez l''Aventura Infinite ($139) moins cher pour la famille. Les points se combinent avec 10 visites salon Priority Pass au total.", "ja": "家族向けに年会費の低いAventura Infinite($139)を追加。ポイントは1つのアカウントに統合、家庭全体で合計10回のPriority Passラウンジ訪問。", "ko": "가족을 위해 저렴한 연회비의 Aventura Infinite($139) 추가. 포인트가 하나의 계정에 결합되며 가정 전체에 총 10회 Priority Pass 라운지 방문.", "zh": "为家人添加低年费Aventura Infinite($139)。积分合并到一个账户，全家共享10次免费Priority Pass贵宾厅。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Aventura Visa Infinite Privilege'), 'TRAVEL_BENEFIT', '{"en": "6 Lounge Visits/Year", "es": "6 visitas salas VIP/año", "fr": "6 visites salon/an", "ja": "年6回ラウンジ", "ko": "연 6회 라운지", "zh": "每年6次贵宾厅"}', '{"en": "Get 6 complimentary airport lounge visits per year via Priority Pass. Worth ~$250+ per year. More visits than the regular Infinite card.", "es": "6 visitas a salas VIP gratis por año vía Priority Pass. Valor ~$250+ por año. Más que la tarjeta Infinite estándar.", "fr": "6 visites salon gratuites par an via Priority Pass. Valeur ~250 $+ par an. Plus que la carte Infinite standard.", "ja": "Priority Passで年6回空港ラウンジ無料。年間約$250以上の価値。通常のInfiniteカードより多い。", "ko": "Priority Pass로 연 6회 무료 공항 라운지. 연간 ~$250+ 가치. 일반 Infinite 카드보다 많은 방문 횟수.", "zh": "每年通过Priority Pass享受6次免费机场贵宾厅。每年价值约$250+。比普通Infinite卡多2次。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'AVOID', '{"en": "In-Store Costco is 1%", "es": "Costco en tienda 1%", "fr": "Costco en magasin 1 %", "ja": "Costco店内は1%", "ko": "Costco 매장 내 1%", "zh": "Costco店内仅1%"}', '{"en": "Surprisingly, in-warehouse Costco purchases only earn 1% (base rate). Consider other cards for large in-store purchases if you have better options.", "es": "Sorprendentemente, las compras en tienda Costco solo ganan 1% (tasa base). Considera otras tarjetas para compras grandes.", "fr": "Étonnamment, les achats en entrepôt Costco ne rapportent que 1 % (taux de base). Considérez d''autres cartes pour gros achats.", "ja": "意外にもCostco店内購入は1%（基本レート）のみ。大きな店内購入には他のカードを検討。", "ko": "놀랍게도 Costco 매장 내 구매는 1%(기본 적립률)만 적립. 큰 매장 구매에는 다른 카드 고려.", "zh": "令人意外的是，Costco店内消费仅返1%（基础费率）。如果你有更好的卡，可考虑用于大额店内消费。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'AVOID', '{"en": "Requires Costco Membership", "es": "Requiere membresía Costco", "fr": "Abonnement Costco requis", "ja": "Costco会員必須", "ko": "Costco 회원권 필요", "zh": "需要Costco会员"}', '{"en": "You must have an active Costco membership ($65 Gold Star or $130 Executive) to apply and use this card. Card is cancelled if membership lapses.", "es": "Debes tener una membresía Costco activa ($65 Gold Star o $130 Executive) para solicitar y usar esta tarjeta. Tarjeta cancelada si la membresía caduca.", "fr": "Vous devez avoir un abonnement Costco actif (65 $ Gold Star ou 130 $ Executive) pour demander et utiliser cette carte. Carte annulée si abonnement expire.", "ja": "このカードの申請と使用にはアクティブなCostco会員資格($65 Gold Starまたは$130 Executive)が必要。会員資格が失効するとカードはキャンセル。", "ko": "이 카드를 신청하고 사용하려면 활성 Costco 회원권($65 Gold Star 또는 $130 Executive)이 필요. 회원권이 만료되면 카드 취소.", "zh": "必须拥有有效Costco会员资格($65 Gold Star或$130 Executive)才能申请和使用此卡。会员资格失效卡片将被取消。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'BEST_USE', '{"en": "3% on All Restaurants", "es": "3% en todos los restaurantes", "fr": "3 % sur tous les restaurants", "ja": "全レストラン3%", "ko": "모든 레스토랑 3%", "zh": "餐饮全部3%"}', '{"en": "Earn 3% unlimited cash back on all restaurant purchases. One of the best dining rates for a no-fee card. Works at any restaurant, not just Costco food court.", "es": "Gana 3% ilimitado en todos los restaurantes. Una de las mejores tasas gastronómicas para una tarjeta sin cuota. Funciona en cualquier restaurante.", "fr": "Gagnez 3 % de remise illimitée sur tous les restaurants. L''un des meilleurs taux restauration pour une carte sans frais. Fonctionne partout.", "ja": "全レストランで3%無制限キャッシュバック。年会費無料カードで最高のダイニングレートの一つ。Costcoフードコートだけでなくどこでも使える。", "ko": "모든 레스토랑에서 3% 무제한 캐시백. 연회비 무료 카드 중 최고의 식사 적립률. Costco 푸드코트뿐만 아니라 모든 레스토랑에서 적용.", "zh": "所有餐厅消费获得3%无上限返现。免年费卡中最佳餐饮返还率之一。适用于任何餐厅，不仅限于Costco美食广场。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'BEST_USE', '{"en": "3% at Costco Gas", "es": "3% en gasolina Costco", "fr": "3 % essence Costco", "ja": "Costcoガソリン3%", "ko": "Costco 주유 3%", "zh": "Costco加油站3%"}', '{"en": "Get 3% cash back at Costco Gas Bars. Combined with Costco''s already low gas prices, this offers excellent value. Other gas stations earn 2%.", "es": "Obtén 3% en gasolineras Costco. Combinado con los precios bajos de Costco, excelente valor. Otras gasolineras 2%.", "fr": "Obtenez 3 % aux stations-service Costco. Combiné aux bas prix Costco, excellente valeur. Autres stations 2 %.", "ja": "Costcoガソリンスタンドで3%キャッシュバック。Costcoの低価格ガスと組み合わせて優れた価値。他のスタンドは2%。", "ko": "Costco 주유소에서 3% 캐시백. Costco의 저렴한 유가와 결합하면 뛰어난 가치. 다른 주유소는 2%.", "zh": "Costco加油站返现3%。结合Costco已经很低的油价，价值极高。其他加油站返2%。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'BEST_USE', '{"en": "2% on Costco.ca", "es": "2% en Costco.ca", "fr": "2 % sur Costco.ca", "ja": "Costco.caで2%", "ko": "Costco.ca 2%", "zh": "Costco.ca网购2%"}', '{"en": "Earn 2% cash back on all Costco.ca online purchases. Great for big-ticket items like appliances, electronics, and furniture delivered to your door.", "es": "Gana 2% en todas las compras de Costco.ca. Ideal para electrodomésticos, electrónicos y muebles con entrega a domicilio.", "fr": "Gagnez 2 % sur tous les achats Costco.ca. Idéal pour électroménagers, électronique et meubles livrés à domicile.", "ja": "Costco.caオンライン購入で2%キャッシュバック。家電、電子機器、配送家具など高額商品に最適。", "ko": "Costco.ca 온라인 구매 전체에서 2% 캐시백. 가전제품, 전자제품, 배송 가구 등 고가 품목에 적합.", "zh": "Costco.ca网上购物全部返现2%。适合购买大件商品如电器、电子产品和送货上门的家具。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'BEST_USE', '{"en": "2% on EV Charging", "es": "2% en carga VE", "fr": "2 % recharge VÉ", "ja": "EV充電2%", "ko": "EV 충전 2%", "zh": "EV充电2%"}', '{"en": "Earn 2% cash back on EV charging stations. Good rate for electric vehicle owners, same as other gas stations.", "es": "Gana 2% en estaciones de carga VE. Buena tasa para propietarios de vehículos eléctricos.", "fr": "Gagnez 2 % sur les bornes de recharge VÉ. Bon taux pour les propriétaires de véhicules électriques.", "ja": "EV充電ステーションで2%キャッシュバック。電気自動車オーナーにとって良いレート。", "ko": "EV 충전소에서 2% 캐시백. 전기차 소유자에게 좋은 적립률.", "zh": "电动车充电站返现2%。对电动车主来说是不错的返还率，与其他加油站相同。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'INSURANCE', '{"en": "Purchase & Extended Warranty", "es": "Protección y garantía extendida", "fr": "Protection achat et garantie", "ja": "購入保護と延長保証", "ko": "구매 보호 및 연장 보증", "zh": "购物保护和延保"}', '{"en": "Includes purchase protection (theft/damage for 90 days) and extended warranty (doubles manufacturer warranty up to 1 extra year). Good for electronics.", "es": "Incluye protección de compra (robo/daño por 90 días) y garantía extendida (duplica garantía del fabricante hasta 1 año). Bueno para electrónicos.", "fr": "Inclut protection achat (vol/dommage 90 jours) et garantie prolongée (double la garantie jusqu''à 1 an). Bon pour l''électronique.", "ja": "購入保護(90日間の盗難/破損)と延長保証(メーカー保証を最大1年延長)付き。電子機器に最適。", "ko": "구매 보호(90일 도난/파손) 및 연장 보증(제조업체 보증을 최대 1년 연장) 포함. 전자제품에 적합.", "zh": "包含购物保护(90天内盗窃/损坏)和延长保修(延长制造商保修最多1年)。适合电子产品。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee makes this card pure profit. You still need a Costco membership ($65-130/year), but the card itself costs nothing.", "es": "Sin cuota anual, esta tarjeta es pura ganancia. Aún necesitas membresía Costco ($65-130/año), pero la tarjeta es gratis.", "fr": "Sans frais annuels, cette carte est du pur profit. Vous avez besoin d''un abonnement Costco (65-130 $/an), mais la carte est gratuite.", "ja": "年会費無料で純利益。Costco会員資格($65-130/年)は必要だが、カード自体は無料。", "ko": "연회비 무료로 순수익. Costco 회원권($65-130/년)은 필요하지만 카드 자체는 무료.", "zh": "免年费让这张卡纯赚。你仍需要Costco会员资格($65-130/年)，但卡本身免费。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'PERK', '{"en": "Unlimited Cash Back", "es": "Cashback ilimitado", "fr": "Remise illimitée", "ja": "キャッシュバック無制限", "ko": "캐시백 무제한", "zh": "无返现上限"}', '{"en": "No annual caps on cash back earnings. High spenders can maximize returns without hitting limits, unlike many competing cards.", "es": "Sin límites anuales en cashback. Los grandes gastadores maximizan retornos sin topes, a diferencia de otras tarjetas.", "fr": "Aucun plafond annuel sur les remises. Les gros dépensiers maximisent leurs retours sans limites.", "ja": "キャッシュバック年間上限なし。他の多くのカードと異なり、高額消費者は制限なく最大のリターンを得られる。", "ko": "캐시백 연간 한도 없음. 많은 경쟁 카드와 달리 고액 소비자도 한도 없이 최대 적립 가능.", "zh": "无返现年度上限。高消费者可最大化回报而不会触及限额，不像很多竞争卡。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'REDEMPTION', '{"en": "Annual Cash Back Cheque", "es": "Cheque de cashback anual", "fr": "Chèque remise annuel", "ja": "年次キャッシュバック小切手", "ko": "연간 캐시백 수표", "zh": "年度返现支票"}', '{"en": "Cash back is paid out once per year as a cheque or credited to your account. Plan ahead - you won''t see rewards until your annual statement.", "es": "El cashback se paga una vez al año como cheque o crédito a la cuenta. Planifica - no verás recompensas hasta el estado de cuenta anual.", "fr": "La remise est versée une fois par an par chèque ou crédit au compte. Planifiez - vous ne verrez les récompenses qu''au relevé annuel.", "ja": "キャッシュバックは年1回小切手またはアカウントクレジットで支払い。計画的に—年次明細まで報酬は表示されない。", "ko": "캐시백은 연 1회 수표 또는 계정 크레딧으로 지급. 계획하세요 - 연간 명세서까지 리워드가 표시되지 않음.", "zh": "返现每年一次以支票形式发放或计入账户。提前计划——直到年度账单才能看到奖励。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Costco Mastercard'), 'STACKING', '{"en": "Stack with Executive Membership", "es": "Combinar con Executive", "fr": "Combiner avec Executive", "ja": "Executive会員と併用", "ko": "Executive 회원권과 결합", "zh": "叠加Executive会员"}', '{"en": "Costco Executive members earn 2% annual reward on Costco purchases. Stack with card rewards: 2% Executive + 1% card = 3% on in-store, or 2% + 2% = 4% on Costco.ca.", "es": "Los miembros Executive ganan 2% en compras Costco. Combina: 2% Executive + 1% tarjeta = 3% en tienda, o 2% + 2% = 4% en Costco.ca.", "fr": "Les membres Executive gagnent 2 % sur les achats Costco. Combinez : 2 % Executive + 1 % carte = 3 % en magasin, ou 2 % + 2 % = 4 % sur Costco.ca.", "ja": "Costco Executive会員はCostco購入で2%年間報酬獲得。カード報酬と併用：店内2%+1%=3%、Costco.caは2%+2%=4%。", "ko": "Costco Executive 회원은 Costco 구매 시 2% 연간 리워드 획득. 카드 리워드와 결합: 매장 2%+1%=3%, Costco.ca 2%+2%=4%.", "zh": "Costco Executive会员在Costco消费获2%年度奖励。叠加卡片奖励：店内2%+1%=3%，Costco.ca 2%+2%=4%。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'AVOID', '{"en": "Only 0.5% Base Rate", "es": "Solo 0.5% tasa base", "fr": "Seulement 0,5 % de base", "ja": "基本はわずか0.5%", "ko": "기본 0.5%만", "zh": "基础仅0.5%"}', '{"en": "Non-bonus categories earn only 0.5% cash back. Use a different card for shopping, entertainment, and other non-grocery purchases.", "es": "Las categorías sin bonificación solo ganan 0.5%. Usa otra tarjeta para compras, entretenimiento y otros gastos.", "fr": "Les catégories non bonifiées ne rapportent que 0,5 %. Utilisez une autre carte pour les achats hors épicerie.", "ja": "ボーナスカテゴリ以外は0.5%のみ。ショッピング、エンターテイメント、その他の食料品以外の購入には別のカードを。", "ko": "비보너스 카테고리는 0.5%만 적립. 쇼핑, 엔터테인먼트, 기타 식료품 외 구매에는 다른 카드 사용.", "zh": "非奖励类别仅获0.5%返现。购物、娱乐和其他非超市消费请使用其他卡。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'BEST_USE', '{"en": "2% on Groceries", "es": "2% en supermercados", "fr": "2 % sur l''épicerie", "ja": "食料品2%", "ko": "식료품 2%", "zh": "超市2%返现"}', '{"en": "Earn 2% unlimited cash back on all grocery purchases. Best rate on this no-fee card. Use it as your dedicated grocery card.", "es": "Gana 2% ilimitado en todos los supermercados. Mejor tasa en esta tarjeta sin cuota. Úsala como tarjeta dedicada para compras.", "fr": "Gagnez 2 % illimité sur toutes les épiceries. Meilleur taux sur cette carte sans frais. Utilisez-la comme carte d''épicerie dédiée.", "ja": "食料品で2%無制限キャッシュバック。この年会費無料カードの最高レート。専用食料品カードとして使用。", "ko": "모든 식료품에서 2% 무제한 캐시백. 이 연회비 무료 카드의 최고 적립률. 전용 식료품 카드로 사용.", "zh": "所有超市消费获得2%无上限返现。这张免年费卡的最佳返还率。作为专用超市卡使用。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'BEST_USE', '{"en": "1% on Gas, Dining, Transit", "es": "1% gasolina, comida, transporte", "fr": "1 % essence, resto, transport", "ja": "ガス/外食/交通1%", "ko": "주유/식사/교통 1%", "zh": "加油/餐饮/交通1%"}', '{"en": "Earn 1% on gas, EV charging, dining, transit, and recurring payments. Decent everyday rate for a no-fee card.", "es": "Gana 1% en gasolina, carga VE, restaurantes, transporte y pagos recurrentes. Buena tasa diaria para tarjeta sin cuota.", "fr": "Gagnez 1 % sur essence, recharge VÉ, restaurants, transport et paiements récurrents. Bon taux quotidien pour carte sans frais.", "ja": "ガス、EV充電、外食、交通、定期支払いで1%獲得。年会費無料カードとして適切な日常レート。", "ko": "주유, EV 충전, 식사, 교통, 정기 결제에서 1% 적립. 연회비 무료 카드로서 적절한 일상 적립률.", "zh": "加油、电动车充电、餐饮、交通和定期付款获1%返现。免年费卡的不错日常返还率。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'BEST_USE', '{"en": "1% on CIBC Travel", "es": "1% en viajes CIBC", "fr": "1 % voyage CIBC", "ja": "CIBC旅行1%", "ko": "CIBC 여행 1%", "zh": "CIBC旅行1%"}', '{"en": "Earn 1% on eligible travel purchases through CIBC by Expedia. Book flights and hotels through the portal to earn cash back.", "es": "Gana 1% en viajes elegibles a través de CIBC by Expedia. Reserva vuelos y hoteles en el portal para ganar cashback.", "fr": "Gagnez 1 % sur les voyages éligibles via CIBC by Expedia. Réservez vols et hôtels via le portail pour gagner des remises.", "ja": "CIBC by Expedia経由の対象旅行購入で1%獲得。ポータルで航空券とホテルを予約してキャッシュバック。", "ko": "CIBC by Expedia를 통한 적격 여행 구매에서 1% 적립. 포털에서 항공권과 호텔 예약 시 캐시백 적립.", "zh": "通过CIBC by Expedia的合格旅行消费获1%。通过门户预订机票和酒店赚取返现。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compra", "fr": "Protection achat", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保护"}', '{"en": "Includes basic purchase protection against theft or damage for 90 days. Also includes extended warranty coverage.", "es": "Incluye protección básica de compra contra robo o daño por 90 días. También garantía extendida.", "fr": "Inclut protection achat de base contre vol ou dommage pour 90 jours. Aussi garantie prolongée.", "ja": "90日間の基本購入保護(盗難・破損)付き。延長保証も含む。", "ko": "90일간 도난 또는 파손에 대한 기본 구매 보호 포함. 연장 보증도 포함.", "zh": "包含90天基本购物保护，防盗窃或损坏。还包括延长保修。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee means pure profit from all cash back earned. Great starter card or secondary card for groceries.", "es": "Sin cuota anual significa ganancia pura de todo el cashback. Excelente tarjeta inicial o secundaria para supermercados.", "fr": "Sans frais annuels signifie profit pur de toutes les remises. Excellente carte de départ ou secondaire pour l''épicerie.", "ja": "年会費無料で獲得したキャッシュバックは全て純利益。初心者カードまたは食料品用サブカードに最適。", "ko": "연회비 무료로 모든 캐시백이 순이익. 입문 카드 또는 식료품용 보조 카드로 적합.", "zh": "免年费意味着所有返现都是纯利润。适合作为入门卡或专用超市副卡。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'PERK', '{"en": "Unlimited Cash Back", "es": "Cashback ilimitado", "fr": "Remise illimitée", "ja": "キャッシュバック無制限", "ko": "캐시백 무제한", "zh": "无返现上限"}', '{"en": "No annual caps on any category. Earn unlimited cash back at all rates without worrying about hitting spending limits.", "es": "Sin límites anuales en ninguna categoría. Gana cashback ilimitado sin preocuparte por límites de gasto.", "fr": "Aucun plafond annuel sur aucune catégorie. Gagnez des remises illimitées sans vous soucier des limites.", "ja": "どのカテゴリにも年間上限なし。消費限度を気にせず全レートで無制限キャッシュバック獲得。", "ko": "모든 카테고리에 연간 한도 없음. 지출 한도 걱정 없이 모든 적립률에서 무제한 캐시백 적립.", "zh": "任何类别无年度上限。以所有费率无限赚取返现，无需担心消费限额。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'PERK', '{"en": "1% on Recurring Bills", "es": "1% en pagos recurrentes", "fr": "1 % paiements récurrents", "ja": "定期支払い1%", "ko": "정기 결제 1%", "zh": "定期账单1%"}', '{"en": "Set up recurring payments for utilities, subscriptions, and bills to earn 1% cash back automatically every month.", "es": "Configura pagos recurrentes para servicios, suscripciones y facturas para ganar 1% automáticamente cada mes.", "fr": "Configurez les paiements récurrents pour services publics et abonnements pour gagner 1 % automatiquement chaque mois.", "ja": "公共料金、サブスク、請求書を定期支払いに設定して毎月自動的に1%獲得。", "ko": "공과금, 구독, 청구서를 정기 결제로 설정하여 매달 자동으로 1% 적립.", "zh": "设置水电、订阅和账单的定期付款，每月自动获得1%返现。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'REDEMPTION', '{"en": "Redeem Anytime", "es": "Canjear en cualquier momento", "fr": "Échanger à tout moment", "ja": "いつでも交換", "ko": "언제든지 교환", "zh": "随时兑换"}', '{"en": "Cash back never expires and can be redeemed anytime as statement credit or deposited to your CIBC account. Minimum $25 redemption.", "es": "El cashback nunca expira y se puede canjear en cualquier momento como crédito o depósito CIBC. Mínimo $25 para canjear.", "fr": "Les remises n''expirent jamais et peuvent être échangées à tout moment en crédit ou dépôt CIBC. Minimum 25 $ à échanger.", "ja": "キャッシュバックは期限なく、いつでも明細クレジットまたはCIBC口座入金で交換可能。最低$25から交換。", "ko": "캐시백은 만료되지 않으며 언제든 명세서 크레딧 또는 CIBC 계정 입금으로 교환 가능. 최소 $25 교환.", "zh": "返现永不过期，可随时兑换为账单抵扣或存入CIBC账户。最低$25起兑。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Card'), 'STACKING', '{"en": "Upgrade to Dividend Infinite", "es": "Actualiza a Dividend Infinite", "fr": "Passer à Dividend Infinite", "ja": "Dividend Infiniteにアップグレード", "ko": "Dividend Infinite로 업그레이드", "zh": "升级到Dividend Infinite"}', '{"en": "If you spend heavily on groceries/gas, consider upgrading to Dividend Infinite ($120/year) for 4% on groceries/gas and 2% on dining/transit/recurring.", "es": "Si gastas mucho en supermercado/gasolina, considera Dividend Infinite ($120/año) para 4% en supermercado/gasolina y 2% en comida/transporte.", "fr": "Si vous dépensez beaucoup en épicerie/essence, passez à Dividend Infinite (120 $/an) pour 4 % épicerie/essence et 2 % resto/transport.", "ja": "食料品/ガスで多く消費するなら、Dividend Infinite($120/年)へアップグレードを。食料品/ガス4%、外食/交通/定期2%。", "ko": "식료품/주유에 많이 지출한다면 Dividend Infinite($120/년) 업그레이드 고려. 식료품/주유 4%, 식사/교통/정기 2%.", "zh": "如果超市/加油消费较多，考虑升级到Dividend Infinite($120/年)，超市/加油4%，餐饮/交通/定期2%。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'AVOID', '{"en": "$120 Annual Fee", "es": "Cuota anual $120", "fr": "Frais annuels 120 $", "ja": "年会費$120", "ko": "연회비 $120", "zh": "$120年费"}', '{"en": "After the first year, you pay $120/year. You need ~$4,000 in grocery/gas spending to offset the fee vs a no-fee 2% card. Fee waived with CIBC Smart Account.", "es": "Después del primer año, pagas $120/año. Necesitas ~$4,000 en supermercado/gasolina para compensar vs tarjeta 2% sin cuota. Exento con CIBC Smart Account.", "fr": "Après la première année, vous payez 120 $/an. Il faut ~4 000 $ en épicerie/essence pour compenser vs une carte 2 % sans frais. Frais annulés avec CIBC Smart Account.", "ja": "初年度後は$120/年。年会費なし2%カードと比較して、年会費を相殺するには食料品/ガスで約$4,000必要。CIBC Smart Accountで免除。", "ko": "첫해 이후 연 $120 지불. 연회비 무료 2% 카드 대비 연회비 상쇄에 식료품/주유 약 $4,000 필요. CIBC Smart Account로 면제.", "zh": "首年后需付$120/年。与免年费2%卡相比，需约$4,000超市/加油消费才能抵消年费。持有CIBC Smart Account可减免。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'BEST_USE', '{"en": "4% on Groceries", "es": "4% en supermercados", "fr": "4 % sur l''épicerie", "ja": "食料品4%", "ko": "식료품 4%", "zh": "超市4%返现"}', '{"en": "Earn 4% unlimited cash back on all grocery purchases. One of the highest grocery rates available. No annual cap on earnings.", "es": "Gana 4% ilimitado en todos los supermercados. Una de las tasas más altas disponibles. Sin límite anual.", "fr": "Gagnez 4 % illimité sur toutes les épiceries. L''un des meilleurs taux épicerie disponibles. Aucun plafond annuel.", "ja": "食料品で4%無制限キャッシュバック。最高の食料品レートの一つ。年間上限なし。", "ko": "모든 식료품에서 4% 무제한 캐시백. 가장 높은 식료품 적립률 중 하나. 연간 한도 없음.", "zh": "所有超市消费获得4%无上限返现。市场上最高的超市返还率之一。无年度上限。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'BEST_USE', '{"en": "4% on Gas & EV Charging", "es": "4% gasolina y carga VE", "fr": "4 % essence et recharge VÉ", "ja": "ガスとEV充電4%", "ko": "주유 및 EV 충전 4%", "zh": "加油和EV充电4%"}', '{"en": "Get 4% cash back at all gas stations and EV charging stations. Excellent for commuters and road trippers. No spending cap.", "es": "Obtén 4% en todas las gasolineras y estaciones de carga VE. Excelente para viajeros. Sin límite de gasto.", "fr": "Obtenez 4 % à toutes les stations-service et bornes de recharge VÉ. Excellent pour les navetteurs. Aucun plafond.", "ja": "全ガソリンスタンドとEV充電ステーションで4%キャッシュバック。通勤者やロードトリップに最適。上限なし。", "ko": "모든 주유소 및 EV 충전소에서 4% 캐시백. 통근자와 로드트립에 적합. 지출 한도 없음.", "zh": "所有加油站和电动车充电站获4%返现。通勤者和自驾游爱好者的绝佳选择。无消费上限。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'BEST_USE', '{"en": "2% on Dining & Transit", "es": "2% comida y transporte", "fr": "2 % restaurants et transport", "ja": "外食・交通2%", "ko": "식사 및 교통 2%", "zh": "餐饮/交通2%"}', '{"en": "Earn 2% on restaurants, transit, recurring payments, and travel via CIBC by Expedia. Solid secondary categories.", "es": "Gana 2% en restaurantes, transporte, pagos recurrentes y viajes vía CIBC by Expedia. Buenas categorías secundarias.", "fr": "Gagnez 2 % sur restaurants, transport, paiements récurrents et voyages via CIBC by Expedia. Bonnes catégories secondaires.", "ja": "レストラン、交通、定期支払い、CIBC by Expedia旅行で2%獲得。堅実なサブカテゴリ。", "ko": "레스토랑, 교통, 정기 결제, CIBC by Expedia 여행에서 2% 적립. 견고한 보조 카테고리.", "zh": "餐厅、交通、定期付款和CIBC by Expedia旅行获2%。稳定的次级类别。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'INSURANCE', '{"en": "Travel & Purchase Insurance", "es": "Seguro de viaje y compra", "fr": "Assurance voyage et achat", "ja": "旅行・購入保険", "ko": "여행 및 구매 보험", "zh": "旅行和购物保险"}', '{"en": "Includes travel emergency medical ($1M), trip cancellation, car rental collision, purchase protection (90 days), and extended warranty.", "es": "Incluye emergencia médica viaje ($1M), cancelación, colisión alquiler, protección compra (90 días) y garantía extendida.", "fr": "Inclut urgence médicale voyage (1 M$), annulation, collision auto, protection achat (90 jours) et garantie prolongée.", "ja": "旅行緊急医療($100万)、旅行キャンセル、レンタカー衝突、購入保護(90日)、延長保証付き。", "ko": "여행 응급 의료($100만), 여행 취소, 렌터카 충돌, 구매 보호(90일), 연장 보증 포함.", "zh": "包含旅行紧急医疗($100万)、行程取消、租车碰撞险、购物保护(90天)和延长保修。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'PERK', '{"en": "Up to $450 Welcome Value", "es": "Hasta $450 de bienvenida", "fr": "Jusqu''à 450 $ de bienvenue", "ja": "最大$450ウェルカムバリュー", "ko": "최대 $450 웰컴 가치", "zh": "最高$450开卡价值"}', '{"en": "Get up to $450: 10% cashback on first 4 statements (up to $300) + $50 pre-authorized payment bonus + $120 first-year fee rebate.", "es": "Obtén hasta $450: 10% en primeros 4 estados (hasta $300) + $50 bono pago preautorizado + $120 cuota primer año.", "fr": "Obtenez jusqu''à 450 $ : 10 % sur 4 premiers relevés (max 300 $) + 50 $ bonus préautorisé + 120 $ frais remboursés.", "ja": "最大$450獲得：最初の4明細で10%(最大$300) + $50事前承認ボーナス + $120初年度年会費リベート。", "ko": "최대 $450 획득: 첫 4개 명세서 10%(최대 $300) + $50 사전 승인 보너스 + $120 첫해 연회비 환급.", "zh": "最高$450：首4期账单10%返现(最高$300) + $50预授权付款奖励 + $120首年年费减免。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'PERK', '{"en": "2% on All Recurring Bills", "es": "2% en facturas recurrentes", "fr": "2 % sur factures récurrentes", "ja": "定期支払い全部2%", "ko": "모든 정기 청구서 2%", "zh": "所有定期账单2%"}', '{"en": "Set up pre-authorized payments for utilities, subscriptions, insurance, and telecom to earn 2% automatically every month.", "es": "Configura pagos preautorizados para servicios, suscripciones, seguro y telecom para ganar 2% automáticamente.", "fr": "Configurez les paiements préautorisés pour services publics, abonnements, assurance et télécom pour gagner 2 % automatiquement.", "ja": "公共料金、サブスク、保険、通信の事前承認支払いを設定して毎月自動的に2%獲得。", "ko": "공과금, 구독, 보험, 통신의 사전 승인 결제를 설정하여 매달 자동으로 2% 적립.", "zh": "设置水电、订阅、保险和电信的预授权付款，每月自动获得2%。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'PERK', '{"en": "No Earning Limits", "es": "Sin límites de ganancias", "fr": "Aucun plafond de gains", "ja": "獲得上限なし", "ko": "적립 한도 없음", "zh": "无收益上限"}', '{"en": "Unlike many competitors, there''s no cap on how much cash back you can earn in any category. High spenders benefit the most.", "es": "A diferencia de muchos competidores, no hay límite en el cashback. Los grandes gastadores se benefician más.", "fr": "Contrairement à de nombreux concurrents, aucun plafond sur les remises. Les gros dépensiers en bénéficient le plus.", "ja": "多くの競合と異なり、どのカテゴリでもキャッシュバック上限なし。高額消費者が最も恩恵を受ける。", "ko": "많은 경쟁사와 달리 모든 카테고리에서 캐시백 한도 없음. 고액 소비자가 가장 큰 혜택.", "zh": "与许多竞品不同，任何类别的返现都没有上限。高消费者获益最大。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem cash back anytime as statement credit, deposit to CIBC account, or apply to travel. Cash back never expires. Minimum $25.", "es": "Canjea cashback en cualquier momento como crédito, depósito CIBC o viaje. El cashback nunca expira. Mínimo $25.", "fr": "Échangez les remises à tout moment en crédit, dépôt CIBC ou voyage. Les remises n''expirent jamais. Minimum 25 $.", "ja": "キャッシュバックはいつでも明細クレジット、CIBC口座入金、旅行に交換可能。期限なし。最低$25。", "ko": "캐시백을 언제든 명세서 크레딧, CIBC 계정 입금, 여행으로 교환. 캐시백 만료 없음. 최소 $25.", "zh": "随时兑换返现为账单抵扣、存入CIBC账户或用于旅行。返现永不过期。最低$25。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'CIBC' AND name = 'Dividend Visa Infinite'), 'STACKING', '{"en": "CIBC Smart Account Waiver", "es": "Exención CIBC Smart Account", "fr": "Exonération CIBC Smart", "ja": "CIBC Smart Account免除", "ko": "CIBC Smart Account 면제", "zh": "CIBC Smart Account减免"}', '{"en": "The $120 annual fee can be waived if you hold an eligible CIBC Smart Account. Check with CIBC for current requirements.", "es": "La cuota de $120 puede eximirse con una cuenta CIBC Smart elegible. Consulta con CIBC los requisitos actuales.", "fr": "Les frais de 120 $ peuvent être annulés avec un compte CIBC Smart admissible. Vérifiez auprès de CIBC.", "ja": "対象のCIBC Smart Accountを保有すると$120年会費が免除される可能性。最新要件はCIBCに確認。", "ko": "적격 CIBC Smart Account 보유 시 $120 연회비 면제 가능. 현재 요건은 CIBC에 확인.", "zh": "持有符合条件的CIBC Smart Account可减免$120年费。请向CIBC确认当前要求。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'AVOID', '{"en": "$5,000 Annual Cap", "es": "Límite anual $5,000", "fr": "Plafond annuel 5 000 $", "ja": "年間$5,000上限", "ko": "연간 $5,000 한도", "zh": "$5,000年度上限"}', '{"en": "The 1% categories share a combined $5,000 annual cap. After hitting the cap, all purchases earn 0.5%. High spenders may want another card.", "es": "Las categorías 1% comparten límite combinado de $5,000. Después del límite, todo gana 0.5%. Grandes gastadores querrán otra tarjeta.", "fr": "Les catégories 1 % partagent un plafond combiné de 5 000 $. Après le plafond, tout gagne 0,5 %. Les gros dépensiers voudront une autre carte.", "ja": "1%カテゴリは合計$5,000の年間上限を共有。上限後は全て0.5%。高額消費者は別のカードを検討。", "ko": "1% 카테고리는 합산 $5,000 연간 한도 공유. 한도 후 모두 0.5%. 고액 소비자는 다른 카드 고려.", "zh": "1%类别共享$5,000年度上限。达到上限后，所有消费仅获0.5%。高消费者可能需要另一张卡。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'AVOID', '{"en": "Only 0.5% Base Rate", "es": "Solo 0.5% tasa base", "fr": "Seulement 0,5 % de base", "ja": "基本はわずか0.5%", "ko": "기본 0.5%만", "zh": "基础仅0.5%"}', '{"en": "Non-bonus categories and spending over the cap earn only 0.5%. Use a different card for shopping, dining, and entertainment.", "es": "Las categorías sin bonificación y gastos sobre el límite solo ganan 0.5%. Usa otra tarjeta para compras y restaurantes.", "fr": "Les catégories non bonifiées et les achats au-delà du plafond ne rapportent que 0,5 %. Utilisez une autre carte pour shopping et restos.", "ja": "ボーナスカテゴリ以外と上限超過は0.5%のみ。ショッピング、外食、エンタメには別のカードを。", "ko": "비보너스 카테고리 및 한도 초과 지출은 0.5%만. 쇼핑, 식사, 엔터테인먼트에는 다른 카드 사용.", "zh": "非奖励类别和超过上限的消费仅获0.5%。购物、餐饮和娱乐请使用其他卡。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "1% on Grocery, Gas, Transit", "es": "1% supermercado, gasolina, transporte", "fr": "1 % épicerie, essence, transport", "ja": "食料品/ガス/交通1%", "ko": "식료품/주유/교통 1%", "zh": "超市/加油/交通1%"}', '{"en": "Earn 1% cash back on groceries, gas, sustainable transit, streaming, and recurring bills. Combined $5,000 annual cap across these categories.", "es": "Gana 1% en supermercado, gasolina, transporte sustentable, streaming y facturas recurrentes. Límite combinado $5,000 anuales.", "fr": "Gagnez 1 % sur épicerie, essence, transport durable, streaming et factures récurrentes. Plafond combiné de 5 000 $ par an.", "ja": "食料品、ガス、サステナブル交通、ストリーミング、定期支払いで1%キャッシュバック。これらのカテゴリ合計で年間$5,000上限。", "ko": "식료품, 주유, 지속가능 교통, 스트리밍, 정기 결제에서 1% 캐시백. 이 카테고리 합산 연간 $5,000 한도.", "zh": "超市、加油、可持续交通、流媒体和定期账单获1%返现。这些类别合计年度上限$5,000。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "1% on Streaming", "es": "1% en streaming", "fr": "1 % sur streaming", "ja": "ストリーミング1%", "ko": "스트리밍 1%", "zh": "流媒体1%"}', '{"en": "Earn 1% on Netflix, Spotify, Disney+, and other streaming services. Set up auto-pay for hands-free rewards.", "es": "Gana 1% en Netflix, Spotify, Disney+ y otros servicios de streaming. Configura pago automático.", "fr": "Gagnez 1 % sur Netflix, Spotify, Disney+ et autres services de streaming. Configurez le paiement auto.", "ja": "Netflix、Spotify、Disney+などストリーミングで1%獲得。自動支払い設定で楽々報酬。", "ko": "Netflix, Spotify, Disney+ 등 스트리밍에서 1% 적립. 자동 결제 설정으로 편리하게.", "zh": "Netflix、Spotify、Disney+等流媒体服务获1%。设置自动付款轻松赚取奖励。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "1% on Sustainable Transit", "es": "1% transporte sustentable", "fr": "1 % transport durable", "ja": "サステナブル交通1%", "ko": "지속가능 교통 1%", "zh": "可持续交通1%"}', '{"en": "Earn 1% on public transit, ride-sharing, and other sustainable transportation options. Supports eco-friendly commuting.", "es": "Gana 1% en transporte público, viajes compartidos y otras opciones de transporte sustentable. Apoya desplazamientos ecológicos.", "fr": "Gagnez 1 % sur transport en commun, covoiturage et autres options de transport durable. Soutient les déplacements écologiques.", "ja": "公共交通、ライドシェア、その他の持続可能な交通手段で1%獲得。エコ通勤をサポート。", "ko": "대중교통, 차량 공유 및 기타 지속 가능한 교통수단에서 1% 적립. 친환경 통근 지원.", "zh": "公共交通、拼车和其他可持续交通方式获1%。支持环保出行。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'INSURANCE', '{"en": "Basic Card Protection", "es": "Protección básica", "fr": "Protection de base", "ja": "基本カード保護", "ko": "기본 카드 보호", "zh": "基本卡片保护"}', '{"en": "Includes standard Mastercard protections including zero liability for unauthorized purchases. Check terms for additional coverage.", "es": "Incluye protecciones estándar Mastercard incluyendo responsabilidad cero por compras no autorizadas. Consulta términos.", "fr": "Inclut les protections Mastercard standard, y compris la responsabilité zéro pour les achats non autorisés. Consultez les termes.", "ja": "不正使用ゼロ責任を含む標準Mastercard保護付き。追加保障は規約を確認。", "ko": "무단 구매에 대한 제로 책임을 포함한 표준 Mastercard 보호. 추가 보장은 약관 확인.", "zh": "包含标准Mastercard保护，未经授权消费零责任。查看条款了解其他保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee means all cash back earned is pure profit. Simple, straightforward rewards with no fee to offset.", "es": "Sin cuota anual significa que todo el cashback es ganancia pura. Recompensas simples sin cuota que compensar.", "fr": "Sans frais annuels signifie que toutes les remises sont du profit pur. Récompenses simples sans frais à compenser.", "ja": "年会費無料で獲得したキャッシュバックは全て純利益。相殺すべき年会費なしのシンプルな報酬。", "ko": "연회비 무료로 모든 캐시백이 순이익. 상쇄할 연회비 없는 간단한 리워드.", "zh": "免年费意味着所有返现都是纯利润。简单直接的奖励，无需抵消年费。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "1% on Recurring Bills", "es": "1% facturas recurrentes", "fr": "1 % factures récurrentes", "ja": "定期支払い1%", "ko": "정기 결제 1%", "zh": "定期账单1%"}', '{"en": "Set up recurring payments for utilities, subscriptions, and bills to earn 1% automatically. Great for passive earning.", "es": "Configura pagos recurrentes para servicios y suscripciones para ganar 1% automáticamente. Excelente para ganancias pasivas.", "fr": "Configurez les paiements récurrents pour services et abonnements pour gagner 1 % automatiquement. Excellent pour gains passifs.", "ja": "公共料金、サブスク、請求書を定期支払いに設定して自動的に1%獲得。パッシブ収入に最適。", "ko": "공과금, 구독, 청구서를 정기 결제로 설정하여 자동으로 1% 적립. 수동적 적립에 적합.", "zh": "设置水电、订阅和账单的定期付款，自动获得1%。被动收益的好选择。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "Credit Union Perks", "es": "Beneficios cooperativa", "fr": "Avantages caisse populaire", "ja": "信用組合特典", "ko": "신용협동조합 혜택", "zh": "信用社福利"}', '{"en": "As a Coast Capital member, you benefit from member-owned banking. Profits go back to members and community, not shareholders.", "es": "Como miembro de Coast Capital, te beneficias de banca cooperativa. Las ganancias van a miembros y comunidad, no a accionistas.", "fr": "En tant que membre Coast Capital, vous bénéficiez d''une banque appartenant aux membres. Les profits vont aux membres et à la communauté.", "ja": "Coast Capital会員として、会員所有の銀行サービスを享受。利益は株主ではなく会員とコミュニティに還元。", "ko": "Coast Capital 회원으로서 회원 소유 뱅킹 혜택. 수익은 주주가 아닌 회원과 커뮤니티로 환원.", "zh": "作为Coast Capital会员，您享受会员所有的银行服务。利润回馈会员和社区，而非股东。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Coast Capital' AND name = 'Cash Back Mastercard'), 'STACKING', '{"en": "Upgrade to World Elite", "es": "Actualiza a World Elite", "fr": "Passer à World Elite", "ja": "World Eliteにアップグレード", "ko": "World Elite로 업그레이드", "zh": "升级到World Elite"}', '{"en": "Coast Capital offers a World Elite version ($120/year) with 4% on groceries/transit, 2% on recurring/streaming/dining, and 1% on everything else.", "es": "Coast Capital ofrece versión World Elite ($120/año) con 4% supermercado/transporte, 2% recurrente/streaming/comida, 1% en todo lo demás.", "fr": "Coast Capital offre une version World Elite (120 $/an) avec 4 % épicerie/transport, 2 % récurrent/streaming/restos, 1 % sur le reste.", "ja": "Coast CapitalはWorld Elite版($120/年)も提供。食料品/交通4%、定期/ストリーミング/外食2%、その他1%。", "ko": "Coast Capital은 World Elite 버전($120/년) 제공. 식료품/교통 4%, 정기/스트리밍/식사 2%, 기타 1%.", "zh": "Coast Capital提供World Elite版本($120/年)，超市/交通4%，定期/流媒体/餐饮2%，其他1%。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'AVOID', '{"en": "Only 0.5% Base Rate", "es": "Solo 0.5% tasa base", "fr": "Seulement 0,5 % de base", "ja": "基本はわずか0.5%", "ko": "기본 0.5%만", "zh": "基础仅0.5%"}', '{"en": "Non-bonus categories earn only 0.5% cash back. Use a different card for groceries, gas, and other purchases.", "es": "Las categorías sin bonificación solo ganan 0.5%. Usa otra tarjeta para supermercado y gasolina.", "fr": "Les catégories non bonifiées ne rapportent que 0,5 %. Utilisez une autre carte pour épicerie et essence.", "ja": "ボーナスカテゴリ以外は0.5%のみ。食料品、ガス、その他の購入には別のカードを。", "ko": "비보너스 카테고리는 0.5%만 적립. 식료품, 주유, 기타 구매에는 다른 카드 사용.", "zh": "非奖励类别仅获0.5%返现。超市、加油和其他消费请使用其他卡。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'AVOID', '{"en": "$3,600 Combined Cap", "es": "Límite combinado $3,600", "fr": "Plafond combiné 3 600 $", "ja": "合計$3,600上限", "ko": "합산 $3,600 한도", "zh": "$3,600合计上限"}', '{"en": "Dining and recurring payments share a $3,600 annual cap at 2%. After that, both categories drop to 0.5%. Track your spending.", "es": "Restaurantes y pagos recurrentes comparten límite de $3,600 al 2%. Después, ambos bajan a 0.5%.", "fr": "Restaurants et paiements récurrents partagent un plafond de 3 600 $ à 2 %. Après, les deux passent à 0,5 %.", "ja": "外食と定期支払いは$3,600年間上限を共有。超過後は両方0.5%に。消費を追跡して。", "ko": "식당과 정기 결제가 연간 $3,600 한도를 2%로 공유. 이후 두 카테고리 모두 0.5%로 하락.", "zh": "餐饮和定期付款共享$3,600年度2%上限。超过后两个类别都降至0.5%。注意追踪消费。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "2% on Restaurants", "es": "2% en restaurantes", "fr": "2 % sur les restaurants", "ja": "レストラン2%", "ko": "레스토랑 2%", "zh": "餐厅2%返现"}', '{"en": "Earn 2% cash back on restaurant purchases. Combined $3,600 annual cap with recurring payments, then drops to 0.5%.", "es": "Gana 2% en restaurantes. Límite combinado $3,600 con pagos recurrentes, luego baja a 0.5%.", "fr": "Gagnez 2 % de remise sur les restaurants. Plafond combiné de 3 600 $ avec paiements préautorisés, puis 0,5 %.", "ja": "レストランで2%キャッシュバック。定期支払いと合計$3,600年間上限、その後0.5%に。", "ko": "레스토랑에서 2% 캐시백. 정기 결제와 합산 연간 $3,600 한도, 이후 0.5%.", "zh": "餐厅消费获得2%返现。与定期付款合计年度上限$3,600，超过后降至0.5%。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "2% on Entertainment", "es": "2% en entretenimiento", "fr": "2 % sur divertissement", "ja": "エンターテイメント2%", "ko": "엔터테인먼트 2%", "zh": "娱乐2%返现"}', '{"en": "Earn 2% cash back on entertainment purchases including movies, concerts, and events. No annual cap on this category.", "es": "Gana 2% en entretenimiento incluyendo cine, conciertos y eventos. Sin límite anual en esta categoría.", "fr": "Gagnez 2 % sur les divertissements incluant cinéma, concerts et événements. Aucun plafond annuel.", "ja": "映画、コンサート、イベントなどエンターテイメントで2%キャッシュバック。このカテゴリは年間上限なし。", "ko": "영화, 콘서트, 이벤트 등 엔터테인먼트에서 2% 캐시백. 이 카테고리는 연간 한도 없음.", "zh": "娱乐消费（电影、演唱会、活动等）获得2%返现。此类别无年度上限。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "2% on Transit", "es": "2% en transporte", "fr": "2 % sur transport", "ja": "交通2%", "ko": "교통 2%", "zh": "交通2%返现"}', '{"en": "Earn 2% cash back on public transit and alternative transportation. Great for commuters using metro, bus, or bike-sharing.", "es": "Gana 2% en transporte público y alternativo. Ideal para usuarios de metro, autobús o bicicletas compartidas.", "fr": "Gagnez 2 % sur le transport en commun et alternatif. Idéal pour les navetteurs utilisant métro, bus ou vélo-partage.", "ja": "公共交通と代替交通で2%キャッシュバック。地下鉄、バス、シェアバイク利用の通勤者に最適。", "ko": "대중교통 및 대체 교통수단에서 2% 캐시백. 지하철, 버스, 자전거 공유 이용 통근자에게 적합.", "zh": "公共交通和替代交通获得2%返现。适合使用地铁、公交或共享单车的通勤者。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "2% on Pre-Authorized Payments", "es": "2% en pagos preautorizados", "fr": "2 % paiements préautorisés", "ja": "事前承認支払い2%", "ko": "사전 승인 결제 2%", "zh": "预授权付款2%"}', '{"en": "Earn 2% on pre-authorized payments including subscriptions, utilities, and insurance. Combined $3,600 cap with dining.", "es": "Gana 2% en pagos preautorizados incluyendo suscripciones, servicios y seguro. Límite combinado con restaurantes.", "fr": "Gagnez 2 % sur les paiements préautorisés incluant abonnements, services publics et assurance. Plafond combiné avec restaurants.", "ja": "サブスク、公共料金、保険など事前承認支払いで2%獲得。外食と合計$3,600上限。", "ko": "구독, 공과금, 보험 등 사전 승인 결제에서 2% 적립. 식당과 합산 $3,600 한도.", "zh": "预授权付款（订阅、水电、保险等）获得2%。与餐饮合计$3,600上限。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee means all cash back earned is pure profit. Great entry-level card for Desjardins members.", "es": "Sin cuota anual significa ganancia pura. Excelente tarjeta inicial para miembros de Desjardins.", "fr": "Sans frais annuels signifie profit pur. Excellente carte d''entrée pour les membres Desjardins.", "ja": "年会費無料で獲得したキャッシュバックは全て純利益。Desjardins会員向けエントリーカード。", "ko": "연회비 무료로 모든 캐시백이 순이익. Desjardins 회원을 위한 입문 카드.", "zh": "免年费意味着所有返现都是纯利润。适合Desjardins会员的入门卡。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "Quebec Credit Union", "es": "Cooperativa de Quebec", "fr": "Caisse populaire du Québec", "ja": "ケベック信用組合", "ko": "퀘벡 신용협동조합", "zh": "魁北克信用社"}', '{"en": "Desjardins is the largest credit union in North America. As a member, you own part of the cooperative and may receive annual dividends.", "es": "Desjardins es la cooperativa de crédito más grande de Norteamérica. Como miembro, eres copropietario y puedes recibir dividendos.", "fr": "Desjardins est la plus grande caisse populaire en Amérique du Nord. En tant que membre, vous possédez une partie de la coopérative.", "ja": "DesjardinsはN.A.最大の信用組合。会員として協同組合の一部を所有し、年間配当を受け取る可能性あり。", "ko": "Desjardins는 북미 최대 신용협동조합. 회원으로서 협동조합의 일부를 소유하고 연간 배당금을 받을 수 있음.", "zh": "Desjardins是北美最大的信用社。作为会员，您拥有合作社的一部分，可能获得年度分红。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'REDEMPTION', '{"en": "Auto Credit at $25", "es": "Crédito automático a $25", "fr": "Crédit auto à 25 $", "ja": "$25で自動クレジット", "ko": "$25에 자동 크레딧", "zh": "$25自动入账"}', '{"en": "Cash back is automatically credited to your account when you accumulate $25. No manual redemption needed.", "es": "El cashback se acredita automáticamente al acumular $25. No se necesita canje manual.", "fr": "La remise est automatiquement créditée lorsque vous accumulez 25 $. Aucun échange manuel nécessaire.", "ja": "$25蓄積するとキャッシュバックが自動的にアカウントにクレジット。手動交換不要。", "ko": "$25 적립 시 캐시백이 자동으로 계정에 적립. 수동 교환 불필요.", "zh": "累积$25后返现自动计入账户。无需手动兑换。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back Mastercard'), 'STACKING', '{"en": "Upgrade to World Elite", "es": "Actualiza a World Elite", "fr": "Passer à World Elite", "ja": "World Eliteにアップグレード", "ko": "World Elite로 업그레이드", "zh": "升级到World Elite"}', '{"en": "Desjardins offers World Elite ($100/year) with 4% groceries, 3% dining/entertainment/transit, and higher caps. Consider if you spend heavily.", "es": "Desjardins ofrece World Elite ($100/año) con 4% supermercado, 3% comida/entretenimiento/transporte y límites más altos.", "fr": "Desjardins offre World Elite (100 $/an) avec 4 % épicerie, 3 % resto/divertissement/transport et plafonds plus élevés.", "ja": "DesjardinsはWorld Elite($100/年)も提供。食料品4%、外食/エンタメ/交通3%、上限も高い。多く消費するなら検討を。", "ko": "Desjardins는 World Elite($100/년) 제공. 식료품 4%, 식사/엔터테인먼트/교통 3%, 더 높은 한도. 지출이 많으면 고려.", "zh": "Desjardins提供World Elite($100/年)，超市4%、餐饮/娱乐/交通3%，上限更高。如果消费较多可考虑。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'AVOID', '{"en": "$100 Annual Fee", "es": "Cuota anual $100", "fr": "Frais annuels 100 $", "ja": "年会費$100", "ko": "연회비 $100", "zh": "$100年费"}', '{"en": "First year is offset by welcome bonus. After that, you need ~$2,500 in groceries to break even vs a 2% no-fee card.", "es": "El primer año se compensa con el bono. Después, necesitas ~$2,500 en supermercado para igualar una tarjeta 2% sin cuota.", "fr": "La première année est compensée par la prime. Après, il faut ~2 500 $ d''épicerie pour rentabiliser vs carte 2 % sans frais.", "ja": "初年度はウェルカムボーナスで相殺。その後、2%年会費無料カードと同等にするには食料品で約$2,500必要。", "ko": "첫해는 웰컴 보너스로 상쇄. 이후 2% 연회비 무료 카드와 동등하려면 식료품에 약 $2,500 필요.", "zh": "首年由开卡奖励抵消。之后需约$2,500超市消费才能与2%免年费卡持平。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'BEST_USE', '{"en": "4% on Groceries", "es": "4% en supermercados", "fr": "4 % sur l''épicerie", "ja": "食料品4%", "ko": "식료품 4%", "zh": "超市4%返现"}', '{"en": "Earn 4% cash back on grocery purchases up to $10,000/year (then 1%). That''s up to $400 in grocery rewards annually.", "es": "Gana 4% en supermercado hasta $10,000/año (luego 1%). Hasta $400 en recompensas de supermercado anuales.", "fr": "Gagnez 4 % sur l''épicerie jusqu''à 10 000 $/an (puis 1 %). Jusqu''à 400 $ de remise épicerie par an.", "ja": "食料品で4%キャッシュバック、年間$10,000まで（その後1%）。年間最大$400の食料品報酬。", "ko": "식료품에서 4% 캐시백, 연간 $10,000까지(이후 1%). 연간 최대 $400 식료품 리워드.", "zh": "超市消费获得4%返现，年度上限$10,000（超过后1%）。每年最高可获$400超市奖励。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'BEST_USE', '{"en": "3% on Restaurants", "es": "3% en restaurantes", "fr": "3 % sur les restaurants", "ja": "レストラン3%", "ko": "레스토랑 3%", "zh": "餐厅3%返现"}', '{"en": "Earn 3% cash back at restaurants up to $6,000/year (then 1%). That''s up to $180 in dining rewards annually.", "es": "Gana 3% en restaurantes hasta $6,000/año (luego 1%). Hasta $180 en recompensas de restaurantes anuales.", "fr": "Gagnez 3 % dans les restaurants jusqu''à 6 000 $/an (puis 1 %). Jusqu''à 180 $ de remise restaurants par an.", "ja": "レストランで3%キャッシュバック、年間$6,000まで（その後1%）。年間最大$180の外食報酬。", "ko": "레스토랑에서 3% 캐시백, 연간 $6,000까지(이후 1%). 연간 최대 $180 식사 리워드.", "zh": "餐厅消费获得3%返现，年度上限$6,000（超过后1%）。每年最高可获$180餐饮奖励。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'BEST_USE', '{"en": "3% on Entertainment", "es": "3% en entretenimiento", "fr": "3 % sur divertissement", "ja": "エンターテイメント3%", "ko": "엔터테인먼트 3%", "zh": "娱乐3%返现"}', '{"en": "Earn 3% cash back on entertainment including movies, concerts, sports events, and streaming services.", "es": "Gana 3% en entretenimiento incluyendo cine, conciertos, deportes y servicios de streaming.", "fr": "Gagnez 3 % sur les divertissements incluant cinéma, concerts, sports et services de streaming.", "ja": "映画、コンサート、スポーツイベント、ストリーミングサービスなどエンターテイメントで3%。", "ko": "영화, 콘서트, 스포츠 이벤트, 스트리밍 서비스 등 엔터테인먼트에서 3%.", "zh": "娱乐消费获得3%返现，包括电影、演唱会、体育赛事和流媒体服务。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'BEST_USE', '{"en": "3% on Transit", "es": "3% en transporte", "fr": "3 % sur transport", "ja": "交通3%", "ko": "교통 3%", "zh": "交通3%返现"}', '{"en": "Earn 3% cash back on public transit and alternative transportation including metro, bus, and bike-sharing.", "es": "Gana 3% en transporte público y alternativo incluyendo metro, autobús y bicicletas compartidas.", "fr": "Gagnez 3 % sur le transport en commun et alternatif incluant métro, bus et vélo-partage.", "ja": "地下鉄、バス、シェアバイクなど公共交通と代替交通で3%キャッシュバック。", "ko": "지하철, 버스, 자전거 공유 등 대중교통 및 대체 교통수단에서 3% 캐시백.", "zh": "公共交通和替代交通获得3%返现，包括地铁、公交和共享单车。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'INSURANCE', '{"en": "Travel Insurance Included", "es": "Seguro de viaje incluido", "fr": "Assurance voyage incluse", "ja": "旅行保険付き", "ko": "여행 보험 포함", "zh": "含旅行保险"}', '{"en": "Includes travel emergency medical insurance, trip cancellation, and car rental collision coverage when you pay with this card.", "es": "Incluye seguro médico de emergencia de viaje, cancelación de viaje y colisión de alquiler de auto al pagar con esta tarjeta.", "fr": "Inclut assurance médicale d''urgence voyage, annulation et collision auto location en payant avec cette carte.", "ja": "このカードで支払うと旅行緊急医療保険、旅行キャンセル、レンタカー衝突保険付き。", "ko": "이 카드로 결제 시 여행 응급 의료 보험, 여행 취소, 렌터카 충돌 보험 포함.", "zh": "使用此卡支付时包含旅行紧急医疗保险、行程取消险和租车碰撞险。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'PERK', '{"en": "$100 Welcome Bonus", "es": "Bono de $100", "fr": "Prime de 100 $", "ja": "$100ウェルカムボーナス", "ko": "$100 웰컴 보너스", "zh": "$100开卡奖励"}', '{"en": "Get $100 cash back as a welcome bonus. No minimum spend required. Offsets the first year annual fee completely.", "es": "Obtén $100 de cashback de bienvenida. Sin gasto mínimo. Compensa la cuota anual del primer año.", "fr": "Obtenez 100 $ de remise de bienvenue. Aucun achat minimum. Compense les frais annuels de la première année.", "ja": "$100キャッシュバックウェルカムボーナス獲得。最低消費なし。初年度年会費を完全相殺。", "ko": "$100 캐시백 웰컴 보너스 획득. 최소 지출 없음. 첫해 연회비 완전 상쇄.", "zh": "获得$100开卡返现奖励。无最低消费要求。完全抵消首年年费。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'PERK', '{"en": "World Elite Benefits", "es": "Beneficios World Elite", "fr": "Avantages World Elite", "ja": "World Elite特典", "ko": "World Elite 혜택", "zh": "World Elite权益"}', '{"en": "Includes Mastercard World Elite perks: Boingo Wi-Fi, ShopRunner free shipping, and exclusive offers from luxury brands.", "es": "Incluye beneficios World Elite: Boingo Wi-Fi, ShopRunner envío gratis, ofertas exclusivas de marcas de lujo.", "fr": "Inclut les avantages World Elite : Boingo Wi-Fi, ShopRunner livraison gratuite, offres exclusives marques de luxe.", "ja": "Mastercard World Elite特典付き：Boingo Wi-Fi、ShopRunner無料配送、高級ブランド限定オファー。", "ko": "Mastercard World Elite 혜택 포함: Boingo Wi-Fi, ShopRunner 무료 배송, 럭셔리 브랜드 독점 오퍼.", "zh": "包含Mastercard World Elite权益：Boingo Wi-Fi、ShopRunner免费配送、奢侈品牌专属优惠。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'PERK', '{"en": "Quebec Credit Union", "es": "Cooperativa de Quebec", "fr": "Caisse populaire du Québec", "ja": "ケベック信用組合", "ko": "퀘벡 신용협동조합", "zh": "魁北克信用社"}', '{"en": "Desjardins is the largest credit union in North America. As a member, you own part of the cooperative and may receive annual dividends.", "es": "Desjardins es la cooperativa de crédito más grande de Norteamérica. Como miembro, eres copropietario y puedes recibir dividendos.", "fr": "Desjardins est la plus grande caisse populaire en Amérique du Nord. En tant que membre, vous possédez une partie de la coopérative.", "ja": "DesjardinsはN.A.最大の信用組合。会員として協同組合の一部を所有し、年間配当を受け取る可能性あり。", "ko": "Desjardins는 북미 최대 신용협동조합. 회원으로서 협동조합의 일부를 소유하고 연간 배당금을 받을 수 있음.", "zh": "Desjardins是北美最大的信用社。作为会员，您拥有合作社的一部分，可能获得年度分红。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Desjardins' AND name = 'Cash Back World Elite Mastercard'), 'REDEMPTION', '{"en": "Auto Credit at $100", "es": "Crédito automático a $100", "fr": "Crédit auto à 100 $", "ja": "$100で自動クレジット", "ko": "$100에 자동 크레딧", "zh": "$100自动入账"}', '{"en": "Cash back is automatically credited to your account when you accumulate $100 in rewards. No manual redemption needed.", "es": "El cashback se acredita automáticamente al acumular $100 en recompensas. No se necesita canje manual.", "fr": "La remise est automatiquement créditée lorsque vous accumulez 100 $ de récompenses. Aucun échange manuel.", "ja": "報酬$100蓄積するとキャッシュバックが自動的にクレジット。手動交換不要。", "ko": "리워드 $100 적립 시 캐시백이 자동으로 크레딧. 수동 교환 불필요.", "zh": "累积$100奖励后返现自动计入账户。无需手动兑换。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'AVOID', '{"en": "No Cashback on Foreign Purchases", "es": "Sin cashback en compras extranjeras", "fr": "Pas de remise sur achats étrangers", "ja": "海外購入は返金なし", "ko": "해외 구매 캐시백 없음", "zh": "外币消费无返现"}', '{"en": "Important: You save the 2.5% FX fee, but foreign currency purchases earn 0% cashback. Still a net savings vs most cards.", "es": "Importante: Ahorras 2.5% de cargo FX, pero compras en moneda extranjera ganan 0% cashback. Aún ahorro neto vs mayoría de tarjetas.", "fr": "Important : Vous économisez 2,5 % de frais de change, mais les achats en devise étrangère ne rapportent rien. Toujours économique vs la plupart des cartes.", "ja": "重要：2.5%の外貨手数料を節約できるが、外貨購入はキャッシュバック0%。それでも多くのカードより純節約。", "ko": "중요: 2.5% FX 수수료를 절약하지만 외화 구매는 캐시백 0%. 그래도 대부분의 카드보다 순 절약.", "zh": "重要：你省了2.5%外汇费，但外币消费不赚取返现。与大多数卡相比仍然净省钱。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'AVOID', '{"en": "$12 Inactivity Fee", "es": "Cargo por inactividad $12", "fr": "Frais d''inactivité 12 $", "ja": "$12非アクティブ料金", "ko": "$12 비활성 수수료", "zh": "$12不活跃费"}', '{"en": "If you don''t make at least one purchase in 12 consecutive months, you''ll be charged $12. Use it occasionally to avoid this fee.", "es": "Si no haces al menos una compra en 12 meses consecutivos, te cobrarán $12. Úsala ocasionalmente para evitar este cargo.", "fr": "Si vous ne faites aucun achat pendant 12 mois consécutifs, vous serez facturé 12 $. Utilisez-la occasionnellement pour éviter ces frais.", "ja": "連続12ヶ月購入しないと$12請求される。この料金を避けるため時々使用を。", "ko": "연속 12개월 동안 구매하지 않으면 $12가 청구됨. 이 수수료를 피하려면 가끔 사용.", "zh": "连续12个月不消费会被收取$12。偶尔使用以避免此费用。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'AVOID', '{"en": "Not Available in Quebec", "es": "No disponible en Quebec", "fr": "Non disponible au Québec", "ja": "ケベックでは利用不可", "ko": "퀘벡에서 사용 불가", "zh": "魁北克不可用"}', '{"en": "This card is not available to Quebec residents. Consider Brim Financial or other no-FX-fee alternatives if you''re in Quebec.", "es": "Esta tarjeta no está disponible en Quebec. Considera Brim Financial u otras alternativas sin cargo FX.", "fr": "Cette carte n''est pas disponible au Québec. Considérez Brim Financial ou d''autres alternatives sans frais de change.", "ja": "このカードはケベック居住者には利用できない。ケベックならBrim Financialまたは他の外貨手数料無料の代替品を検討。", "ko": "이 카드는 퀘벡 거주자에게 제공되지 않음. 퀘벡에 있다면 Brim Financial 또는 다른 FX 수수료 무료 대안 고려.", "zh": "此卡不向魁北克居民开放。如果你在魁北克，可考虑Brim Financial或其他无外汇费替代品。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'BEST_USE', '{"en": "No Foreign Transaction Fee", "es": "Sin cargo por transacción extranjera", "fr": "Sans frais de change", "ja": "海外取引手数料なし", "ko": "해외 거래 수수료 없음", "zh": "无外汇费"}', '{"en": "Save 2.5% on every foreign currency purchase. One of the few no-fee cards in Canada with no FX fee. Perfect for travel and international online shopping.", "es": "Ahorra 2.5% en cada compra en moneda extranjera. Una de las pocas tarjetas sin cuota sin cargo FX. Perfecta para viajes y compras internacionales.", "fr": "Économisez 2,5 % sur chaque achat en devise étrangère. L''une des rares cartes sans frais avec aucun frais de change. Parfait pour voyages et achats internationaux.", "ja": "外貨購入ごとに2.5%節約。カナダで数少ない年会費無料・外貨手数料無料カード。旅行と海外オンラインショッピングに最適。", "ko": "모든 외화 구매에서 2.5% 절약. 캐나다에서 드문 연회비 무료 외환 수수료 무료 카드. 여행 및 해외 온라인 쇼핑에 적합.", "zh": "每笔外币消费节省2.5%。加拿大少数无外汇费的免年费卡之一。适合旅行和海外网购。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'BEST_USE', '{"en": "1% on All CAD Purchases", "es": "1% en compras en CAD", "fr": "1 % sur achats en CAD", "ja": "CAD購入全て1%", "ko": "CAD 구매 전체 1%", "zh": "加元消费1%返现"}', '{"en": "Earn 1% unlimited cash back on all Canadian dollar purchases. Simple flat rate with no category restrictions or caps.", "es": "Gana 1% ilimitado en todas las compras en dólares canadienses. Tasa simple sin restricciones de categoría ni límites.", "fr": "Gagnez 1 % illimité sur tous les achats en dollars canadiens. Taux simple sans restrictions de catégorie ni plafond.", "ja": "カナダドル購入全てで1%無制限キャッシュバック。カテゴリ制限や上限なしのシンプルな一律レート。", "ko": "모든 캐나다 달러 구매에서 1% 무제한 캐시백. 카테고리 제한이나 한도 없는 간단한 균일 요율.", "zh": "所有加元消费获得1%无上限返现。简单的统一费率，无类别限制或上限。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee makes this the only free card in Canada with no FX fee. Pure savings on every international purchase.", "es": "Sin cuota anual, es la única tarjeta gratis en Canadá sin cargo FX. Ahorros puros en cada compra internacional.", "fr": "Sans frais annuels, c''est la seule carte gratuite au Canada sans frais de change. Économies pures sur chaque achat international.", "ja": "年会費無料でカナダ唯一の外貨手数料無料無料カード。海外購入ごとに純粋な節約。", "ko": "연회비 무료로 캐나다에서 유일한 외환 수수료 무료 무료 카드. 모든 해외 구매에서 순수 절약.", "zh": "免年费使其成为加拿大唯一无外汇费的免费卡。每笔海外消费都是纯省钱。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'PERK', '{"en": "Visa Card Benefits", "es": "Beneficios Visa", "fr": "Avantages Visa", "ja": "Visaカード特典", "ko": "Visa 카드 혜택", "zh": "Visa卡权益"}', '{"en": "Includes Visa zero liability protection, emergency card replacement, and purchase security. Widely accepted globally.", "es": "Incluye protección de responsabilidad cero Visa, reemplazo de emergencia y seguridad de compra. Ampliamente aceptada globalmente.", "fr": "Inclut protection zéro responsabilité Visa, remplacement d''urgence et sécurité des achats. Largement acceptée mondialement.", "ja": "Visaゼロ責任保護、緊急カード交換、購入セキュリティ付き。世界中で広く受け入れられている。", "ko": "Visa 제로 책임 보호, 긴급 카드 교체, 구매 보안 포함. 전 세계적으로 널리 허용.", "zh": "包含Visa零责任保护、紧急换卡和购物安全。全球广泛接受。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'REDEMPTION', '{"en": "Annual Statement Credit", "es": "Crédito anual en estado de cuenta", "fr": "Crédit annuel sur relevé", "ja": "年次明細クレジット", "ko": "연간 명세서 크레딧", "zh": "年度账单抵扣"}', '{"en": "Cash back accumulates throughout the year and is automatically credited to your January statement. No manual redemption needed.", "es": "El cashback se acumula durante el año y se acredita automáticamente en tu estado de cuenta de enero. Sin canje manual.", "fr": "Les remises s''accumulent toute l''année et sont créditées automatiquement sur votre relevé de janvier. Aucun échange manuel.", "ja": "キャッシュバックは年間を通じて蓄積され、1月の明細に自動クレジット。手動交換不要。", "ko": "캐시백은 연중 누적되어 1월 명세서에 자동 적립. 수동 교환 불필요.", "zh": "返现全年累积，自动计入1月账单。无需手动兑换。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'STACKING', '{"en": "Pair with Category Cards", "es": "Combinar con tarjetas de categorías", "fr": "Combiner avec cartes catégories", "ja": "カテゴリカードと併用", "ko": "카테고리 카드와 결합", "zh": "搭配分类卡使用"}', '{"en": "Use this card exclusively for foreign purchases, and pair it with high-category cards (4-5% grocery, 3% dining) for Canadian spending.", "es": "Usa esta tarjeta exclusivamente para compras extranjeras, y combínala con tarjetas de categorías altas (4-5% supermercado, 3% comida) para gastos canadienses.", "fr": "Utilisez cette carte exclusivement pour les achats étrangers, et combinez avec cartes à catégories (4-5 % épicerie, 3 % restos) pour les dépenses canadiennes.", "ja": "外貨購入専用に使い、カナダ消費には高カテゴリカード（食料品4-5%、外食3%）と併用。", "ko": "해외 구매 전용으로 사용하고 캐나다 지출에는 고카테고리 카드(식료품 4-5%, 식사 3%)와 결합.", "zh": "专门用于外币消费，搭配高类别卡（超市4-5%、餐饮3%）用于加元消费。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Home Trust' AND name = 'Preferred Visa'), 'TRAVEL_BENEFIT', '{"en": "Perfect for Snowbirds", "es": "Perfecto para snowbirds", "fr": "Parfait pour snowbirds", "ja": "スノーバードに最適", "ko": "스노우버드에 적합", "zh": "雪鸟族首选"}', '{"en": "Ideal for Canadians wintering in the US or traveling abroad. Save 2.5% on every USD purchase compared to cards with FX fees.", "es": "Ideal para canadienses que pasan el invierno en EE.UU. o viajan. Ahorra 2.5% en cada compra USD vs tarjetas con cargo FX.", "fr": "Idéal pour les Canadiens hivernant aux É.-U. ou voyageant. Économisez 2,5 % sur chaque achat USD vs cartes avec frais de change.", "ja": "米国で越冬するカナダ人や海外旅行者に最適。外貨手数料付きカードと比較してUSD購入ごとに2.5%節約。", "ko": "미국에서 겨울을 보내거나 해외 여행하는 캐나다인에게 이상적. FX 수수료 카드 대비 USD 구매당 2.5% 절약.", "zh": "适合在美国过冬或出国旅行的加拿大人。与有外汇费的卡相比，每笔美元消费节省2.5%。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'AVOID', '{"en": "Lower Rates Without Prime", "es": "Tasas más bajas sin Prime", "fr": "Taux réduits sans Prime", "ja": "Prime無しは低レート", "ko": "Prime 없이는 낮은 요율", "zh": "非Prime会员费率较低"}', '{"en": "Without Prime, you only earn 1.5% at Amazon/Whole Foods and 1% on foreign purchases. Consider if Prime''s $99/year cost makes sense for your usage.", "es": "Sin Prime, solo ganas 1.5% en Amazon/Whole Foods y 1% en compras extranjeras. Considera si los $99/año de Prime valen la pena.", "fr": "Sans Prime, vous ne gagnez que 1,5 % chez Amazon/Whole Foods et 1 % sur achats étrangers. Évaluez si les 99 $/an de Prime en valent la peine.", "ja": "Prime無しではAmazon/Whole Foodsで1.5%、外貨購入1%のみ。Primeの年間$99が使用頻度に見合うか検討を。", "ko": "Prime 없이는 Amazon/Whole Foods에서 1.5%, 외화 구매 1%만 적립. Prime 연간 $99가 사용량에 맞는지 고려.", "zh": "没有Prime会员只能在Amazon/Whole Foods获得1.5%，外币消费1%。考虑Prime年费$99是否适合你的使用频率。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'AVOID', '{"en": "No Grocery Bonus After 6 Months", "es": "Sin bono de supermercado después de 6 meses", "fr": "Pas de bonus épicerie après 6 mois", "ja": "6ヶ月後は食料品ボーナスなし", "ko": "6개월 후 식료품 보너스 없음", "zh": "6个月后超市无奖励"}', '{"en": "The 5% on groceries and restaurants is only for the first 6 months. After that, these categories drop to the base 1% rate.", "es": "El 5% en supermercado y restaurantes es solo por 6 meses. Después, estas categorías bajan a la tasa base de 1%.", "fr": "Le 5 % sur épicerie et restaurants n''est valable que 6 mois. Après, ces catégories passent au taux de base de 1 %.", "ja": "食料品・レストランの5%は最初の6ヶ月のみ。その後は基本1%レートに。", "ko": "식료품과 레스토랑 5%는 첫 6개월만. 이후 이 카테고리는 기본 1% 요율로 하락.", "zh": "超市和餐厅的5%返现仅限前6个月。之后这些类别降至基础1%费率。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'BEST_USE', '{"en": "2.5% at Amazon.ca (Prime)", "es": "2.5% en Amazon.ca (Prime)", "fr": "2,5 % sur Amazon.ca (Prime)", "ja": "Amazon.ca 2.5%（Prime会員）", "ko": "Amazon.ca 2.5% (Prime)", "zh": "Amazon.ca 2.5%（Prime会员）"}', '{"en": "Prime members earn 2.5% back on Amazon.ca purchases. Non-Prime members earn 1.5%. Perfect if you''re already a Prime subscriber.", "es": "Los miembros Prime ganan 2.5% en Amazon.ca. No Prime: 1.5%. Perfecto si ya eres suscriptor Prime.", "fr": "Les membres Prime gagnent 2,5 % sur Amazon.ca. Non-Prime : 1,5 %. Parfait si vous êtes déjà abonné Prime.", "ja": "Prime会員はAmazon.caで2.5%還元、非会員は1.5%。すでにPrime会員なら最適。", "ko": "Prime 회원은 Amazon.ca에서 2.5% 적립, 비회원은 1.5%. 이미 Prime 구독자라면 적합.", "zh": "Prime会员在Amazon.ca购物可获2.5%返现，非会员1.5%。如果你已是Prime订阅用户，非常划算。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'BEST_USE', '{"en": "2.5% at Whole Foods (Prime)", "es": "2.5% en Whole Foods (Prime)", "fr": "2,5 % chez Whole Foods (Prime)", "ja": "Whole Foods 2.5%（Prime会員）", "ko": "Whole Foods 2.5% (Prime)", "zh": "Whole Foods 2.5%（Prime会员）"}', '{"en": "Prime members earn 2.5% at Whole Foods Market stores in Canada. Non-Prime members earn 1.5%. Stack with Whole Foods in-store deals.", "es": "Los miembros Prime ganan 2.5% en Whole Foods en Canadá. No Prime: 1.5%. Combinable con ofertas en tienda.", "fr": "Les membres Prime gagnent 2,5 % chez Whole Foods au Canada. Non-Prime : 1,5 %. Cumulable avec les offres en magasin.", "ja": "Prime会員はカナダのWhole Foodsで2.5%還元、非会員は1.5%。店舗内セールと併用可能。", "ko": "Prime 회원은 캐나다 Whole Foods에서 2.5% 적립, 비회원은 1.5%. 매장 내 딜과 결합 가능.", "zh": "Prime会员在加拿大Whole Foods门店可获2.5%返现，非会员1.5%。可与店内优惠叠加。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'PERK', '{"en": "5% Welcome Offer", "es": "Oferta de bienvenida 5%", "fr": "Offre de bienvenue 5 %", "ja": "5%ウェルカムオファー", "ko": "5% 웰컴 오퍼", "zh": "5%开卡优惠"}', '{"en": "Get 5% back at Amazon.ca, Whole Foods, grocery stores, and restaurants for the first 6 months on up to $3,000 in purchases. That''s up to $150 in rewards!", "es": "Obtén 5% en Amazon.ca, Whole Foods, supermercados y restaurantes por 6 meses en hasta $3,000 de compras. ¡Hasta $150 en recompensas!", "fr": "Obtenez 5 % sur Amazon.ca, Whole Foods, épiceries et restaurants pendant 6 mois sur 3 000 $ d''achats. Jusqu''à 150 $ de récompenses !", "ja": "最初の6ヶ月間、Amazon.ca、Whole Foods、食料品店、レストランで5%還元（$3,000まで）。最大$150の報酬！", "ko": "첫 6개월간 Amazon.ca, Whole Foods, 식료품점, 레스토랑에서 5% 적립 ($3,000까지). 최대 $150 리워드!", "zh": "前6个月在Amazon.ca、Whole Foods、超市和餐厅消费可获5%返现，最高$3,000消费。最多可赚$150！"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual credit card fee. All rewards earned are pure profit. Great companion to your Prime membership.", "es": "Sin cuota anual. Todas las recompensas son ganancia pura. Gran compañero para tu membresía Prime.", "fr": "Aucuns frais annuels. Toutes les récompenses sont du profit pur. Excellent complément à votre abonnement Prime.", "ja": "年会費無料。獲得した報酬は全て純利益。Prime会員の良きパートナー。", "ko": "연회비 무료. 모든 리워드가 순이익. Prime 멤버십의 좋은 동반자.", "zh": "无信用卡年费。所有返现都是纯利润。与Prime会员完美搭配。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'PERK', '{"en": "Amazon Ecosystem Integration", "es": "Integración ecosistema Amazon", "fr": "Intégration écosystème Amazon", "ja": "Amazonエコシステム統合", "ko": "Amazon 생태계 통합", "zh": "Amazon生态系统整合"}', '{"en": "Seamlessly integrated with your Amazon account. View rewards, manage card, and redeem points all within Amazon.ca.", "es": "Integrado con tu cuenta Amazon. Ve recompensas, gestiona la tarjeta y canjea puntos en Amazon.ca.", "fr": "Intégré à votre compte Amazon. Consultez les récompenses, gérez la carte et échangez les points sur Amazon.ca.", "ja": "Amazonアカウントとシームレスに統合。Amazon.ca内で報酬確認、カード管理、ポイント交換が可能。", "ko": "Amazon 계정과 원활하게 통합. Amazon.ca 내에서 리워드 확인, 카드 관리, 포인트 사용 가능.", "zh": "与您的Amazon账户无缝整合。在Amazon.ca内查看返现、管理卡片、兑换积分。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'REDEMPTION', '{"en": "Automatic Statement Credit", "es": "Crédito automático en estado de cuenta", "fr": "Crédit automatique sur relevé", "ja": "自動明細クレジット", "ko": "자동 명세서 크레딧", "zh": "自动账单抵扣"}', '{"en": "Cash back is automatically applied as a statement credit. No manual redemption required - just earn and save.", "es": "El cashback se aplica automáticamente como crédito. No se requiere canje manual.", "fr": "La remise est automatiquement appliquée comme crédit sur relevé. Aucun échange manuel requis.", "ja": "キャッシュバックは自動的に明細クレジットとして適用。手動交換不要。", "ko": "캐시백이 자동으로 명세서 크레딧으로 적용. 수동 교환 불필요.", "zh": "返现自动作为账单抵扣。无需手动兑换，只需消费即可省钱。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'STACKING', '{"en": "Pair with Grocery Card", "es": "Combinar con tarjeta de supermercado", "fr": "Combiner avec carte épicerie", "ja": "食料品カードと併用", "ko": "식료품 카드와 결합", "zh": "搭配超市卡使用"}', '{"en": "Use this card exclusively for Amazon.ca and Whole Foods. Pair with a 4-5% grocery card for other supermarkets and a dining card for restaurants.", "es": "Usa esta tarjeta exclusivamente para Amazon.ca y Whole Foods. Combínala con una tarjeta de supermercado 4-5% y una de restaurantes.", "fr": "Utilisez cette carte exclusivement pour Amazon.ca et Whole Foods. Combinez avec une carte épicerie 4-5 % et une carte restaurant.", "ja": "Amazon.caとWhole Foods専用に使用。他のスーパーには4-5%食料品カード、レストランには外食カードと併用。", "ko": "Amazon.ca와 Whole Foods 전용으로 사용. 다른 슈퍼마켓에는 4-5% 식료품 카드, 레스토랑에는 식사 카드와 결합.", "zh": "专门用于Amazon.ca和Whole Foods消费。搭配4-5%超市卡用于其他超市，餐饮卡用于餐厅。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Amazon.ca Rewards Mastercard'), 'TRAVEL_BENEFIT', '{"en": "FX Fee Offset (Prime)", "es": "Compensación cargo FX (Prime)", "fr": "Compensation frais FX (Prime)", "ja": "FX手数料相殺（Prime会員）", "ko": "FX 수수료 상쇄 (Prime)", "zh": "外汇费抵消（Prime会员）"}', '{"en": "Prime members earn 2.5% on foreign currency purchases, which exactly offsets the 2.5% FX fee. Net result: 0% cost for international purchases.", "es": "Los miembros Prime ganan 2.5% en compras en moneda extranjera, compensando exactamente el cargo FX de 2.5%. Resultado: 0% de costo.", "fr": "Les membres Prime gagnent 2,5 % sur les achats en devises, compensant exactement les frais de change de 2,5 %. Résultat : 0 % de frais.", "ja": "Prime会員は外貨購入で2.5%還元、2.5%のFX手数料を正確に相殺。純結果：海外購入コスト0%。", "ko": "Prime 회원은 외화 구매에서 2.5% 적립, 2.5% FX 수수료를 정확히 상쇄. 순결과: 해외 구매 비용 0%.", "zh": "Prime会员外币消费可获2.5%返现，正好抵消2.5%外汇费。净结果：海外消费0成本。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'AVOID', '{"en": "$120 Annual Fee", "es": "Cuota anual $120", "fr": "Frais annuels 120 $", "ja": "年会費$120", "ko": "연회비 $120", "zh": "$120年费"}', '{"en": "Annual fee of $120. You need to spend ~$2,400/year in 5x categories to break even vs a 2% no-fee card. Birthday bonus helps offset.", "es": "Cuota de $120/año. Necesitas gastar ~$2,400/año en categorías 5x para igualar una tarjeta 2% sin cuota.", "fr": "Frais de 120 $/an. Il faut dépenser ~2 400 $/an dans les catégories 5x pour rentabiliser vs carte 2 % sans frais.", "ja": "年会費$120。2%年会費無料カードと同等にするには5xカテゴリで約$2,400/年の消費が必要。", "ko": "연회비 $120. 2% 연회비 무료 카드와 동등하려면 5배 카테고리에서 연간 약 $2,400 지출 필요.", "zh": "年费$120。需在5倍类别消费约$2,400/年才能与2%免年费卡持平。生日奖励有助于抵消。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'BEST_USE', '{"en": "5x Points on Groceries", "es": "5x puntos en supermercados", "fr": "5x points épicerie", "ja": "食料品5倍ポイント", "ko": "식료품 5배 포인트", "zh": "超市5倍积分"}', '{"en": "Earn 5 points per $1 at grocery stores, up to $50,000 annual spend. That''s effectively 5% back when redeemed for travel.", "es": "Gana 5 puntos por $1 en supermercados, hasta $50,000 anuales. Equivale a 5% al canjear por viajes.", "fr": "Gagnez 5 points par dollar à l''épicerie, jusqu''à 50 000 $ par an. Équivalent à 5 % en voyage.", "ja": "食料品店で$1あたり5ポイント、年間$50,000まで。旅行交換で実質5%還元。", "ko": "식료품점에서 $1당 5포인트, 연간 $50,000까지. 여행 교환 시 실질 5% 적립.", "zh": "超市消费每$1获5积分，年度上限$50,000消费。旅行兑换相当于5%返现。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'BEST_USE', '{"en": "5x Points on Dining", "es": "5x puntos en restaurantes", "fr": "5x points restaurants", "ja": "レストラン5倍ポイント", "ko": "레스토랑 5배 포인트", "zh": "餐厅5倍积分"}', '{"en": "Earn 5 points per $1 at restaurants. One of the highest dining rewards among Canadian credit cards.", "es": "Gana 5 puntos por $1 en restaurantes. Una de las mejores tasas de comida en Canadá.", "fr": "Gagnez 5 points par dollar aux restaurants. L''un des meilleurs taux restaurants au Canada.", "ja": "レストランで$1あたり5ポイント。カナダのクレジットカードで最高の外食報酬の一つ。", "ko": "레스토랑에서 $1당 5포인트. 캐나다 신용카드 중 최고의 식사 리워드 중 하나.", "zh": "餐厅消费每$1获5积分。加拿大信用卡中餐饮奖励最高的卡之一。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'BEST_USE', '{"en": "5x on Streaming Services", "es": "5x en streaming", "fr": "5x sur streaming", "ja": "ストリーミング5倍", "ko": "스트리밍 5배", "zh": "流媒体5倍积分"}', '{"en": "Earn 5 points per $1 on digital media subscriptions like Netflix, Spotify, Apple Music, and gaming services.", "es": "Gana 5 puntos por $1 en suscripciones digitales como Netflix, Spotify, Apple Music y servicios de juegos.", "fr": "Gagnez 5 points par dollar sur les abonnements numériques : Netflix, Spotify, Apple Music, jeux vidéo.", "ja": "Netflix、Spotify、Apple Music、ゲームサービスなどデジタルメディアで$1あたり5ポイント。", "ko": "Netflix, Spotify, Apple Music, 게임 서비스 등 디지털 미디어 구독에서 $1당 5포인트.", "zh": "流媒体订阅消费每$1获5积分，包括Netflix、Spotify、Apple Music和游戏服务。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'BEST_USE', '{"en": "5x on Utilities & Telecom", "es": "5x en servicios públicos", "fr": "5x sur services publics", "ja": "公共料金5倍", "ko": "공과금 5배", "zh": "水电网5倍积分"}', '{"en": "Earn 5 points per $1 on household utilities (electricity, gas, water) and telecom bills. Set up auto-pay for passive rewards.", "es": "Gana 5 puntos por $1 en servicios públicos y telecom. Configura pago automático para recompensas pasivas.", "fr": "Gagnez 5 points par dollar sur les services publics et télécom. Configurez le paiement automatique pour des récompenses passives.", "ja": "電気・ガス・水道・通信で$1あたり5ポイント。自動支払い設定でパッシブ報酬を獲得。", "ko": "전기, 가스, 수도, 통신에서 $1당 5포인트. 자동 결제 설정으로 패시브 리워드 획득.", "zh": "水电气账单和电信费用每$1获5积分。设置自动付款即可被动获取奖励。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'INSURANCE', '{"en": "World Elite Insurance", "es": "Seguro World Elite", "fr": "Assurance World Elite", "ja": "World Elite保険", "ko": "World Elite 보험", "zh": "World Elite保险"}', '{"en": "Includes travel emergency medical, trip cancellation, car rental collision, mobile device insurance, and extended warranty.", "es": "Incluye seguro médico de viaje, cancelación, colisión de alquiler de auto, dispositivo móvil y garantía extendida.", "fr": "Inclut assurance médicale voyage, annulation, collision auto location, appareil mobile et garantie prolongée.", "ja": "旅行緊急医療、旅行キャンセル、レンタカー衝突、モバイル機器保険、延長保証付き。", "ko": "여행 응급 의료, 여행 취소, 렌터카 충돌, 모바일 기기 보험, 연장 보증 포함.", "zh": "包含旅行紧急医疗、行程取消、租车碰撞、手机保险和延长保修。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'PERK', '{"en": "Birthday Bonus: 10%", "es": "Bono de cumpleaños: 10%", "fr": "Bonus anniversaire : 10 %", "ja": "誕生日ボーナス：10%", "ko": "생일 보너스: 10%", "zh": "生日奖励：10%"}', '{"en": "Receive up to 15,000 bonus points on your birthday - that''s 10% of your annual earnings! A unique perk among Canadian cards.", "es": "Recibe hasta 15,000 puntos de bonificación en tu cumpleaños - ¡10% de tus ganancias anuales! Un beneficio único en Canadá.", "fr": "Recevez jusqu''à 15 000 points bonus à votre anniversaire - soit 10 % de vos gains annuels ! Avantage unique au Canada.", "ja": "誕生日に最大15,000ボーナスポイント獲得 - 年間獲得ポイントの10%！カナダのカードでユニークな特典。", "ko": "생일에 최대 15,000 보너스 포인트 - 연간 적립의 10%! 캐나다 카드 중 독특한 혜택.", "zh": "生日时可获最高15,000积分奖励 - 相当于年度积分的10%！加拿大信用卡中独特的权益。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'PERK', '{"en": "30,000 Points Welcome Offer", "es": "Oferta de bienvenida 30,000 puntos", "fr": "Offre de bienvenue 30 000 points", "ja": "30,000ポイントウェルカムオファー", "ko": "30,000 포인트 웰컴 오퍼", "zh": "30,000积分开卡奖励"}', '{"en": "Get 20,000 points after $2,000 spend in 90 days, plus 10,000 bonus for e-statements. Total 30,000 points worth $300 in travel!", "es": "20,000 puntos tras $2,000 en 90 días, más 10,000 por e-statements. ¡30,000 puntos = $300 en viajes!", "fr": "20 000 points après 2 000 $ en 90 jours, plus 10 000 pour les relevés électroniques. 30 000 points = 300 $ en voyage !", "ja": "90日以内に$2,000消費で20,000ポイント、電子明細で10,000追加。合計30,000ポイント、旅行で$300相当！", "ko": "90일 내 $2,000 지출 후 20,000 포인트, 전자 명세서로 10,000 추가. 총 30,000 포인트, 여행 $300 상당!", "zh": "90天内消费$2,000获20,000积分，注册电子账单再获10,000积分。共30,000积分，旅行价值$300！"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'PERK', '{"en": "Points Never Expire", "es": "Puntos sin vencimiento", "fr": "Points sans expiration", "ja": "ポイント無期限", "ko": "포인트 만료 없음", "zh": "积分永不过期"}', '{"en": "Your MBNA Rewards points never expire as long as your account is open and in good standing. Accumulate freely.", "es": "Tus puntos MBNA nunca expiran mientras tu cuenta esté abierta y al día. Acumula libremente.", "fr": "Vos points MBNA n''expirent jamais tant que votre compte est ouvert et en règle. Accumulez librement.", "ja": "アカウントが開設され良好な状態であれば、MBNAポイントは無期限。自由に貯められる。", "ko": "계정이 열려 있고 양호한 상태라면 MBNA 포인트는 만료되지 않음. 자유롭게 적립.", "zh": "只要账户开放且信誉良好，MBNA积分永不过期。可自由累积。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'Rewards World Elite Mastercard'), 'REDEMPTION', '{"en": "Redeem for Travel: Best Value", "es": "Canjear por viajes: mejor valor", "fr": "Échange voyage : meilleure valeur", "ja": "旅行交換が最高価値", "ko": "여행 교환이 최고 가치", "zh": "旅行兑换价值最高"}', '{"en": "Travel redemption: 100 points = $1. Cash redemption: 120 points = $1. Always redeem for travel to maximize value.", "es": "Viajes: 100 puntos = $1. Efectivo: 120 puntos = $1. Siempre canjea por viajes para maximizar el valor.", "fr": "Voyage : 100 points = 1 $. Argent : 120 points = 1 $. Échangez toujours contre des voyages pour maximiser la valeur.", "ja": "旅行交換：100ポイント=$1。現金交換：120ポイント=$1。価値最大化には常に旅行交換を。", "ko": "여행 교환: 100포인트 = $1. 현금 교환: 120포인트 = $1. 가치 극대화를 위해 항상 여행으로 교환.", "zh": "旅行兑换：100积分=$1。现金兑换：120积分=$1。始终选择旅行兑换以最大化价值。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'AVOID', '{"en": "No Cash Back or Rewards", "es": "Sin cashback ni recompensas", "fr": "Pas de remise ni récompenses", "ja": "キャッシュバックなし", "ko": "캐시백 또는 리워드 없음", "zh": "无返现或奖励"}', '{"en": "This is a low-interest card, not a rewards card. If you pay your balance in full each month, use a cashback card instead.", "es": "Es una tarjeta de bajo interés, no de recompensas. Si pagas el saldo completo cada mes, usa una tarjeta de cashback.", "fr": "C''est une carte à faible taux, pas une carte de récompenses. Payez en entier chaque mois ? Utilisez une carte remise.", "ja": "これは低金利カードで、報酬カードではない。毎月全額返済するならキャッシュバックカードを使うべき。", "ko": "이것은 저금리 카드이며 리워드 카드가 아님. 매달 잔액을 전액 납부하면 캐시백 카드를 사용하세요.", "zh": "这是低利率卡，不是返现卡。如果你每月全额还款，应该使用返现卡。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'AVOID', '{"en": "$39 Annual Fee", "es": "Cuota anual $39", "fr": "Frais annuels 39 $", "ja": "年会費$39", "ko": "연회비 $39", "zh": "$39年费"}', '{"en": "Consider: You need to carry ~$390 balance for a year to save $39 in interest vs a 19.99% card. Only worth it if you regularly carry balances.", "es": "Considera: necesitas cargar ~$390 por un año para ahorrar $39 vs tarjeta de 19.99%.", "fr": "Réfléchissez : vous devez porter ~390 $ pendant un an pour économiser 39 $ vs carte à 19,99 %.", "ja": "検討：19.99%カードより$39節約するには約$390の残高を1年持つ必要あり。", "ko": "고려: 19.99% 카드 대비 $39 절약하려면 1년간 약 $390 잔액 필요.", "zh": "考虑：需要持续一年约$390的余额，才能比19.99%的卡省下$39利息。只有经常分期才值得。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'BEST_USE', '{"en": "10.99% APR - Lowest Rate", "es": "10.99% APR - Tasa más baja", "fr": "10,99 % TAP - Taux le plus bas", "ja": "10.99% APR - 最低金利", "ko": "10.99% APR - 최저 금리", "zh": "10.99%年利率 - 最低利率"}', '{"en": "One of the lowest purchase interest rates in Canada at 10.99%. Ideal if you occasionally carry a balance and want to minimize interest charges.", "es": "Una de las tasas de interés más bajas de Canadá al 10.99%. Ideal si ocasionalmente cargas un saldo.", "fr": "L''un des taux d''intérêt les plus bas au Canada à 10,99 %. Idéal si vous portez parfois un solde.", "ja": "カナダで最も低い購入金利の一つ、10.99%。たまに残高を持ち越す場合に最適。", "ko": "캐나다에서 가장 낮은 구매 금리 중 하나인 10.99%. 가끔 잔액을 이월하는 경우 적합.", "zh": "加拿大最低购物利率之一，仅10.99%。如果你偶尔需要分期付款，可以最大限度减少利息支出。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'BEST_USE', '{"en": "Debt Consolidation", "es": "Consolidación de deudas", "fr": "Consolidation de dettes", "ja": "債務整理", "ko": "부채 통합", "zh": "债务整合"}', '{"en": "Transfer high-interest balances at 13.99% (1% fee). Save significantly vs 19.99%+ cards. Good for paying down debt faster.", "es": "Transfiere saldos de alto interés al 13.99% (1% de comisión). Ahorra vs tarjetas de 19.99%+.", "fr": "Transférez les soldes à taux élevé à 13,99 % (frais de 1 %). Économisez vs cartes à 19,99 %+.", "ja": "高金利残高を13.99%で移行（1%手数料）。19.99%+カードより大幅節約。", "ko": "고금리 잔액을 13.99%로 이전 (1% 수수료). 19.99%+ 카드 대비 대폭 절약.", "zh": "以13.99%利率转移高息余额（1%手续费）。比19.99%+的卡节省大量利息。有助于更快还清债务。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'PERK', '{"en": "9 Free Authorized Users", "es": "9 usuarios autorizados gratis", "fr": "9 utilisateurs autorisés gratuits", "ja": "9人の無料追加ユーザー", "ko": "9명의 무료 추가 사용자", "zh": "9张免费附属卡"}', '{"en": "Add up to 9 authorized users at no extra cost. Great for families who want to share a low-interest card.", "es": "Agrega hasta 9 usuarios sin costo adicional. Ideal para familias.", "fr": "Ajoutez jusqu''à 9 utilisateurs sans frais supplémentaires. Idéal pour les familles.", "ja": "追加費用なしで最大9人の追加ユーザー。低金利カードを共有したい家族に最適。", "ko": "추가 비용 없이 최대 9명의 추가 사용자. 저금리 카드를 공유하려는 가족에게 적합.", "zh": "可免费添加最多9名附属卡用户。适合想共享低利率卡的家庭。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'PERK', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Includes 90-day Purchase Assurance and Extended Warranty that doubles manufacturer warranty. Protects your purchases.", "es": "Incluye 90 días de protección de compras y garantía extendida. Protege tus compras.", "fr": "Inclut 90 jours de protection des achats et garantie prolongée. Protège vos achats.", "ja": "90日間の購入保証と延長保証（メーカー保証を2倍に）付き。", "ko": "90일 구매 보장 및 연장 보증(제조사 보증 2배) 포함. 구매 보호.", "zh": "包含90天购物保障和延长保修（双倍制造商保修期）。保护您的购物。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'PERK', '{"en": "Rental Car Discounts", "es": "Descuentos en alquiler de autos", "fr": "Rabais location auto", "ja": "レンタカー割引", "ko": "렌터카 할인", "zh": "租车折扣"}', '{"en": "Get 10% off Avis/Budget rentals in Canada/US and 5% internationally. A nice perk for travelers.", "es": "10% de descuento en Avis/Budget en Canadá/EE.UU. y 5% internacional.", "fr": "10 % de rabais Avis/Budget au Canada/É.-U. et 5 % à l''international.", "ja": "カナダ/米国でAvis/Budgetレンタル10%オフ、国際5%オフ。", "ko": "캐나다/미국에서 Avis/Budget 렌탈 10% 할인, 국제 5% 할인.", "zh": "加拿大/美国Avis/Budget租车享9折，国际5%折扣。旅行者的好福利。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'MBNA' AND name = 'True Line Gold Mastercard'), 'STACKING', '{"en": "Pair with Rewards Card", "es": "Combinar con tarjeta de recompensas", "fr": "Combiner avec carte récompenses", "ja": "報酬カードと併用", "ko": "리워드 카드와 결합", "zh": "搭配返现卡使用"}', '{"en": "Use this card only for purchases you plan to pay off over time. Use a high-cashback card for everyday spending you''ll pay in full.", "es": "Usa esta tarjeta solo para compras que planeas pagar a plazos. Usa una tarjeta de cashback para gastos diarios.", "fr": "Utilisez cette carte uniquement pour les achats à payer sur le temps. Utilisez une carte remise pour le quotidien.", "ja": "分割払い予定の購入のみに使用。毎月全額返済する日常消費には高キャッシュバックカードを。", "ko": "할부로 갚을 구매에만 사용. 전액 납부할 일상 지출에는 고캐시백 카드 사용.", "zh": "仅用于计划分期付款的消费。日常消费（全额还款）应使用高返现卡。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'AVOID', '{"en": "Only 0.5% on Other Purchases", "es": "Solo 0.5% en otras compras", "fr": "Seulement 0,5 % sur autres achats", "ja": "他の購入は0.5%のみ", "ko": "기타 구매는 0.5%만", "zh": "其他消费仅0.5%"}', '{"en": "Non-bonus categories earn only 0.5%. Use a different card for dining, travel, and other spending.", "es": "Las categorías sin bonificación solo ganan 0.5%. Usa otra tarjeta para comida y viajes.", "fr": "Les catégories non bonifiées ne rapportent que 0,5 %. Utilisez une autre carte pour restaurants et voyages.", "ja": "ボーナスカテゴリ外は0.5%のみ。外食や旅行には別のカードを。", "ko": "비보너스 카테고리는 0.5%만 적립. 식사, 여행 등에는 다른 카드 사용.", "zh": "非奖励类别仅获0.5%。餐饮、旅行和其他消费请使用其他卡。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'AVOID', '{"en": "Consider Infinite Version", "es": "Considera la versión Infinite", "fr": "Considérez la version Infinite", "ja": "Infinite版を検討", "ko": "Infinite 버전 고려", "zh": "考虑Infinite版本"}', '{"en": "Meridian Visa Infinite offers 4% gas/grocery, 2% pharmacy/bills. Worth the $99 fee if you spend $3,300+/year in these categories.", "es": "Meridian Visa Infinite ofrece 4% gasolina/supermercado, 2% farmacia/facturas. Vale los $99 si gastas $3,300+/año.", "fr": "Meridian Visa Infinite offre 4 % essence/épicerie, 2 % pharmacie/factures. Vaut les 99 $ si vous dépensez 3 300 $+/an.", "ja": "Meridian Visa Infiniteはガス/食料品4%、薬局/請求書2%。年間$3,300+消費なら$99の年会費は価値あり。", "ko": "Meridian Visa Infinite는 주유/식료품 4%, 약국/청구서 2%. 이 카테고리에서 연간 $3,300+ 지출 시 $99 연회비 가치 있음.", "zh": "Meridian Visa Infinite提供加油/超市4%、药房/账单2%。如果这些类别年消费$3,300+，$99年费值得。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'BEST_USE', '{"en": "1% on Gas & Groceries", "es": "1% en gasolina y supermercado", "fr": "1 % sur essence et épicerie", "ja": "ガス・食料品1%", "ko": "주유 및 식료품 1%", "zh": "加油超市1%返现"}', '{"en": "Earn 1% cash back on gas and grocery purchases. Simple no-fee card for everyday essentials.", "es": "Gana 1% en gasolina y supermercado. Tarjeta simple sin cuota para gastos esenciales.", "fr": "Gagnez 1 % sur essence et épicerie. Carte simple sans frais pour les essentiels du quotidien.", "ja": "ガスと食料品で1%キャッシュバック。日常の必需品にシンプルな年会費無料カード。", "ko": "주유와 식료품에서 1% 캐시백. 일상 필수품을 위한 간단한 연회비 무료 카드.", "zh": "加油和超市消费获得1%返现。日常消费的简单免年费卡。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'BEST_USE', '{"en": "1% on Pharmacy & Bills", "es": "1% en farmacia y facturas", "fr": "1 % sur pharmacie et factures", "ja": "薬局・請求書1%", "ko": "약국 및 청구서 1%", "zh": "药房账单1%返现"}', '{"en": "Earn 1% on pharmacy purchases and utility bill payments. Set up auto-pay for passive rewards on recurring bills.", "es": "Gana 1% en farmacia y pagos de servicios. Configura pago automático para recompensas pasivas.", "fr": "Gagnez 1 % sur pharmacie et paiements de factures. Configurez le paiement auto pour des récompenses passives.", "ja": "薬局と公共料金支払いで1%獲得。自動支払いでパッシブ報酬を獲得。", "ko": "약국과 공과금 지불에서 1% 적립. 자동 결제 설정으로 패시브 리워드 획득.", "zh": "药房消费和水电账单支付可获1%返现。设置自动付款可被动获取定期账单奖励。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee means all rewards earned are pure savings. Great entry-level card from a credit union.", "es": "Sin cuota anual significa ahorros puros. Excelente tarjeta inicial de una cooperativa de crédito.", "fr": "Sans frais annuels signifie économies pures. Excellente carte d''entrée d''une caisse populaire.", "ja": "年会費無料で獲得した報酬は全て純粋な節約。信用組合の良いエントリーカード。", "ko": "연회비 무료로 모든 리워드가 순수 절약. 신용협동조합의 좋은 입문 카드.", "zh": "免年费意味着所有返现都是纯省钱。信用社的优质入门卡。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'PERK', '{"en": "Credit Union Member", "es": "Miembro de cooperativa", "fr": "Membre de la caisse", "ja": "信用組合会員", "ko": "신용협동조합 회원", "zh": "信用社会员"}', '{"en": "As a Meridian member, you''re a part-owner of the credit union. May receive annual profit-sharing dividends.", "es": "Como miembro de Meridian, eres copropietario de la cooperativa. Puede recibir dividendos anuales.", "fr": "En tant que membre Meridian, vous êtes copropriétaire de la caisse. Peut recevoir des dividendes annuels.", "ja": "Meridian会員として信用組合の共同オーナー。年間利益配当を受け取る可能性あり。", "ko": "Meridian 회원으로서 신용협동조합의 공동 소유자. 연간 이익 배당금을 받을 수 있음.", "zh": "作为Meridian会员，你是信用社的部分所有者。可能获得年度利润分红。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'REDEMPTION', '{"en": "Redeem for Travel or Credit", "es": "Canjear por viaje o crédito", "fr": "Échanger pour voyage ou crédit", "ja": "旅行またはクレジットに交換", "ko": "여행 또는 크레딧으로 교환", "zh": "兑换旅行或账单抵扣"}', '{"en": "Redeem Meridian Rewards points for travel (100 pts = $1), statement credit, gift cards, or merchandise.", "es": "Canjea puntos Meridian por viajes (100 pts = $1), crédito, tarjetas regalo o mercancía.", "fr": "Échangez les points Meridian pour voyages (100 pts = 1 $), crédit, cartes-cadeaux ou marchandise.", "ja": "Meridianポイントを旅行（100ポイント=$1）、明細クレジット、ギフトカード、商品に交換。", "ko": "Meridian 포인트를 여행(100포인트 = $1), 명세서 크레딧, 기프트 카드, 상품으로 교환.", "zh": "Meridian积分可兑换旅行（100积分=$1）、账单抵扣、礼品卡或商品。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Cash Back'), 'STACKING', '{"en": "Pair with Dining Card", "es": "Combinar con tarjeta de restaurantes", "fr": "Combiner avec carte restaurants", "ja": "ダイニングカードと併用", "ko": "식사 카드와 결합", "zh": "搭配餐饮卡使用"}', '{"en": "Use this card for gas, groceries, pharmacy, and bills. Pair with a 3-4% dining card for restaurants.", "es": "Usa para gasolina, supermercado, farmacia y facturas. Combina con tarjeta de restaurantes 3-4%.", "fr": "Utilisez pour essence, épicerie, pharmacie et factures. Combinez avec carte restaurants 3-4 %.", "ja": "ガス、食料品、薬局、請求書に使用。レストランには3-4%の外食カードと併用。", "ko": "주유, 식료품, 약국, 청구서에 사용. 레스토랑에는 3-4% 식사 카드와 결합.", "zh": "用于加油、超市、药房和账单。搭配3-4%餐饮卡用于餐厅消费。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'AVOID', '{"en": "$25,000 Annual Cap", "es": "Límite anual $25,000", "fr": "Plafond annuel 25 000 $", "ja": "年間$25,000上限", "ko": "연간 $25,000 한도", "zh": "$25,000年度上限"}', '{"en": "Bonus categories share a $25,000 annual cap. After that, all spending drops to 1%. Resets January 1 each year.", "es": "Las categorías de bonificación comparten límite de $25,000/año. Después, todo baja a 1%. Se reinicia el 1 de enero.", "fr": "Les catégories bonus partagent un plafond de 25 000 $/an. Après, tout passe à 1 %. Réinitialisation le 1er janvier.", "ja": "ボーナスカテゴリは$25,000年間上限を共有。超過後は全て1%に。毎年1月1日リセット。", "ko": "보너스 카테고리가 연간 $25,000 한도 공유. 이후 모든 지출 1%로 하락. 매년 1월 1일 리셋.", "zh": "奖励类别共享$25,000年度上限。超过后所有消费降至1%。每年1月1日重置。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'AVOID', '{"en": "$99 Annual Fee", "es": "Cuota anual $99", "fr": "Frais annuels 99 $", "ja": "年会費$99", "ko": "연회비 $99", "zh": "$99年费"}', '{"en": "After year 1, the $99 fee applies. Need ~$3,300/year in 4% categories to break even vs a 1% no-fee card.", "es": "Después del año 1, aplica cuota de $99. Necesitas ~$3,300/año en categorías 4% para igualar tarjeta 1% sin cuota.", "fr": "Après l''an 1, les frais de 99 $ s''appliquent. Il faut ~3 300 $/an en catégories 4 % pour rentabiliser.", "ja": "1年目以降$99の年会費適用。1%年会費無料カードと同等にするには4%カテゴリで約$3,300/年必要。", "ko": "1년차 이후 $99 연회비 적용. 1% 연회비 무료 카드와 동등하려면 4% 카테고리에서 연간 약 $3,300 필요.", "zh": "第一年后需支付$99年费。需在4%类别年消费约$3,300才能与1%免年费卡持平。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'BEST_USE', '{"en": "4% on Gas", "es": "4% en gasolina", "fr": "4 % sur essence", "ja": "ガソリン4%", "ko": "주유 4%", "zh": "加油4%返现"}', '{"en": "Earn 4% cash back on gas purchases up to $25,000/year combined with groceries. One of the best gas rates in Canada.", "es": "Gana 4% en gasolina hasta $25,000/año combinado con supermercado. Una de las mejores tasas de gasolina en Canadá.", "fr": "Gagnez 4 % sur l''essence jusqu''à 25 000 $/an combiné avec épicerie. L''un des meilleurs taux essence au Canada.", "ja": "ガソリンで4%キャッシュバック、食料品と合計年間$25,000まで。カナダ最高のガソリンレートの一つ。", "ko": "주유에서 4% 캐시백, 식료품과 합산 연간 $25,000까지. 캐나다 최고의 주유 요율 중 하나.", "zh": "加油消费获得4%返现，与超市合计年度上限$25,000。加拿大最高的加油返现率之一。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'BEST_USE', '{"en": "4% on Groceries", "es": "4% en supermercado", "fr": "4 % sur épicerie", "ja": "食料品4%", "ko": "식료품 4%", "zh": "超市4%返现"}', '{"en": "Earn 4% cash back on grocery purchases up to $25,000/year combined with gas. Perfect for families with high grocery spending.", "es": "Gana 4% en supermercado hasta $25,000/año combinado con gasolina. Perfecto para familias con alto gasto en supermercado.", "fr": "Gagnez 4 % sur l''épicerie jusqu''à 25 000 $/an combiné avec essence. Parfait pour familles avec dépenses épicerie élevées.", "ja": "食料品で4%キャッシュバック、ガソリンと合計年間$25,000まで。食料品支出の多い家族に最適。", "ko": "식료품에서 4% 캐시백, 주유와 합산 연간 $25,000까지. 식료품 지출이 많은 가정에 적합.", "zh": "超市消费获得4%返现，与加油合计年度上限$25,000。适合超市消费高的家庭。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'BEST_USE', '{"en": "2% on Pharmacy & Bills", "es": "2% en farmacia y facturas", "fr": "2 % pharmacie et factures", "ja": "薬局・請求書2%", "ko": "약국 및 청구서 2%", "zh": "药房账单2%返现"}', '{"en": "Earn 2% on pharmacy and utility bill payments up to $25,000/year. Set up auto-pay for bills to earn passively.", "es": "Gana 2% en farmacia y facturas hasta $25,000/año. Configura pago automático para ganar pasivamente.", "fr": "Gagnez 2 % sur pharmacie et factures jusqu''à 25 000 $/an. Configurez le paiement auto pour gagner passivement.", "ja": "薬局と公共料金で2%獲得、年間$25,000まで。請求書を自動支払いに設定でパッシブ獲得。", "ko": "약국과 공과금에서 2% 적립, 연간 $25,000까지. 청구서 자동 결제로 패시브 적립.", "zh": "药房和水电账单支付获得2%返现，年度上限$25,000。设置账单自动付款可被动赚取。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'INSURANCE', '{"en": "Visa Infinite Insurance", "es": "Seguro Visa Infinite", "fr": "Assurance Visa Infinite", "ja": "Visa Infinite保険", "ko": "Visa Infinite 보험", "zh": "Visa Infinite保险"}', '{"en": "Includes travel emergency medical, trip cancellation/interruption, car rental collision, and purchase protection.", "es": "Incluye seguro médico de viaje, cancelación/interrupción, colisión de alquiler de auto y protección de compras.", "fr": "Inclut assurance médicale voyage, annulation/interruption, collision location auto et protection des achats.", "ja": "旅行緊急医療、旅行キャンセル/中断、レンタカー衝突、購入保護付き。", "ko": "여행 응급 의료, 여행 취소/중단, 렌터카 충돌, 구매 보호 포함.", "zh": "包含旅行紧急医疗、行程取消/中断、租车碰撞和购物保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'PERK', '{"en": "First Year Fee Waived", "es": "Primer año sin cuota", "fr": "1re année sans frais", "ja": "初年度年会費無料", "ko": "첫해 연회비 면제", "zh": "首年年费减免"}', '{"en": "The $99 annual fee is waived for the first year. Try the card risk-free and decide if the rewards justify the fee.", "es": "La cuota anual de $99 se exime el primer año. Prueba sin riesgo y decide si las recompensas justifican la cuota.", "fr": "Les frais annuels de 99 $ sont annulés la 1re année. Essayez sans risque et décidez si les récompenses justifient les frais.", "ja": "初年度は$99の年会費無料。リスクなしで試して、報酬が年会費に見合うか判断を。", "ko": "첫해 $99 연회비 면제. 리스크 없이 체험하고 리워드가 연회비 가치가 있는지 결정.", "zh": "$99年费首年减免。无风险试用，再决定返现是否值得年费。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'PERK', '{"en": "5% for First 3 Months", "es": "5% los primeros 3 meses", "fr": "5 % les 3 premiers mois", "ja": "最初の3ヶ月5%", "ko": "처음 3개월 5%", "zh": "前3个月5%返现"}', '{"en": "Earn up to 5% cash back in your first 3 months. Maximize by timing big grocery and gas purchases early.", "es": "Gana hasta 5% los primeros 3 meses. Maximiza programando compras grandes de supermercado y gasolina temprano.", "fr": "Gagnez jusqu''à 5 % les 3 premiers mois. Maximisez en planifiant vos gros achats épicerie et essence tôt.", "ja": "最初の3ヶ月は最大5%キャッシュバック。大きな食料品・ガソリン購入を早めに行い最大化。", "ko": "처음 3개월 최대 5% 캐시백. 큰 식료품과 주유 구매를 일찍 하여 극대화.", "zh": "前3个月可获最高5%返现。尽早进行大额超市和加油消费以最大化收益。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'PERK', '{"en": "Credit Union Benefits", "es": "Beneficios de cooperativa", "fr": "Avantages caisse populaire", "ja": "信用組合特典", "ko": "신용협동조합 혜택", "zh": "信用社会员权益"}', '{"en": "As a Meridian member, you''re a part-owner of the credit union. May receive annual profit-sharing dividends.", "es": "Como miembro de Meridian, eres copropietario. Puede recibir dividendos anuales de participación.", "fr": "En tant que membre Meridian, vous êtes copropriétaire. Peut recevoir des dividendes annuels.", "ja": "Meridian会員として信用組合の共同オーナー。年間利益配当を受け取る可能性あり。", "ko": "Meridian 회원으로서 신용협동조합의 공동 소유자. 연간 이익 배당금을 받을 수 있음.", "zh": "作为Meridian会员，你是信用社的部分所有者。可能获得年度利润分红。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Meridian' AND name = 'Visa Infinite Cash Back'), 'REDEMPTION', '{"en": "Redeem for Travel: Best Value", "es": "Canjear por viaje: mejor valor", "fr": "Échange voyage : meilleure valeur", "ja": "旅行交換が最高価値", "ko": "여행 교환이 최고 가치", "zh": "旅行兑换价值最高"}', '{"en": "Redeem via Meridian travel portal at 100 points = $1 (1 cent per point). Also available: statement credit, gift cards, merchandise.", "es": "Canjea vía portal de viajes Meridian a 100 puntos = $1. También: crédito, tarjetas regalo, mercancía.", "fr": "Échangez via le portail voyage Meridian à 100 points = 1 $. Aussi : crédit, cartes-cadeaux, marchandise.", "ja": "Meridian旅行ポータルで100ポイント=$1で交換。明細クレジット、ギフトカード、商品も可能。", "ko": "Meridian 여행 포털에서 100포인트 = $1로 교환. 명세서 크레딧, 기프트 카드, 상품도 가능.", "zh": "通过Meridian旅行门户兑换，100积分=$1（每积分1分）。也可兑换账单抵扣、礼品卡、商品。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'AVOID', '{"en": "$2,500 Monthly Threshold", "es": "Umbral mensual $2,500", "fr": "Seuil mensuel 2 500 $", "ja": "月間$2,500閾値", "ko": "월간 $2,500 임계값", "zh": "$2,500月度门槛"}', '{"en": "Important: 5x rate on grocery/dining applies only until $2,500 TOTAL monthly spending (all categories). After that, drops to 2x.", "es": "Importante: La tasa 5x en supermercado/restaurante aplica solo hasta $2,500 de gasto TOTAL mensual. Después, baja a 2x.", "fr": "Important : Le taux 5x épicerie/resto s''applique jusqu''à 2 500 $ de dépenses TOTALES mensuelles. Après, 2x.", "ja": "重要：食料品/レストランの5倍は月間総支出（全カテゴリ）$2,500まで。その後2倍に低下。", "ko": "중요: 식료품/식당 5배는 월간 총 지출(모든 카테고리) $2,500까지만 적용. 이후 2배로 하락.", "zh": "重要：超市/餐厅5倍仅在月度总消费（所有类别）$2,500前有效。超过后降至2倍。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'AVOID', '{"en": "$150 Annual Fee", "es": "Cuota anual $150", "fr": "Frais annuels 150 $", "ja": "年会費$150", "ko": "연회비 $150", "zh": "$150年费"}', '{"en": "Higher annual fee, but $250 travel credit and strong rewards offset it. Net cost is effectively negative if you use the travel credit.", "es": "Cuota más alta, pero $250 de crédito de viaje y buenas recompensas lo compensan. Costo neto negativo si usas el crédito.", "fr": "Frais plus élevés, mais crédit voyage de 250 $ et récompenses les compensent. Coût net négatif si vous utilisez le crédit.", "ja": "年会費は高いが$250旅行クレジットと充実した報酬で相殺。旅行クレジットを使えば実質マイナス。", "ko": "연회비가 높지만 $250 여행 크레딧과 풍부한 리워드로 상쇄. 여행 크레딧 사용 시 순비용 마이너스.", "zh": "年费较高，但$250旅行额度和丰厚奖励可抵消。如果使用旅行额度，净成本实际为负。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "5x Points on Groceries", "es": "5x puntos en supermercados", "fr": "5x points épicerie", "ja": "食料品5倍ポイント", "ko": "식료품 5배 포인트", "zh": "超市5倍积分"}', '{"en": "Earn 5 points per $1 at grocery stores until $2,500 monthly gross spending (then 2x). Includes meal kits and food delivery.", "es": "Gana 5 puntos por $1 en supermercados hasta $2,500 de gasto mensual (luego 2x). Incluye kits de comida y delivery.", "fr": "Gagnez 5 points par dollar à l''épicerie jusqu''à 2 500 $ de dépenses mensuelles (puis 2x). Inclut kits repas et livraison.", "ja": "食料品店で$1あたり5ポイント、月間総支出$2,500まで（その後2倍）。ミールキットとデリバリー含む。", "ko": "식료품점에서 $1당 5포인트, 월간 총 지출 $2,500까지 (이후 2배). 밀키트와 배달 포함.", "zh": "超市消费每$1获5积分，月度总消费$2,500前有效（之后2倍）。包括预制餐和外卖。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "5x Points on Dining", "es": "5x puntos en restaurantes", "fr": "5x points restaurants", "ja": "レストラン5倍ポイント", "ko": "레스토랑 5배 포인트", "zh": "餐厅5倍积分"}', '{"en": "Earn 5 points per $1 at restaurants until $2,500 monthly gross spending (then 2x). Includes fast food, bars, and cafes.", "es": "Gana 5 puntos por $1 en restaurantes hasta $2,500 mensual (luego 2x). Incluye comida rápida, bares y cafés.", "fr": "Gagnez 5 points par dollar aux restaurants jusqu''à 2 500 $ mensuels (puis 2x). Inclut fast-food, bars et cafés.", "ja": "レストランで$1あたり5ポイント、月間総支出$2,500まで（その後2倍）。ファストフード、バー、カフェ含む。", "ko": "레스토랑에서 $1당 5포인트, 월간 총 지출 $2,500까지 (이후 2배). 패스트푸드, 바, 카페 포함.", "zh": "餐厅消费每$1获5积分，月度总消费$2,500前有效（之后2倍）。包括快餐、酒吧和咖啡店。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "2x on Gas & Travel", "es": "2x en gasolina y viajes", "fr": "2x essence et voyages", "ja": "ガス・旅行2倍", "ko": "주유 및 여행 2배", "zh": "加油旅行2倍积分"}', '{"en": "Earn 2 points per $1 on gas, EV charging, and travel booked through À la carte Travel. No monthly cap on these categories.", "es": "Gana 2 puntos por $1 en gasolina, carga EV y viajes vía À la carte Travel. Sin límite mensual.", "fr": "Gagnez 2 points par dollar sur essence, recharge VÉ et voyages via À la carte Travel. Aucun plafond mensuel.", "ja": "ガス、EV充電、À la carte Travel経由の旅行で$1あたり2ポイント。これらのカテゴリは月間上限なし。", "ko": "주유, EV 충전, À la carte Travel 통해 예약한 여행에서 $1당 2포인트. 월간 한도 없음.", "zh": "加油、电动车充电和通过À la carte Travel预订的旅行每$1获2积分。这些类别无月度上限。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'INSURANCE', '{"en": "Premium Travel Insurance", "es": "Seguro de viaje premium", "fr": "Assurance voyage premium", "ja": "プレミアム旅行保険", "ko": "프리미엄 여행 보험", "zh": "高端旅行保险"}', '{"en": "Includes comprehensive travel emergency medical, trip cancellation/interruption, car rental collision, and extended warranty.", "es": "Incluye seguro médico de viaje completo, cancelación/interrupción, colisión de alquiler de auto y garantía extendida.", "fr": "Inclut assurance médicale voyage complète, annulation/interruption, collision location auto et garantie prolongée.", "ja": "包括的な旅行緊急医療、旅行キャンセル/中断、レンタカー衝突、延長保証付き。", "ko": "종합 여행 응급 의료, 여행 취소/중단, 렌터카 충돌, 연장 보증 포함.", "zh": "包含全面旅行紧急医疗、行程取消/中断、租车碰撞和延长保修。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "$250 Annual Travel Credit", "es": "$250/año crédito de viaje", "fr": "250 $/an crédit voyage", "ja": "年間$250旅行クレジット", "ko": "연간 $250 여행 크레딧", "zh": "每年$250旅行额度"}', '{"en": "Get up to $250 in travel perks each year. This alone offsets most of the $150 annual fee.", "es": "Obtén hasta $250 en beneficios de viaje cada año. Esto solo compensa la mayor parte de la cuota de $150.", "fr": "Obtenez jusqu''à 250 $ en avantages voyage chaque année. Cela compense la majeure partie des frais de 150 $.", "ja": "毎年最大$250の旅行特典獲得。これだけで$150の年会費の大部分を相殺。", "ko": "매년 최대 $250 여행 혜택 획득. 이것만으로 $150 연회비 대부분 상쇄.", "zh": "每年可获最高$250旅行福利。仅此一项就能抵消大部分$150年费。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "30,000 Points Welcome Bonus", "es": "Bono de 30,000 puntos", "fr": "Prime de 30 000 points", "ja": "30,000ポイントウェルカムボーナス", "ko": "30,000 포인트 웰컴 보너스", "zh": "30,000积分开卡奖励"}', '{"en": "Earn 30,000 points ($300 value) after spending $1,500 in the first 90 days. One of the best welcome bonuses in Canada.", "es": "Gana 30,000 puntos (valor $300) tras gastar $1,500 en 90 días. Uno de los mejores bonos de bienvenida en Canadá.", "fr": "Gagnez 30 000 points (valeur 300 $) après 1 500 $ en 90 jours. L''une des meilleures primes au Canada.", "ja": "90日以内に$1,500消費で30,000ポイント（$300相当）獲得。カナダ最高のウェルカムボーナスの一つ。", "ko": "처음 90일 내 $1,500 지출 후 30,000 포인트 ($300 가치) 획득. 캐나다 최고의 웰컴 보너스 중 하나.", "zh": "前90天消费$1,500后获30,000积分（价值$300）。加拿大最佳开卡奖励之一。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "Best Mastercard in Canada", "es": "Mejor Mastercard en Canadá", "fr": "Meilleure Mastercard au Canada", "ja": "カナダ最高のMastercard", "ko": "캐나다 최고의 Mastercard", "zh": "加拿大最佳Mastercard"}', '{"en": "Named Best Mastercard and Best Travel Credit Card by Milesopedia in 2024 and 2025. A top-tier rewards card.", "es": "Nombrada Mejor Mastercard y Mejor Tarjeta de Viaje por Milesopedia en 2024 y 2025. Tarjeta de recompensas premium.", "fr": "Nommée meilleure Mastercard et carte voyage par Milesopedia en 2024 et 2025. Carte de récompenses haut de gamme.", "ja": "Milesopediaで2024年と2025年の最優秀Mastercardと最優秀旅行カードに選出。トップクラスの報酬カード。", "ko": "Milesopedia에서 2024년과 2025년 최고의 Mastercard 및 최고의 여행 카드로 선정. 최고급 리워드 카드.", "zh": "被Milesopedia评为2024和2025年最佳Mastercard和最佳旅行信用卡。顶级奖励卡。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'National Bank' AND name = 'World Elite Mastercard'), 'REDEMPTION', '{"en": "Book via À la carte Travel", "es": "Reserva vía À la carte Travel", "fr": "Réservez via À la carte Travel", "ja": "À la carte Travel経由で予約", "ko": "À la carte Travel 통해 예약", "zh": "通过À la carte Travel预订"}', '{"en": "Redeem points at 1 cent each (10,000 pts = $100) through À la carte Travel. Can also book through any travel agency.", "es": "Canjea puntos a 1 centavo cada uno (10,000 pts = $100) vía À la carte Travel. También puedes reservar por cualquier agencia.", "fr": "Échangez les points à 1 ¢ chacun (10 000 pts = 100 $) via À la carte Travel. Réservation possible via toute agence.", "ja": "À la carte Travel経由で1ポイント1セントで交換（10,000ポイント=$100）。任意の旅行代理店でも予約可能。", "ko": "À la carte Travel 통해 포인트당 1센트로 교환 (10,000포인트 = $100). 어느 여행사에서든 예약 가능.", "zh": "通过À la carte Travel兑换积分，每积分1分（10,000积分=$100）。也可通过任何旅行社预订。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'AVOID', '{"en": "Monthly Spending Caps", "es": "Límites mensuales", "fr": "Plafonds mensuels", "ja": "月間消費上限", "ko": "월간 지출 한도", "zh": "月度消费上限"}', '{"en": "Caps: $1,000 grocery, $500 recurring, $1,000 gas. After caps, drops to 1%. Track spending to maximize high rates.", "es": "Límites: $1,000 supermercado, $500 recurrente, $1,000 gasolina. Después, 1%. Rastrea gastos.", "fr": "Plafonds : 1 000 $ épicerie, 500 $ récurrent, 1 000 $ essence. Après, 1 %. Suivez vos dépenses.", "ja": "上限：食料品$1,000、定期$500、ガス$1,000。上限後は1%に。消費を追跡して高レートを最大化。", "ko": "한도: 식료품 $1,000, 정기 $500, 주유 $1,000. 한도 후 1%. 지출 추적으로 높은 요율 극대화.", "zh": "上限：超市$1,000、定期$500、加油$1,000。超过后降至1%。追踪消费以最大化高返现率。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'AVOID', '{"en": "$125 Annual Fee", "es": "Cuota anual $125", "fr": "Frais annuels 125 $", "ja": "年会費$125", "ko": "연회비 $125", "zh": "$125年费"}', '{"en": "High annual fee. Need ~$3,100/year in 5% categories to break even vs a 1% no-fee card. Worth it if you max the caps.", "es": "Cuota alta. Necesitas ~$3,100/año en categorías 5% para igualar tarjeta 1% sin cuota.", "fr": "Frais élevés. Il faut ~3 100 $/an en catégories 5 % pour rentabiliser vs carte 1 % sans frais.", "ja": "年会費が高い。1%年会費無料カードと同等にするには5%カテゴリで約$3,100/年必要。", "ko": "연회비가 높음. 1% 연회비 무료 카드와 동등하려면 5% 카테고리에서 연간 약 $3,100 필요.", "zh": "年费较高。需在5%类别年消费约$3,100才能与1%免年费卡持平。如果能用满上限则值得。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "5% on Groceries", "es": "5% en supermercados", "fr": "5 % sur épicerie", "ja": "食料品5%", "ko": "식료품 5%", "zh": "超市5%返现"}', '{"en": "Earn 5% cash back on grocery purchases up to $1,000/month. After cap, drops to 1%. One of the best grocery rates in Canada.", "es": "Gana 5% en supermercado hasta $1,000/mes. Después del límite, baja a 1%. Una de las mejores tasas de supermercado.", "fr": "Gagnez 5 % sur l''épicerie jusqu''à 1 000 $/mois. Après le plafond, passe à 1 %. L''un des meilleurs taux épicerie.", "ja": "食料品で5%キャッシュバック、月$1,000まで。上限後は1%に。カナダ最高の食料品レートの一つ。", "ko": "식료품에서 5% 캐시백, 월 $1,000까지. 한도 후 1%로 하락. 캐나다 최고의 식료품 요율 중 하나.", "zh": "超市消费获得5%返现，月度上限$1,000。超过后降至1%。加拿大最高的超市返现率之一。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "4% on Recurring Bills", "es": "4% en facturas recurrentes", "fr": "4 % factures récurrentes", "ja": "定期支払い4%", "ko": "정기 청구서 4%", "zh": "定期账单4%返现"}', '{"en": "Earn 4% on recurring payments including utilities, telecom, insurance, and streaming. Up to $500/month cap.", "es": "Gana 4% en pagos recurrentes incluyendo servicios, telecom, seguro y streaming. Límite $500/mes.", "fr": "Gagnez 4 % sur les paiements récurrents incluant services publics, télécom, assurance et streaming. Plafond 500 $/mois.", "ja": "公共料金、通信、保険、ストリーミングなど定期支払いで4%。月$500上限。", "ko": "공과금, 통신, 보험, 스트리밍 등 정기 결제에서 4%. 월 $500 한도.", "zh": "定期付款（水电、电信、保险、流媒体）获得4%返现。月度上限$500。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "3% on Gas & EV Charging", "es": "3% en gasolina y carga EV", "fr": "3 % essence et recharge VÉ", "ja": "ガス・EV充電3%", "ko": "주유 및 EV 충전 3%", "zh": "加油/电动车充电3%"}', '{"en": "Earn 3% cash back on gas and EV charging up to $1,000/month. Great for commuters.", "es": "Gana 3% en gasolina y carga EV hasta $1,000/mes. Ideal para commuters.", "fr": "Gagnez 3 % sur essence et recharge VÉ jusqu''à 1 000 $/mois. Idéal pour les navetteurs.", "ja": "ガスとEV充電で3%キャッシュバック、月$1,000まで。通勤者に最適。", "ko": "주유와 EV 충전에서 3% 캐시백, 월 $1,000까지. 통근자에게 적합.", "zh": "加油和电动车充电获得3%返现，月度上限$1,000。适合通勤者。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "5%+ at Neo Partners", "es": "5%+ en socios Neo", "fr": "5 %+ chez partenaires Neo", "ja": "Neoパートナーで5%+", "ko": "Neo 파트너에서 5%+", "zh": "Neo合作商户5%+"}', '{"en": "Earn 5% or more at thousands of Neo partner stores. Average rate across partners is 5%. Check the Neo app for nearby partners.", "es": "Gana 5% o más en miles de tiendas socias Neo. Tasa promedio de 5%. Consulta la app Neo para socios cercanos.", "fr": "Gagnez 5 % ou plus chez des milliers de partenaires Neo. Taux moyen de 5 %. Consultez l''appli Neo pour les partenaires.", "ja": "数千のNeoパートナー店舗で5%以上獲得。パートナー平均5%。Neoアプリで近くのパートナーを確認。", "ko": "수천 개의 Neo 파트너 매장에서 5% 이상 적립. 파트너 평균 5%. Neo 앱에서 근처 파트너 확인.", "zh": "在数千家Neo合作商户可获5%或更高返现。合作商户平均返现率5%。可在Neo App查看附近商户。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'INSURANCE', '{"en": "World Elite Insurance", "es": "Seguro World Elite", "fr": "Assurance World Elite", "ja": "World Elite保険", "ko": "World Elite 보험", "zh": "World Elite保险"}', '{"en": "Includes travel emergency medical, trip cancellation, car rental collision, mobile device insurance, and purchase protection.", "es": "Incluye seguro médico de viaje, cancelación, colisión de alquiler de auto, dispositivo móvil y protección de compras.", "fr": "Inclut assurance médicale voyage, annulation, collision location auto, appareil mobile et protection des achats.", "ja": "旅行緊急医療、旅行キャンセル、レンタカー衝突、モバイル機器保険、購入保護付き。", "ko": "여행 응급 의료, 여행 취소, 렌터카 충돌, 모바일 기기 보험, 구매 보호 포함.", "zh": "包含旅行紧急医疗、行程取消、租车碰撞、手机保险和购物保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "Boost with $10K Balance", "es": "Aumenta con saldo $10K", "fr": "Boostez avec solde 10 000 $", "ja": "$10K残高でブースト", "ko": "$10K 잔액으로 부스트", "zh": "$10K余额提升返现"}', '{"en": "Keep $10,000+ in Neo Everyday Account to boost rates: 7% groceries, 5% recurring, 4% gas. Maximize your rewards!", "es": "Mantén $10,000+ en cuenta Neo Everyday para aumentar: 7% supermercado, 5% recurrente, 4% gasolina.", "fr": "Gardez 10 000 $+ dans le compte Neo Everyday pour booster : 7 % épicerie, 5 % récurrent, 4 % essence.", "ja": "Neo Everyday口座に$10,000+でレート向上：食料品7%、定期5%、ガス4%。報酬を最大化！", "ko": "Neo Everyday 계좌에 $10,000+ 유지로 요율 상승: 식료품 7%, 정기 5%, 주유 4%. 리워드 극대화!", "zh": "Neo Everyday账户保持$10,000+可提升返现率：超市7%、定期5%、加油4%。最大化您的奖励！"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "Instant Cashback", "es": "Cashback instantáneo", "fr": "Remise instantanée", "ja": "即時キャッシュバック", "ko": "즉시 캐시백", "zh": "即时返现"}', '{"en": "Cash back is applied instantly as a statement credit after each purchase. No waiting, no minimum redemption.", "es": "El cashback se aplica instantáneamente después de cada compra. Sin espera, sin mínimo.", "fr": "La remise est appliquée instantanément après chaque achat. Pas d''attente, pas de minimum.", "ja": "購入ごとにキャッシュバックが即時適用。待ち時間なし、最低交換額なし。", "ko": "각 구매 후 캐시백이 즉시 적용. 대기 없음, 최소 교환 없음.", "zh": "每次消费后返现即时作为账单抵扣。无需等待，无最低兑换门槛。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Elite Mastercard'), 'STACKING', '{"en": "Start with Neo Secured", "es": "Empieza con Neo Secured", "fr": "Commencer avec Neo Secured", "ja": "Neo Securedから始める", "ko": "Neo Secured로 시작", "zh": "可先用Neo Secured"}', '{"en": "Neo offers a free Secured card with similar partner benefits. Try it first to test the Neo ecosystem before committing to the $125 fee.", "es": "Neo ofrece una tarjeta Secured gratis con beneficios de socios similares. Pruébala antes de pagar los $125.", "fr": "Neo offre une carte Secured gratuite avec avantages partenaires similaires. Essayez-la avant de payer les 125 $.", "ja": "Neoは類似のパートナー特典付き無料Securedカードを提供。$125を支払う前にNeoエコシステムを試す。", "ko": "Neo는 유사한 파트너 혜택이 있는 무료 Secured 카드 제공. $125 지불 전에 Neo 생태계를 먼저 시험.", "zh": "Neo提供免费的Secured卡，有类似的合作商户权益。可先试用Neo生态系统，再决定是否支付$125年费。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'AVOID', '{"en": "Only 0.5% on Other Purchases", "es": "Solo 0.5% en otras compras", "fr": "Seulement 0,5 % sur autres achats", "ja": "他の購入は0.5%のみ", "ko": "기타 구매는 0.5%만", "zh": "其他消费仅0.5%"}', '{"en": "Non-bonus categories earn only 0.5%. Use a different card for dining, travel, and non-partner retail.", "es": "Las categorías sin bonificación solo ganan 0.5%. Usa otra tarjeta para comida, viajes y retail no asociado.", "fr": "Les catégories non bonifiées ne rapportent que 0,5 %. Utilisez une autre carte pour restaurants et voyages.", "ja": "ボーナスカテゴリ外は0.5%のみ。外食、旅行、非パートナー店舗には別のカードを。", "ko": "비보너스 카테고리는 0.5%만 적립. 식사, 여행, 비파트너 소매에는 다른 카드 사용.", "zh": "非奖励类别仅获0.5%。餐饮、旅行和非合作商户消费请使用其他卡。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "2% on Groceries", "es": "2% en supermercados", "fr": "2 % sur épicerie", "ja": "食料品2%", "ko": "식료품 2%", "zh": "超市2%返现"}', '{"en": "Earn 2% cash back on grocery purchases up to $12,000/year. Great rate for a no-fee card.", "es": "Gana 2% en supermercado hasta $12,000/año. Gran tasa para una tarjeta sin cuota.", "fr": "Gagnez 2 % sur l''épicerie jusqu''à 12 000 $/an. Excellent taux pour une carte sans frais.", "ja": "食料品で2%キャッシュバック、年間$12,000まで。年会費無料カードで優秀なレート。", "ko": "식료품에서 2% 캐시백, 연간 $12,000까지. 연회비 무료 카드 중 우수한 요율.", "zh": "超市消费获得2%返现，年度上限$12,000。免年费卡中的优秀返现率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "2% on Gas & EV Charging", "es": "2% en gasolina y carga EV", "fr": "2 % essence et recharge VÉ", "ja": "ガス・EV充電2%", "ko": "주유 및 EV 충전 2%", "zh": "加油/电动车充电2%"}', '{"en": "Earn 2% cash back on gas and EV charging. Solid rate for commuters with no annual fee.", "es": "Gana 2% en gasolina y carga EV. Buena tasa para commuters sin cuota anual.", "fr": "Gagnez 2 % sur essence et recharge VÉ. Bon taux pour navetteurs sans frais annuels.", "ja": "ガスとEV充電で2%キャッシュバック。年会費無料で通勤者に堅実なレート。", "ko": "주유와 EV 충전에서 2% 캐시백. 연회비 없이 통근자에게 좋은 요율.", "zh": "加油和电动车充电获得2%返现。免年费通勤者的好选择。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "2% on Recurring Bills", "es": "2% en facturas recurrentes", "fr": "2 % factures récurrentes", "ja": "定期支払い2%", "ko": "정기 청구서 2%", "zh": "定期账单2%返现"}', '{"en": "Earn 2% on recurring payments including utilities and telecom up to $6,000/year. Set and forget.", "es": "Gana 2% en pagos recurrentes hasta $6,000/año. Configura y olvida.", "fr": "Gagnez 2 % sur les paiements récurrents jusqu''à 6 000 $/an. Configurez et oubliez.", "ja": "公共料金や通信など定期支払いで2%、年間$6,000まで。設定したら放置でOK。", "ko": "정기 결제에서 2%, 연간 $6,000까지. 설정하고 잊어버려도 OK.", "zh": "定期付款（水电、电信）获得2%返现，年度上限$6,000。设置后无需管理。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "5%+ at Neo Partners", "es": "5%+ en socios Neo", "fr": "5 %+ chez partenaires Neo", "ja": "Neoパートナーで5%+", "ko": "Neo 파트너에서 5%+", "zh": "Neo合作商户5%+"}', '{"en": "Earn 5% or more at 10,000+ Neo partner stores. Check the Neo app for nearby partners and exclusive offers.", "es": "Gana 5% o más en 10,000+ tiendas socias Neo. Consulta la app Neo para socios y ofertas exclusivas.", "fr": "Gagnez 5 % ou plus chez 10 000+ partenaires Neo. Consultez l''appli Neo pour partenaires et offres exclusives.", "ja": "10,000+のNeoパートナー店舗で5%以上獲得。Neoアプリで近くのパートナーと限定オファーを確認。", "ko": "10,000+ Neo 파트너 매장에서 5% 이상 적립. Neo 앱에서 근처 파트너와 독점 오퍼 확인.", "zh": "在10,000+家Neo合作商户可获5%或更高返现。可在Neo App查看附近商户和专属优惠。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'INSURANCE', '{"en": "World Mastercard Perks", "es": "Beneficios World Mastercard", "fr": "Avantages World Mastercard", "ja": "World Mastercard特典", "ko": "World Mastercard 혜택", "zh": "World Mastercard权益"}', '{"en": "Includes purchase protection, extended warranty, and Mastercard World benefits. Good coverage for a no-fee card.", "es": "Incluye protección de compras, garantía extendida y beneficios Mastercard World. Buena cobertura para tarjeta sin cuota.", "fr": "Inclut protection des achats, garantie prolongée et avantages Mastercard World. Bonne couverture pour carte sans frais.", "ja": "購入保護、延長保証、Mastercard World特典付き。年会費無料カードで良いカバレッジ。", "ko": "구매 보호, 연장 보증, Mastercard World 혜택 포함. 연회비 무료 카드 중 좋은 보장.", "zh": "包含购物保障、延长保修和Mastercard World权益。免年费卡中保障较好。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee means all rewards are pure profit. Best no-fee card for Neo partner shoppers.", "es": "Sin cuota anual significa ganancia pura. Mejor tarjeta sin cuota para compradores de socios Neo.", "fr": "Sans frais annuels signifie profit pur. Meilleure carte sans frais pour les acheteurs partenaires Neo.", "ja": "年会費無料で全ての報酬は純利益。Neoパートナーで買い物する人に最適な無料カード。", "ko": "연회비 무료로 모든 리워드가 순이익. Neo 파트너 쇼핑객을 위한 최고의 무료 카드.", "zh": "免年费意味着所有返现都是纯利润。Neo合作商户购物者的最佳免年费卡。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'PERK', '{"en": "Boost with Account Balance", "es": "Aumenta con saldo", "fr": "Boostez avec le solde", "ja": "残高でブースト", "ko": "잔액으로 부스트", "zh": "账户余额提升返现"}', '{"en": "Keep $5K+ in Neo Everyday for 3% on all categories, or $10K+ for 4% on groceries/gas/recurring and 1% everywhere else.", "es": "Mantén $5K+ en Neo Everyday para 3% en todo, o $10K+ para 4% supermercado/gasolina/recurrente.", "fr": "Gardez 5 000 $+ dans Neo Everyday pour 3 % partout, ou 10 000 $+ pour 4 % épicerie/essence/récurrent.", "ja": "Neo Everydayに$5K+で全カテゴリ3%、$10K+で食料品/ガス/定期4%、他1%。", "ko": "Neo Everyday에 $5K+로 전체 3%, $10K+로 식료품/주유/정기 4%, 기타 1%.", "zh": "Neo Everyday保持$5K+可获所有类别3%，$10K+超市/加油/定期4%，其他1%。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'PERK', '{"en": "Instant Cashback", "es": "Cashback instantáneo", "fr": "Remise instantanée", "ja": "即時キャッシュバック", "ko": "즉시 캐시백", "zh": "即时返现"}', '{"en": "Cash back is applied instantly as a statement credit after each purchase. No waiting, no minimum redemption.", "es": "El cashback se aplica instantáneamente después de cada compra. Sin espera, sin mínimo.", "fr": "La remise est appliquée instantanément après chaque achat. Pas d''attente, pas de minimum.", "ja": "購入ごとにキャッシュバックが即時適用。待ち時間なし、最低交換額なし。", "ko": "각 구매 후 캐시백이 즉시 적용. 대기 없음, 최소 교환 없음.", "zh": "每次消费后返现即时作为账单抵扣。无需等待，无最低兑换门槛。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Neo' AND name = 'World Mastercard'), 'STACKING', '{"en": "Consider World Elite Upgrade", "es": "Considera World Elite", "fr": "Considérez World Elite", "ja": "World Eliteへの昇格検討", "ko": "World Elite 업그레이드 고려", "zh": "考虑升级World Elite"}', '{"en": "Neo World Elite ($125/year) offers 5% grocery, 4% recurring, 3% gas. Worth it if you spend $3,100+/year in bonus categories.", "es": "Neo World Elite ($125/año) ofrece 5% supermercado, 4% recurrente, 3% gasolina. Vale si gastas $3,100+/año en categorías bonus.", "fr": "Neo World Elite (125 $/an) offre 5 % épicerie, 4 % récurrent, 3 % essence. Vaut le coup si 3 100 $+/an en catégories bonus.", "ja": "Neo World Elite ($125/年) は食料品5%、定期4%、ガス3%。ボーナスカテゴリで年間$3,100+消費なら価値あり。", "ko": "Neo World Elite ($125/년)는 식료품 5%, 정기 4%, 주유 3%. 보너스 카테고리에서 연간 $3,100+ 지출 시 가치 있음.", "zh": "Neo World Elite ($125/年) 提供超市5%、定期4%、加油3%。如果奖励类别年消费$3,100+则值得。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'AVOID', '{"en": "Only 1% Outside Ecosystem", "es": "Solo 1% fuera del ecosistema", "fr": "Seulement 1 % hors écosystème", "ja": "エコシステム外は1%のみ", "ko": "생태계 외 1%만", "zh": "生态外仅1%"}', '{"en": "Only earns 1% (10 points per $1) outside Loblaw/Shoppers/Esso. Use a different card for dining, travel, and other spending.", "es": "Solo gana 1% (10 puntos por $1) fuera de Loblaw/Shoppers/Esso. Usa otra tarjeta para comida y viajes.", "fr": "Gagne seulement 1 % (10 points par dollar) hors Loblaw/Shoppers/Esso. Utilisez une autre carte pour restos et voyages.", "ja": "Loblaw/Shoppers/Esso以外は1%（$1あたり10ポイント）のみ。外食や旅行には別のカードを。", "ko": "Loblaw/Shoppers/Esso 외에서는 1% ($1당 10포인트)만 적립. 식사, 여행에는 다른 카드 사용.", "zh": "Loblaw/Shoppers/Esso以外仅获1%（每$1获10积分）。餐饮、旅行等请使用其他卡。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'AVOID', '{"en": "Points Only for Loblaw/Shoppers", "es": "Puntos solo para Loblaw/Shoppers", "fr": "Points uniquement chez Loblaw/Shoppers", "ja": "ポイントはLoblaw/Shoppersのみ", "ko": "포인트는 Loblaw/Shoppers에서만", "zh": "积分只能在Loblaw/Shoppers用"}', '{"en": "PC Optimum points can only be redeemed at Loblaw stores and Shoppers. No travel, gift cards, or cash redemption options.", "es": "Los puntos PC Optimum solo se canjean en Loblaw y Shoppers. Sin opciones de viaje, tarjetas regalo o efectivo.", "fr": "Les points PC Optimum ne peuvent être échangés que chez Loblaw et Shoppers. Pas de voyage, cartes-cadeaux ou argent.", "ja": "PC OptimumポイントはLoblawとShoppersでのみ交換可能。旅行、ギフトカード、現金オプションなし。", "ko": "PC Optimum 포인트는 Loblaw와 Shoppers에서만 교환 가능. 여행, 기프트 카드, 현금 옵션 없음.", "zh": "PC Optimum积分只能在Loblaw超市和Shoppers兑换。没有旅行、礼品卡或现金选项。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "4.5% at Shoppers Drug Mart", "es": "4.5% en Shoppers Drug Mart", "fr": "4,5 % chez Shoppers Drug Mart", "ja": "Shoppers Drug Mart 4.5%", "ko": "Shoppers Drug Mart 4.5%", "zh": "Shoppers Drug Mart 4.5%"}', '{"en": "Earn 45 PC Optimum points per $1 (~4.5%) at Shoppers Drug Mart. Stack with 20x points events for massive earnings.", "es": "Gana 45 puntos PC Optimum por $1 (~4.5%) en Shoppers Drug Mart. Combina con eventos 20x para ganancias masivas.", "fr": "Gagnez 45 points PC Optimum par dollar (~4,5 %) chez Shoppers. Combinez avec les événements 20x points.", "ja": "Shoppers Drug Martで$1あたり45 PC Optimumポイント（約4.5%）。20倍ポイントイベントと併用で大量獲得。", "ko": "Shoppers Drug Mart에서 $1당 45 PC Optimum 포인트 (약 4.5%). 20배 포인트 이벤트와 결합하여 대량 적립.", "zh": "在Shoppers Drug Mart每$1获45 PC Optimum积分（约4.5%）。与20倍积分活动叠加可获更多奖励。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "3% at Loblaw Grocery Stores", "es": "3% en tiendas Loblaw", "fr": "3 % chez Loblaw", "ja": "Loblawスーパー3%", "ko": "Loblaw 식료품점 3%", "zh": "Loblaw超市3%"}', '{"en": "Earn 30 points per $1 (~3%) at Loblaw, No Frills, Real Canadian Superstore, Zehrs, Fortinos, and other Loblaw banners.", "es": "Gana 30 puntos por $1 (~3%) en Loblaw, No Frills, Real Canadian Superstore y otras tiendas Loblaw.", "fr": "Gagnez 30 points par dollar (~3 %) chez Loblaw, No Frills, Real Canadian Superstore, Zehrs et autres bannières.", "ja": "Loblaw、No Frills、Real Canadian Superstoreなどで$1あたり30ポイント（約3%）。", "ko": "Loblaw, No Frills, Real Canadian Superstore 등에서 $1당 30포인트 (약 3%).", "zh": "在Loblaw、No Frills、Real Canadian Superstore等Loblaw旗下超市每$1获30积分（约3%）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'BEST_USE', '{"en": "3% at Esso & Mobil", "es": "3% en Esso y Mobil", "fr": "3 % chez Esso et Mobil", "ja": "Esso/Mobil 3%", "ko": "Esso & Mobil 3%", "zh": "Esso/Mobil加油站3%"}', '{"en": "Earn 30 points per $1 (~3%) at Esso and Mobil gas stations. Link your PC Optimum card at the pump for extra points.", "es": "Gana 30 puntos por $1 (~3%) en gasolineras Esso y Mobil. Vincula tu tarjeta PC Optimum para puntos extra.", "fr": "Gagnez 30 points par dollar (~3 %) chez Esso et Mobil. Liez votre carte PC Optimum à la pompe pour plus de points.", "ja": "EssoとMobilで$1あたり30ポイント（約3%）。ポンプでPC Optimumカードをリンクして追加ポイント。", "ko": "Esso와 Mobil에서 $1당 30포인트 (약 3%). 주유기에서 PC Optimum 카드 연결 시 추가 포인트.", "zh": "在Esso和Mobil加油站每$1获30积分（约3%）。在油泵关联PC Optimum卡可获额外积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'INSURANCE', '{"en": "World Elite Insurance", "es": "Seguro World Elite", "fr": "Assurance World Elite", "ja": "World Elite保険", "ko": "World Elite 보험", "zh": "World Elite保险"}', '{"en": "Includes travel emergency medical, trip cancellation, car rental collision, mobile device insurance, and purchase protection.", "es": "Incluye seguro médico de viaje, cancelación, colisión de alquiler de auto, dispositivo móvil y protección de compras.", "fr": "Inclut assurance médicale voyage, annulation, collision location auto, appareil mobile et protection des achats.", "ja": "旅行緊急医療、旅行キャンセル、レンタカー衝突、モバイル機器保険、購入保護付き。", "ko": "여행 응급 의료, 여행 취소, 렌터카 충돌, 모바일 기기 보험, 구매 보호 포함.", "zh": "包含旅行紧急医疗、行程取消、租车碰撞、手机保险和购物保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee for a World Elite card. All points earned are pure savings. Best free card for Loblaw shoppers.", "es": "Sin cuota anual para una tarjeta World Elite. Mejor tarjeta gratis para compradores de Loblaw.", "fr": "Aucuns frais annuels pour une carte World Elite. Meilleure carte gratuite pour les acheteurs Loblaw.", "ja": "World Eliteカードで年会費無料。獲得ポイントは全て純粋な節約。Loblaw買い物客に最適な無料カード。", "ko": "World Elite 카드 연회비 무료. 모든 포인트가 순수 절약. Loblaw 쇼핑객을 위한 최고의 무료 카드.", "zh": "World Elite卡免年费。所有积分都是纯省钱。Loblaw购物者的最佳免费卡。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'PERK', '{"en": "Stack with PC Optimum App", "es": "Combina con PC Optimum", "fr": "Combiner avec PC Optimum", "ja": "PC Optimumアプリと併用", "ko": "PC Optimum 앱과 결합", "zh": "与PC Optimum App叠加"}', '{"en": "Load personalized offers in PC Optimum app before shopping. Stack with 20x points events for up to 25%+ effective rewards.", "es": "Carga ofertas personalizadas en la app PC Optimum. Combina con eventos 20x para 25%+ de recompensas efectivas.", "fr": "Chargez les offres personnalisées dans l''appli PC Optimum. Combinez avec les événements 20x pour 25 %+ de récompenses.", "ja": "買い物前にPC Optimumアプリでパーソナライズオファーをロード。20倍イベントと併用で25%+の実効報酬。", "ko": "쇼핑 전 PC Optimum 앱에서 개인화 오퍼 로드. 20배 이벤트와 결합하여 25%+ 유효 리워드.", "zh": "购物前在PC Optimum App加载个性化优惠。与20倍积分活动叠加可获25%+有效奖励。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'REDEMPTION', '{"en": "Redeem at Checkout", "es": "Canjear al pagar", "fr": "Échanger à la caisse", "ja": "レジで交換", "ko": "계산대에서 교환", "zh": "结账时兑换"}', '{"en": "Redeem 10,000 points for $10 off at any Loblaw store or Shoppers. Points never expire as long as you earn or redeem within 12 months.", "es": "Canjea 10,000 puntos por $10 en cualquier Loblaw o Shoppers. Los puntos no expiran mientras ganes/canjees en 12 meses.", "fr": "Échangez 10 000 points pour 10 $ chez Loblaw ou Shoppers. Les points n''expirent jamais si vous gagnez/échangez dans les 12 mois.", "ja": "Loblawまたは Shoppersで10,000ポイント=$10として交換。12ヶ月以内に獲得/交換があればポイント無期限。", "ko": "Loblaw 또는 Shoppers에서 10,000 포인트를 $10으로 교환. 12개월 내 적립/교환 시 포인트 만료 없음.", "zh": "在任何Loblaw超市或Shoppers用10,000积分抵扣$10。只要12个月内有积分变动，积分不过期。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Elite Mastercard'), 'STACKING', '{"en": "Use at Joe Fresh Too", "es": "Usa en Joe Fresh también", "fr": "Utilisez chez Joe Fresh aussi", "ja": "Joe Freshでも使用", "ko": "Joe Fresh에서도 사용", "zh": "Joe Fresh也可用"}', '{"en": "Earn bonus points at Joe Fresh stores (often inside Loblaw/Superstore). Points stack with in-store promotions.", "es": "Gana puntos bonus en Joe Fresh (a menudo dentro de Loblaw/Superstore). Puntos acumulables con promociones en tienda.", "fr": "Gagnez des points bonus chez Joe Fresh (souvent dans Loblaw/Superstore). Points cumulables avec les promotions en magasin.", "ja": "Joe Fresh店舗（Loblaw/Superstore内にあることが多い）でもボーナスポイント獲得。店舗プロモと併用可能。", "ko": "Joe Fresh 매장 (보통 Loblaw/Superstore 내)에서도 보너스 포인트 적립. 매장 프로모션과 결합 가능.", "zh": "在Joe Fresh门店（通常在Loblaw/Superstore内）也可获奖励积分。积分可与店内促销叠加。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'AVOID', '{"en": "Lower Rates Than World Elite", "es": "Tasas menores que World Elite", "fr": "Taux inférieurs au World Elite", "ja": "World Eliteより低レート", "ko": "World Elite보다 낮은 요율", "zh": "返现率低于World Elite"}', '{"en": "Earns 1% less than World Elite at Shoppers (3.5% vs 4.5%) and Loblaw/Esso (2.5% vs 3%). Upgrade if eligible.", "es": "Gana 1% menos que World Elite en Shoppers (3.5% vs 4.5%) y Loblaw/Esso (2.5% vs 3%).", "fr": "Gagne 1 % de moins que World Elite chez Shoppers (3,5 % vs 4,5 %) et Loblaw/Esso (2,5 % vs 3 %).", "ja": "World Eliteより1%低い：Shoppers 3.5%対4.5%、Loblaw/Esso 2.5%対3%。資格があれば昇格を。", "ko": "World Elite보다 1% 낮음: Shoppers 3.5% vs 4.5%, Loblaw/Esso 2.5% vs 3%. 자격이 되면 업그레이드.", "zh": "比World Elite少1%：Shoppers 3.5%对4.5%，Loblaw/Esso 2.5%对3%。符合条件可升级。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'AVOID', '{"en": "Only 1% Outside Ecosystem", "es": "Solo 1% fuera del ecosistema", "fr": "Seulement 1 % hors écosystème", "ja": "エコシステム外は1%のみ", "ko": "생태계 외 1%만", "zh": "生态外仅1%"}', '{"en": "Only earns 1% (10 points per $1) outside Loblaw/Shoppers/Esso. Use a different card for dining and travel.", "es": "Solo gana 1% (10 puntos por $1) fuera de Loblaw/Shoppers/Esso. Usa otra tarjeta para comida y viajes.", "fr": "Gagne seulement 1 % (10 points par dollar) hors Loblaw/Shoppers/Esso. Utilisez une autre carte ailleurs.", "ja": "Loblaw/Shoppers/Esso以外は1%（$1あたり10ポイント）のみ。外食や旅行には別のカードを。", "ko": "Loblaw/Shoppers/Esso 외에서는 1% ($1당 10포인트)만 적립. 식사, 여행에는 다른 카드 사용.", "zh": "Loblaw/Shoppers/Esso以外仅获1%（每$1获10积分）。餐饮、旅行请使用其他卡。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "3.5% at Shoppers Drug Mart", "es": "3.5% en Shoppers Drug Mart", "fr": "3,5 % chez Shoppers Drug Mart", "ja": "Shoppers Drug Mart 3.5%", "ko": "Shoppers Drug Mart 3.5%", "zh": "Shoppers Drug Mart 3.5%"}', '{"en": "Earn 35 PC Optimum points per $1 (~3.5%) at Shoppers Drug Mart. Stack with 20x points events for even more.", "es": "Gana 35 puntos PC Optimum por $1 (~3.5%) en Shoppers Drug Mart. Combina con eventos 20x.", "fr": "Gagnez 35 points PC Optimum par dollar (~3,5 %) chez Shoppers. Combinez avec les événements 20x.", "ja": "Shoppers Drug Martで$1あたり35 PC Optimumポイント（約3.5%）。20倍ポイントイベントと併用可。", "ko": "Shoppers Drug Mart에서 $1당 35 PC Optimum 포인트 (약 3.5%). 20배 포인트 이벤트와 결합 가능.", "zh": "在Shoppers Drug Mart每$1获35 PC Optimum积分（约3.5%）。与20倍积分活动叠加可获更多。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "2.5% at Loblaw Grocery Stores", "es": "2.5% en tiendas Loblaw", "fr": "2,5 % chez Loblaw", "ja": "Loblawスーパー2.5%", "ko": "Loblaw 식료품점 2.5%", "zh": "Loblaw超市2.5%"}', '{"en": "Earn 25 points per $1 (~2.5%) at Loblaw, No Frills, Real Canadian Superstore, Zehrs, and other Loblaw banners.", "es": "Gana 25 puntos por $1 (~2.5%) en Loblaw, No Frills, Real Canadian Superstore y otras tiendas Loblaw.", "fr": "Gagnez 25 points par dollar (~2,5 %) chez Loblaw, No Frills, Real Canadian Superstore et autres bannières.", "ja": "Loblaw、No Frills、Real Canadian Superstoreなどで$1あたり25ポイント（約2.5%）。", "ko": "Loblaw, No Frills, Real Canadian Superstore 등에서 $1당 25포인트 (약 2.5%).", "zh": "在Loblaw、No Frills、Real Canadian Superstore等Loblaw旗下超市每$1获25积分（约2.5%）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "2.5% at Esso & Mobil", "es": "2.5% en Esso y Mobil", "fr": "2,5 % chez Esso et Mobil", "ja": "Esso/Mobil 2.5%", "ko": "Esso & Mobil 2.5%", "zh": "Esso/Mobil加油站2.5%"}', '{"en": "Earn 25 points per $1 (~2.5%) at Esso and Mobil gas stations. Link PC Optimum card at the pump for extra points.", "es": "Gana 25 puntos por $1 (~2.5%) en gasolineras Esso y Mobil. Vincula tu tarjeta PC Optimum.", "fr": "Gagnez 25 points par dollar (~2,5 %) chez Esso et Mobil. Liez votre carte PC Optimum à la pompe.", "ja": "EssoとMobilで$1あたり25ポイント（約2.5%）。ポンプでPC Optimumカードをリンク。", "ko": "Esso와 Mobil에서 $1당 25포인트 (약 2.5%). 주유기에서 PC Optimum 카드 연결.", "zh": "在Esso和Mobil加油站每$1获25积分（约2.5%）。在油泵关联PC Optimum卡可获额外积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'INSURANCE', '{"en": "World Mastercard Perks", "es": "Beneficios World Mastercard", "fr": "Avantages World Mastercard", "ja": "World Mastercard特典", "ko": "World Mastercard 혜택", "zh": "World Mastercard权益"}', '{"en": "Includes purchase protection and extended warranty. Basic World Mastercard benefits included for a no-fee card.", "es": "Incluye protección de compras y garantía extendida. Beneficios básicos World Mastercard para tarjeta gratis.", "fr": "Inclut protection des achats et garantie prolongée. Avantages World Mastercard de base pour une carte gratuite.", "ja": "購入保護と延長保証付き。年会費無料カードで基本的なWorld Mastercard特典。", "ko": "구매 보호 및 연장 보증 포함. 연회비 무료 카드에 기본 World Mastercard 혜택.", "zh": "包含购物保障和延长保修。免年费卡包含基本World Mastercard权益。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee and no income requirement. All points earned are pure savings. Perfect entry-level PC card.", "es": "Sin cuota anual ni requisito de ingresos. Perfecta tarjeta PC de nivel de entrada.", "fr": "Aucuns frais annuels ni exigence de revenu. Parfaite carte PC d''entrée de gamme.", "ja": "年会費無料、収入要件なし。獲得ポイントは全て純粋な節約。完璧なPC入門カード。", "ko": "연회비 무료, 소득 요건 없음. 모든 포인트가 순수 절약. 완벽한 PC 입문 카드.", "zh": "免年费，无收入要求。所有积分都是纯省钱。完美的PC入门卡。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'PERK', '{"en": "Stack with PC Optimum App", "es": "Combina con PC Optimum", "fr": "Combiner avec PC Optimum", "ja": "PC Optimumアプリと併用", "ko": "PC Optimum 앱과 결합", "zh": "与PC Optimum App叠加"}', '{"en": "Load personalized offers in PC Optimum app before shopping. Stack with 20x points events for 20%+ effective rewards.", "es": "Carga ofertas personalizadas en la app PC Optimum. Combina con eventos 20x para 20%+ de recompensas.", "fr": "Chargez les offres personnalisées dans l''appli PC Optimum. Combinez avec les événements 20x.", "ja": "買い物前にPC Optimumアプリでパーソナライズオファーをロード。20倍イベントと併用で20%+。", "ko": "쇼핑 전 PC Optimum 앱에서 개인화 오퍼 로드. 20배 이벤트와 결합하여 20%+ 유효 리워드.", "zh": "购物前在PC Optimum App加载个性化优惠。与20倍积分活动叠加可获20%+有效奖励。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'REDEMPTION', '{"en": "Redeem at Checkout", "es": "Canjear al pagar", "fr": "Échanger à la caisse", "ja": "レジで交換", "ko": "계산대에서 교환", "zh": "结账时兑换"}', '{"en": "Redeem 10,000 points for $10 off at any Loblaw store or Shoppers. Points never expire with activity in 12 months.", "es": "Canjea 10,000 puntos por $10 en cualquier Loblaw o Shoppers. Puntos no expiran con actividad.", "fr": "Échangez 10 000 points pour 10 $ chez Loblaw ou Shoppers. Points n''expirent jamais avec activité.", "ja": "Loblawまたは Shoppersで10,000ポイント=$10として交換。12ヶ月活動があれば無期限。", "ko": "Loblaw 또는 Shoppers에서 10,000 포인트를 $10으로 교환. 12개월 활동 시 만료 없음.", "zh": "在任何Loblaw超市或Shoppers用10,000积分抵扣$10。12个月内有积分变动则不过期。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'PC Financial' AND name = 'World Mastercard'), 'STACKING', '{"en": "Upgrade to World Elite", "es": "Actualizar a World Elite", "fr": "Passer au World Elite", "ja": "World Eliteへアップグレード", "ko": "World Elite로 업그레이드", "zh": "升级到World Elite"}', '{"en": "World Elite offers 1% higher rates (4.5% Shoppers, 3% Loblaw/Esso). Also free - upgrade if you meet income requirement.", "es": "World Elite ofrece 1% más (4.5% Shoppers, 3% Loblaw/Esso). También gratis - actualiza si calificas.", "fr": "World Elite offre 1 % de plus (4,5 % Shoppers, 3 % Loblaw/Esso). Gratuit aussi - passez si éligible.", "ja": "World Eliteは1%高い（Shoppers 4.5%、Loblaw/Esso 3%）。同じく無料-収入要件を満たせば昇格を。", "ko": "World Elite는 1% 높음 (Shoppers 4.5%, Loblaw/Esso 3%). 역시 무료 - 자격이 되면 업그레이드.", "zh": "World Elite返现率高1%（Shoppers 4.5%，Loblaw/Esso 3%）。同样免年费，符合收入要求可升级。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'AVOID', '{"en": "Only 1x on Everything Else", "es": "Solo 1x en todo lo demás", "fr": "Seulement 1x sur le reste", "ja": "その他は1倍のみ", "ko": "기타 1배만", "zh": "其他消费仅1倍"}', '{"en": "Only earns 1 point per $1 on non-travel purchases. Consider pairing with a grocery/gas card for everyday spending.", "es": "Solo gana 1 punto por $1 en compras no viajes. Combina con tarjeta de supermercado/gasolina para gastos diarios.", "fr": "Gagne seulement 1 point par dollar hors voyage. Combinez avec une carte épicerie/essence pour le quotidien.", "ja": "非旅行購入は$1あたり1ポイントのみ。日常消費には食料品/ガスカードとの併用を検討。", "ko": "비여행 구매에서 $1당 1포인트만. 일상 지출에는 식료품/주유 카드와 병행 고려.", "zh": "非旅行消费仅获每$1得1积分。建议搭配超市/加油卡用于日常消费。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'AVOID', '{"en": "$120 Annual Fee", "es": "Cuota anual $120", "fr": "Frais annuels 120 $", "ja": "年会費$120", "ko": "연회비 $120", "zh": "年费$120"}', '{"en": "Need to earn ~12,000 points worth of extra value to justify the fee. Best for travelers who use the insurance and lounge benefits.", "es": "Necesitas ganar ~12,000 puntos extra para justificar la cuota. Ideal para viajeros que usan seguro y salas.", "fr": "Il faut gagner ~12 000 points de valeur extra pour justifier les frais. Idéal pour voyageurs utilisant assurance et salons.", "ja": "年会費の価値を得るには約12,000ポイント相当の追加価値が必要。保険とラウンジを使う旅行者に最適。", "ko": "연회비를 정당화하려면 약 12,000 포인트 상당의 추가 가치 필요. 보험과 라운지 혜택을 사용하는 여행자에게 적합.", "zh": "需获约12,000积分额外价值才值回年费。最适合使用保险和贵宾厅权益的旅行者。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'BEST_USE', '{"en": "1.25x on Travel", "es": "1.25x en viajes", "fr": "1,25x sur voyages", "ja": "旅行1.25倍", "ko": "여행 1.25배", "zh": "旅行1.25倍积分"}', '{"en": "Earn 1.25 Avion points per $1 on travel including flights, hotels, car rentals, and travel agencies.", "es": "Gana 1.25 puntos Avion por $1 en viajes incluyendo vuelos, hoteles, alquiler de autos y agencias.", "fr": "Gagnez 1,25 point Avion par dollar sur les voyages incluant vols, hôtels, location auto et agences.", "ja": "旅行で$1あたり1.25 Avionポイント。航空券、ホテル、レンタカー、旅行代理店含む。", "ko": "여행에서 $1당 1.25 Avion 포인트. 항공권, 호텔, 렌터카, 여행사 포함.", "zh": "旅行消费每$1获1.25 Avion积分，包括机票、酒店、租车和旅行社。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'BEST_USE', '{"en": "Transfer to 10+ Airlines", "es": "Transferir a 10+ aerolíneas", "fr": "Transférer à 10+ compagnies", "ja": "10+航空会社に移行", "ko": "10+ 항공사로 이전", "zh": "转换至10+航空公司"}', '{"en": "Transfer Avion points 1:1 to WestJet, British Airways, Cathay Pacific, Asia Miles, and other airline partners.", "es": "Transfiere puntos Avion 1:1 a WestJet, British Airways, Cathay Pacific, Asia Miles y otros socios.", "fr": "Transférez points Avion 1:1 vers WestJet, British Airways, Cathay Pacific, Asia Miles et autres partenaires.", "ja": "AvionポイントをWestJet、ブリティッシュエアウェイズ、キャセイパシフィック、アジアマイルなどに1:1移行。", "ko": "Avion 포인트를 WestJet, 영국항공, 캐세이퍼시픽, 아시아마일 등에 1:1 전환.", "zh": "Avion积分可1:1转换至WestJet、英航、国泰、亚洲万里通等航空合作伙伴。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'BEST_USE', '{"en": "RBC Travel Redemption", "es": "Canje RBC Travel", "fr": "Échange RBC Voyages", "ja": "RBCトラベル交換", "ko": "RBC Travel 교환", "zh": "RBC旅行兑换"}', '{"en": "Redeem points through RBC Travel at 1 cent per point. No blackout dates, book any flight or hotel available online.", "es": "Canjea vía RBC Travel a 1 centavo por punto. Sin fechas bloqueadas, reserva cualquier vuelo u hotel.", "fr": "Échangez via RBC Voyages à 1 ¢ par point. Pas de dates bloquées, réservez tout vol ou hôtel disponible.", "ja": "RBC Travelで1ポイント=1セントで交換。ブラックアウト日なし、オンラインの航空券やホテル予約可能。", "ko": "RBC Travel에서 포인트당 1센트로 교환. 블랙아웃 날짜 없음, 온라인 항공편/호텔 예약 가능.", "zh": "通过RBC Travel兑换，每积分价值1分。无封锁日期，可预订任何在线航班或酒店。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'PERK', '{"en": "Travel Insurance Included", "es": "Seguro de viaje incluido", "fr": "Assurance voyage incluse", "ja": "旅行保険付き", "ko": "여행 보험 포함", "zh": "含旅行保险"}', '{"en": "Includes $5M travel medical, trip cancellation, baggage delay, flight delay, car rental collision, and mobile device insurance.", "es": "Incluye $5M seguro médico viaje, cancelación, retraso equipaje/vuelo, colisión alquiler y dispositivo móvil.", "fr": "Inclut 5 M$ assurance médicale voyage, annulation, retard bagages/vol, collision location et appareil mobile.", "ja": "旅行医療$500万、旅行キャンセル、手荷物遅延、航空遅延、レンタカー衝突、モバイル保険付き。", "ko": "여행 의료 $500만, 여행 취소, 수하물 지연, 항공 지연, 렌터카 충돌, 모바일 기기 보험 포함.", "zh": "包含$500万旅行医疗、行程取消、行李延误、航班延误、租车碰撞和手机保险。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'PERK', '{"en": "Airport Lounge Passes", "es": "Pases de sala VIP", "fr": "Accès salon aéroport", "ja": "空港ラウンジパス", "ko": "공항 라운지 패스", "zh": "机场贵宾厅通行证"}', '{"en": "Get 4 complimentary Dragon Pass lounge visits per year. Access 1,000+ lounges worldwide.", "es": "Obtén 4 visitas Dragon Pass gratis al año. Acceso a 1,000+ salas en todo el mundo.", "fr": "Obtenez 4 visites gratuites Dragon Pass par an. Accès à 1 000+ salons dans le monde.", "ja": "年4回の無料Dragon Passラウンジ訪問。世界1,000+ラウンジにアクセス。", "ko": "연간 4회 무료 Dragon Pass 라운지 방문. 전세계 1,000+ 라운지 이용.", "zh": "每年4次免费Dragon Pass贵宾厅访问。全球1,000+贵宾厅可用。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'REDEMPTION', '{"en": "Best Value: Airline Transfers", "es": "Mejor valor: transferencias aéreas", "fr": "Meilleure valeur : transferts aériens", "ja": "最高価値：航空会社転送", "ko": "최고 가치: 항공사 전환", "zh": "最佳价值：航司转换"}', '{"en": "Transfer to British Airways or Asia Miles for premium cabin redemptions. Can get 2-3 cents per point value on business/first class.", "es": "Transfiere a British Airways o Asia Miles para cabinas premium. 2-3 centavos por punto en business/primera.", "fr": "Transférez vers British Airways ou Asia Miles pour cabines premium. 2-3 ¢ par point en affaires/première.", "ja": "ブリティッシュエアウェイズやアジアマイルに移行してプレミアムキャビン交換。ビジネス/ファーストで2-3セント/ポイント。", "ko": "영국항공/아시아마일로 전환하여 프리미엄 캐빈 교환. 비즈니스/퍼스트에서 포인트당 2-3센트 가치.", "zh": "转换至英航或亚洲万里通兑换高端舱位。商务/头等舱可获每积分2-3分价值。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'STACKING', '{"en": "Pair with Everyday Card", "es": "Combina con tarjeta diaria", "fr": "Combiner avec carte quotidienne", "ja": "日常カードと併用", "ko": "일상 카드와 병행", "zh": "搭配日常消费卡"}', '{"en": "Use Avion Infinite for travel bookings and a 2%+ cash back card for groceries, gas, and everyday spending.", "es": "Usa Avion Infinite para viajes y una tarjeta 2%+ para supermercado, gasolina y gastos diarios.", "fr": "Utilisez Avion Infinite pour voyages et une carte 2 %+ pour épicerie, essence et quotidien.", "ja": "旅行予約にはAvion Infinite、食料品、ガス、日常消費には2%+キャッシュバックカードを使用。", "ko": "여행 예약에는 Avion Infinite, 식료품, 주유, 일상 지출에는 2%+ 캐시백 카드 사용.", "zh": "用Avion Infinite预订旅行，用2%+返现卡支付超市、加油和日常消费。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite'), 'STACKING', '{"en": "Consider Privilege Upgrade", "es": "Considera Privilege", "fr": "Considérer le Privilege", "ja": "Privilegeへの昇格検討", "ko": "Privilege 업그레이드 고려", "zh": "考虑升级Privilege"}', '{"en": "Avion Privilege ($175/year) offers 1.25x on all purchases, 6 lounge passes, and higher signup bonus. Worth it for high spenders.", "es": "Avion Privilege ($175/año) ofrece 1.25x en todo, 6 pases de sala y mejor bono. Para grandes gastadores.", "fr": "Avion Privilege (175 $/an) offre 1,25x partout, 6 passes salon et meilleur bonus. Pour gros dépensiers.", "ja": "Avion Privilege ($175/年) は全消費1.25倍、ラウンジパス6回、より高い開設ボーナス。高額消費者向け。", "ko": "Avion Privilege ($175/년)는 모든 구매 1.25배, 라운지 패스 6회, 더 높은 가입 보너스. 고액 지출자에게 적합.", "zh": "Avion Privilege ($175/年) 所有消费1.25倍、6次贵宾厅、更高开卡奖励。适合高消费者。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'AVOID', '{"en": "$175 Annual Fee", "es": "Cuota anual $175", "fr": "Frais annuels 175 $", "ja": "年会費$175", "ko": "연회비 $175", "zh": "年费$175"}', '{"en": "$55 more than regular Infinite. Worth it if you spend $20K+/year (the 0.25x boost = $50+ extra value) and use the perks.", "es": "$55 más que Infinite regular. Vale si gastas $20K+/año y usas los beneficios.", "fr": "55 $ de plus que Infinite standard. Vaut le coup si vous dépensez 20 000 $+/an et utilisez les avantages.", "ja": "通常Infiniteより$55高い。年間$20K+消費（0.25倍ブースト=$50+の追加価値）してパークを使うなら価値あり。", "ko": "일반 Infinite보다 $55 더 비쌈. 연간 $20K+ 지출하고 혜택을 사용하면 가치 있음.", "zh": "比普通Infinite贵$55。如果年消费$20K+（0.25倍提升=$50+额外价值）并使用权益则值得。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'BEST_USE', '{"en": "2x on Travel", "es": "2x en viajes", "fr": "2x sur voyages", "ja": "旅行2倍", "ko": "여행 2배", "zh": "旅行2倍积分"}', '{"en": "Earn 2 Avion points per $1 on travel including flights, hotels, car rentals, cruises, and travel agencies.", "es": "Gana 2 puntos Avion por $1 en viajes incluyendo vuelos, hoteles, alquiler de autos, cruceros y agencias.", "fr": "Gagnez 2 points Avion par dollar sur les voyages incluant vols, hôtels, location auto, croisières et agences.", "ja": "旅行で$1あたり2 Avionポイント。航空券、ホテル、レンタカー、クルーズ、旅行代理店含む。", "ko": "여행에서 $1당 2 Avion 포인트. 항공권, 호텔, 렌터카, 크루즈, 여행사 포함.", "zh": "旅行消费每$1获2 Avion积分，包括机票、酒店、租车、游轮和旅行社。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'BEST_USE', '{"en": "1.5x on Dining", "es": "1.5x en restaurantes", "fr": "1,5x sur restaurants", "ja": "ダイニング1.5倍", "ko": "식사 1.5배", "zh": "餐饮1.5倍积分"}', '{"en": "Earn 1.5 Avion points per $1 at restaurants, bars, and food delivery services.", "es": "Gana 1.5 puntos Avion por $1 en restaurantes, bares y servicios de entrega de comida.", "fr": "Gagnez 1,5 point Avion par dollar dans les restaurants, bars et services de livraison.", "ja": "レストラン、バー、フードデリバリーで$1あたり1.5 Avionポイント。", "ko": "레스토랑, 바, 음식 배달 서비스에서 $1당 1.5 Avion 포인트.", "zh": "在餐厅、酒吧和外卖服务每$1获1.5 Avion积分。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'BEST_USE', '{"en": "1.25x on Everything", "es": "1.25x en todo", "fr": "1,25x sur tout", "ja": "全て1.25倍", "ko": "모든 구매 1.25배", "zh": "所有消费1.25倍"}', '{"en": "Earn 1.25 points per $1 on all other purchases. No bonus categories to track - solid rate on everything.", "es": "Gana 1.25 puntos por $1 en todas las demás compras. Sin categorías bonus que rastrear - buena tasa en todo.", "fr": "Gagnez 1,25 point par dollar sur tous les autres achats. Pas de catégories bonus à suivre - bon taux partout.", "ja": "その他全ての購入で$1あたり1.25ポイント。ボーナスカテゴリ追跡不要、全てに良いレート。", "ko": "기타 모든 구매에서 $1당 1.25 포인트. 추적할 보너스 카테고리 없음 - 모든 곳에서 좋은 요율.", "zh": "其他所有消费每$1获1.25积分。无需追踪奖励类别，一切消费都有不错的返还率。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'BEST_USE', '{"en": "Transfer to 10+ Airlines", "es": "Transferir a 10+ aerolíneas", "fr": "Transférer à 10+ compagnies", "ja": "10+航空会社に移行", "ko": "10+ 항공사로 이전", "zh": "转换至10+航空公司"}', '{"en": "Transfer Avion points 1:1 to WestJet, British Airways, Cathay Pacific, Asia Miles, and other airline partners.", "es": "Transfiere puntos Avion 1:1 a WestJet, British Airways, Cathay Pacific, Asia Miles y otros socios.", "fr": "Transférez points Avion 1:1 vers WestJet, British Airways, Cathay Pacific, Asia Miles et autres partenaires.", "ja": "AvionポイントをWestJet、ブリティッシュエアウェイズ、キャセイパシフィック、アジアマイルなどに1:1移行。", "ko": "Avion 포인트를 WestJet, 영국항공, 캐세이퍼시픽, 아시아마일 등에 1:1 전환.", "zh": "Avion积分可1:1转换至WestJet、英航、国泰、亚洲万里通等航空合作伙伴。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'INSURANCE', '{"en": "Mobile Device Insurance", "es": "Seguro de dispositivo móvil", "fr": "Assurance appareil mobile", "ja": "モバイル機器保険", "ko": "모바일 기기 보험", "zh": "手机保险"}', '{"en": "Up to $1,000 coverage for phone damage or theft if you pay your cell bill with this card. $50 deductible.", "es": "Cobertura hasta $1,000 por daño/robo de teléfono si pagas tu factura celular con esta tarjeta. Deducible $50.", "fr": "Couverture jusqu''à 1 000 $ pour dommages/vol de téléphone si vous payez votre facture avec cette carte. Franchise 50 $.", "ja": "このカードで携帯料金を支払うと、最大$1,000の損傷・盗難保険。$50の免責金額。", "ko": "이 카드로 휴대폰 요금 결제 시 최대 $1,000 손상/도난 보장. $50 공제액.", "zh": "用此卡支付手机账单，可获最高$1,000手机损坏或被盗保障。$50免赔额。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'PERK', '{"en": "6 Airport Lounge Passes", "es": "6 pases de sala VIP", "fr": "6 accès salon aéroport", "ja": "空港ラウンジパス6回", "ko": "공항 라운지 패스 6회", "zh": "6次机场贵宾厅通行证"}', '{"en": "Get 6 complimentary Dragon Pass lounge visits per year (2 more than regular Infinite). Access 1,300+ lounges worldwide.", "es": "Obtén 6 visitas Dragon Pass gratis al año (2 más que Infinite regular). Acceso a 1,300+ salas.", "fr": "Obtenez 6 visites gratuites Dragon Pass par an (2 de plus que Infinite standard). Accès à 1 300+ salons.", "ja": "年6回の無料Dragon Passラウンジ訪問（通常Infiniteより2回多い）。世界1,300+ラウンジにアクセス。", "ko": "연간 6회 무료 Dragon Pass 라운지 방문 (일반 Infinite보다 2회 더). 전세계 1,300+ 라운지 이용.", "zh": "每年6次免费Dragon Pass贵宾厅访问（比普通Infinite多2次）。全球1,300+贵宾厅可用。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'PERK', '{"en": "Premium Travel Insurance", "es": "Seguro de viaje premium", "fr": "Assurance voyage premium", "ja": "プレミアム旅行保険", "ko": "프리미엄 여행 보험", "zh": "高端旅行保险"}', '{"en": "Includes $10M travel medical, trip cancellation/interruption, baggage, flight delay, car rental, and mobile device insurance.", "es": "Incluye $10M seguro médico viaje, cancelación/interrupción, equipaje, retraso vuelo, alquiler auto y móvil.", "fr": "Inclut 10 M$ assurance médicale voyage, annulation/interruption, bagages, retard vol, location auto et mobile.", "ja": "旅行医療$1000万、旅行キャンセル/中断、手荷物、航空遅延、レンタカー、モバイル保険付き。", "ko": "여행 의료 $1000만, 여행 취소/중단, 수하물, 항공 지연, 렌터카, 모바일 기기 보험 포함.", "zh": "包含$1000万旅行医疗、行程取消/中断、行李、航班延误、租车和手机保险。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'REDEMPTION', '{"en": "Best Value: Airline Transfers", "es": "Mejor valor: transferencias aéreas", "fr": "Meilleure valeur : transferts aériens", "ja": "最高価値：航空会社転送", "ko": "최고 가치: 항공사 전환", "zh": "最佳价值：航司转换"}', '{"en": "Transfer to British Airways or Asia Miles for premium cabin redemptions. Can get 2-3 cents per point value on business/first class.", "es": "Transfiere a British Airways o Asia Miles para cabinas premium. 2-3 centavos por punto en business/primera.", "fr": "Transférez vers British Airways ou Asia Miles pour cabines premium. 2-3 ¢ par point en affaires/première.", "ja": "ブリティッシュエアウェイズやアジアマイルに移行してプレミアムキャビン交換。ビジネス/ファーストで2-3セント/ポイント。", "ko": "영국항공/아시아마일로 전환하여 프리미엄 캐빈 교환. 비즈니스/퍼스트에서 포인트당 2-3센트 가치.", "zh": "转换至英航或亚洲万里通兑换高端舱位。商务/头等舱可获每积分2-3分价值。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Avion Visa Infinite Privilege'), 'STACKING', '{"en": "Good as Primary Card", "es": "Buena como tarjeta principal", "fr": "Bonne carte principale", "ja": "メインカードに適す", "ko": "주카드로 적합", "zh": "适合作主力卡"}', '{"en": "With 1.25x on everything, this can be your primary card. Only switch to specialized cards for grocery 3%+ or gas 3%+.", "es": "Con 1.25x en todo, puede ser tu tarjeta principal. Solo cambia por supermercado/gasolina 3%+.", "fr": "Avec 1,25x partout, peut être votre carte principale. Ne changez que pour épicerie/essence 3 %+.", "ja": "全て1.25倍なのでメインカードとして使用可能。食料品3%+やガス3%+の専用カードのみ切替を。", "ko": "모든 곳에서 1.25배로 주카드로 사용 가능. 식료품 3%+ 또는 주유 3%+ 전용 카드만 전환.", "zh": "所有消费1.25倍，可作为主力卡。只有超市3%+或加油3%+的专用卡才值得切换。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'AVOID', '{"en": "Only 1% on Other Purchases", "es": "Solo 1% en otras compras", "fr": "Seulement 1 % sur autres achats", "ja": "他の購入は1%のみ", "ko": "기타 구매는 1%만", "zh": "其他消费仅1%"}', '{"en": "Only earns 1% on non-grocery and non-pharmacy purchases. Use a different card for gas, dining, and travel.", "es": "Solo gana 1% fuera de supermercado/farmacia. Usa otra tarjeta para gasolina, comida y viajes.", "fr": "Gagne seulement 1 % hors épicerie/pharmacie. Utilisez une autre carte pour essence, restos et voyages.", "ja": "食料品・薬局以外は1%のみ。ガス、外食、旅行には別のカードを使用。", "ko": "식료품/약국 외에서는 1%만 적립. 주유, 식사, 여행에는 다른 카드 사용.", "zh": "非超市和药店消费仅获1%。加油、餐饮和旅行请使用其他卡。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'AVOID', '{"en": "No Gas Bonus", "es": "Sin bonus de gasolina", "fr": "Pas de bonus essence", "ja": "ガスボーナスなし", "ko": "주유 보너스 없음", "zh": "加油无奖励"}', '{"en": "Unlike many competing cards, this card only earns 1% at gas stations. Consider pairing with a gas rewards card.", "es": "A diferencia de otras tarjetas, solo gana 1% en gasolineras. Considera combinar con tarjeta de gasolina.", "fr": "Contrairement à d''autres cartes, seulement 1 % aux stations-service. Combinez avec une carte essence.", "ja": "競合カードと異なり、ガソリンスタンドで1%のみ。ガス報酬カードとの併用を検討。", "ko": "경쟁 카드와 달리 주유소에서 1%만 적립. 주유 리워드 카드와 병행 고려.", "zh": "与许多竞品卡不同，此卡在加油站仅获1%。建议搭配加油奖励卡使用。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "2% on Groceries", "es": "2% en supermercados", "fr": "2 % sur épicerie", "ja": "食料品2%", "ko": "식료품 2%", "zh": "超市2%返现"}', '{"en": "Earn 2% cash back on grocery purchases at supermarkets. Great rate for a no-fee card.", "es": "Gana 2% de reembolso en compras de supermercado. Gran tasa para tarjeta sin cuota.", "fr": "Gagnez 2 % de remise sur l''épicerie. Excellent taux pour une carte sans frais.", "ja": "スーパーでの食料品購入で2%キャッシュバック。年会費無料カードで優秀なレート。", "ko": "슈퍼마켓에서 식료품 구매 시 2% 캐시백. 연회비 무료 카드 중 우수한 요율.", "zh": "在超市购物获得2%返现。免年费卡中的优秀返现率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'BEST_USE', '{"en": "2% at Pharmacies", "es": "2% en farmacias", "fr": "2 % en pharmacie", "ja": "薬局2%", "ko": "약국 2%", "zh": "药店2%返现"}', '{"en": "Earn 2% cash back at pharmacies including Shoppers Drug Mart, Rexall, and London Drugs.", "es": "Gana 2% en farmacias incluyendo Shoppers Drug Mart, Rexall y London Drugs.", "fr": "Gagnez 2 % en pharmacie incluant Shoppers Drug Mart, Rexall et London Drugs.", "ja": "Shoppers Drug Mart、Rexall、London Drugsなどの薬局で2%キャッシュバック。", "ko": "Shoppers Drug Mart, Rexall, London Drugs 등 약국에서 2% 캐시백.", "zh": "在药店获得2%返现，包括Shoppers Drug Mart、Rexall和London Drugs。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'INSURANCE', '{"en": "Basic Purchase Protection", "es": "Protección básica de compras", "fr": "Protection de base", "ja": "基本購入保護", "ko": "기본 구매 보호", "zh": "基本购物保障"}', '{"en": "Includes purchase protection and extended warranty. Basic coverage for a no-fee card.", "es": "Incluye protección de compras y garantía extendida. Cobertura básica para tarjeta sin cuota.", "fr": "Inclut protection des achats et garantie prolongée. Couverture de base pour carte gratuite.", "ja": "購入保護と延長保証付き。年会費無料カードの基本的なカバレッジ。", "ko": "구매 보호 및 연장 보증 포함. 연회비 무료 카드의 기본 보장.", "zh": "包含购物保障和延长保修。免年费卡的基本保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee means all cash back earned is pure savings. Simple and effective everyday card.", "es": "Sin cuota anual significa que todo el reembolso es ganancia pura. Tarjeta diaria simple y efectiva.", "fr": "Sans frais annuels signifie que toute remise est profit pur. Carte quotidienne simple et efficace.", "ja": "年会費無料で獲得したキャッシュバックは全て純利益。シンプルで効果的な日常カード。", "ko": "연회비 무료로 모든 캐시백이 순수익. 간단하고 효과적인 일상 카드.", "zh": "免年费意味着所有返现都是纯收益。简单有效的日常消费卡。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'PERK', '{"en": "No Income Requirement", "es": "Sin requisito de ingresos", "fr": "Aucune exigence de revenu", "ja": "収入要件なし", "ko": "소득 요건 없음", "zh": "无收入要求"}', '{"en": "No minimum income requirement makes this card accessible to students, newcomers, and those building credit.", "es": "Sin requisito de ingresos mínimos, accesible para estudiantes, recién llegados y quienes construyen crédito.", "fr": "Pas d''exigence de revenu minimum, accessible aux étudiants, nouveaux arrivants et ceux qui bâtissent leur crédit.", "ja": "最低収入要件なしで、学生、新規移民、クレジット構築中の方に適切。", "ko": "최소 소득 요건 없음. 학생, 신규 이민자, 신용 구축 중인 분들에게 적합.", "zh": "无最低收入要求，适合学生、新移民和正在建立信用的人。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'REDEMPTION', '{"en": "Automatic Cash Back", "es": "Reembolso automático", "fr": "Remise automatique", "ja": "自動キャッシュバック", "ko": "자동 캐시백", "zh": "自动返现"}', '{"en": "Cash back is automatically applied as a statement credit annually. No minimum balance or redemption hassle.", "es": "El reembolso se aplica automáticamente como crédito anual. Sin mínimo ni complicaciones.", "fr": "La remise est automatiquement appliquée annuellement au relevé. Pas de minimum ni de tracas.", "ja": "キャッシュバックは年次で明細クレジットとして自動適用。最低残高なし、交換の手間なし。", "ko": "캐시백은 연간 명세서 크레딧으로 자동 적용. 최소 잔액 없음, 교환 번거로움 없음.", "zh": "返现每年自动作为账单抵扣。无最低余额要求，无兑换麻烦。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'STACKING', '{"en": "Pair with Gas Card", "es": "Combina con tarjeta de gas", "fr": "Combiner avec carte essence", "ja": "ガスカードと併用", "ko": "주유 카드와 병행", "zh": "搭配加油卡"}', '{"en": "Use this card for groceries/pharmacy and a card with 3%+ gas rewards for fill-ups. Simple two-card strategy.", "es": "Usa esta tarjeta para supermercado/farmacia y una tarjeta con 3%+ gas para llenar. Estrategia simple de dos tarjetas.", "fr": "Utilisez cette carte pour épicerie/pharmacie et une carte 3 %+ essence pour les pleins. Stratégie simple à deux cartes.", "ja": "食料品/薬局にはこのカード、給油には3%+のガスカードを使用。シンプルな2枚カード戦略。", "ko": "식료품/약국에는 이 카드, 주유에는 3%+ 주유 카드 사용. 간단한 2카드 전략.", "zh": "用此卡购买超市/药店商品，用3%+加油返现卡加油。简单的双卡策略。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'Cash Back Mastercard'), 'STACKING', '{"en": "Consider Cash Back Preferred", "es": "Considera Cash Back Preferred", "fr": "Considérer Cash Back Preferred", "ja": "Cash Back Preferred検討", "ko": "Cash Back Preferred 고려", "zh": "考虑升级Preferred"}', '{"en": "RBC Cash Back Preferred ($99/year) offers 2% on recurring and gas too. Worth it if you spend $5,000+/year on gas.", "es": "RBC Cash Back Preferred ($99/año) ofrece 2% en recurrente y gas. Vale si gastas $5,000+/año en gas.", "fr": "RBC Cash Back Preferred (99 $/an) offre aussi 2 % récurrent et essence. Vaut si 5 000 $+/an en essence.", "ja": "RBC Cash Back Preferred ($99/年) は定期払い・ガスも2%。年間ガス$5,000+なら価値あり。", "ko": "RBC Cash Back Preferred ($99/년)는 정기 결제와 주유도 2%. 연간 주유 $5,000+ 지출 시 가치 있음.", "zh": "RBC Cash Back Preferred ($99/年) 定期付款和加油也有2%。如果年加油消费$5,000+则值得。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'AVOID', '{"en": "Only 1x on Gas", "es": "Solo 1x en gasolina", "fr": "Seulement 1x sur essence", "ja": "ガスは1倍のみ", "ko": "주유는 1배만", "zh": "加油仅1倍"}', '{"en": "Only earns 1 point per $1 at gas stations. Use a different card for gas or consider ION+ for 3x on gas.", "es": "Solo gana 1 punto por $1 en gasolina. Considera ION+ para 3x en gasolina.", "fr": "Gagne seulement 1 point par dollar à l''essence. Considérez ION+ pour 3x sur essence.", "ja": "ガソリンスタンドで$1あたり1ポイントのみ。ガスにはION+（3倍）を検討。", "ko": "주유소에서 $1당 1포인트만 적립. 주유에는 ION+ (3배) 고려.", "zh": "加油站仅获每$1得1积分。加油请使用其他卡，或考虑ION+可获3倍。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'BEST_USE', '{"en": "1.5x on Groceries", "es": "1.5x en supermercados", "fr": "1,5x sur épicerie", "ja": "食料品1.5倍", "ko": "식료품 1.5배", "zh": "超市1.5倍积分"}', '{"en": "Earn 1.5 Avion points per $1 at grocery stores. Solid rate for a no-fee card.", "es": "Gana 1.5 puntos Avion por $1 en supermercados. Buena tasa para tarjeta sin cuota.", "fr": "Gagnez 1,5 point Avion par dollar à l''épicerie. Bon taux pour une carte gratuite.", "ja": "スーパーで$1あたり1.5 Avionポイント。年会費無料カードで良いレート。", "ko": "슈퍼마켓에서 $1당 1.5 Avion 포인트. 연회비 무료 카드 중 좋은 요율.", "zh": "在超市每$1获1.5 Avion积分。免年费卡的优秀返还率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'BEST_USE', '{"en": "1.5x on Dining", "es": "1.5x en restaurantes", "fr": "1,5x sur restaurants", "ja": "ダイニング1.5倍", "ko": "식사 1.5배", "zh": "餐饮1.5倍积分"}', '{"en": "Earn 1.5 Avion points per $1 at restaurants and food delivery. Great for foodies.", "es": "Gana 1.5 puntos Avion por $1 en restaurantes y delivery. Ideal para foodies.", "fr": "Gagnez 1,5 point Avion par dollar aux restaurants et livraison. Idéal pour les gourmets.", "ja": "レストランやデリバリーで$1あたり1.5 Avionポイント。グルメに最適。", "ko": "레스토랑과 배달에서 $1당 1.5 Avion 포인트. 미식가에게 적합.", "zh": "在餐厅和外卖每$1获1.5 Avion积分。美食爱好者的好选择。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'BEST_USE', '{"en": "1.5x on Transit & Rideshare", "es": "1.5x en transporte", "fr": "1,5x sur transports", "ja": "交通機関1.5倍", "ko": "대중교통 1.5배", "zh": "交通/网约车1.5倍"}', '{"en": "Earn 1.5 Avion points per $1 on public transit, Uber, Lyft, and other rideshare services.", "es": "Gana 1.5 puntos Avion por $1 en transporte público, Uber, Lyft y rideshare.", "fr": "Gagnez 1,5 point Avion par dollar sur transports en commun, Uber, Lyft et covoiturage.", "ja": "公共交通機関、Uber、Lyftなどで$1あたり1.5 Avionポイント。", "ko": "대중교통, Uber, Lyft 등에서 $1당 1.5 Avion 포인트.", "zh": "在公共交通、Uber、Lyft等网约车服务每$1获1.5 Avion积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'BEST_USE', '{"en": "1.5x on Recurring Bills", "es": "1.5x en facturas", "fr": "1,5x sur factures", "ja": "定期支払い1.5倍", "ko": "정기 청구서 1.5배", "zh": "定期账单1.5倍"}', '{"en": "Earn 1.5 Avion points per $1 on recurring bills including streaming, phone, and utilities.", "es": "Gana 1.5 puntos Avion por $1 en facturas recurrentes como streaming, teléfono y servicios.", "fr": "Gagnez 1,5 point Avion par dollar sur factures récurrentes : streaming, téléphone, services.", "ja": "ストリーミング、電話、公共料金など定期支払いで$1あたり1.5 Avionポイント。", "ko": "스트리밍, 전화, 공과금 등 정기 청구서에서 $1당 1.5 Avion 포인트.", "zh": "在定期账单（流媒体、电话、水电）每$1获1.5 Avion积分。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'INSURANCE', '{"en": "Basic Purchase Protection", "es": "Protección básica", "fr": "Protection de base", "ja": "基本購入保護", "ko": "기본 구매 보호", "zh": "基本购物保障"}', '{"en": "Includes purchase protection and extended warranty. Basic coverage for a no-fee card.", "es": "Incluye protección de compras y garantía extendida. Cobertura básica para tarjeta sin cuota.", "fr": "Inclut protection des achats et garantie prolongée. Couverture de base pour carte gratuite.", "ja": "購入保護と延長保証付き。年会費無料カードの基本的なカバレッジ。", "ko": "구매 보호 및 연장 보증 포함. 연회비 무료 카드의 기본 보장.", "zh": "包含购物保障和延长保修。免年费卡的基本保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee for an Avion points card. All points earned are pure rewards with flexible redemption options.", "es": "Sin cuota anual para una tarjeta Avion. Todos los puntos son recompensas puras con opciones flexibles.", "fr": "Sans frais annuels pour une carte Avion. Tous les points sont des récompenses pures avec options flexibles.", "ja": "年会費無料のAvionポイントカード。全ポイントが純粋な報酬、柔軟な交換オプション。", "ko": "Avion 포인트 카드 연회비 무료. 모든 포인트가 순수 리워드, 유연한 교환 옵션.", "zh": "免年费Avion积分卡。所有积分都是纯奖励，兑换选项灵活。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'PERK', '{"en": "Transfer to Airlines", "es": "Transferir a aerolíneas", "fr": "Transférer aux compagnies", "ja": "航空会社に移行", "ko": "항공사로 이전", "zh": "转换至航空公司"}', '{"en": "Transfer Avion points to WestJet, British Airways, Cathay Pacific, and other airline partners for travel redemptions.", "es": "Transfiere puntos Avion a WestJet, British Airways, Cathay Pacific y otros socios aéreos.", "fr": "Transférez les points Avion vers WestJet, British Airways, Cathay Pacific et autres partenaires.", "ja": "AvionポイントをWestJet、ブリティッシュエアウェイズ、キャセイなどに移行して旅行交換。", "ko": "Avion 포인트를 WestJet, 영국항공, 캐세이퍼시픽 등 항공 파트너로 전환.", "zh": "Avion积分可转换至WestJet、英航、国泰等航空合作伙伴兑换旅行。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem for travel, statement credits, gift cards, or merchandise. Best value through RBC Travel or airline transfers.", "es": "Canjea por viajes, créditos, tarjetas regalo o productos. Mejor valor vía RBC Travel o transferencias.", "fr": "Échangez pour voyages, crédits, cartes-cadeaux ou articles. Meilleure valeur via RBC Voyages ou transferts.", "ja": "旅行、明細クレジット、ギフトカード、商品に交換。RBC Travelや航空会社転送で最高価値。", "ko": "여행, 명세서 크레딧, 기프트 카드, 상품으로 교환. RBC Travel 또는 항공사 전환이 최고 가치.", "zh": "可兑换旅行、账单抵扣、礼品卡或商品。通过RBC Travel或航司转换价值最高。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION Visa'), 'STACKING', '{"en": "Consider ION+ Upgrade", "es": "Considera ION+", "fr": "Considérer ION+", "ja": "ION+へのアップグレード検討", "ko": "ION+ 업그레이드 고려", "zh": "考虑升级ION+"}', '{"en": "ION+ ($48/year) offers 3x on groceries, dining, gas, transit, and streaming. Worth it if you spend $4,800+/year in these categories.", "es": "ION+ ($48/año) ofrece 3x en supermercado, restaurantes, gas, transporte y streaming. Vale si gastas $4,800+/año.", "fr": "ION+ (48 $/an) offre 3x épicerie, restos, essence, transports et streaming. Vaut si 4 800 $+/an dans ces catégories.", "ja": "ION+ ($48/年) は食料品、外食、ガス、交通、ストリーミングで3倍。これらで年間$4,800+消費なら価値あり。", "ko": "ION+ ($48/년)는 식료품, 식사, 주유, 교통, 스트리밍에서 3배. 해당 카테고리에서 연간 $4,800+ 지출 시 가치 있음.", "zh": "ION+ ($48/年) 提供超市、餐饮、加油、交通和流媒体3倍。如果这些类别年消费$4,800+则值得。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'AVOID', '{"en": "Only 1x on Other Purchases", "es": "Solo 1x en otros", "fr": "Seulement 1x sur autres", "ja": "その他は1倍のみ", "ko": "기타 구매는 1배만", "zh": "其他消费仅1倍"}', '{"en": "Only earns 1 point per $1 on travel, shopping, and other purchases outside the 5 bonus categories.", "es": "Solo gana 1 punto por $1 en viajes, compras y otras fuera de las 5 categorías bonus.", "fr": "Gagne seulement 1 point par dollar hors des 5 catégories bonus (voyages, achats, etc.).", "ja": "5つのボーナスカテゴリ外の旅行、ショッピングなどは$1あたり1ポイントのみ。", "ko": "5개 보너스 카테고리 외 여행, 쇼핑 등에서 $1당 1포인트만.", "zh": "旅行、购物等5大奖励类别以外的消费仅获每$1得1积分。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'BEST_USE', '{"en": "3x on Groceries", "es": "3x en supermercados", "fr": "3x sur épicerie", "ja": "食料品3倍", "ko": "식료품 3배", "zh": "超市3倍积分"}', '{"en": "Earn 3 Avion points per $1 at grocery stores. One of the best grocery rates for a low-fee card.", "es": "Gana 3 puntos Avion por $1 en supermercados. Una de las mejores tasas para tarjeta de baja cuota.", "fr": "Gagnez 3 points Avion par dollar à l''épicerie. L''un des meilleurs taux épicerie pour carte à frais modiques.", "ja": "スーパーで$1あたり3 Avionポイント。低年会費カードで最高の食料品レートの一つ。", "ko": "슈퍼마켓에서 $1당 3 Avion 포인트. 저렴한 연회비 카드 중 최고의 식료품 요율.", "zh": "在超市每$1获3 Avion积分。低年费卡中最佳超市返还率之一。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'BEST_USE', '{"en": "3x on Gas & EV Charging", "es": "3x en gasolina y carga EV", "fr": "3x essence et recharge VÉ", "ja": "ガス・EV充電3倍", "ko": "주유 및 EV 충전 3배", "zh": "加油/电动车充电3倍"}', '{"en": "Earn 3 Avion points per $1 on gas and EV charging. Great for commuters and road trippers.", "es": "Gana 3 puntos Avion por $1 en gasolina y carga EV. Ideal para commuters y viajeros.", "fr": "Gagnez 3 points Avion par dollar sur essence et recharge VÉ. Idéal pour navetteurs et voyageurs.", "ja": "ガスとEV充電で$1あたり3 Avionポイント。通勤者やロードトリップに最適。", "ko": "주유와 EV 충전에서 $1당 3 Avion 포인트. 통근자와 로드트립에 적합.", "zh": "加油和电动车充电每$1获3 Avion积分。适合通勤者和公路旅行者。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'BEST_USE', '{"en": "3x on Dining & Delivery", "es": "3x en restaurantes y delivery", "fr": "3x restos et livraison", "ja": "ダイニング・デリバリー3倍", "ko": "식사 및 배달 3배", "zh": "餐饮/外卖3倍"}', '{"en": "Earn 3 Avion points per $1 at restaurants and food delivery apps like DoorDash and Uber Eats.", "es": "Gana 3 puntos Avion por $1 en restaurantes y apps como DoorDash y Uber Eats.", "fr": "Gagnez 3 points Avion par dollar aux restaurants et applis comme DoorDash et Uber Eats.", "ja": "レストランやDoorDash、Uber Eatsなどで$1あたり3 Avionポイント。", "ko": "레스토랑과 DoorDash, Uber Eats 등에서 $1당 3 Avion 포인트.", "zh": "在餐厅和外卖App（DoorDash、Uber Eats）每$1获3 Avion积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'BEST_USE', '{"en": "3x on Streaming", "es": "3x en streaming", "fr": "3x sur streaming", "ja": "ストリーミング3倍", "ko": "스트리밍 3배", "zh": "流媒体3倍"}', '{"en": "Earn 3 Avion points per $1 on streaming services like Netflix, Spotify, and digital subscriptions.", "es": "Gana 3 puntos Avion por $1 en Netflix, Spotify y suscripciones digitales.", "fr": "Gagnez 3 points Avion par dollar sur Netflix, Spotify et abonnements numériques.", "ja": "Netflix、Spotifyなどのストリーミングやデジタル購読で$1あたり3 Avionポイント。", "ko": "Netflix, Spotify 등 스트리밍과 디지털 구독에서 $1당 3 Avion 포인트.", "zh": "在Netflix、Spotify等流媒体和数字订阅每$1获3 Avion积分。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'BEST_USE', '{"en": "3x on Transit & Rideshare", "es": "3x en transporte", "fr": "3x transports", "ja": "交通機関3倍", "ko": "대중교통 3배", "zh": "交通/网约车3倍"}', '{"en": "Earn 3 Avion points per $1 on public transit, Uber, Lyft, and rideshare services.", "es": "Gana 3 puntos Avion por $1 en transporte público, Uber, Lyft y rideshare.", "fr": "Gagnez 3 points Avion par dollar sur transports en commun, Uber, Lyft et covoiturage.", "ja": "公共交通機関、Uber、Lyftなどで$1あたり3 Avionポイント。", "ko": "대중교통, Uber, Lyft 등에서 $1당 3 Avion 포인트.", "zh": "在公共交通、Uber、Lyft等网约车每$1获3 Avion积分。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'INSURANCE', '{"en": "Purchase & Extended Warranty", "es": "Protección y garantía", "fr": "Protection et garantie", "ja": "購入保護と延長保証", "ko": "구매 보호 및 연장 보증", "zh": "购物保障和延保"}', '{"en": "Includes purchase protection and extended warranty coverage. Good basic protection for a low-fee card.", "es": "Incluye protección de compras y garantía extendida. Buena protección básica para tarjeta de baja cuota.", "fr": "Inclut protection des achats et garantie prolongée. Bonne protection de base pour carte à frais modiques.", "ja": "購入保護と延長保証付き。低年会費カードで良い基本保護。", "ko": "구매 보호 및 연장 보증 포함. 저렴한 연회비 카드의 좋은 기본 보장.", "zh": "包含购物保障和延长保修。低年费卡的良好基本保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'PERK', '{"en": "Only $48/Year", "es": "Solo $48/año", "fr": "Seulement 48 $/an", "ja": "年会費$48のみ", "ko": "연회비 $48만", "zh": "年费仅$48"}', '{"en": "Low $48 annual fee for 3x earning on 5 categories. Free for students/under 24 with RBC student account.", "es": "$48/año para 3x en 5 categorías. Gratis para estudiantes/menores de 24 con cuenta RBC.", "fr": "48 $/an pour 3x sur 5 catégories. Gratuit pour étudiants/moins de 24 ans avec compte RBC.", "ja": "5カテゴリ3倍で年会費わずか$48。学生/24歳以下でRBC学生口座なら無料。", "ko": "5개 카테고리 3배에 연회비 $48만. 학생/24세 미만 + RBC 학생 계좌 시 무료.", "zh": "年费仅$48，5大类别3倍积分。学生/24岁以下+RBC学生账户免年费。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'PERK', '{"en": "Transfer to Airlines", "es": "Transferir a aerolíneas", "fr": "Transférer aux compagnies", "ja": "航空会社に移行", "ko": "항공사로 이전", "zh": "转换至航空公司"}', '{"en": "Transfer Avion points to WestJet, British Airways, Cathay Pacific, Asia Miles, and 10+ airline partners.", "es": "Transfiere puntos Avion a WestJet, British Airways, Cathay Pacific y 10+ socios aéreos.", "fr": "Transférez les points Avion vers WestJet, British Airways, Cathay Pacific et 10+ partenaires.", "ja": "AvionポイントをWestJet、ブリティッシュエアウェイズ、キャセイなど10+航空パートナーに移行。", "ko": "Avion 포인트를 WestJet, 영국항공, 캐세이퍼시픽 등 10+ 항공 파트너로 전환.", "zh": "Avion积分可转换至WestJet、英航、国泰、亚洲万里通等10+航空合作伙伴。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'ION+ Visa'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem for travel, gift cards, statement credits, or transfer to airlines. Best value through airline transfers.", "es": "Canjea por viajes, tarjetas regalo, créditos o transferencias aéreas. Mejor valor vía transferencias.", "fr": "Échangez pour voyages, cartes-cadeaux, crédits ou transferts aériens. Meilleure valeur via transferts.", "ja": "旅行、ギフトカード、明細クレジット、航空会社転送に交換。航空会社転送で最高価値。", "ko": "여행, 기프트 카드, 명세서 크레딧, 항공사 전환으로 교환. 항공사 전환이 최고 가치.", "zh": "可兑换旅行、礼品卡、账单抵扣或转换航司。航司转换价值最高。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'AVOID', '{"en": "Points Only for WestJet", "es": "Puntos solo para WestJet", "fr": "Points WestJet uniquement", "ja": "WestJetのみ", "ko": "WestJet에서만", "zh": "积分只能用于WestJet"}', '{"en": "WestJet dollars can only be redeemed for WestJet flights and vacations. Not suitable if you prefer other airlines.", "es": "Los dólares WestJet solo se canjean en WestJet. No apto si prefieres otras aerolíneas.", "fr": "Les dollars WestJet ne sont échangeables que sur WestJet. Pas idéal si vous préférez d''autres compagnies.", "ja": "WestJetドルはWestJet航空とバケーションのみ交換可能。他の航空会社を好む場合は不向き。", "ko": "WestJet 달러는 WestJet 항공과 휴가에만 교환 가능. 다른 항공사 선호 시 부적합.", "zh": "WestJet元只能兑换WestJet航班和度假。如果您偏好其他航空公司则不适合。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'AVOID', '{"en": "$139 Annual Fee", "es": "Cuota anual $139", "fr": "Frais annuels 139 $", "ja": "年会費$139", "ko": "연회비 $139", "zh": "年费$139"}', '{"en": "Need to fly WestJet 2+ times/year to justify the fee with companion voucher and baggage savings.", "es": "Necesitas volar WestJet 2+ veces/año para justificar la cuota con voucher y ahorro de equipaje.", "fr": "Il faut voler WestJet 2+ fois/an pour justifier les frais avec le voucher et économies bagages.", "ja": "年会費をコンパニオンバウチャーと荷物節約で正当化するには年2回以上のWestJet利用が必要。", "ko": "동반자 바우처와 수하물 절약으로 연회비를 정당화하려면 연간 2회 이상 WestJet 이용 필요.", "zh": "需每年乘坐WestJet 2+次才能通过同行券和行李节省抵消年费。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'BEST_USE', '{"en": "2x on WestJet Flights", "es": "2x en vuelos WestJet", "fr": "2x sur vols WestJet", "ja": "WestJet航空2倍", "ko": "WestJet 항공 2배", "zh": "WestJet航班2倍"}', '{"en": "Earn 2 WestJet dollars per $1 on WestJet flights and WestJet Vacations. Points worth 1 cent each toward WestJet flights.", "es": "Gana 2 dólares WestJet por $1 en vuelos WestJet y Vacations. Puntos valen 1¢ hacia vuelos WestJet.", "fr": "Gagnez 2 dollars WestJet par dollar sur vols WestJet et Vacations. Points valent 1 ¢ vers vols WestJet.", "ja": "WestJet航空とバケーションで$1あたり2 WestJetドル。ポイントは1セントでWestJet航空に交換。", "ko": "WestJet 항공 및 Vacations에서 $1당 2 WestJet 달러. 포인트는 WestJet 항공에 1센트로 교환.", "zh": "在WestJet航班和WestJet度假每$1获2 WestJet元。积分可按每分1分兑换WestJet航班。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'BEST_USE', '{"en": "2x on Groceries", "es": "2x en supermercados", "fr": "2x sur épicerie", "ja": "食料品2倍", "ko": "식료품 2배", "zh": "超市2倍"}', '{"en": "Earn 2 WestJet dollars per $1 at grocery stores. Build points quickly on everyday spending.", "es": "Gana 2 dólares WestJet por $1 en supermercados. Acumula puntos rápido en gastos diarios.", "fr": "Gagnez 2 dollars WestJet par dollar à l''épicerie. Accumulez vite sur les achats quotidiens.", "ja": "スーパーで$1あたり2 WestJetドル。日常消費でポイントを素早く貯める。", "ko": "슈퍼마켓에서 $1당 2 WestJet 달러. 일상 지출로 포인트 빠르게 적립.", "zh": "在超市每$1获2 WestJet元。日常消费快速积累积分。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'BEST_USE', '{"en": "2x on Gas & EV Charging", "es": "2x en gasolina y EV", "fr": "2x essence et VÉ", "ja": "ガス・EV充電2倍", "ko": "주유 및 EV 충전 2배", "zh": "加油/充电2倍"}', '{"en": "Earn 2 WestJet dollars per $1 on gas and EV charging. Great for commuters who fly WestJet.", "es": "Gana 2 dólares WestJet por $1 en gasolina y carga EV. Ideal para viajeros WestJet.", "fr": "Gagnez 2 dollars WestJet par dollar sur essence et recharge VÉ. Idéal pour voyageurs WestJet.", "ja": "ガスとEV充電で$1あたり2 WestJetドル。WestJetを利用する通勤者に最適。", "ko": "주유와 EV 충전에서 $1당 2 WestJet 달러. WestJet 이용 통근자에게 적합.", "zh": "加油和电动车充电每$1获2 WestJet元。适合经常乘坐WestJet的通勤者。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'INSURANCE', '{"en": "Comprehensive Travel Insurance", "es": "Seguro de viaje completo", "fr": "Assurance voyage complète", "ja": "総合旅行保険", "ko": "종합 여행 보험", "zh": "全面旅行保险"}', '{"en": "Includes travel medical, trip cancellation/interruption, baggage delay, flight delay, and car rental collision insurance.", "es": "Incluye seguro médico viaje, cancelación/interrupción, retraso equipaje/vuelo y colisión alquiler.", "fr": "Inclut assurance médicale voyage, annulation/interruption, retard bagages/vol et collision location.", "ja": "旅行医療、旅行キャンセル/中断、手荷物遅延、航空遅延、レンタカー衝突保険付き。", "ko": "여행 의료, 여행 취소/중단, 수하물 지연, 항공 지연, 렌터카 충돌 보험 포함.", "zh": "包含旅行医疗、行程取消/中断、行李延误、航班延误和租车碰撞保险。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'PERK', '{"en": "Companion Voucher from $119", "es": "Voucher acompañante $119", "fr": "Billet accompagnateur 119 $", "ja": "コンパニオンバウチャー$119〜", "ko": "동반자 바우처 $119부터", "zh": "同行券$119起"}', '{"en": "Welcome companion voucher for round-trip from $119. Annual voucher after $5,000 spend, or exchange for 30% off flights, $200 vacation credit, or 2 lounge passes.", "es": "Voucher acompañante ida/vuelta desde $119. Anual tras $5,000, o cambia por 30% descuento, $200 vacaciones o 2 pases de sala.", "fr": "Billet accompagnateur aller-retour dès 119 $. Annuel après 5 000 $, ou échangez pour 30 % rabais, 200 $ vacances ou 2 passes salon.", "ja": "往復$119〜の歓迎コンパニオンバウチャー。$5,000消費後に年次バウチャー、または30%割引、$200バケーション、ラウンジパス2回に交換。", "ko": "왕복 $119부터 웰컴 동반자 바우처. $5,000 지출 후 연간 바우처, 또는 30% 할인, $200 휴가 크레딧, 라운지 패스 2회로 교환.", "zh": "欢迎同行券往返$119起。年消费$5,000后获年度同行券，或换30%机票折扣、$200度假抵扣或2次贵宾厅。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'PERK', '{"en": "Free First Checked Bag", "es": "Primera maleta gratis", "fr": "Premier bagage gratuit", "ja": "最初の預け荷物無料", "ko": "첫 위탁 수하물 무료", "zh": "首件托运行李免费"}', '{"en": "Primary cardholder and up to 8 companions get free first checked bag on WestJet flights when booked with the card.", "es": "Titular principal y hasta 8 acompañantes obtienen primera maleta gratis en vuelos WestJet.", "fr": "Le titulaire principal et jusqu''à 8 accompagnateurs ont le premier bagage gratuit sur vols WestJet.", "ja": "主カード会員と最大8名の同行者はWestJet航空で最初の預け荷物無料。", "ko": "주카드 소유자와 최대 8명의 동반자는 WestJet 항공에서 첫 위탁 수하물 무료.", "zh": "主卡持卡人和最多8位同行者用此卡预订WestJet航班可享首件托运行李免费。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'REDEMPTION', '{"en": "Redeem on Any WestJet Seat", "es": "Canjea en cualquier asiento WestJet", "fr": "Échangez sur tout siège WestJet", "ja": "任意のWestJet座席に交換", "ko": "모든 WestJet 좌석에서 교환", "zh": "任意WestJet机位可兑换"}', '{"en": "Redeem WestJet dollars on any available seat, no blackout dates. 1 WestJet dollar = $1 toward flights.", "es": "Canjea dólares WestJet en cualquier asiento disponible, sin fechas bloqueadas. 1 dólar WestJet = $1 hacia vuelos.", "fr": "Échangez des dollars WestJet sur tout siège disponible, sans dates bloquées. 1 $ WestJet = 1 $ vers vols.", "ja": "WestJetドルは空席で交換可能、ブラックアウト日なし。1 WestJetドル = $1で航空券に。", "ko": "WestJet 달러로 가용 좌석 교환, 블랙아웃 날짜 없음. 1 WestJet 달러 = $1 항공권.", "zh": "WestJet元可兑换任意可用座位，无封锁日期。1 WestJet元 = $1机票抵扣。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'RBC' AND name = 'WestJet World Elite Mastercard'), 'STACKING', '{"en": "Good as Primary Card", "es": "Buena como tarjeta principal", "fr": "Bonne carte principale", "ja": "メインカードに適す", "ko": "주카드로 적합", "zh": "适合作主力卡"}', '{"en": "With 2x on groceries/gas/dining and 1.5x everywhere else, use as primary card if you fly WestJet regularly.", "es": "Con 2x en supermercado/gas/comida y 1.5x en todo, usa como tarjeta principal si vuelas WestJet.", "fr": "Avec 2x épicerie/essence/restos et 1,5x partout, utilisez comme carte principale si vous volez WestJet.", "ja": "食料品/ガス/外食2倍、他1.5倍で、WestJetを定期的に利用するならメインカードとして使用。", "ko": "식료품/주유/식사 2배, 기타 1.5배로 WestJet을 정기적으로 이용하면 주카드로 사용.", "zh": "超市/加油/餐饮2倍，其他1.5倍，如果经常乘坐WestJet可作为主力卡使用。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'AVOID', '{"en": "2.5% FX Fee on Foreign", "es": "2.5% comisión FX", "fr": "2,5 % frais sur devises", "ja": "外貨2.5%手数料", "ko": "외화 2.5% 수수료", "zh": "外币2.5%手续费"}', '{"en": "WARNING: 2.5% foreign transaction fee applies. With only 2% back on USD, you actually LOSE 0.5% on foreign purchases.", "es": "ADVERTENCIA: 2.5% comisión FX. Con solo 2% en USD, PIERDES 0.5% en compras extranjeras.", "fr": "ATTENTION : frais de change de 2,5 %. Avec seulement 2 % USD, vous PERDEZ 0,5 % sur achats étrangers.", "ja": "警告：2.5%の外貨手数料あり。USDで2%のみなので、外貨購入で実質0.5%損失。", "ko": "경고: 2.5% 외환 수수료 있음. USD에서 2%만 적립되어 외화 구매 시 실제로 0.5% 손실.", "zh": "警告：有2.5%外汇手续费。美元仅返2%，外币消费实际亏损0.5%。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'AVOID', '{"en": "Only 1% for Non-Customers", "es": "Solo 1% para no-clientes", "fr": "Seulement 1 % non-clients", "ja": "非顧客は1%のみ", "ko": "비고객은 1%만", "zh": "非客户仅1%"}', '{"en": "Non-Rogers customers only earn 1% on CAD purchases. This card is best for Rogers/Fido/Shaw customers.", "es": "No-clientes Rogers solo ganan 1% en compras CAD. Esta tarjeta es mejor para clientes Rogers/Fido/Shaw.", "fr": "Les non-clients Rogers ne gagnent que 1 % sur achats CAD. Carte idéale pour clients Rogers/Fido/Shaw.", "ja": "非Rogersユーザーはカナダドル購入で1%のみ。このカードはRogers/Fido/Shaw顧客に最適。", "ko": "비Rogers 고객은 CAD 구매에서 1%만 적립. 이 카드는 Rogers/Fido/Shaw 고객에게 최적.", "zh": "非Rogers客户加币消费仅获1%。此卡最适合Rogers/Fido/Shaw客户。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'BEST_USE', '{"en": "2% on USD Purchases", "es": "2% en compras USD", "fr": "2 % sur achats USD", "ja": "USD購入2%", "ko": "USD 구매 2%", "zh": "美元消费2%"}', '{"en": "Earn 2% cash back on US dollar purchases. Note: 2.5% FX fee applies, so net benefit is -0.5% on USD.", "es": "Gana 2% en compras en USD. Nota: hay 2.5% de comisión FX, beneficio neto -0.5% en USD.", "fr": "Gagnez 2 % sur les achats en USD. Note : frais de change de 2,5 %, donc bénéfice net de -0,5 % sur USD.", "ja": "USD購入で2%キャッシュバック。注意：2.5%の外貨手数料があり、実質-0.5%の損失。", "ko": "USD 구매에서 2% 캐시백. 참고: 2.5% 외환 수수료가 있어 순이익은 -0.5%.", "zh": "美元消费获2%返现。注意：有2.5%外汇手续费，实际美元消费净收益为-0.5%。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'BEST_USE', '{"en": "2% for Rogers Customers", "es": "2% para clientes Rogers", "fr": "2 % pour clients Rogers", "ja": "Rogersユーザー2%", "ko": "Rogers 고객 2%", "zh": "Rogers客户2%"}', '{"en": "Rogers/Fido/Shaw/Comwave customers earn 2% on ALL non-USD purchases. Must have eligible Rogers service.", "es": "Clientes Rogers/Fido/Shaw/Comwave ganan 2% en TODAS las compras no-USD. Requiere servicio Rogers elegible.", "fr": "Les clients Rogers/Fido/Shaw/Comwave gagnent 2 % sur TOUS les achats non-USD. Service Rogers éligible requis.", "ja": "Rogers/Fido/Shaw/Comwave顧客は全ての非USD購入で2%獲得。有効なRogersサービスが必要。", "ko": "Rogers/Fido/Shaw/Comwave 고객은 모든 비USD 구매에서 2% 적립. 자격 있는 Rogers 서비스 필요.", "zh": "Rogers/Fido/Shaw/Comwave客户所有非美元消费获2%。需持有合格Rogers服务。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'INSURANCE', '{"en": "No Travel Insurance", "es": "Sin seguro de viaje", "fr": "Pas d''assurance voyage", "ja": "旅行保険なし", "ko": "여행 보험 없음", "zh": "无旅行保险"}', '{"en": "No travel insurance included. Consider Red World Elite for travel medical, trip cancellation, and car rental coverage.", "es": "Sin seguro de viaje incluido. Considera Red World Elite para seguro médico, cancelación y alquiler.", "fr": "Pas d''assurance voyage incluse. Considérez Red World Elite pour assurance médicale, annulation et location.", "ja": "旅行保険なし。旅行医療、キャンセル、レンタカー保険が必要ならRed World Eliteを検討。", "ko": "여행 보험 미포함. 여행 의료, 취소, 렌터카 보장이 필요하면 Red World Elite 고려.", "zh": "不含旅行保险。如需旅行医疗、行程取消和租车保障，请考虑Red World Elite。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'PERK', '{"en": "1.5x Value on Rogers", "es": "1.5x valor en Rogers", "fr": "1,5x valeur chez Rogers", "ja": "Rogers交換で1.5倍価値", "ko": "Rogers 교환 시 1.5배 가치", "zh": "Rogers兑换1.5倍价值"}', '{"en": "Get 1.5x cash back value when you redeem on Rogers, Fido, Shaw, or Comwave purchases. $10 becomes $15.", "es": "Obtén 1.5x valor al canjear en Rogers, Fido, Shaw o Comwave. $10 se convierten en $15.", "fr": "Obtenez 1,5x la valeur en échangeant sur Rogers, Fido, Shaw ou Comwave. 10 $ deviennent 15 $.", "ja": "Rogers、Fido、Shaw、Comwaveで交換時に1.5倍の価値。$10が$15に。", "ko": "Rogers, Fido, Shaw, Comwave에서 교환 시 1.5배 가치. $10이 $15으로.", "zh": "在Rogers、Fido、Shaw或Comwave消费兑换时获1.5倍返现价值。$10变成$15。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee. Best value for Rogers/Fido/Shaw customers who want 2% on all spending.", "es": "Sin cuota anual. Mejor valor para clientes Rogers/Fido/Shaw que quieren 2% en todo.", "fr": "Sans frais annuels. Meilleure valeur pour clients Rogers/Fido/Shaw voulant 2 % partout.", "ja": "年会費無料。全消費2%が欲しいRogers/Fido/Shawユーザーに最適。", "ko": "연회비 무료. 모든 지출에서 2%를 원하는 Rogers/Fido/Shaw 고객에게 최고 가치.", "zh": "免年费。对于想要所有消费2%的Rogers/Fido/Shaw客户来说价值最高。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'PERK', '{"en": "5 Roam Like Home Days", "es": "5 días Roam Like Home", "fr": "5 jours Roam Like Home", "ja": "Roam Like Home 5日間", "ko": "Roam Like Home 5일", "zh": "5天Roam Like Home"}', '{"en": "Get 5 free Roam Like Home days per year with eligible Rogers mobile plan. Use your phone abroad without extra fees.", "es": "Obtén 5 días Roam Like Home gratis por año con plan móvil Rogers elegible.", "fr": "Obtenez 5 jours Roam Like Home gratuits par an avec forfait Rogers mobile éligible.", "ja": "対象のRogersモバイルプランで年間5日間の無料Roam Like Home。海外で追加料金なしで使用。", "ko": "자격 있는 Rogers 모바일 플랜으로 연간 5일 무료 Roam Like Home. 해외에서 추가 요금 없이 사용.", "zh": "持有合格Rogers手机计划每年获5天免费Roam Like Home。海外使用手机无额外费用。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'REDEMPTION', '{"en": "Minimum $10 Redemption", "es": "Mínimo $10 canje", "fr": "Minimum 10 $ échange", "ja": "最低$10交換", "ko": "최소 $10 교환", "zh": "最低$10兑换"}', '{"en": "Redeem starting at $10. Best value when redeeming on Rogers/Fido/Shaw bills for 1.5x value. Can also redeem on any purchase.", "es": "Canjea desde $10. Mejor valor en facturas Rogers/Fido/Shaw para 1.5x. También en cualquier compra.", "fr": "Échange dès 10 $. Meilleure valeur sur factures Rogers/Fido/Shaw pour 1,5x. Aussi sur tout achat.", "ja": "最低$10から交換。Rogers/Fido/Shaw請求書で1.5倍価値が最良。任意の購入にも交換可能。", "ko": "최소 $10부터 교환. Rogers/Fido/Shaw 청구서에서 1.5배 가치가 최고. 모든 구매에도 교환 가능.", "zh": "最低$10起兑换。在Rogers/Fido/Shaw账单兑换获1.5倍价值。也可抵扣任意消费。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red Mastercard'), 'STACKING', '{"en": "Consider Red World Elite", "es": "Considera Red World Elite", "fr": "Considérer Red World Elite", "ja": "Red World Elite検討", "ko": "Red World Elite 고려", "zh": "考虑Red World Elite"}', '{"en": "Red World Elite (no fee, $80K income) offers 1.5% on everything, 3% on Rogers/USD. Better for non-Rogers customers.", "es": "Red World Elite (gratis, ingreso $80K) ofrece 1.5% en todo, 3% Rogers/USD. Mejor para no-clientes.", "fr": "Red World Elite (gratuit, revenu 80 K$) offre 1,5 % partout, 3 % Rogers/USD. Mieux pour non-clients.", "ja": "Red World Elite（無料、収入$80K必要）は全て1.5%、Rogers/USD 3%。非Rogersユーザーに最適。", "ko": "Red World Elite (무료, 소득 $80K)는 전체 1.5%, Rogers/USD 3%. 비Rogers 고객에게 더 적합.", "zh": "Red World Elite（免年费，需$80K收入）所有消费1.5%，Rogers/美元3%。更适合非Rogers客户。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'AVOID', '{"en": "2.5% FX Fee Non-USD", "es": "2.5% comisión no-USD", "fr": "2,5 % frais non-USD", "ja": "非USD外貨2.5%手数料", "ko": "비USD 외화 2.5% 수수료", "zh": "非美元外币2.5%费"}', '{"en": "WARNING: 2.5% FX fee on non-CAD/non-USD currencies (EUR, GBP, etc). USD purchases have no FX fee. Use for USD travel only.", "es": "ADVERTENCIA: 2.5% en monedas no-CAD/USD (EUR, GBP, etc). Sin comisión en USD. Solo para viajes USD.", "fr": "ATTENTION : 2,5 % sur devises non-CAD/USD (EUR, GBP, etc). Pas de frais sur USD. Pour voyages USD uniquement.", "ja": "警告：非CAD/USD通貨（EUR、GBPなど）に2.5%手数料。USD購入は手数料なし。USD旅行のみ使用。", "ko": "경고: 비CAD/비USD 통화(EUR, GBP 등)에 2.5% 수수료. USD 구매는 수수료 없음. USD 여행에만 사용.", "zh": "警告：非加币/美元货币（欧元、英镑等）有2.5%外汇手续费。美元消费无手续费。仅限美元旅行使用。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'AVOID', '{"en": "$80K Income Required", "es": "Se requiere $80K", "fr": "Revenu 80 K$ requis", "ja": "収入$80K必要", "ko": "소득 $80K 필요", "zh": "需$80K收入"}', '{"en": "Requires $80,000 personal income or $150,000 household income. Consider Red Mastercard if you don''t qualify.", "es": "Requiere $80,000 ingreso personal o $150,000 familiar. Considera Red Mastercard si no calificas.", "fr": "Exige 80 000 $ revenu personnel ou 150 000 $ revenu familial. Considérez Red Mastercard si non éligible.", "ja": "個人収入$80,000または世帯収入$150,000が必要。資格がない場合はRed Mastercardを検討。", "ko": "개인 소득 $80,000 또는 가구 소득 $150,000 필요. 자격이 없으면 Red Mastercard 고려.", "zh": "需个人收入$80,000或家庭收入$150,000。不符合条件可考虑Red Mastercard。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'BEST_USE', '{"en": "3% on USD Purchases", "es": "3% en compras USD", "fr": "3 % sur achats USD", "ja": "USD購入3%", "ko": "USD 구매 3%", "zh": "美元消费3%"}', '{"en": "Earn 3% cash back on all US dollar purchases. Best rate for cross-border shopping and US travel.", "es": "Gana 3% en todas las compras en USD. Mejor tasa para compras transfronterizas y viajes a EE.UU.", "fr": "Gagnez 3 % sur tous les achats en USD. Meilleur taux pour achats transfrontaliers et voyages aux É.-U.", "ja": "全てのUSD購入で3%キャッシュバック。越境ショッピングと米国旅行に最適。", "ko": "모든 USD 구매에서 3% 캐시백. 국경 간 쇼핑과 미국 여행에 최적.", "zh": "所有美元消费获3%返现。跨境购物和美国旅行的最佳返现率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'BEST_USE', '{"en": "2% for Rogers Customers", "es": "2% para clientes Rogers", "fr": "2 % pour clients Rogers", "ja": "Rogersユーザー2%", "ko": "Rogers 고객 2%", "zh": "Rogers客户2%"}', '{"en": "Rogers/Fido/Shaw/Comwave customers earn 2% on ALL non-USD purchases. 0.5% more than non-customers.", "es": "Clientes Rogers/Fido/Shaw/Comwave ganan 2% en TODAS las compras no-USD. 0.5% más que no-clientes.", "fr": "Les clients Rogers/Fido/Shaw/Comwave gagnent 2 % sur TOUS les achats non-USD. 0,5 % de plus que non-clients.", "ja": "Rogers/Fido/Shaw/Comwave顧客は全ての非USD購入で2%獲得。非顧客より0.5%多い。", "ko": "Rogers/Fido/Shaw/Comwave 고객은 모든 비USD 구매에서 2% 적립. 비고객보다 0.5% 더.", "zh": "Rogers/Fido/Shaw/Comwave客户所有非美元消费获2%。比非客户多0.5%。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'INSURANCE', '{"en": "Travel Insurance Included", "es": "Seguro viaje incluido", "fr": "Assurance voyage incluse", "ja": "旅行保険付き", "ko": "여행 보험 포함", "zh": "含旅行保险"}', '{"en": "Includes emergency medical (10 days under 65), trip cancellation/interruption, and car rental collision insurance.", "es": "Incluye médico emergencia (10 días <65), cancelación/interrupción viaje y colisión alquiler.", "fr": "Inclut assurance médicale urgence (10 jours <65 ans), annulation/interruption voyage et collision location.", "ja": "緊急医療（65歳未満10日間）、旅行キャンセル/中断、レンタカー衝突保険付き。", "ko": "응급 의료(65세 미만 10일), 여행 취소/중단, 렌터카 충돌 보험 포함.", "zh": "包含紧急医疗（65岁以下10天）、行程取消/中断和租车碰撞保险。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'PERK', '{"en": "1.5x Value on Rogers", "es": "1.5x valor en Rogers", "fr": "1,5x valeur chez Rogers", "ja": "Rogers交換で1.5倍価値", "ko": "Rogers 교환 시 1.5배 가치", "zh": "Rogers兑换1.5倍价值"}', '{"en": "Get 1.5x cash back value when you redeem on Rogers, Fido, Shaw, or Comwave purchases. $100 becomes $150.", "es": "Obtén 1.5x valor al canjear en Rogers, Fido, Shaw o Comwave. $100 se convierten en $150.", "fr": "Obtenez 1,5x la valeur en échangeant sur Rogers, Fido, Shaw ou Comwave. 100 $ deviennent 150 $.", "ja": "Rogers、Fido、Shaw、Comwaveで交換時に1.5倍の価値。$100が$150に。", "ko": "Rogers, Fido, Shaw, Comwave에서 교환 시 1.5배 가치. $100이 $150으로.", "zh": "在Rogers、Fido、Shaw或Comwave消费兑换时获1.5倍返现价值。$100变成$150。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee for a World Elite card. Includes travel insurance, lounge access, and 3% USD earning.", "es": "Sin cuota anual para una tarjeta World Elite. Incluye seguro viaje, acceso a salas y 3% USD.", "fr": "Pas de frais annuels pour une carte World Elite. Inclut assurance voyage, salon et 3 % USD.", "ja": "World Eliteカードで年会費無料。旅行保険、ラウンジアクセス、3% USD獲得付き。", "ko": "World Elite 카드에 연회비 무료. 여행 보험, 라운지 이용권, 3% USD 적립 포함.", "zh": "世界精英卡免年费。包含旅行保险、贵宾厅会员和3%美元返现。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'PERK', '{"en": "5 Roam Like Home Days", "es": "5 días Roam Like Home", "fr": "5 jours Roam Like Home", "ja": "Roam Like Home 5日間", "ko": "Roam Like Home 5일", "zh": "5天Roam Like Home"}', '{"en": "Get 5 free Roam Like Home days per year (up to $90 value) with eligible Rogers mobile plan.", "es": "Obtén 5 días Roam Like Home gratis por año (hasta $90 valor) con plan móvil Rogers elegible.", "fr": "Obtenez 5 jours Roam Like Home gratuits par an (jusqu''à 90 $) avec forfait Rogers mobile éligible.", "ja": "対象のRogersモバイルプランで年間5日間の無料Roam Like Home（最大$90相当）。", "ko": "자격 있는 Rogers 모바일 플랜으로 연간 5일 무료 Roam Like Home (최대 $90 가치).", "zh": "持有合格Rogers手机计划每年获5天免费Roam Like Home（价值最高$90）。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'PERK', '{"en": "DragonPass Lounge Access", "es": "Acceso DragonPass", "fr": "Accès salon DragonPass", "ja": "DragonPassラウンジ", "ko": "DragonPass 라운지", "zh": "DragonPass贵宾厅"}', '{"en": "Complimentary Mastercard Travel Pass (DragonPass) membership. Access 1,300+ lounges for $32 USD per visit.", "es": "Membresía gratuita Mastercard Travel Pass (DragonPass). Acceso a 1,300+ salas por $32 USD por visita.", "fr": "Adhésion gratuite Mastercard Travel Pass (DragonPass). Accès à 1 300+ salons pour 32 $ USD par visite.", "ja": "無料でMastercard Travel Pass（DragonPass）会員資格。1,300以上のラウンジに$32 USDでアクセス。", "ko": "무료 Mastercard Travel Pass (DragonPass) 멤버십. 1,300+ 라운지에 방문당 $32 USD로 이용.", "zh": "免费获得Mastercard Travel Pass（DragonPass）会员资格。$32 USD/次进入1,300+贵宾厅。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Rogers' AND name = 'Red World Elite Mastercard'), 'REDEMPTION', '{"en": "Minimum $10 Redemption", "es": "Mínimo $10 canje", "fr": "Minimum 10 $ échange", "ja": "最低$10交換", "ko": "최소 $10 교환", "zh": "最低$10兑换"}', '{"en": "Redeem starting at $10. Best value when redeeming on Rogers/Fido/Shaw bills for 1.5x value. Can also redeem on any purchase.", "es": "Canjea desde $10. Mejor valor en facturas Rogers/Fido/Shaw para 1.5x. También en cualquier compra.", "fr": "Échange dès 10 $. Meilleure valeur sur factures Rogers/Fido/Shaw pour 1,5x. Aussi sur tout achat.", "ja": "最低$10から交換。Rogers/Fido/Shaw請求書で1.5倍価値が最良。任意の購入にも交換可能。", "ko": "최소 $10부터 교환. Rogers/Fido/Shaw 청구서에서 1.5배 가치가 최고. 모든 구매에도 교환 가능.", "zh": "最低$10起兑换。在Rogers/Fido/Shaw账单兑换获1.5倍价值。也可抵扣任意消费。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'AVOID', '{"en": "$50K Annual Spending Cap", "es": "Límite $50K/año", "fr": "Plafond 50 K$/an", "ja": "年間$5万上限", "ko": "연간 $5만 한도", "zh": "年消费$5万上限"}', '{"en": "Accelerated earning rates (3x-6x) only apply to first $50,000 in annual spending. After that, only 1x.", "es": "Tasas aceleradas (3x-6x) solo aplican a los primeros $50,000/año. Después, solo 1x.", "fr": "Les taux accélérés (3x-6x) ne s''appliquent qu''aux premiers 50 000 $/an. Ensuite, seulement 1x.", "ja": "加速レート（3x-6x）は年間$50,000までのみ。それ以降は1xのみ。", "ko": "가속 적립률(3x-6x)은 연간 $50,000까지만 적용. 이후 1배만.", "zh": "加速积分率（3-6倍）仅适用于年消费前$50,000。之后仅1倍。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'AVOID', '{"en": "Limited Amex Acceptance", "es": "Aceptación Amex limitada", "fr": "Acceptation Amex limitée", "ja": "Amex受入制限", "ko": "Amex 사용처 제한", "zh": "Amex接受度有限"}', '{"en": "American Express not accepted everywhere. Consider pairing with a Visa/Mastercard for backup.", "es": "American Express no aceptada en todos lados. Considera una Visa/Mastercard de respaldo.", "fr": "American Express pas acceptée partout. Considérez une Visa/Mastercard en complément.", "ja": "American Expressはどこでも使えるわけではない。Visa/Mastercardをバックアップに。", "ko": "American Express는 모든 곳에서 사용 불가. Visa/Mastercard 백업 권장.", "zh": "American Express并非所有商户都接受。建议搭配Visa/Mastercard作为备用。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'BEST_USE', '{"en": "6x at Sobeys Family", "es": "6x en Sobeys", "fr": "6x chez Sobeys", "ja": "Sobeys系列6倍", "ko": "Sobeys 계열 6배", "zh": "Sobeys系6倍积分"}', '{"en": "Earn 6x Scene+ points at Sobeys, Safeway, FreshCo, Foodland, and IGA locations. Best grocery rate in Canada.", "es": "Gana 6x puntos Scene+ en Sobeys, Safeway, FreshCo, Foodland e IGA. Mejor tasa de supermercado en Canadá.", "fr": "Gagnez 6x points Scene+ chez Sobeys, Safeway, FreshCo, Foodland et IGA. Meilleur taux épicerie au Canada.", "ja": "Sobeys、Safeway、FreshCo、Foodland、IGAで6倍Scene+ポイント。カナダ最高の食料品レート。", "ko": "Sobeys, Safeway, FreshCo, Foodland, IGA에서 6배 Scene+ 포인트. 캐나다 최고의 식료품 적립률.", "zh": "在Sobeys、Safeway、FreshCo、Foodland和IGA获6倍Scene+积分。加拿大最佳超市积分率。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'BEST_USE', '{"en": "5x Dining & Entertainment", "es": "5x restaurantes y entretenimiento", "fr": "5x restos et divertissement", "ja": "外食・エンタメ5倍", "ko": "식사 및 엔터테인먼트 5배", "zh": "餐饮娱乐5倍"}', '{"en": "Earn 5x Scene+ points on dining, food delivery, other grocers, and entertainment (movies, theatre).", "es": "Gana 5x puntos Scene+ en restaurantes, delivery, otros supermercados y entretenimiento (cine, teatro).", "fr": "Gagnez 5x points Scene+ sur restos, livraison, autres épiceries et divertissement (cinéma, théâtre).", "ja": "外食、フードデリバリー、他の食料品店、エンターテイメント（映画、劇場）で5倍Scene+ポイント。", "ko": "식사, 배달, 기타 식료품점, 엔터테인먼트(영화, 극장)에서 5배 Scene+ 포인트.", "zh": "餐饮、外卖、其他超市和娱乐（电影、剧院）获5倍Scene+积分。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'BEST_USE', '{"en": "3x Gas, Transit & Streaming", "es": "3x gasolina, transporte, streaming", "fr": "3x essence, transports, streaming", "ja": "ガス・交通・ストリーミング3倍", "ko": "주유, 대중교통, 스트리밍 3배", "zh": "加油/交通/流媒体3倍"}', '{"en": "Earn 3x Scene+ points on gas, public transit, rideshare (Uber/Lyft), and streaming services.", "es": "Gana 3x puntos Scene+ en gasolina, transporte público, rideshare (Uber/Lyft) y streaming.", "fr": "Gagnez 3x points Scene+ sur essence, transports, covoiturage (Uber/Lyft) et streaming.", "ja": "ガス、公共交通、ライドシェア（Uber/Lyft）、ストリーミングで3倍Scene+ポイント。", "ko": "주유, 대중교통, 라이드셰어(Uber/Lyft), 스트리밍에서 3배 Scene+ 포인트.", "zh": "加油、公共交通、网约车（Uber/Lyft）和流媒体服务获3倍Scene+积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'INSURANCE', '{"en": "Comprehensive Insurance", "es": "Seguro completo", "fr": "Assurance complète", "ja": "総合保険", "ko": "종합 보험", "zh": "全面保险保障"}', '{"en": "Travel medical ($1M/25 days), trip cancellation ($1,500), flight delay ($500), rental car, and purchase protection.", "es": "Médico viaje ($1M/25 días), cancelación ($1,500), retraso vuelo ($500), alquiler auto y protección compras.", "fr": "Médical voyage (1M $/25 jours), annulation (1 500 $), retard vol (500 $), location et protection achats.", "ja": "旅行医療（$100万/25日）、旅行キャンセル（$1,500）、航空遅延（$500）、レンタカー、購入保護。", "ko": "여행 의료($100만/25일), 여행 취소($1,500), 항공 지연($500), 렌터카, 구매 보호.", "zh": "旅行医疗（$100万/25天）、行程取消（$1,500）、航班延误（$500）、租车和购物保障。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'PERK', '{"en": "No Foreign Transaction Fee", "es": "Sin comisión FX", "fr": "Sans frais de change", "ja": "外貨手数料なし", "ko": "외환 수수료 없음", "zh": "无外汇手续费"}', '{"en": "No foreign transaction fees on purchases in any currency. Saves 2.5% compared to most cards. Great for travel.", "es": "Sin comisiones FX en cualquier moneda. Ahorra 2.5% vs otras tarjetas. Ideal para viajar.", "fr": "Pas de frais de change sur achats en devises. Économisez 2,5 % vs autres cartes. Idéal pour voyages.", "ja": "どの通貨でも外貨手数料なし。他のカードより2.5%節約。旅行に最適。", "ko": "모든 통화에서 외환 수수료 없음. 다른 카드 대비 2.5% 절약. 여행에 최적.", "zh": "任何货币消费均无外汇手续费。比大多数卡节省2.5%。非常适合旅行。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'PERK', '{"en": "First Year Fee Waived", "es": "Primer año gratis", "fr": "1re année gratuite", "ja": "初年度年会費無料", "ko": "첫해 연회비 면제", "zh": "首年免年费"}', '{"en": "$120 annual fee waived for first year. Can be waived ongoing with Scotia Ultimate Package account.", "es": "Cuota de $120 gratis el primer año. Puede eliminarse con cuenta Ultimate Package.", "fr": "Frais de 120 $ gratuits la 1re année. Peuvent être annulés avec compte Ultimate Package.", "ja": "初年度$120年会費無料。Ultimate Packageアカウントで継続的に無料可能。", "ko": "첫해 $120 연회비 면제. Ultimate Package 계좌로 계속 면제 가능.", "zh": "首年免$120年费。持有Scotia Ultimate Package账户可持续免年费。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'PERK', '{"en": "Priority Pass Access", "es": "Acceso Priority Pass", "fr": "Accès Priority Pass", "ja": "Priority Passアクセス", "ko": "Priority Pass 이용", "zh": "Priority Pass贵宾厅"}', '{"en": "Discounted Priority Pass membership for access to 1,200+ airport lounges worldwide.", "es": "Membresía Priority Pass con descuento para 1,200+ salas de aeropuerto en el mundo.", "fr": "Adhésion Priority Pass à prix réduit pour 1 200+ salons d''aéroport dans le monde.", "ja": "世界1,200以上の空港ラウンジにアクセスできる割引Priority Pass会員資格。", "ko": "전 세계 1,200+ 공항 라운지 이용 가능한 할인 Priority Pass 멤버십.", "zh": "可享折扣价Priority Pass会员资格，进入全球1,200+机场贵宾厅。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'PERK', '{"en": "Mobile Device Insurance", "es": "Seguro de móvil", "fr": "Assurance mobile", "ja": "モバイル保険", "ko": "모바일 기기 보험", "zh": "手机保险"}', '{"en": "Up to $1,000 mobile device insurance coverage. Pay your phone bill with this card to activate.", "es": "Hasta $1,000 de seguro de móvil. Paga tu factura de teléfono con esta tarjeta para activar.", "fr": "Jusqu''à 1 000 $ d''assurance mobile. Payez votre facture téléphone avec cette carte pour activer.", "ja": "最大$1,000のモバイル保険。この カードで携帯料金を支払うと有効化。", "ko": "최대 $1,000 모바일 기기 보험. 이 카드로 휴대폰 요금을 결제하면 활성화.", "zh": "最高$1,000手机保险。使用此卡支付手机账单即可激活。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Gold American Express'), 'REDEMPTION', '{"en": "Scene+ Flexibility", "es": "Flexibilidad Scene+", "fr": "Flexibilité Scene+", "ja": "Scene+柔軟性", "ko": "Scene+ 유연성", "zh": "Scene+灵活兑换"}', '{"en": "Redeem Scene+ points for travel, movies, groceries at Sobeys, or statement credits. 1,000 pts = $10.", "es": "Canjea puntos Scene+ por viajes, cine, supermercado Sobeys o créditos. 1,000 pts = $10.", "fr": "Échangez les points Scene+ pour voyages, cinéma, épicerie Sobeys ou crédits. 1 000 pts = 10 $.", "ja": "Scene+ポイントを旅行、映画、Sobeysでの食料品、明細クレジットに交換。1,000ポイント = $10。", "ko": "Scene+ 포인트를 여행, 영화, Sobeys 식료품, 명세서 크레딧으로 교환. 1,000 포인트 = $10.", "zh": "Scene+积分可兑换旅行、电影、Sobeys超市消费或账单抵扣。1,000积分 = $10。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'AVOID', '{"en": "$25K Cap per Category", "es": "Límite $25K por categoría", "fr": "Plafond 25 K$ par catégorie", "ja": "カテゴリ別$2.5万上限", "ko": "카테고리당 $2.5만 한도", "zh": "各类别$2.5万上限"}', '{"en": "Accelerated rates (4%/2%) capped at $25,000/year per category. After cap, earns 1% on all purchases.", "es": "Tasas aceleradas (4%/2%) limitadas a $25,000/año por categoría. Después, 1% en todo.", "fr": "Taux accélérés (4 %/2 %) plafonnés à 25 000 $/an par catégorie. Après, 1 % sur tout.", "ja": "加速レート（4%/2%）はカテゴリ別に年間$25,000まで。超過後は全て1%。", "ko": "가속 적립률(4%/2%)은 카테고리당 연간 $25,000까지. 초과 후 전체 1%.", "zh": "加速返现率（4%/2%）各类别年消费$25,000封顶。超过后所有消费返1%。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'AVOID', '{"en": "Has Foreign Transaction Fee", "es": "Tiene comisión FX", "fr": "Frais de change", "ja": "外貨手数料あり", "ko": "외환 수수료 있음", "zh": "有外汇手续费"}', '{"en": "Standard 2.5% foreign transaction fee applies. Use Scotia Gold Amex for no-FX-fee foreign purchases.", "es": "Comisión FX estándar de 2.5%. Usa Scotia Gold Amex para compras extranjeras sin comisión.", "fr": "Frais de change standard de 2,5 %. Utilisez Scotia Gold Amex pour achats étrangers sans frais.", "ja": "標準2.5%外貨手数料あり。海外購入にはScotia Gold Amex（手数料なし）を使用。", "ko": "표준 2.5% 외환 수수료 있음. 해외 구매에는 Scotia Gold Amex(수수료 없음) 사용 권장.", "zh": "有标准2.5%外汇手续费。外币消费建议使用Scotia Gold Amex（无手续费）。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'BEST_USE', '{"en": "4% on Groceries", "es": "4% en supermercados", "fr": "4 % sur épicerie", "ja": "食料品4%", "ko": "식료품 4%", "zh": "超市4%返现"}', '{"en": "Earn 4% cash back on grocery purchases up to $25,000/year. One of the best grocery rates in Canada.", "es": "Gana 4% en supermercados hasta $25,000/año. Una de las mejores tasas de supermercado en Canadá.", "fr": "Gagnez 4 % sur épicerie jusqu''à 25 000 $/an. L''un des meilleurs taux épicerie au Canada.", "ja": "食料品で4%キャッシュバック、年間$25,000まで。カナダ最高の食料品レートの一つ。", "ko": "식료품에서 4% 캐시백, 연간 $25,000까지. 캐나다 최고의 식료품 적립률 중 하나.", "zh": "超市消费4%返现，年消费$25,000封顶。加拿大最佳超市返现率之一。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'BEST_USE', '{"en": "4% on Recurring Bills", "es": "4% en facturas recurrentes", "fr": "4 % sur factures récurrentes", "ja": "定期支払い4%", "ko": "정기 청구서 4%", "zh": "定期账单4%返现"}', '{"en": "Earn 4% on recurring bills: phone, internet, streaming, insurance, subscriptions. Up to $25,000/year.", "es": "Gana 4% en facturas recurrentes: teléfono, internet, streaming, seguro. Hasta $25,000/año.", "fr": "Gagnez 4 % sur factures récurrentes : téléphone, internet, streaming, assurance. Jusqu''à 25 000 $/an.", "ja": "定期支払いで4%：電話、インターネット、ストリーミング、保険、サブスク。年間$25,000まで。", "ko": "정기 청구서 4%: 전화, 인터넷, 스트리밍, 보험, 구독. 연간 $25,000까지.", "zh": "定期账单4%返现：手机、网络、流媒体、保险、订阅。年消费$25,000封顶。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'BEST_USE', '{"en": "2% on Gas & Transit", "es": "2% en gasolina y transporte", "fr": "2 % sur essence et transports", "ja": "ガス・交通2%", "ko": "주유 및 교통 2%", "zh": "加油/交通2%返现"}', '{"en": "Earn 2% cash back on gas, EV charging, public transit, and rideshare. Up to $25,000/year.", "es": "Gana 2% en gasolina, carga EV, transporte público y rideshare. Hasta $25,000/año.", "fr": "Gagnez 2 % sur essence, recharge VÉ, transports et covoiturage. Jusqu''à 25 000 $/an.", "ja": "ガス、EV充電、公共交通、ライドシェアで2%。年間$25,000まで。", "ko": "주유, EV 충전, 대중교통, 라이드셰어에서 2%. 연간 $25,000까지.", "zh": "加油、电动车充电、公共交通和网约车2%返现。年消费$25,000封顶。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'INSURANCE', '{"en": "Comprehensive Insurance", "es": "Seguro completo", "fr": "Assurance complète", "ja": "総合保険", "ko": "종합 보험", "zh": "全面保险保障"}', '{"en": "Travel medical ($1M/15 days), trip cancellation ($2,000), flight delay ($500), rental car, and purchase protection.", "es": "Médico viaje ($1M/15 días), cancelación ($2,000), retraso vuelo ($500), alquiler auto y protección compras.", "fr": "Médical voyage (1M $/15 jours), annulation (2 000 $), retard vol (500 $), location et protection achats.", "ja": "旅行医療（$100万/15日）、旅行キャンセル（$2,000）、航空遅延（$500）、レンタカー、購入保護。", "ko": "여행 의료($100만/15일), 여행 취소($2,000), 항공 지연($500), 렌터카, 구매 보호.", "zh": "旅行医疗（$100万/15天）、行程取消（$2,000）、航班延误（$500）、租车和购物保障。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'PERK', '{"en": "First Year Fee Waived", "es": "Primer año gratis", "fr": "1re année gratuite", "ja": "初年度年会費無料", "ko": "첫해 연회비 면제", "zh": "首年免年费"}', '{"en": "$120 annual fee waived for first year. Can be waived ongoing with Scotia Ultimate Package account.", "es": "Cuota de $120 gratis el primer año. Puede eliminarse con cuenta Ultimate Package.", "fr": "Frais de 120 $ gratuits la 1re année. Peuvent être annulés avec compte Ultimate Package.", "ja": "初年度$120年会費無料。Ultimate Packageアカウントで継続的に無料可能。", "ko": "첫해 $120 연회비 면제. Ultimate Package 계좌로 계속 면제 가능.", "zh": "首年免$120年费。持有Scotia Ultimate Package账户可持续免年费。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'PERK', '{"en": "Mobile Device Insurance", "es": "Seguro de móvil", "fr": "Assurance mobile", "ja": "モバイル保険", "ko": "모바일 기기 보험", "zh": "手机保险"}', '{"en": "Up to $1,000 mobile device insurance. Purchase device with card or pay phone bill to activate coverage.", "es": "Hasta $1,000 seguro de móvil. Compra el dispositivo o paga tu factura con esta tarjeta.", "fr": "Jusqu''à 1 000 $ assurance mobile. Achetez l''appareil ou payez votre facture téléphone avec la carte.", "ja": "最大$1,000のモバイル保険。カードで購入するか携帯料金を支払うと有効化。", "ko": "최대 $1,000 모바일 기기 보험. 카드로 기기 구매 또는 휴대폰 요금 결제 시 활성화.", "zh": "最高$1,000手机保险。用此卡购买设备或支付手机账单即可激活。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'PERK', '{"en": "Visa Infinite Benefits", "es": "Beneficios Visa Infinite", "fr": "Avantages Visa Infinite", "ja": "Visa Infinite特典", "ko": "Visa Infinite 혜택", "zh": "Visa Infinite权益"}', '{"en": "24/7 concierge, Visa Infinite Hotel Collection (upgrades, free Wi-Fi), up to 25% off AVIS/Budget car rentals.", "es": "Concierge 24/7, Colección hoteles Visa Infinite (upgrades, Wi-Fi gratis), hasta 25% descuento AVIS/Budget.", "fr": "Concierge 24/7, Collection hôtels Visa Infinite (surclassements, Wi-Fi gratuit), jusqu''à 25 % rabais AVIS/Budget.", "ja": "24時間コンシェルジュ、Visa Infiniteホテル特典（アップグレード、無料Wi-Fi）、AVIS/Budget最大25%オフ。", "ko": "24시간 컨시어지, Visa Infinite 호텔 컬렉션(업그레이드, 무료 Wi-Fi), AVIS/Budget 최대 25% 할인.", "zh": "24/7礼宾服务、Visa Infinite酒店特权（升级、免费WiFi）、AVIS/Budget租车最高75折。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'REDEMPTION', '{"en": "Flexible Cash Back", "es": "Cashback flexible", "fr": "Remise flexible", "ja": "柔軟なキャッシュバック", "ko": "유연한 캐시백", "zh": "灵活返现兑换"}', '{"en": "Redeem cash back as statement credit, direct deposit, or apply to purchases. No minimum redemption.", "es": "Canjea como crédito en estado de cuenta, depósito directo o en compras. Sin mínimo.", "fr": "Échangez en crédit sur relevé, dépôt direct ou sur achats. Pas de minimum d''échange.", "ja": "明細クレジット、直接入金、購入に適用で交換。最低交換なし。", "ko": "명세서 크레딧, 직접 입금, 구매 적용으로 교환. 최소 교환 없음.", "zh": "返现可兑换为账单抵扣、直接存款或抵扣消费。无最低兑换门槛。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Momentum Visa Infinite'), 'STACKING', '{"en": "Pair with Scotia Gold Amex", "es": "Combina con Scotia Gold Amex", "fr": "Combiner avec Scotia Gold Amex", "ja": "Scotia Gold Amexと併用", "ko": "Scotia Gold Amex와 병행", "zh": "搭配Scotia Gold Amex"}', '{"en": "Use Momentum for groceries/bills (4%), Scotia Gold Amex for dining/travel (5x, no FX fee). Best of both worlds.", "es": "Momentum para supermercado/facturas (4%), Scotia Gold Amex para restaurantes/viajes (5x, sin FX).", "fr": "Momentum pour épicerie/factures (4 %), Scotia Gold Amex pour restos/voyages (5x, sans frais FX).", "ja": "Momentumは食料品/請求書（4%）、Scotia Gold Amexは外食/旅行（5x、FX手数料なし）に。", "ko": "Momentum은 식료품/청구서(4%), Scotia Gold Amex는 식사/여행(5x, FX 수수료 없음)에 사용.", "zh": "Momentum用于超市/账单（4%），Scotia Gold Amex用于餐饮/旅行（5倍，无外汇费）。两全其美。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'AVOID', '{"en": "$50K Accelerated Cap", "es": "Límite acelerado $50K", "fr": "Plafond accéléré 50 K$", "ja": "加速上限$5万", "ko": "가속 한도 $5만", "zh": "加速积分$5万上限"}', '{"en": "2x-3x earning rates capped at $50,000 annual spend. After that, earns 1x on all purchases.", "es": "Tasas 2x-3x limitadas a $50,000/año. Después, 1x en todas las compras.", "fr": "Taux 2x-3x plafonnés à 50 000 $/an. Ensuite, 1x sur tous les achats.", "ja": "2x-3xレートは年間$50,000まで。超過後は全て1x。", "ko": "2x-3x 적립률은 연간 $50,000까지. 초과 후 전체 1배.", "zh": "2-3倍积分率年消费$50,000封顶。超过后所有消费仅1倍。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'BEST_USE', '{"en": "No Foreign Transaction Fee", "es": "Sin comisión FX", "fr": "Sans frais de change", "ja": "外貨手数料なし", "ko": "외환 수수료 없음", "zh": "无外汇手续费"}', '{"en": "No FX fees on purchases in any currency. Saves 2.5% compared to most cards. Ideal travel card.", "es": "Sin comisiones FX en cualquier moneda. Ahorra 2.5% vs otras tarjetas. Tarjeta de viaje ideal.", "fr": "Pas de frais de change sur achats en devises. Économisez 2,5 % vs autres cartes. Carte voyage idéale.", "ja": "どの通貨でも外貨手数料なし。他のカードより2.5%節約。理想的な旅行カード。", "ko": "모든 통화에서 외환 수수료 없음. 다른 카드 대비 2.5% 절약. 이상적인 여행 카드.", "zh": "任何货币消费均无外汇手续费。比大多数卡节省2.5%。理想的旅行卡。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'BEST_USE', '{"en": "3x at Sobeys Family", "es": "3x en Sobeys", "fr": "3x chez Sobeys", "ja": "Sobeys系列3倍", "ko": "Sobeys 계열 3배", "zh": "Sobeys系3倍积分"}', '{"en": "Earn 3x Scene+ points at Sobeys, Safeway, IGA, Foodland, and participating co-ops.", "es": "Gana 3x puntos Scene+ en Sobeys, Safeway, IGA, Foodland y cooperativas participantes.", "fr": "Gagnez 3x points Scene+ chez Sobeys, Safeway, IGA, Foodland et coopératives participantes.", "ja": "Sobeys、Safeway、IGA、Foodland、参加コープで3倍Scene+ポイント。", "ko": "Sobeys, Safeway, IGA, Foodland 및 참여 협동조합에서 3배 Scene+ 포인트.", "zh": "在Sobeys、Safeway、IGA、Foodland及合作社获3倍Scene+积分。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'BEST_USE', '{"en": "2x Dining & Entertainment", "es": "2x restaurantes y entretenimiento", "fr": "2x restos et divertissement", "ja": "外食・エンタメ2倍", "ko": "식사 및 엔터테인먼트 2배", "zh": "餐饮娱乐2倍"}', '{"en": "Earn 2x Scene+ points on dining, other groceries, entertainment, and transit purchases.", "es": "Gana 2x puntos Scene+ en restaurantes, otros supermercados, entretenimiento y transporte.", "fr": "Gagnez 2x points Scene+ sur restos, autres épiceries, divertissement et transports.", "ja": "外食、他の食料品店、エンターテイメント、交通機関で2倍Scene+ポイント。", "ko": "식사, 기타 식료품점, 엔터테인먼트, 교통에서 2배 Scene+ 포인트.", "zh": "餐饮、其他超市、娱乐和交通消费获2倍Scene+积分。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'INSURANCE', '{"en": "Top-Tier Travel Insurance", "es": "Seguro viaje premium", "fr": "Assurance voyage premium", "ja": "最高級旅行保険", "ko": "최고급 여행 보험", "zh": "顶级旅行保险"}', '{"en": "Emergency medical ($2M), trip cancellation ($1,500), interruption ($2,500), flight delay ($500), rental car, baggage.", "es": "Médico emergencia ($2M), cancelación ($1,500), interrupción ($2,500), retraso vuelo ($500), alquiler, equipaje.", "fr": "Médical urgence (2 M$), annulation (1 500 $), interruption (2 500 $), retard vol (500 $), location, bagages.", "ja": "緊急医療（$200万）、キャンセル（$1,500）、中断（$2,500）、航空遅延（$500）、レンタカー、手荷物。", "ko": "응급 의료($200만), 취소($1,500), 중단($2,500), 항공 지연($500), 렌터카, 수하물.", "zh": "紧急医疗（$200万）、行程取消（$1,500）、中断（$2,500）、航班延误（$500）、租车、行李。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'PERK', '{"en": "6 Free Lounge Visits/Year", "es": "6 visitas a sala gratis/año", "fr": "6 accès salon gratuits/an", "ja": "年間6回無料ラウンジ", "ko": "연간 6회 무료 라운지", "zh": "每年6次免费贵宾厅"}', '{"en": "Access 1,200+ airport lounges worldwide with 6 complimentary visits per year. Great for frequent travelers.", "es": "Acceso a 1,200+ salas de aeropuerto con 6 visitas gratis al año. Ideal para viajeros frecuentes.", "fr": "Accès à 1 200+ salons d''aéroport avec 6 visites gratuites par an. Idéal pour voyageurs fréquents.", "ja": "世界1,200以上の空港ラウンジに年間6回無料アクセス。頻繁な旅行者に最適。", "ko": "전 세계 1,200+ 공항 라운지에 연간 6회 무료 입장. 잦은 여행자에게 최적.", "zh": "全球1,200+机场贵宾厅，每年6次免费入场。非常适合常旅客。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'PERK', '{"en": "$2M Emergency Medical", "es": "$2M médico emergencia", "fr": "2 M$ médical urgence", "ja": "$200万緊急医療", "ko": "$200만 응급 의료", "zh": "$200万紧急医疗"}', '{"en": "Industry-leading $2 million emergency medical coverage. One of the highest in Canadian travel cards.", "es": "Cobertura médica de emergencia de $2M líder en la industria. Una de las más altas en Canadá.", "fr": "Couverture médicale d''urgence de 2 M$ parmi les meilleures. L''une des plus élevées au Canada.", "ja": "業界トップの$200万緊急医療保障。カナダの旅行カードで最高水準。", "ko": "업계 최고 $200만 응급 의료 보장. 캐나다 여행 카드 중 최고 수준.", "zh": "业内领先的$200万紧急医疗保障。加拿大旅行卡中最高之一。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'PERK', '{"en": "Luxury Hotel Collection", "es": "Colección hoteles lujo", "fr": "Collection hôtels luxe", "ja": "ラグジュアリーホテル", "ko": "럭셔리 호텔 컬렉션", "zh": "豪华酒店特权"}', '{"en": "Access Visa Infinite Luxury Hotel Collection: 900+ properties with upgrades, breakfast, credits, and Wi-Fi.", "es": "Acceso a Colección Hoteles de Lujo Visa Infinite: 900+ propiedades con upgrades, desayuno, créditos.", "fr": "Accès à la Collection Hôtels de Luxe Visa Infinite : 900+ hôtels avec surclassements, déjeuner, crédits.", "ja": "Visa Infiniteラグジュアリーホテルコレクション：900以上のホテルでアップグレード、朝食、クレジット付き。", "ko": "Visa Infinite 럭셔리 호텔 컬렉션: 900+ 호텔에서 업그레이드, 조식, 크레딧, Wi-Fi.", "zh": "Visa Infinite豪华酒店系列：900+酒店享升级、早餐、积分和WiFi。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'PERK', '{"en": "10K Annual Spend Bonus", "es": "Bono 10K gasto anual", "fr": "Bonus 10K dépenses annuelles", "ja": "年間ボーナス1万ポイント", "ko": "연간 지출 보너스 1만", "zh": "年消费$4万奖励1万分"}', '{"en": "Earn 10,000 bonus Scene+ points each year you spend $40,000 or more. Ongoing benefit beyond welcome bonus.", "es": "Gana 10,000 pts Scene+ bonus cada año que gastes $40,000+. Beneficio continuo.", "fr": "Gagnez 10 000 pts Scene+ bonus chaque année où vous dépensez 40 000 $+. Avantage continu.", "ja": "年間$40,000以上利用で毎年10,000 Scene+ポイントボーナス。継続的な特典。", "ko": "연간 $40,000 이상 사용 시 매년 10,000 Scene+ 포인트 보너스. 지속적인 혜택.", "zh": "每年消费$40,000及以上可获10,000 Scene+积分奖励。欢迎奖励之外的持续福利。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'REDEMPTION', '{"en": "Scene+ Travel Portal", "es": "Portal viajes Scene+", "fr": "Portail voyage Scene+", "ja": "Scene+トラベル", "ko": "Scene+ 트래블 포털", "zh": "Scene+旅行门户"}', '{"en": "Book through Scene+ Travel for 3 pts/$1 on hotels and car rentals. Redeem points for travel, groceries, or credits.", "es": "Reserva por Scene+ Travel para 3 pts/$1 en hoteles y autos. Canjea por viajes, supermercado o créditos.", "fr": "Réservez via Scene+ Travel pour 3 pts/1 $ sur hôtels et voitures. Échangez pour voyages, épicerie ou crédits.", "ja": "Scene+ Travelでホテル・レンタカー予約で$1あたり3ポイント。旅行、食料品、クレジットに交換。", "ko": "Scene+ Travel로 호텔/렌터카 예약 시 $1당 3포인트. 여행, 식료품, 크레딧으로 교환.", "zh": "通过Scene+ Travel预订酒店和租车可获$1/3积分。积分可兑换旅行、超市消费或账单抵扣。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Passport Visa Infinite'), 'STACKING', '{"en": "Pair with Scotia Gold Amex", "es": "Combina con Scotia Gold Amex", "fr": "Combiner avec Scotia Gold Amex", "ja": "Scotia Gold Amexと併用", "ko": "Scotia Gold Amex와 병행", "zh": "搭配Scotia Gold Amex"}', '{"en": "Use Passport for travel (no FX fee) and Scotia Gold Amex for dining/entertainment (5x). Both earn Scene+ points.", "es": "Passport para viajes (sin FX), Scotia Gold Amex para restaurantes/entretenimiento (5x). Ambas ganan Scene+.", "fr": "Passport pour voyages (sans FX), Scotia Gold Amex pour restos/divertissement (5x). Les deux gagnent Scene+.", "ja": "Passportは旅行（FX手数料なし）、Scotia Gold Amexは外食/エンタメ（5x）に。両方Scene+ポイント獲得。", "ko": "Passport는 여행(FX 수수료 없음), Scotia Gold Amex는 식사/엔터테인먼트(5x)에 사용. 둘 다 Scene+ 포인트 적립.", "zh": "Passport用于旅行（无外汇费），Scotia Gold Amex用于餐饮娱乐（5倍）。两者都积累Scene+积分。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'AVOID', '{"en": "Has Foreign Transaction Fee", "es": "Tiene comisión FX", "fr": "Frais de change", "ja": "外貨手数料あり", "ko": "외환 수수료 있음", "zh": "有外汇手续费"}', '{"en": "Standard 2.5% foreign transaction fee applies. Use Scotia Passport for no-FX-fee travel spending.", "es": "Comisión FX estándar de 2.5%. Usa Scotia Passport para viajes sin comisión.", "fr": "Frais de change standard de 2,5 %. Utilisez Scotia Passport pour voyages sans frais.", "ja": "標準2.5%外貨手数料あり。海外はScotia Passport（手数料なし）を使用。", "ko": "표준 2.5% 외환 수수료 있음. 해외 결제에는 Scotia Passport(수수료 없음) 사용 권장.", "zh": "有标准2.5%外汇手续费。旅行消费建议使用Scotia Passport（无手续费）。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'AVOID', '{"en": "Only 1x on Most Purchases", "es": "Solo 1x en mayoría", "fr": "Seulement 1x sur la plupart", "ja": "ほとんど1倍のみ", "ko": "대부분 구매 1배만", "zh": "大部分消费仅1倍"}', '{"en": "Only earns 1x on purchases outside bonus categories. Consider Gold Amex for 5x dining/entertainment.", "es": "Solo 1x fuera de categorías bonus. Considera Gold Amex para 5x restaurantes/entretenimiento.", "fr": "Seulement 1x hors catégories bonus. Considérez Gold Amex pour 5x restos/divertissement.", "ja": "ボーナスカテゴリ外は1倍のみ。外食/エンタメにはGold Amex（5倍）を検討。", "ko": "보너스 카테고리 외 구매는 1배만. 식사/엔터테인먼트에는 Gold Amex(5배) 고려.", "zh": "奖励类别以外的消费仅获1倍积分。餐饮娱乐建议使用Gold Amex（5倍）。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'BEST_USE', '{"en": "2x at Sobeys Family", "es": "2x en Sobeys", "fr": "2x chez Sobeys", "ja": "Sobeys系列2倍", "ko": "Sobeys 계열 2배", "zh": "Sobeys系2倍积分"}', '{"en": "Earn 2x Scene+ points at Sobeys, Safeway, IGA, Foodland, and participating co-ops.", "es": "Gana 2x puntos Scene+ en Sobeys, Safeway, IGA, Foodland y cooperativas participantes.", "fr": "Gagnez 2x points Scene+ chez Sobeys, Safeway, IGA, Foodland et coopératives participantes.", "ja": "Sobeys、Safeway、IGA、Foodland、参加コープで2倍Scene+ポイント。", "ko": "Sobeys, Safeway, IGA, Foodland 및 참여 협동조합에서 2배 Scene+ 포인트.", "zh": "在Sobeys、Safeway、IGA、Foodland及合作社获2倍Scene+积分。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'BEST_USE', '{"en": "2x at Cineplex", "es": "2x en Cineplex", "fr": "2x chez Cineplex", "ja": "Cineplex 2倍", "ko": "Cineplex 2배", "zh": "Cineplex 2倍积分"}', '{"en": "Earn 2x Scene+ points at Cineplex theatres and cineplex.com. Perfect for movie lovers.", "es": "Gana 2x puntos Scene+ en Cineplex y cineplex.com. Perfecto para amantes del cine.", "fr": "Gagnez 2x points Scene+ chez Cineplex et cineplex.com. Parfait pour les cinéphiles.", "ja": "Cineplex映画館とcineplex.comで2倍Scene+ポイント。映画好きに最適。", "ko": "Cineplex 극장과 cineplex.com에서 2배 Scene+ 포인트. 영화 애호가에게 완벽.", "zh": "在Cineplex影院和cineplex.com获2倍Scene+积分。电影爱好者的完美选择。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'BEST_USE', '{"en": "2x at Home Hardware", "es": "2x en Home Hardware", "fr": "2x chez Home Hardware", "ja": "Home Hardware 2倍", "ko": "Home Hardware 2배", "zh": "Home Hardware 2倍积分"}', '{"en": "Earn 2x Scene+ points at Home Hardware locations and online. Great for DIY projects.", "es": "Gana 2x puntos Scene+ en Home Hardware en tienda y online. Ideal para proyectos DIY.", "fr": "Gagnez 2x points Scene+ chez Home Hardware en magasin et en ligne. Idéal pour projets DIY.", "ja": "Home Hardwareの店舗とオンラインで2倍Scene+ポイント。DIYプロジェクトに最適。", "ko": "Home Hardware 매장과 온라인에서 2배 Scene+ 포인트. DIY 프로젝트에 적합.", "zh": "在Home Hardware门店和网上购物获2倍Scene+积分。适合DIY项目。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee for primary or supplementary cards. Great entry-level Scene+ card.", "es": "Sin cuota anual para tarjetas principales o suplementarias. Excelente tarjeta Scene+ de entrada.", "fr": "Pas de frais pour carte principale ou supplémentaire. Excellente carte Scene+ d''entrée.", "ja": "主カード・追加カードともに年会費無料。Scene+入門に最適。", "ko": "기본 카드와 추가 카드 모두 연회비 무료. 훌륭한 입문용 Scene+ 카드.", "zh": "主卡和附属卡均免年费。优秀的入门级Scene+卡。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'PERK', '{"en": "4x via Scene+ Travel", "es": "4x vía Scene+ Travel", "fr": "4x via Scene+ Travel", "ja": "Scene+ Travel 4倍", "ko": "Scene+ Travel 4배", "zh": "Scene+ Travel 4倍积分"}', '{"en": "Earn 4x total (1x base + 3x bonus) on hotels and car rentals booked through Scene+ Travel portal.", "es": "Gana 4x total (1x base + 3x bonus) en hoteles y autos vía portal Scene+ Travel.", "fr": "Gagnez 4x total (1x base + 3x bonus) sur hôtels et voitures via portail Scene+ Travel.", "ja": "Scene+ Travelでホテル・レンタカー予約で合計4倍（1倍基本 + 3倍ボーナス）。", "ko": "Scene+ Travel 포털에서 호텔/렌터카 예약 시 총 4배 (1배 기본 + 3배 보너스).", "zh": "通过Scene+ Travel预订酒店和租车共获4倍积分（1倍基础 + 3倍奖励）。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'PERK', '{"en": "25% Off Car Rentals", "es": "25% descuento alquiler", "fr": "25 % rabais location", "ja": "レンタカー25%オフ", "ko": "렌터카 25% 할인", "zh": "租车75折"}', '{"en": "Up to 25% savings on Avis and Budget car rentals in Canada and the US.", "es": "Hasta 25% de ahorro en Avis y Budget en Canadá y EE.UU.", "fr": "Jusqu''à 25 % d''économies sur Avis et Budget au Canada et aux É.-U.", "ja": "カナダと米国のAvis・Budgetレンタカーで最大25%節約。", "ko": "캐나다와 미국의 Avis 및 Budget 렌터카에서 최대 25% 할인.", "zh": "在加拿大和美国Avis和Budget租车最高节省25%。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'REDEMPTION', '{"en": "Scene+ Flexibility", "es": "Flexibilidad Scene+", "fr": "Flexibilité Scene+", "ja": "Scene+柔軟性", "ko": "Scene+ 유연성", "zh": "Scene+灵活兑换"}', '{"en": "Redeem Scene+ points for movies, groceries at Sobeys, travel, or credits. 1,000 pts = $10.", "es": "Canjea puntos Scene+ por cine, supermercado Sobeys, viajes o créditos. 1,000 pts = $10.", "fr": "Échangez les points Scene+ pour cinéma, épicerie Sobeys, voyages ou crédits. 1 000 pts = 10 $.", "ja": "Scene+ポイントを映画、Sobeys食料品、旅行、クレジットに交換。1,000ポイント = $10。", "ko": "Scene+ 포인트를 영화, Sobeys 식료품, 여행, 크레딧으로 교환. 1,000 포인트 = $10.", "zh": "Scene+积分可兑换电影、Sobeys超市消费、旅行或账单抵扣。1,000积分 = $10。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Scotiabank' AND name = 'Scene+ Visa'), 'STACKING', '{"en": "Entry to Scene+ Ecosystem", "es": "Entrada a ecosistema Scene+", "fr": "Entrée écosystème Scene+", "ja": "Scene+エコシステム入門", "ko": "Scene+ 생태계 입문", "zh": "Scene+生态入门"}', '{"en": "Start with Scene+ Visa (no fee), upgrade to Gold Amex (5x dining) or Passport (no FX fee) as spending grows.", "es": "Comienza con Scene+ Visa (gratis), sube a Gold Amex (5x comida) o Passport (sin FX) después.", "fr": "Commencez avec Scene+ Visa (gratuit), passez à Gold Amex (5x restos) ou Passport (sans FX) plus tard.", "ja": "Scene+ Visa（無料）から始め、利用増加でGold Amex（外食5倍）やPassport（FX手数料なし）へ。", "ko": "Scene+ Visa(무료)로 시작, 지출 증가 시 Gold Amex(식사 5배) 또는 Passport(FX 수수료 없음)로 업그레이드.", "zh": "从Scene+ Visa（免年费）开始，消费增长后可升级到Gold Amex（餐饮5倍）或Passport（无外汇费）。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'AVOID', '{"en": "$5K Restaurant Cap", "es": "Límite $5K restaurantes", "fr": "Plafond 5 K$ restaurants", "ja": "レストラン$5千上限", "ko": "레스토랑 $5천 한도", "zh": "餐饮$5千上限"}', '{"en": "4% restaurant cashback capped at $5,000/year ($200 max). After cap, earns only 0.5%.", "es": "4% restaurantes limitado a $5,000/año ($200 máx). Después, solo 0.5%.", "fr": "4 % restos plafonné à 5 000 $/an (max 200 $). Après, seulement 0,5 %.", "ja": "4%レストランは年間$5,000まで（最大$200）。超過後は0.5%のみ。", "ko": "4% 레스토랑은 연간 $5,000까지 (최대 $200). 초과 후 0.5%만.", "zh": "4%餐饮返现年消费$5,000封顶（最高$200）。超过后仅0.5%。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'AVOID', '{"en": "Only 0.5% Base Rate", "es": "Solo 0.5% base", "fr": "Seulement 0,5 % de base", "ja": "基本0.5%のみ", "ko": "기본 0.5%만", "zh": "基础仅0.5%"}', '{"en": "Only 0.5% on purchases outside bonus categories or after caps. Consider pairing with a 2% flat-rate card.", "es": "Solo 0.5% fuera de categorías o tras límites. Considera combinar con tarjeta de 2% sin límite.", "fr": "Seulement 0,5 % hors catégories ou après plafonds. Considérez une carte à 2 % sans limite.", "ja": "カテゴリ外や上限超過後は0.5%のみ。2%フラットレートカードとの併用を検討。", "ko": "카테고리 외 또는 한도 초과 후 0.5%만. 2% 정액 카드와 병행 고려.", "zh": "奖励类别外或超过上限后仅0.5%。建议搭配2%无上限卡使用。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'BEST_USE', '{"en": "4% on Restaurants", "es": "4% en restaurantes", "fr": "4 % sur restaurants", "ja": "レストラン4%", "ko": "레스토랑 4%", "zh": "餐饮4%返现"}', '{"en": "Earn 4% cash back at restaurants, bars, and coffee shops. One of the best no-fee dining rates in Canada.", "es": "Gana 4% en restaurantes, bares y cafeterías. Una de las mejores tasas sin cuota en Canadá.", "fr": "Gagnez 4 % sur restos, bars et cafés. L''un des meilleurs taux sans frais au Canada.", "ja": "レストラン、バー、コーヒーショップで4%キャッシュバック。カナダ最高の年会費無料ダイニングレート。", "ko": "레스토랑, 바, 커피숍에서 4% 캐시백. 캐나다 최고의 무료 다이닝 적립률.", "zh": "在餐厅、酒吧和咖啡店获4%返现。加拿大最佳免年费餐饮返现率之一。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'BEST_USE', '{"en": "1.5% Groceries/Gas/Pharmacy", "es": "1.5% supermercado/gas/farmacia", "fr": "1,5 % épicerie/essence/pharmacie", "ja": "食料品/ガス/薬局1.5%", "ko": "식료품/주유/약국 1.5%", "zh": "超市/加油/药店1.5%"}', '{"en": "Earn 1.5% cash back on groceries, gas, drugstores, and pre-authorized payments up to $15,000/year.", "es": "Gana 1.5% en supermercados, gasolina, farmacias y pagos preautorizados hasta $15,000/año.", "fr": "Gagnez 1,5 % sur épicerie, essence, pharmacies et paiements préautorisés jusqu''à 15 000 $/an.", "ja": "食料品、ガス、薬局、自動引落で1.5%キャッシュバック、年間$15,000まで。", "ko": "식료품, 주유, 약국, 자동 결제에서 1.5% 캐시백, 연간 $15,000까지.", "zh": "超市、加油、药店和自动扣款消费获1.5%返现，年消费$15,000封顶。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'INSURANCE', '{"en": "Purchase & Extended Warranty", "es": "Protección y garantía", "fr": "Protection et garantie", "ja": "購入保護と延長保証", "ko": "구매 보호 및 연장 보증", "zh": "购物保障和延保"}', '{"en": "Purchase security plus extended warranty that doubles manufacturer warranty, plus one additional year.", "es": "Protección de compras más garantía extendida (doble fabricante + 1 año).", "fr": "Protection des achats plus garantie prolongée (double fabricant + 1 an).", "ja": "購入保護と延長保証（メーカー保証2倍+1年追加）。", "ko": "구매 보호 및 연장 보증(제조사 보증 2배 + 1년 추가).", "zh": "购物保障加延长保修，保修期延长一倍，再加一年。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee for primary card or up to 3 additional cardholders. Great value for 4% dining.", "es": "Sin cuota para tarjeta principal o hasta 3 adicionales. Gran valor para 4% restaurantes.", "fr": "Pas de frais pour carte principale ou jusqu''à 3 cartes additionnelles. Excellent pour 4 % restos.", "ja": "主カードと最大3枚の追加カードが年会費無料。4%ダイニングで高コスパ。", "ko": "기본 카드와 최대 3명의 추가 카드 소지자 연회비 무료. 4% 다이닝에 훌륭한 가치.", "zh": "主卡和最多3张附属卡均免年费。4%餐饮返现超高性价比。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'PERK', '{"en": "8% Dining for 3 Months", "es": "8% restaurantes por 3 meses", "fr": "8 % restos pendant 3 mois", "ja": "3ヶ月間レストラン8%", "ko": "3개월간 레스토랑 8%", "zh": "前3个月餐饮8%"}', '{"en": "Double restaurant cashback (8% instead of 4%) for first 3 months, up to $80. Plus $50 PRESTO voucher.", "es": "Doble cashback restaurantes (8% en vez de 4%) por 3 meses, hasta $80. Más voucher PRESTO $50.", "fr": "Double remise restos (8 % au lieu de 4 %) pendant 3 mois, jusqu''à 80 $. Plus bon PRESTO de 50 $.", "ja": "3ヶ月間レストラン2倍（4%→8%）、最大$80。さらに$50 PRESTOバウチャー。", "ko": "3개월간 레스토랑 더블 캐시백(4%→8%), 최대 $80. 추가로 $50 PRESTO 바우처.", "zh": "前3个月餐饮双倍返现（8%而非4%），最高$80。另获$50 PRESTO券。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'PERK', '{"en": "New to Canada Program", "es": "Programa nuevos en Canadá", "fr": "Programme nouveaux arrivants", "ja": "カナダ新規移住者プログラム", "ko": "캐나다 신규 이민자 프로그램", "zh": "新移民计划"}', '{"en": "New to Canada applicants can get up to $10,000 credit limit. No Canadian credit history required.", "es": "Nuevos en Canadá pueden obtener hasta $10,000 de límite. Sin historial crediticio canadiense.", "fr": "Nouveaux arrivants peuvent obtenir jusqu''à 10 000 $ de limite. Pas d''historique canadien requis.", "ja": "カナダ新規移住者は最大$10,000の限度額取得可能。カナダの信用履歴不要。", "ko": "캐나다 신규 이민자는 최대 $10,000 신용 한도 가능. 캐나다 신용 기록 불필요.", "zh": "新移民可获最高$10,000信用额度。无需加拿大信用记录。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'PERK', '{"en": "Mobile Wallet Ready", "es": "Compatible con billetera móvil", "fr": "Compatible portefeuille mobile", "ja": "モバイルウォレット対応", "ko": "모바일 월렛 지원", "zh": "支持移动钱包"}', '{"en": "Works with Apple Pay, Google Pay, and Samsung Pay for convenient contactless payments.", "es": "Funciona con Apple Pay, Google Pay y Samsung Pay para pagos sin contacto.", "fr": "Compatible Apple Pay, Google Pay et Samsung Pay pour paiements sans contact pratiques.", "ja": "Apple Pay、Google Pay、Samsung Pay対応で便利な非接触決済。", "ko": "Apple Pay, Google Pay, Samsung Pay 지원으로 편리한 비접촉 결제.", "zh": "支持Apple Pay、Google Pay和Samsung Pay便捷非接触支付。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Simplii' AND name = 'Cash Back Visa Card'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem cash back as statement credit or deposit to Simplii account. No minimum redemption amount.", "es": "Canjea como crédito en estado de cuenta o depósito a cuenta Simplii. Sin mínimo.", "fr": "Échangez en crédit sur relevé ou dépôt au compte Simplii. Pas de minimum.", "ja": "明細クレジットまたはSimplii口座入金で交換。最低交換なし。", "ko": "명세서 크레딧 또는 Simplii 계좌 입금으로 교환. 최소 교환 없음.", "zh": "返现可兑换为账单抵扣或存入Simplii账户。无最低兑换门槛。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'AVOID', '{"en": "Only 0.5% Outside Categories", "es": "Solo 0.5% fuera de categorías", "fr": "Seulement 0,5 % hors catégories", "ja": "カテゴリ外は0.5%のみ", "ko": "카테고리 외 0.5%만", "zh": "类别外仅0.5%"}', '{"en": "Only 0.5% on purchases outside your chosen categories. Pick categories that match your highest spending.", "es": "Solo 0.5% fuera de categorías elegidas. Elige según tu mayor gasto.", "fr": "Seulement 0,5 % hors catégories choisies. Choisissez selon vos dépenses principales.", "ja": "選択カテゴリ外は0.5%のみ。最も支出の多いカテゴリを選択。", "ko": "선택한 카테고리 외에는 0.5%만. 가장 많이 지출하는 카테고리를 선택하세요.", "zh": "所选类别以外的消费仅获0.5%。选择与最高消费匹配的类别。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'AVOID', '{"en": "2.5% Foreign Transaction Fee", "es": "2.5% comisión FX", "fr": "2,5 % frais de change", "ja": "外貨手数料2.5%", "ko": "외환 수수료 2.5%", "zh": "外汇手续费2.5%"}', '{"en": "2.5% FX fee applies. Even with Foreign Currency category (2%), net is -0.5% loss. Use no-FX card for travel.", "es": "2.5% comisión FX. Incluso con categoría Divisa (2%), pérdida neta de 0.5%. Usa tarjeta sin FX para viajar.", "fr": "2,5 % frais de change. Même avec catégorie devises (2 %), perte nette de 0,5 %. Utilisez carte sans frais FX.", "ja": "2.5%外貨手数料あり。外貨カテゴリ（2%）でも純損失0.5%。旅行にはFX手数料なしカードを。", "ko": "2.5% 외환 수수료 있음. 외화 카테고리(2%)를 선택해도 순손실 0.5%. 여행에는 FX 수수료 없는 카드 사용.", "zh": "有2.5%外汇手续费。即使选择外币类别（2%），净损失0.5%。旅行建议使用无外汇费卡。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'BEST_USE', '{"en": "Choose Your 2% Categories", "es": "Elige tus categorías 2%", "fr": "Choisissez vos catégories 2 %", "ja": "2%カテゴリを選択", "ko": "2% 카테고리 선택", "zh": "自选2%返现类别"}', '{"en": "Pick 2 categories for 2% cashback (3 if rewards go to Tangerine Savings). Choose from 13 categories including groceries, gas, dining.", "es": "Elige 2 categorías para 2% (3 si van a Tangerine Savings). 13 categorías incluyendo supermercado, gas, restaurantes.", "fr": "Choisissez 2 catégories pour 2 % (3 si vers compte épargne Tangerine). 13 catégories disponibles.", "ja": "2カテゴリで2%（Tangerine貯蓄なら3カテゴリ）。食料品、ガス、外食など13カテゴリから選択。", "ko": "2% 캐시백을 위해 2개 카테고리 선택 (Tangerine 저축 시 3개). 식료품, 주유, 식사 등 13개 카테고리.", "zh": "自选2个类别获2%返现（存入Tangerine储蓄账户可选3个）。13个类别可选：超市、加油、餐饮等。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'BEST_USE', '{"en": "13 Categories Available", "es": "13 categorías disponibles", "fr": "13 catégories disponibles", "ja": "13カテゴリ利用可能", "ko": "13개 카테고리 이용 가능", "zh": "13个类别可选"}', '{"en": "Grocery, Gas, Dining, Entertainment, Hotels, Furniture, Drug Store, Bills, Home Improvement, Transit, E-Games, Fitness, Foreign Currency.", "es": "Supermercado, gas, restaurantes, entretenimiento, hoteles, muebles, farmacia, facturas, hogar, transporte, juegos, fitness, divisas.", "fr": "Épicerie, essence, restos, divertissement, hôtels, meubles, pharmacie, factures, rénovation, transports, jeux, fitness, devises.", "ja": "食料品、ガス、外食、エンタメ、ホテル、家具、薬局、請求書、家庭用品、交通、ゲーム、フィットネス、外貨。", "ko": "식료품, 주유, 식사, 엔터테인먼트, 호텔, 가구, 약국, 청구서, 홈개선, 교통, 게임, 피트니스, 외화.", "zh": "超市、加油、餐饮、娱乐、酒店、家具、药店、账单、家装、交通、电竞、健身、外币消费。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'INSURANCE', '{"en": "Purchase & Extended Warranty", "es": "Protección y garantía", "fr": "Protection et garantie", "ja": "購入保護と延長保証", "ko": "구매 보호 및 연장 보증", "zh": "购物保障和延保"}', '{"en": "Purchase assurance and extended warranty coverage up to $60,000 lifetime. Protects eligible purchases.", "es": "Protección de compras y garantía extendida hasta $60,000 de por vida. Protege compras elegibles.", "fr": "Assurance achats et garantie prolongée jusqu''à 60 000 $ à vie. Protège les achats éligibles.", "ja": "購入保証と延長保証、生涯最大$60,000。対象購入品を保護。", "ko": "구매 보호 및 연장 보증, 평생 최대 $60,000. 적격 구매품 보호.", "zh": "购物保障和延长保修，终身最高$60,000。保护符合条件的消费。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee, no caps on cashback. Up to 5 free authorized users.", "es": "Sin cuota anual, sin límites de cashback. Hasta 5 usuarios autorizados gratis.", "fr": "Pas de frais annuels, pas de plafond. Jusqu''à 5 utilisateurs autorisés gratuits.", "ja": "年会費無料、キャッシュバック上限なし。最大5名の無料追加ユーザー。", "ko": "연회비 무료, 캐시백 한도 없음. 최대 5명의 무료 추가 사용자.", "zh": "免年费，返现无上限。最多5名免费授权用户。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'PERK', '{"en": "3rd Category with Savings", "es": "3ra categoría con ahorro", "fr": "3e catégorie avec épargne", "ja": "貯蓄で3つ目のカテゴリ", "ko": "저축으로 3번째 카테고리", "zh": "储蓄账户解锁第3个类别"}', '{"en": "Deposit rewards to Tangerine Savings Account to unlock a 3rd 2% category. Easy way to maximize earning.", "es": "Deposita recompensas en cuenta Tangerine Savings para desbloquear 3ra categoría 2%.", "fr": "Déposez les récompenses dans un compte épargne Tangerine pour une 3e catégorie à 2 %.", "ja": "Tangerine貯蓄に報酬を入金して3つ目の2%カテゴリを解除。", "ko": "Tangerine 저축 계좌에 리워드 입금 시 3번째 2% 카테고리 해제.", "zh": "将返现存入Tangerine储蓄账户可解锁第3个2%类别。轻松最大化收益。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'PERK', '{"en": "Change Every 90 Days", "es": "Cambia cada 90 días", "fr": "Changez tous les 90 jours", "ja": "90日ごとに変更可能", "ko": "90일마다 변경 가능", "zh": "每90天可更换类别"}', '{"en": "Adjust your 2% categories every 90 days to match seasonal spending. First change anytime.", "es": "Ajusta tus categorías 2% cada 90 días según tu gasto estacional. Primer cambio en cualquier momento.", "fr": "Ajustez vos catégories 2 % tous les 90 jours selon vos dépenses saisonnières.", "ja": "90日ごとに2%カテゴリを季節の支出に合わせて調整。初回変更はいつでも可能。", "ko": "90일마다 2% 카테고리를 계절별 지출에 맞게 조정. 첫 변경은 언제든지.", "zh": "每90天可调整2%类别以匹配季节性消费。首次更换可随时进行。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'PERK', '{"en": "10% for 2 Months", "es": "10% por 2 meses", "fr": "10 % pendant 2 mois", "ja": "2ヶ月間10%", "ko": "2개월간 10%", "zh": "前2个月10%返现"}', '{"en": "Earn 10% cash back on all purchases for first 2 months, up to $100. Apply by Jan 30, 2026.", "es": "10% en todas las compras por 2 meses, hasta $100. Aplica antes del 30 de enero 2026.", "fr": "10 % sur tous achats pendant 2 mois, jusqu''à 100 $. Postulez avant le 30 janvier 2026.", "ja": "最初の2ヶ月間全購入で10%キャッシュバック、最大$100。2026年1月30日まで。", "ko": "첫 2개월간 모든 구매에서 10% 캐시백, 최대 $100. 2026년 1월 30일까지 신청.", "zh": "前2个月所有消费10%返现，最高$100。2026年1月30日前申请。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'Money-Back Credit Card'), 'REDEMPTION', '{"en": "Automatic Monthly Deposit", "es": "Depósito mensual automático", "fr": "Dépôt mensuel automatique", "ja": "毎月自動入金", "ko": "매월 자동 입금", "zh": "每月自动存入"}', '{"en": "Cash back automatically deposited monthly to your Tangerine account or credited to card. No manual redemption needed.", "es": "Cashback depositado automáticamente cada mes en tu cuenta Tangerine o acreditado a la tarjeta.", "fr": "Remise déposée automatiquement chaque mois dans votre compte Tangerine ou créditée sur la carte.", "ja": "キャッシュバックは毎月自動でTangerine口座に入金またはカードにクレジット。", "ko": "캐시백이 매월 자동으로 Tangerine 계좌에 입금되거나 카드에 적립됩니다.", "zh": "返现每月自动存入Tangerine账户或抵扣卡上。无需手动兑换。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'AVOID', '{"en": "$50K Income Required", "es": "Se requiere $50K", "fr": "Revenu 50 K$ requis", "ja": "収入$5万必要", "ko": "소득 $5만 필요", "zh": "需$5万收入"}', '{"en": "Requires $50K personal or $80K household income. Consider Money-Back card ($12K) if you don''t qualify.", "es": "Requiere $50K personal o $80K familiar. Considera Money-Back ($12K) si no calificas.", "fr": "Exige 50 K$ personnel ou 80 K$ familial. Considérez Money-Back (12 K$) si non éligible.", "ja": "個人$5万または世帯$8万の収入が必要。資格がない場合はMoney-Back（$1.2万）を検討。", "ko": "개인 $5만 또는 가구 $8만 소득 필요. 자격이 없으면 Money-Back ($1.2만) 고려.", "zh": "需个人收入$5万或家庭收入$8万。不符合条件可考虑Money-Back卡（$1.2万）。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'AVOID', '{"en": "2.5% Foreign Transaction Fee", "es": "2.5% comisión FX", "fr": "2,5 % frais de change", "ja": "外貨手数料2.5%", "ko": "외환 수수료 2.5%", "zh": "外汇手续费2.5%"}', '{"en": "2.5% FX fee applies. Despite travel perks, not ideal for foreign purchases. Use no-FX card abroad.", "es": "2.5% comisión FX. A pesar de beneficios de viaje, no ideal para compras extranjeras.", "fr": "2,5 % frais de change. Malgré les avantages voyage, pas idéal pour achats étrangers.", "ja": "2.5%外貨手数料あり。旅行特典があるが、海外購入には不向き。", "ko": "2.5% 외환 수수료 있음. 여행 혜택에도 불구하고 해외 구매에는 비적합.", "zh": "有2.5%外汇手续费。尽管有旅行福利，外币消费不理想。建议海外使用无外汇费卡。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'BEST_USE', '{"en": "Choose Your 2% Categories", "es": "Elige tus categorías 2%", "fr": "Choisissez vos catégories 2 %", "ja": "2%カテゴリを選択", "ko": "2% 카테고리 선택", "zh": "自选2%返现类别"}', '{"en": "Pick 2 categories for 2% cashback (3 if rewards go to Tangerine Savings). Same flexibility as Money-Back card.", "es": "Elige 2 categorías para 2% (3 si van a Tangerine Savings). Misma flexibilidad que Money-Back.", "fr": "Choisissez 2 catégories pour 2 % (3 si vers compte épargne Tangerine). Même flexibilité que Money-Back.", "ja": "2カテゴリで2%（Tangerine貯蓄なら3カテゴリ）。Money-Backカードと同じ柔軟性。", "ko": "2% 캐시백을 위해 2개 카테고리 선택 (Tangerine 저축 시 3개). Money-Back 카드와 동일한 유연성.", "zh": "自选2个类别获2%返现（存入Tangerine储蓄账户可选3个）。与Money-Back卡相同的灵活性。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'INSURANCE', '{"en": "World Card Insurance", "es": "Seguro World", "fr": "Assurance World", "ja": "Worldカード保険", "ko": "World 카드 보험", "zh": "World卡保险"}', '{"en": "Mobile device ($1,000), rental car collision, purchase protection & extended warranty ($60,000 lifetime).", "es": "Móvil ($1,000), colisión alquiler, protección compras y garantía extendida ($60,000 de por vida).", "fr": "Mobile (1 000 $), collision location, protection achats et garantie prolongée (60 000 $ à vie).", "ja": "モバイル（$1,000）、レンタカー衝突、購入保護と延長保証（生涯$60,000）。", "ko": "모바일($1,000), 렌터카 충돌, 구매 보호 및 연장 보증(평생 $60,000).", "zh": "手机保险（$1,000）、租车碰撞、购物保障和延保（终身$60,000）。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'PERK', '{"en": "$120 Welcome Bonus", "es": "Bono de $120", "fr": "Bonus de 120 $", "ja": "$120ウェルカムボーナス", "ko": "$120 웰컴 보너스", "zh": "$120欢迎奖励"}', '{"en": "Get $120 cash back after spending $1,500 in first 3 months. Better than Money-Back card''s $100 bonus.", "es": "$120 después de $1,500 en 3 meses. Mejor que el bono de $100 de Money-Back.", "fr": "120 $ après 1 500 $ en 3 mois. Mieux que le bonus de 100 $ de la carte Money-Back.", "ja": "3ヶ月で$1,500利用後$120キャッシュバック。Money-Backの$100ボーナスより良い。", "ko": "3개월 내 $1,500 사용 시 $120 캐시백. Money-Back 카드의 $100 보너스보다 우수.", "zh": "3个月内消费$1,500可获$120返现。比Money-Back卡的$100奖励更高。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'PERK', '{"en": "Airport Lounge Access", "es": "Acceso a salas", "fr": "Accès salon aéroport", "ja": "空港ラウンジ", "ko": "공항 라운지", "zh": "机场贵宾厅"}', '{"en": "DragonPass access to 1,300+ airport lounges in 140+ countries. Pay-per-visit basis.", "es": "Acceso DragonPass a 1,300+ salas en 140+ países. Pago por visita.", "fr": "Accès DragonPass à 1 300+ salons dans 140+ pays. Paiement par visite.", "ja": "DragonPassで140+カ国1,300以上のラウンジにアクセス。利用ごとに支払い。", "ko": "140+ 국가 1,300+ 공항 라운지에 DragonPass 접근. 방문당 결제.", "zh": "DragonPass可进入140+国家1,300+机场贵宾厅。按次付费。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'PERK', '{"en": "Mobile Device Insurance", "es": "Seguro de móvil", "fr": "Assurance mobile", "ja": "モバイル保険", "ko": "모바일 기기 보험", "zh": "手机保险"}', '{"en": "Up to $1,000 mobile device insurance coverage. Not available on standard Money-Back card.", "es": "Seguro de móvil hasta $1,000. No disponible en la tarjeta Money-Back estándar.", "fr": "Assurance mobile jusqu''à 1 000 $. Non disponible sur la carte Money-Back standard.", "ja": "最大$1,000のモバイル保険。標準Money-Backカードにはない特典。", "ko": "최대 $1,000 모바일 기기 보험. 표준 Money-Back 카드에는 없는 혜택.", "zh": "最高$1,000手机保险。标准Money-Back卡不含此保障。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'PERK', '{"en": "Rental Car Insurance", "es": "Seguro de alquiler", "fr": "Assurance location auto", "ja": "レンタカー保険", "ko": "렌터카 보험", "zh": "租车保险"}', '{"en": "Rental car damage and theft protection included. Great for road trips.", "es": "Protección contra daños y robo de auto de alquiler incluida.", "fr": "Protection contre les dommages et le vol de voiture de location incluse.", "ja": "レンタカーの損害・盗難保護付き。ロードトリップに最適。", "ko": "렌터카 손해 및 도난 보호 포함. 로드트립에 최적.", "zh": "包含租车损坏和盗窃保护。非常适合自驾游。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'PERK', '{"en": "Free 1GB Global Data", "es": "1GB de datos global gratis", "fr": "1 Go de données mondial gratuit", "ja": "無料1GB グローバルデータ", "ko": "무료 1GB 글로벌 데이터", "zh": "免费1GB全球流量"}', '{"en": "Complimentary 1GB FlexiRoam global data + 15% discount on additional plans. Perfect for travelers.", "es": "1GB FlexiRoam gratis + 15% descuento en planes adicionales. Perfecto para viajeros.", "fr": "1 Go FlexiRoam gratuit + 15 % rabais sur forfaits supplémentaires. Idéal pour voyageurs.", "ja": "無料1GB FlexiRoamグローバルデータ + 追加プラン15%割引。旅行者に最適。", "ko": "무료 1GB FlexiRoam 글로벌 데이터 + 추가 플랜 15% 할인. 여행자에게 완벽.", "zh": "免费1GB FlexiRoam全球流量 + 额外套餐85折。旅行者的完美选择。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee for premium World Mastercard benefits. Rare value in the market.", "es": "Sin cuota anual para beneficios World Mastercard premium. Valor raro en el mercado.", "fr": "Pas de frais annuels pour avantages World Mastercard premium. Valeur rare sur le marché.", "ja": "プレミアムWorld Mastercard特典で年会費無料。市場で稀な価値。", "ko": "프리미엄 World Mastercard 혜택에 연회비 무료. 시장에서 보기 드문 가치.", "zh": "高级World Mastercard权益免年费。市场上罕见的超值卡。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Tangerine' AND name = 'World Mastercard'), 'STACKING', '{"en": "Upgrade from Money-Back", "es": "Mejorar desde Money-Back", "fr": "Passer de Money-Back", "ja": "Money-Backからアップグレード", "ko": "Money-Back에서 업그레이드", "zh": "从Money-Back升级"}', '{"en": "Same 2% categories as Money-Back but with travel perks, mobile insurance, and better welcome bonus. Worth upgrading if you qualify.", "es": "Mismas categorías 2% que Money-Back pero con beneficios de viaje, seguro móvil y mejor bono.", "fr": "Mêmes catégories 2 % que Money-Back mais avec avantages voyage, assurance mobile et meilleur bonus.", "ja": "Money-Backと同じ2%カテゴリだが、旅行特典、モバイル保険、より良いボーナス付き。", "ko": "Money-Back과 동일한 2% 카테고리지만 여행 혜택, 모바일 보험, 더 나은 보너스 포함.", "zh": "与Money-Back相同的2%类别，但有旅行福利、手机保险和更高欢迎奖励。符合条件值得升级。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'AVOID', '{"en": "$139 Annual Fee After Year 1", "es": "$139 después del año 1", "fr": "139 $ après la 1re année", "ja": "2年目以降$139年会費", "ko": "1년 후 $139 연회비", "zh": "第二年起$139年费"}', '{"en": "Annual fee of $139 after first year. Consider TD All-Inclusive Banking Plan to waive it, or evaluate if perks justify cost.", "es": "Cuota de $139 después del primer año. Considera TD All-Inclusive o evalúa si los beneficios lo justifican.", "fr": "Frais de 139 $ après la 1re année. Considérez le forfait TD tout inclus ou évaluez si les avantages le justifient.", "ja": "初年度以降$139年会費。TD全包プランで免除を検討、または特典で元が取れるか評価。", "ko": "첫해 이후 $139 연회비. TD 올인클루시브 플랜으로 면제 고려, 또는 혜택이 비용 가치가 있는지 평가.", "zh": "首年后年费$139。可考虑TD全包银行计划免年费，或评估权益是否值得。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'AVOID', '{"en": "High Spend for Full Bonus", "es": "Alto gasto para bono completo", "fr": "Dépenses élevées pour bonus", "ja": "満額ボーナスに高額消費", "ko": "풀 보너스에 높은 지출 필요", "zh": "完整奖励需高消费"}', '{"en": "Need to spend $7,500 in 180 days for full 25,000 welcome bonus. Plan spending accordingly.", "es": "Necesitas $7,500 en 180 días para los 25,000 puntos completos. Planifica tus gastos.", "fr": "Besoin de 7 500 $ en 180 jours pour les 25 000 points. Planifiez vos dépenses.", "ja": "25,000ポイント満額には180日で$7,500消費が必要。支出計画を立てて。", "ko": "25,000 포인트 전체를 받으려면 180일 내 $7,500 사용 필요. 지출을 계획하세요.", "zh": "需在180天内消费$7,500才能获得完整25,000积分奖励。请提前规划消费。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'BEST_USE', '{"en": "1.5x on Gas & Groceries", "es": "1.5x en gas y supermercados", "fr": "1,5x sur essence et épicerie", "ja": "ガス・食料品で1.5倍", "ko": "주유·식료품 1.5배", "zh": "加油和超市1.5倍积分"}', '{"en": "Earn 1.5 Aeroplan points per $1 on gas, EV charging, and groceries. Great for everyday spending.", "es": "Gana 1.5 puntos Aeroplan por $1 en gas, carga EV y supermercados. Ideal para gastos diarios.", "fr": "Gagnez 1,5 point Aeroplan par $ sur essence, recharge VE et épicerie. Idéal pour dépenses quotidiennes.", "ja": "ガス、EV充電、食料品で$1につき1.5 Aeroplanポイント獲得。日常支出に最適。", "ko": "주유, EV 충전, 식료품에서 $1당 1.5 Aeroplan 포인트 적립. 일상 지출에 최적.", "zh": "加油、电动车充电和超市消费每$1赚1.5 Aeroplan积分。日常消费首选。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'BEST_USE', '{"en": "1.5x on Air Canada", "es": "1.5x en Air Canada", "fr": "1,5x sur Air Canada", "ja": "エアカナダで1.5倍", "ko": "에어캐나다 1.5배", "zh": "加航消费1.5倍积分"}', '{"en": "Earn 1.5 Aeroplan points per $1 on Air Canada purchases. Stack with Aeroplan member earnings.", "es": "Gana 1.5 puntos por $1 en compras Air Canada. Acumulable con puntos de miembro Aeroplan.", "fr": "Gagnez 1,5 point par $ sur achats Air Canada. Cumulable avec les points membre Aeroplan.", "ja": "エアカナダ購入で$1につき1.5ポイント。Aeroplan会員ポイントと併用可能。", "ko": "에어캐나다 구매 시 $1당 1.5포인트. Aeroplan 회원 포인트와 중복 적립 가능.", "zh": "加航消费每$1赚1.5 Aeroplan积分。可与Aeroplan会员积分叠加。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'INSURANCE', '{"en": "Premium Travel Insurance", "es": "Seguro de viaje premium", "fr": "Assurance voyage premium", "ja": "プレミアム旅行保険", "ko": "프리미엄 여행 보험", "zh": "高端旅行保险"}', '{"en": "$2M travel medical (21 days), trip cancellation up to $5,000, flight delay $500, rental car (48 days), mobile device $1,000.", "es": "Médico viaje $2M (21 días), cancelación $5,000, retraso vuelo $500, alquiler auto (48 días), móvil $1,000.", "fr": "2 M$ médical voyage (21 j), annulation 5 000 $, retard vol 500 $, location auto (48 j), mobile 1 000 $.", "ja": "旅行医療$200万（21日）、旅行キャンセル$5,000、遅延$500、レンタカー（48日）、モバイル$1,000。", "ko": "여행 의료 $200만(21일), 여행 취소 $5,000, 항공 지연 $500, 렌터카(48일), 모바일 $1,000.", "zh": "旅行医疗$200万（21天）、行程取消最高$5,000、航班延误$500、租车（48天）、手机$1,000。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "Free Checked Bag", "es": "Equipaje gratis", "fr": "Bagage gratuit", "ja": "無料受託手荷物", "ko": "무료 수하물", "zh": "免费托运行李"}', '{"en": "Free first checked bag (up to 23kg) for you and up to 8 travel companions on Air Canada flights.", "es": "Primera maleta gratis (hasta 23kg) para ti y hasta 8 acompañantes en vuelos Air Canada.", "fr": "Premier bagage gratuit (jusqu''à 23 kg) pour vous et jusqu''à 8 accompagnateurs sur Air Canada.", "ja": "エアカナダで本人と最大8名の同行者が1個目の手荷物（23kgまで）無料。", "ko": "에어캐나다에서 본인과 최대 8명의 동반자 첫 번째 수하물(23kg까지) 무료.", "zh": "加航航班可享本人及最多8名同行者免费托运首件行李（最重23公斤）。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "NEXUS Fee Rebate", "es": "Reembolso NEXUS", "fr": "Remboursement NEXUS", "ja": "NEXUS料金リベート", "ko": "NEXUS 수수료 환급", "zh": "NEXUS费用返还"}', '{"en": "Get up to $100 CAD rebate for NEXUS application fee once every 48 months. Speeds up border crossing.", "es": "Hasta $100 CAD de reembolso por NEXUS cada 48 meses. Acelera el cruce fronterizo.", "fr": "Remboursement jusqu''à 100 $ CAD pour frais NEXUS tous les 48 mois. Accélère le passage aux frontières.", "ja": "48ヶ月ごとにNEXUS申請料最大$100 CADのリベート。国境通過を迅速化。", "ko": "48개월마다 NEXUS 신청비 최대 $100 CAD 환급. 국경 통과 가속화.", "zh": "每48个月可获最高$100加币NEXUS申请费返还。加速边境通关。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "First Year Fee Waived", "es": "Primer año gratis", "fr": "1re année gratuite", "ja": "初年度年会費無料", "ko": "첫해 연회비 면제", "zh": "首年年费减免"}', '{"en": "$139 annual fee waived first year with card activation. Also waived with TD All-Inclusive Banking Plan.", "es": "Cuota de $139 exonerada el primer año con activación. También con TD All-Inclusive Banking Plan.", "fr": "Frais de 139 $ exonérés la 1re année à l''activation. Aussi exonérés avec forfait bancaire TD tout inclus.", "ja": "カード有効化で初年度$139年会費無料。TD All-Inclusive Banking Planでも免除。", "ko": "카드 활성화 시 첫해 $139 연회비 면제. TD All-Inclusive Banking Plan에서도 면제.", "zh": "激活卡片后首年$139年费减免。持有TD全包银行计划也可免年费。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "25,000 Point Welcome Bonus", "es": "Bono de 25,000 puntos", "fr": "Bonus de 25 000 points", "ja": "25,000ポイントボーナス", "ko": "25,000 포인트 보너스", "zh": "25,000积分欢迎奖励"}', '{"en": "10,000 pts on first purchase + 15,000 pts after $7,500 spend in 180 days. Plus 20,000 anniversary bonus.", "es": "10,000 pts en primera compra + 15,000 pts tras $7,500 en 180 días. Más 20,000 pts aniversario.", "fr": "10 000 pts au 1er achat + 15 000 pts après 7 500 $ en 180 jours. Plus 20 000 pts anniversaire.", "ja": "初回購入10,000pt + 180日$7,500で15,000pt。さらに20,000pt周年ボーナス。", "ko": "첫 구매 10,000pt + 180일 $7,500 사용 시 15,000pt. 추가로 20,000pt 주년 보너스.", "zh": "首次消费获10,000积分 + 180天内消费$7,500再获15,000积分。另有20,000周年奖励。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'PERK', '{"en": "Elite Status Acceleration", "es": "Aceleración de estatus Elite", "fr": "Accélération statut Élite", "ja": "エリートステータス加速", "ko": "엘리트 자격 가속", "zh": "精英等级加速"}', '{"en": "Earn 1,000 Status Qualifying Miles per $10,000 spent. Helps achieve Aeroplan 25K/35K/50K/75K status.", "es": "Gana 1,000 millas de calificación por $10,000 gastados. Ayuda a lograr estatus Aeroplan.", "fr": "Gagnez 1 000 milles de qualification par 10 000 $ dépensés. Aide à atteindre le statut Aeroplan.", "ja": "$10,000支出ごとに1,000資格マイル獲得。Aeroplanステータス達成をサポート。", "ko": "$10,000 사용 시 1,000 자격 마일 적립. Aeroplan 엘리트 자격 달성 지원.", "zh": "每消费$10,000可获1,000资格里程。助您达成Aeroplan 25K/35K/50K/75K精英等级。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'STACKING', '{"en": "Earn Points Twice", "es": "Gana puntos dobles", "fr": "Gagnez deux fois", "ja": "ポイント二重取り", "ko": "포인트 이중 적립", "zh": "双重积分"}', '{"en": "Earn points twice at 150+ Aeroplan partners and 200+ eStore retailers. Pay with card + show Aeroplan number.", "es": "Gana puntos dos veces en 150+ socios Aeroplan y 200+ tiendas eStore. Paga con tarjeta + número Aeroplan.", "fr": "Gagnez deux fois chez 150+ partenaires Aeroplan et 200+ détaillants eStore. Payez par carte + numéro Aeroplan.", "ja": "150以上のAeroplan提携店と200以上のeStoreで二重取り。カード払い+Aeroplan番号提示。", "ko": "150+ Aeroplan 파트너와 200+ eStore에서 이중 적립. 카드 결제 + Aeroplan 번호 제시.", "zh": "在150+Aeroplan合作商家和200+网上商城可双重积分。刷卡+出示Aeroplan会员号。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite'), 'STACKING', '{"en": "Pair with TD Banking Plan", "es": "Combinar con plan TD", "fr": "Combiner avec forfait TD", "ja": "TD銀行プランと併用", "ko": "TD 뱅킹 플랜과 병행", "zh": "搭配TD银行计划"}', '{"en": "TD All-Inclusive Banking Plan ($35.95/mo) waives the annual fee and provides extra Aeroplan benefits.", "es": "TD All-Inclusive ($35.95/mes) exonera cuota anual y ofrece beneficios Aeroplan adicionales.", "fr": "Forfait TD tout inclus (35,95 $/mois) exonère frais annuels et offre avantages Aeroplan supplémentaires.", "ja": "TD全包プラン（$35.95/月）で年会費無料、追加Aeroplan特典も。", "ko": "TD 올인클루시브 플랜($35.95/월)으로 연회비 면제 및 추가 Aeroplan 혜택.", "zh": "TD全包银行计划（$35.95/月）可免年费，并提供额外Aeroplan权益。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'AVOID', '{"en": "$599 Annual Fee", "es": "Cuota anual $599", "fr": "Frais annuels 599 $", "ja": "年会費$599", "ko": "연회비 $599", "zh": "年费$599"}', '{"en": "High $599 annual fee + $199 per additional cardholder. Best for frequent Air Canada travelers.", "es": "Cuota alta de $599 + $199 por tarjeta adicional. Mejor para viajeros frecuentes de Air Canada.", "fr": "Frais élevés de 599 $ + 199 $ par carte additionnelle. Idéal pour voyageurs fréquents Air Canada.", "ja": "高額$599年会費 + 追加カード$199。エアカナダ頻繁利用者に最適。", "ko": "높은 $599 연회비 + 추가 카드 $199. 에어캐나다 상용 고객에게 최적.", "zh": "年费高达$599 + 附属卡$199/张。最适合加航常旅客。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'BEST_USE', '{"en": "2x on Air Canada", "es": "2x en Air Canada", "fr": "2x sur Air Canada", "ja": "エアカナダで2倍", "ko": "에어캐나다 2배", "zh": "加航消费2倍积分"}', '{"en": "Earn 2 Aeroplan points per $1 on Air Canada purchases. Better rate than Infinite card (1.5x).", "es": "Gana 2 puntos Aeroplan por $1 en Air Canada. Mejor que Infinite (1.5x).", "fr": "Gagnez 2 points Aeroplan par $ sur Air Canada. Meilleur que Infinite (1,5x).", "ja": "エアカナダで$1につき2ポイント。Infiniteカード（1.5倍）より高い。", "ko": "에어캐나다에서 $1당 2포인트. Infinite 카드(1.5배)보다 우수.", "zh": "加航消费每$1赚2 Aeroplan积分。比Infinite卡（1.5倍）更高。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'BEST_USE', '{"en": "1.5x on Gas/Grocery/Dining/Transit", "es": "1.5x gas/supermercado/restaurante/transporte", "fr": "1,5x essence/épicerie/resto/transport", "ja": "ガス/食料品/外食/交通で1.5倍", "ko": "주유/식료품/식사/교통 1.5배", "zh": "加油/超市/餐饮/交通1.5倍"}', '{"en": "1.5 points per $1 on gas, groceries, dining, and transit. Covers most daily expenses.", "es": "1.5 puntos por $1 en gas, supermercados, restaurantes y transporte. Cubre la mayoría de gastos diarios.", "fr": "1,5 point par $ sur essence, épicerie, resto et transport. Couvre la plupart des dépenses quotidiennes.", "ja": "ガス、食料品、外食、交通で$1につき1.5ポイント。日常支出の大部分をカバー。", "ko": "주유, 식료품, 식사, 교통에서 $1당 1.5포인트. 대부분의 일상 지출 커버.", "zh": "加油、超市、餐饮、交通每$1赚1.5积分。覆盖大部分日常消费。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'BEST_USE', '{"en": "1.25x on All Other Purchases", "es": "1.25x en otras compras", "fr": "1,25x sur autres achats", "ja": "その他の購入で1.25倍", "ko": "기타 구매 1.25배", "zh": "其他消费1.25倍"}', '{"en": "Earn 1.25 points per $1 on all other purchases. Better base rate than most cards.", "es": "1.25 puntos por $1 en todas las demás compras. Mejor tasa base que la mayoría de las tarjetas.", "fr": "1,25 point par $ sur tous les autres achats. Meilleur taux de base que la plupart des cartes.", "ja": "その他の購入で$1につき1.25ポイント。大多数のカードより高い基本レート。", "ko": "기타 구매에서 $1당 1.25포인트. 대부분의 카드보다 높은 기본 적립률.", "zh": "其他消费每$1赚1.25积分。比大多数卡的基础率更高。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'INSURANCE', '{"en": "Premium Travel Insurance", "es": "Seguro de viaje premium", "fr": "Assurance voyage premium", "ja": "プレミアム旅行保険", "ko": "프리미엄 여행 보험", "zh": "顶级旅行保险"}', '{"en": "$5M travel medical (31 days), trip cancellation $5,000, lost baggage $2,500, accident $500,000.", "es": "$5M médico viaje (31 días), cancelación $5,000, equipaje perdido $2,500, accidente $500,000.", "fr": "5 M$ médical voyage (31 j), annulation 5 000 $, bagages perdus 2 500 $, accident 500 000 $.", "ja": "旅行医療$500万（31日）、キャンセル$5,000、紛失手荷物$2,500、事故$50万。", "ko": "여행 의료 $500만(31일), 취소 $5,000, 분실 수하물 $2,500, 사고 $50만.", "zh": "旅行医疗$500万（31天）、行程取消$5,000、行李丢失$2,500、意外$50万。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'PERK', '{"en": "Unlimited Maple Leaf Lounge", "es": "Maple Leaf Lounge ilimitado", "fr": "Salon Feuille d''érable illimité", "ja": "メープルリーフラウンジ無制限", "ko": "메이플 리프 라운지 무제한", "zh": "无限次枫叶贵宾厅"}', '{"en": "Unlimited Maple Leaf Lounge access with one complimentary guest. Premium Air Canada experience.", "es": "Acceso ilimitado a Maple Leaf Lounge con un acompañante. Experiencia premium Air Canada.", "fr": "Accès illimité au salon Feuille d''érable avec un invité. Expérience Air Canada premium.", "ja": "メープルリーフラウンジ無制限+同伴者1名無料。プレミアムエアカナダ体験。", "ko": "메이플 리프 라운지 무제한 + 동반자 1명 무료. 프리미엄 에어캐나다 경험.", "zh": "无限次进入枫叶贵宾厅，可带1名同行者。加航高端体验。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'PERK', '{"en": "Annual Companion Pass", "es": "Pase acompañante anual", "fr": "Billet accompagnateur annuel", "ja": "年間コンパニオンパス", "ko": "연간 동반자 패스", "zh": "年度同行票"}', '{"en": "Get a companion pass ($99 + taxes) after spending $25,000/year. Fly together for less.", "es": "Obtén pase acompañante ($99 + impuestos) después de $25,000/año. Vuela juntos por menos.", "fr": "Obtenez un billet accompagnateur (99 $ + taxes) après 25 000 $/an. Voyagez ensemble à moindre coût.", "ja": "年間$25,000利用後にコンパニオンパス（$99+税）取得。お得に一緒に飛行。", "ko": "연간 $25,000 사용 후 동반자 패스($99+세금) 획득. 함께 저렴하게 비행.", "zh": "年消费$25,000后可获同行票（$99+税费）。一起飞行更省钱。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'PERK', '{"en": "Priority Check-in & Boarding", "es": "Check-in y embarque prioritario", "fr": "Enregistrement et embarquement prioritaires", "ja": "優先チェックイン・搭乗", "ko": "우선 체크인 및 탑승", "zh": "优先值机和登机"}', '{"en": "Priority check-in, boarding, and baggage handling for you and up to 8 companions on Air Canada.", "es": "Check-in, embarque y manejo de equipaje prioritario para ti y hasta 8 acompañantes en Air Canada.", "fr": "Enregistrement, embarquement et bagages prioritaires pour vous et 8 accompagnateurs sur Air Canada.", "ja": "エアカナダで本人と最大8名が優先チェックイン・搭乗・手荷物取扱。", "ko": "에어캐나다에서 본인과 최대 8명의 동반자 우선 체크인, 탑승, 수하물 처리.", "zh": "本人及最多8名同行者可享加航优先值机、登机和行李处理。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'PERK', '{"en": "Up to 85,000 Points", "es": "Hasta 85,000 puntos", "fr": "Jusqu''à 85 000 points", "ja": "最大85,000ポイント", "ko": "최대 85,000 포인트", "zh": "最高85,000积分"}', '{"en": "20,000 pts on first purchase + 35,000 after $12K/180 days + 30,000 anniversary bonus. Up to $3,000 value.", "es": "20,000 pts en primera compra + 35,000 tras $12K/180 días + 30,000 aniversario. Hasta $3,000 de valor.", "fr": "20 000 pts au 1er achat + 35 000 après 12 K$/180 jours + 30 000 anniversaire. Valeur jusqu''à 3 000 $.", "ja": "初回20,000pt + $12K/180日後35,000pt + 30,000pt周年ボーナス。最大$3,000相当。", "ko": "첫 구매 20,000pt + $12K/180일 후 35,000pt + 30,000pt 주년 보너스. 최대 $3,000 가치.", "zh": "首次消费20,000积分 + $12K/180天后35,000积分 + 30,000周年奖励。价值高达$3,000。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'PERK', '{"en": "6 Global Lounge Visits", "es": "6 visitas salon global", "fr": "6 visites salon mondial", "ja": "6回のグローバルラウンジ", "ko": "6회 글로벌 라운지", "zh": "6次全球贵宾厅"}', '{"en": "6 complimentary worldwide airport lounge visits annually. Use at non-Air Canada airports.", "es": "6 visitas anuales gratuitas a salones de aeropuerto mundiales. Úsalas fuera de Air Canada.", "fr": "6 visites gratuites aux salons d''aéroport mondiaux par an. Utilisez hors aéroports Air Canada.", "ja": "年6回の世界空港ラウンジ無料利用。エアカナダ以外の空港で使用。", "ko": "연간 6회 전 세계 공항 라운지 무료 이용. 에어캐나다 외 공항에서 사용.", "zh": "每年6次免费全球机场贵宾厅。可在非加航机场使用。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Aeroplan Visa Infinite Privilege'), 'STACKING', '{"en": "Earn Points Twice", "es": "Gana puntos dobles", "fr": "Gagnez deux fois", "ja": "ポイント二重取り", "ko": "포인트 이중 적립", "zh": "双重积分"}', '{"en": "Double dip at 150+ Aeroplan partners and 200+ eStore retailers. Card points + member points.", "es": "Puntos dobles en 150+ socios Aeroplan y 200+ tiendas eStore. Puntos tarjeta + miembro.", "fr": "Double points chez 150+ partenaires Aeroplan et 200+ détaillants eStore. Points carte + membre.", "ja": "150以上のAeroplan提携店と200以上のeStoreで二重取り。カード+会員ポイント。", "ko": "150+ Aeroplan 파트너와 200+ eStore에서 이중 적립. 카드 + 회원 포인트.", "zh": "在150+Aeroplan合作商家和200+网上商城双重积分。卡积分+会员积分。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'AVOID', '{"en": "Only 0.5% Outside Categories", "es": "Solo 0.5% fuera de categorías", "fr": "Seulement 0,5 % hors catégories", "ja": "カテゴリ外は0.5%のみ", "ko": "카테고리 외 0.5%만", "zh": "类别外仅0.5%"}', '{"en": "Only 0.5% on purchases outside bonus categories. Best paired with a flat-rate card for other spending.", "es": "Solo 0.5% fuera de categorías bonus. Mejor combinada con tarjeta de tasa fija para otros gastos.", "fr": "Seulement 0,5 % hors catégories. Mieux combinée avec une carte à taux fixe pour autres dépenses.", "ja": "カテゴリ外は0.5%のみ。その他の支出にはフラットレートカードと併用を。", "ko": "카테고리 외 0.5%만. 기타 지출에는 정액 카드와 병행 권장.", "zh": "奖励类别以外的消费仅获0.5%。建议搭配无上限2%卡使用。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'AVOID', '{"en": "Basic Insurance Only", "es": "Solo seguro básico", "fr": "Assurance de base seulement", "ja": "基本保険のみ", "ko": "기본 보험만", "zh": "仅基础保险"}', '{"en": "Only purchase protection and extended warranty. No travel insurance included; available as optional add-on.", "es": "Solo protección de compras y garantía extendida. Sin seguro de viaje; disponible como complemento.", "fr": "Seulement protection achats et garantie prolongée. Pas d''assurance voyage incluse; option payante.", "ja": "購入保護と延長保証のみ。旅行保険なし；オプションで追加可能。", "ko": "구매 보호 및 연장 보증만. 여행 보험 미포함; 옵션으로 추가 가능.", "zh": "仅有购物保障和延保。不含旅行保险；可选择付费添加。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'BEST_USE', '{"en": "1% on Everyday Spending", "es": "1% en gastos diarios", "fr": "1 % sur dépenses quotidiennes", "ja": "日常支出で1%", "ko": "일상 지출 1%", "zh": "日常消费1%返现"}', '{"en": "Earn 1% on groceries, gas, EV charging, transit, recurring bills, streaming, and digital gaming.", "es": "Gana 1% en supermercados, gas, carga EV, transporte, facturas, streaming y juegos digitales.", "fr": "Gagnez 1 % sur épicerie, essence, recharge VE, transport, factures, streaming et jeux numériques.", "ja": "食料品、ガス、EV充電、交通、固定費、ストリーミング、デジタルゲームで1%。", "ko": "식료품, 주유, EV 충전, 교통, 정기 청구, 스트리밍, 디지털 게임에서 1%.", "zh": "超市、加油、电动车充电、交通、固定账单、流媒体和数字游戏消费获1%返现。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'BEST_USE', '{"en": "1% on Recurring Bills", "es": "1% en facturas recurrentes", "fr": "1 % sur factures récurrentes", "ja": "固定費で1%", "ko": "정기 청구 1%", "zh": "固定账单1%返现"}', '{"en": "Set up recurring bills (phone, internet, utilities) on this card for automatic 1% cash back.", "es": "Configura facturas recurrentes (teléfono, internet, servicios) para 1% automático.", "fr": "Configurez les factures récurrentes (téléphone, internet, services publics) pour 1 % automatique.", "ja": "固定費（電話、インターネット、公共料金）をこのカードで自動引落して1%獲得。", "ko": "정기 청구(전화, 인터넷, 공과금)를 이 카드로 설정하여 자동 1% 캐시백.", "zh": "将固定账单（电话、网络、水电）设为自动扣款，自动获1%返现。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'INSURANCE', '{"en": "Purchase Protection", "es": "Protección de compras", "fr": "Protection des achats", "ja": "購入保護", "ko": "구매 보호", "zh": "购物保障"}', '{"en": "Purchase security (90 days for stolen/damaged items) and extended warranty protection included.", "es": "Seguridad de compras (90 días para artículos robados/dañados) y garantía extendida incluidas.", "fr": "Sécurité d''achat (90 jours pour articles volés/endommagés) et garantie prolongée incluses.", "ja": "購入保護（90日間の盗難/破損）と延長保証付き。", "ko": "구매 보호(90일간 도난/파손 물품) 및 연장 보증 포함.", "zh": "购物保障（90天内被盗/损坏物品）和延长保修保护。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee ever. Great starter card for building credit with cash back rewards.", "es": "Sin cuota anual nunca. Gran tarjeta inicial para construir crédito con cashback.", "fr": "Aucun frais annuel. Excellente carte de départ pour bâtir son crédit avec remises.", "ja": "年会費永久無料。信用構築に最適なスターターカード。", "ko": "연회비 영구 무료. 신용 구축에 좋은 스타터 카드.", "zh": "永久免年费。非常适合作为建立信用记录的起步卡。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'PERK', '{"en": "$50 Welcome Bonus", "es": "Bono de $50", "fr": "Bonus de 50 $", "ja": "$50ウェルカムボーナス", "ko": "$50 웰컴 보너스", "zh": "$50欢迎奖励"}', '{"en": "$10 on first purchase + $40 after spending $1,500 in 3 months. Easy to earn on a no-fee card.", "es": "$10 en primera compra + $40 tras $1,500 en 3 meses. Fácil de ganar en tarjeta sin cuota.", "fr": "10 $ au 1er achat + 40 $ après 1 500 $ en 3 mois. Facile à gagner sur une carte sans frais.", "ja": "初回購入$10 + 3ヶ月で$1,500利用後$40。年会費無料カードで簡単に獲得。", "ko": "첫 구매 $10 + 3개월 내 $1,500 사용 시 $40. 무료 카드에서 쉽게 획득.", "zh": "首次消费$10 + 3个月内消费$1,500再获$40。免年费卡中很容易达成。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'PERK', '{"en": "Cash Back Never Expires", "es": "Cashback nunca expira", "fr": "Remise n''expire jamais", "ja": "キャッシュバック無期限", "ko": "캐시백 만료 없음", "zh": "返现永不过期"}', '{"en": "Cash Back Dollars never expire while your account remains open and in good standing.", "es": "El cashback nunca expira mientras la cuenta esté abierta y en buen estado.", "fr": "Les remises n''expirent jamais tant que le compte reste ouvert et en règle.", "ja": "アカウントが有効である限り、キャッシュバックは無期限。", "ko": "계정이 정상 상태로 유지되는 한 캐시백 만료 없음.", "zh": "只要账户保持正常状态，返现永不过期。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'PERK', '{"en": "Mobile Wallet Ready", "es": "Compatible con billetera móvil", "fr": "Compatible portefeuille mobile", "ja": "モバイルウォレット対応", "ko": "모바일 월렛 지원", "zh": "支持移动钱包"}', '{"en": "Works with Apple Pay, Google Pay, and Samsung Pay for convenient contactless payments.", "es": "Funciona con Apple Pay, Google Pay y Samsung Pay para pagos sin contacto.", "fr": "Compatible Apple Pay, Google Pay et Samsung Pay pour paiements sans contact.", "ja": "Apple Pay、Google Pay、Samsung Pay対応で便利な非接触決済。", "ko": "Apple Pay, Google Pay, Samsung Pay 지원으로 편리한 비접촉 결제.", "zh": "支持Apple Pay、Google Pay和Samsung Pay便捷非接触支付。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'REDEMPTION', '{"en": "Redeem Anytime", "es": "Canjea cuando quieras", "fr": "Échangez à tout moment", "ja": "いつでも交換", "ko": "언제든지 교환", "zh": "随时兑换"}', '{"en": "Redeem Cash Back Dollars anytime to pay down your account balance. No minimum required.", "es": "Canjea cashback cuando quieras para pagar tu saldo. Sin mínimo requerido.", "fr": "Échangez vos remises à tout moment pour réduire votre solde. Pas de minimum requis.", "ja": "キャッシュバックはいつでも残高支払いに交換可能。最低額なし。", "ko": "캐시백을 언제든지 잔액 결제에 사용 가능. 최소 금액 없음.", "zh": "随时可将返现抵扣账单余额。无最低兑换金额。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa'), 'STACKING', '{"en": "Good Starter Card", "es": "Buena tarjeta inicial", "fr": "Bonne carte de départ", "ja": "良いスターターカード", "ko": "좋은 스타터 카드", "zh": "优质起步卡"}', '{"en": "Great for building credit. Consider upgrading to Cash Back Visa Infinite for 3% groceries when ready.", "es": "Ideal para construir crédito. Considera mejorar a Cash Back Visa Infinite para 3% en supermercados.", "fr": "Idéale pour bâtir son crédit. Passez à Cash Back Visa Infinite pour 3 % épicerie quand prêt.", "ja": "信用構築に最適。準備ができたらCash Back Visa Infiniteにアップグレードして食料品3%に。", "ko": "신용 구축에 최적. 준비되면 Cash Back Visa Infinite로 업그레이드하여 식료품 3%.", "zh": "非常适合建立信用记录。条件成熟后可升级到Cash Back Visa Infinite享超市3%。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa Infinite'), 'AVOID', '{"en": "$139 Annual Fee After Year 1", "es": "$139 después del año 1", "fr": "139 $ après la 1re année", "ja": "2年目以降$139年会費", "ko": "1년 후 $139 연회비", "zh": "第二年起$139年费"}', '{"en": "Annual fee of $139 applies after first year. Need ~$4,633 in 3% spending to break even on fee.", "es": "Cuota de $139 después del primer año. Necesitas ~$4,633 en gastos 3% para compensar.", "fr": "Frais de 139 $ après la 1re année. Besoin d''environ 4 633 $ en 3 % pour rentabiliser.", "ja": "初年度以降$139年会費。手数料回収には3%カテゴリで約$4,633必要。", "ko": "첫해 이후 $139 연회비. 수수료 상쇄에 3% 카테고리에서 ~$4,633 필요.", "zh": "首年后年费$139。需在3%类别消费约$4,633才能回本。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa Infinite'), 'BEST_USE', '{"en": "3% on Everyday Categories", "es": "3% en categorías diarias", "fr": "3 % sur catégories quotidiennes", "ja": "日常カテゴリで3%", "ko": "일상 카테고리 3%", "zh": "日常类别3%返现"}', '{"en": "Earn 3% on groceries, gas, EV charging, transit, recurring bills, and streaming. Top-tier everyday card.", "es": "Gana 3% en supermercados, gas, carga EV, transporte, facturas y streaming. Tarjeta diaria de primer nivel.", "fr": "Gagnez 3 % sur épicerie, essence, recharge VE, transport, factures et streaming. Carte quotidienne haut de gamme.", "ja": "食料品、ガス、EV充電、交通、固定費、ストリーミングで3%。最高の日常カード。", "ko": "식료품, 주유, EV 충전, 교통, 정기 청구, 스트리밍에서 3%. 최고의 일상 카드.", "zh": "超市、加油、电动车充电、交通、固定账单和流媒体均获3%返现。顶级日常消费卡。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'Cash Back Visa Infinite'), 'BEST_USE', '{"en": "3% on Groceries", "es": "3% en supermercados", "fr": "3 % sur épicerie", "ja": "食料品で3%", "ko": "식료품 3%", "zh": "超市3%返现"}', '{"en": "One of the best no-cap grocery rates in Canada. Great for families with high grocery spending.", "es": "Una de las mejores tasas de supermercado sin límite en Canadá. Ideal para familias con alto gasto.", "fr": "L''un des meilleurs taux épicerie sans plafond au Canada. Idéal pour familles à dépenses élevées.", "ja": "カナダで最高の食料品レート（上限なし）の一つ。食料品支出の多い家庭に最適。", "ko": "캐나다 최고의 무제한 식료품 적립률. 식료품 지출이 많은 가정에 최적.", "zh": "加拿大超市返现率最高之一，无上限。适合超市消费高的家庭。"}', NULL, 9, 1;
