INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'First Class Visa Infinite'), 'PERK', '{"en": "$100 Annual Travel Credit", "es": "$100 crédito viaje anual", "fr": "100 $ crédit voyage annuel", "ja": "年間$100トラベルクレジット", "ko": "연간 $100 여행 크레딧", "zh": "年度$100旅行信用"}', '{"en": "Get $100 TD Travel Credit annually when booking through Expedia for TD. Offsets annual fee.", "es": "$100 crédito viaje anual al reservar vía Expedia para TD. Compensa la cuota anual.", "fr": "100 $ crédit voyage annuel via Expedia pour TD. Compense les frais annuels.", "ja": "Expedia for TD予約で年$100トラベルクレジット。年会費を相殺。", "ko": "Expedia for TD 예약 시 연간 $100 여행 크레딧. 연회비 상쇄.", "zh": "每年通过Expedia TD预订可获$100旅行信用。可抵消年费。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'First Class Visa Infinite'), 'PERK', '{"en": "4 Free Lounge Visits", "es": "4 visitas sala gratis", "fr": "4 visites salon gratuites", "ja": "4回の無料ラウンジ", "ko": "4회 무료 라운지", "zh": "4次免费贵宾厅"}', '{"en": "4 complimentary airport lounge visits via Visa Airport Companion. Access to 1,200+ global lounges.", "es": "4 visitas gratuitas vía Visa Airport Companion. Acceso a 1,200+ salas globales.", "fr": "4 visites salon gratuites via Visa Airport Companion. Accès à 1 200+ salons mondiaux.", "ja": "Visa Airport Companionで4回の無料ラウンジ。1,200以上のグローバルラウンジにアクセス。", "ko": "Visa Airport Companion으로 4회 무료 라운지. 1,200+ 글로벌 라운지 이용.", "zh": "通过Visa Airport Companion获4次免费机场贵宾厅。可进入全球1,200+贵宾厅。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'First Class Visa Infinite'), 'PERK', '{"en": "Birthday Bonus Points", "es": "Puntos bonus cumpleaños", "fr": "Points bonus anniversaire", "ja": "誕生日ボーナスポイント", "ko": "생일 보너스 포인트", "zh": "生日奖励积分"}', '{"en": "Earn up to 10,000 additional TD Rewards points as a birthday bonus each year.", "es": "Gana hasta 10,000 puntos adicionales como bono de cumpleaños cada año.", "fr": "Gagnez jusqu''à 10 000 points supplémentaires en bonus d''anniversaire chaque année.", "ja": "毎年誕生日ボーナスとして最大10,000追加ポイント獲得。", "ko": "매년 생일 보너스로 최대 10,000 추가 포인트 획득.", "zh": "每年生日可获最高10,000额外TD积分奖励。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'First Class Visa Infinite'), 'PERK', '{"en": "First Year Fee Waived", "es": "Primer año gratis", "fr": "1re année gratuite", "ja": "初年度年会費無料", "ko": "첫해 연회비 면제", "zh": "首年年费减免"}', '{"en": "$139 annual fee waived first year. Also rebated with TD All-Inclusive Banking Plan.", "es": "Cuota de $139 exonerada el primer año. También con TD All-Inclusive Banking Plan.", "fr": "Frais de 139 $ exonérés la 1re année. Aussi remboursés avec forfait TD tout inclus.", "ja": "初年度$139年会費無料。TD全包プランでも毎年リベート。", "ko": "첫해 $139 연회비 면제. TD 올인클루시브 플랜에서도 환급.", "zh": "首年$139年费减免。持有TD全包银行计划也可每年减免。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'TD' AND name = 'First Class Visa Infinite'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem for Expedia travel, Pay off Purchases, balance payments, Amazon, or Starbucks.", "es": "Canjea por viajes Expedia, compras, pagos, Amazon o Starbucks.", "fr": "Échangez pour voyages Expedia, achats, paiements, Amazon ou Starbucks.", "ja": "Expedia旅行、購入、残高支払い、Amazon、Starbucksに交換。", "ko": "Expedia 여행, 구매, 잔액 결제, Amazon, Starbucks로 교환.", "zh": "可兑换Expedia旅行、抵扣消费、账单支付、亚马逊或星巴克。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Classic'), 'AVOID', '{"en": "1 Point per $2 Base Rate", "es": "1 punto por $2 base", "fr": "1 point par 2 $ de base", "ja": "基本$2につき1ポイント", "ko": "기본 $2당 1포인트", "zh": "基础每$2赚1积分"}', '{"en": "Base rate is 1 point per $2 spent (0.5% effective). Lower than many no-fee cashback cards.", "es": "Tasa base 1 punto por $2 (0.5% efectivo). Menor que muchas tarjetas sin cuota.", "fr": "Taux de base 1 point par 2 $ (0,5 % effectif). Inférieur à plusieurs cartes sans frais.", "ja": "基本レートは$2につき1ポイント（実質0.5%）。多くの年会費無料カードより低い。", "ko": "기본 적립률 $2당 1포인트 (실질 0.5%). 많은 무료 카드보다 낮음.", "zh": "基础积分率为每$2赚1积分（有效0.5%）。低于许多免年费返现卡。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Classic'), 'AVOID', '{"en": "BC Residents Only", "es": "Solo residentes BC", "fr": "Résidents C.-B. seulement", "ja": "BC州居住者のみ", "ko": "BC 거주자 전용", "zh": "仅BC省居民"}', '{"en": "Only available to residents of British Columbia. Must be a Vancity member to apply.", "es": "Solo disponible para residentes de BC. Debe ser miembro de Vancity para aplicar.", "fr": "Disponible uniquement pour résidents de C.-B. Être membre Vancity requis.", "ja": "BC州居住者のみ利用可能。申請にはVancity会員が必要。", "ko": "BC 거주자만 이용 가능. 신청하려면 Vancity 회원이어야 함.", "zh": "仅限BC省居民申请。需成为Vancity会员才能申请。"}', NULL, 3, 1;
