INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Classic'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem for cash back, travel, charitable donations, or gift cards. 1 point = 1 cent.", "es": "Canjea por cashback, viajes, donaciones o tarjetas regalo. 1 punto = 1 centavo.", "fr": "Échangez contre remises, voyages, dons caritatifs ou cartes-cadeaux. 1 point = 1 ¢.", "ja": "キャッシュバック、旅行、寄付、ギフトカードに交換。1ポイント=1セント。", "ko": "캐시백, 여행, 기부, 기프트 카드로 교환. 1포인트 = 1센트.", "zh": "可兑换返现、旅行、慈善捐款或礼品卡。1积分=1分钱。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Classic'), 'STACKING', '{"en": "Best for Eco-Conscious", "es": "Ideal para eco-conscientes", "fr": "Idéal pour éco-conscients", "ja": "エコ意識の高い人に最適", "ko": "친환경 의식 있는 분에게 최적", "zh": "最适合环保人士"}', '{"en": "Choose this card if environmental impact matters more than maximizing rewards. Pair with higher-rate card for daily spending.", "es": "Elige si el impacto ambiental importa más que maximizar recompensas.", "fr": "Choisissez si l''impact environnemental compte plus que maximiser les récompenses.", "ja": "報酬最大化より環境影響を重視するならこのカードを。日常支出には高レートカードと併用。", "ko": "보상 극대화보다 환경 영향이 중요하다면 이 카드를 선택. 일상 지출에는 고적립 카드와 병행.", "zh": "如果环保影响比最大化奖励更重要，选择此卡。日常消费可搭配高返现卡。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'AVOID', '{"en": "$120 Annual Fee", "es": "Cuota anual $120", "fr": "Frais annuels 120 $", "ja": "年会費$120", "ko": "연회비 $120", "zh": "年费$120"}', '{"en": "$120 annual fee after first year. Waived with Total Chequing Account. BC residents only.", "es": "$120 después del primer año. Exonerado con Total Chequing Account. Solo residentes de BC.", "fr": "120 $ après la 1re année. Exonérés avec compte Total Chequing. Résidents C.-B. seulement.", "ja": "初年度以降$120年会費。Total Chequing口座で免除。BC州居住者のみ。", "ko": "첫해 이후 $120 연회비. Total Chequing 계좌로 면제. BC 거주자 전용.", "zh": "首年后年费$120。持有Total Chequing账户可免年费。仅限BC省居民。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'BEST_USE', '{"en": "5x on Transit & Ferries", "es": "5x transporte y ferries", "fr": "5x transport et traversiers", "ja": "交通/フェリーで5倍", "ko": "교통/페리 5배", "zh": "交通/渡轮5倍积分"}', '{"en": "Earn 5 points per $1 (5% value) on public transit and BC Ferries. Best transit card in Canada.", "es": "Gana 5 puntos por $1 (5% valor) en transporte público y BC Ferries. Mejor tarjeta de transporte en Canadá.", "fr": "Gagnez 5 points par $ (5 % valeur) sur transports publics et BC Ferries. Meilleure carte transport au Canada.", "ja": "公共交通とBCフェリーで$1につき5ポイント（5%価値）。カナダ最高の交通カード。", "ko": "대중교통과 BC 페리에서 $1당 5포인트 (5% 가치). 캐나다 최고의 교통 카드.", "zh": "公共交通和BC渡轮每$1赚5积分（5%价值）。加拿大最佳交通卡。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'BEST_USE', '{"en": "10x at Local Partners", "es": "10x socios locales", "fr": "10x partenaires locaux", "ja": "地元パートナーで10倍", "ko": "지역 파트너 10배", "zh": "本地合作商家10倍积分"}', '{"en": "Earn 10 points per $1 (10% value) at Modo carshare, JJ Bean coffee, Fresh Prep meals, and more BC partners.", "es": "Gana 10 puntos por $1 (10% valor) en Modo, JJ Bean, Fresh Prep y otros socios de BC.", "fr": "Gagnez 10 points par $ (10 % valeur) chez Modo, JJ Bean, Fresh Prep et autres partenaires C.-B.", "ja": "Modo、JJ Bean、Fresh PrepなどBCパートナーで$1につき10ポイント（10%価値）。", "ko": "Modo, JJ Bean, Fresh Prep 등 BC 파트너에서 $1당 10포인트 (10% 가치).", "zh": "在Modo汽车共享、JJ Bean咖啡、Fresh Prep等BC合作商家每$1赚10积分（10%价值）。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'BEST_USE', '{"en": "2.5x on Groceries", "es": "2.5x supermercados", "fr": "2,5x épicerie", "ja": "食料品で2.5倍", "ko": "식료품 2.5배", "zh": "超市2.5倍积分"}', '{"en": "Earn 2.5 points per $1 (2.5% value) on groceries. Strong return for everyday food shopping.", "es": "Gana 2.5 puntos por $1 (2.5% valor) en supermercados. Buen retorno para compras diarias.", "fr": "Gagnez 2,5 points par $ (2,5 % valeur) sur l''épicerie. Bon rendement pour achats alimentaires.", "ja": "食料品で$1につき2.5ポイント（2.5%価値）。日常の食品買い物に高いリターン。", "ko": "식료품에서 $1당 2.5포인트 (2.5% 가치). 일상 식품 쇼핑에 높은 적립.", "zh": "超市消费每$1赚2.5积分（2.5%价值）。日常食品采购的高回报。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'INSURANCE', '{"en": "Premium Insurance", "es": "Seguro premium", "fr": "Assurance premium", "ja": "プレミアム保険", "ko": "프리미엄 보험", "zh": "高端保险"}', '{"en": "Travel accident $500K, rental car, delayed/lost baggage, trip cancellation, extended warranty, mobile device $1,000.", "es": "Accidente viaje $500K, alquiler auto, equipaje, cancelación, garantía extendida, móvil $1,000.", "fr": "Accident voyage 500 K$, location auto, bagages, annulation, garantie prolongée, mobile 1 000 $.", "ja": "旅行事故$50万、レンタカー、手荷物、キャンセル、延長保証、モバイル$1,000。", "ko": "여행 사고 $50만, 렌터카, 수하물, 취소, 연장 보증, 모바일 $1,000.", "zh": "旅行意外$50万、租车、行李延误/丢失、行程取消、延保、手机$1,000。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'PERK', '{"en": "Airport Lounge Access", "es": "Acceso a salas", "fr": "Accès salon aéroport", "ja": "空港ラウンジ", "ko": "공항 라운지", "zh": "机场贵宾厅"}', '{"en": "Complimentary Visa Airport Companion membership ($90 value). Access global airport lounges.", "es": "Membresía Visa Airport Companion gratis ($90 valor). Acceso a salas de aeropuerto globales.", "fr": "Adhésion Visa Airport Companion gratuite (valeur 90 $). Accès aux salons d''aéroport mondiaux.", "ja": "Visa Airport Companion会員資格無料（$90相当）。世界の空港ラウンジにアクセス。", "ko": "Visa Airport Companion 멤버십 무료 ($90 가치). 전 세계 공항 라운지 이용.", "zh": "免费Visa Airport Companion会员资格（价值$90）。可进入全球机场贵宾厅。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'PERK', '{"en": "18,000 Point Bonus", "es": "Bono de 18,000 puntos", "fr": "Bonus de 18 000 points", "ja": "18,000ポイントボーナス", "ko": "18,000 포인트 보너스", "zh": "18,000积分奖励"}', '{"en": "5,000 pts on first purchase + 13,000 pts after $3,000 in 3 months. First year $120 fee waived.", "es": "5,000 pts en primera compra + 13,000 pts tras $3,000 en 3 meses. Cuota de $120 exonerada el primer año.", "fr": "5 000 pts au 1er achat + 13 000 pts après 3 000 $ en 3 mois. Frais de 120 $ exonérés la 1re année.", "ja": "初回5,000pt + 3ヶ月$3,000後13,000pt。初年度$120年会費無料。", "ko": "첫 구매 5,000pt + 3개월 $3,000 후 13,000pt. 첫해 $120 연회비 면제.", "zh": "首次消费5,000积分 + 3个月$3,000后获13,000积分。首年$120年费减免。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'PERK', '{"en": "Eco-Friendly Choice", "es": "Opción ecológica", "fr": "Choix écologique", "ja": "エコフレンドリー", "ko": "친환경 선택", "zh": "环保之选"}', '{"en": "5% of card profits go to Vancity enviroFund supporting environmental initiatives in BC.", "es": "5% de ganancias va al enviroFund Vancity para iniciativas ambientales en BC.", "fr": "5 % des profits vont au enviroFund Vancity pour initiatives environnementales en C.-B.", "ja": "利益の5%がBC州の環境イニシアチブを支援するVancity enviroFundへ。", "ko": "카드 수익의 5%가 BC 환경 이니셔티브를 지원하는 Vancity enviroFund로.", "zh": "5%卡片利润捐给Vancity环保基金，支持BC省环保项目。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'PERK', '{"en": "Hotel & Dining Perks", "es": "Beneficios hotel y restaurante", "fr": "Avantages hôtel et resto", "ja": "ホテル・ダイニング特典", "ko": "호텔 및 다이닝 혜택", "zh": "酒店和餐饮特权"}', '{"en": "Hotel upgrades, late checkout, dining events, Sandman Platinum status, and 24/7 concierge.", "es": "Upgrades hotel, late checkout, eventos gastronómicos, estatus Sandman Platino y concierge 24/7.", "fr": "Surclassements hôtel, départ tardif, événements restos, statut Sandman Platine et concierge 24/7.", "ja": "ホテルアップグレード、レイトチェックアウト、ダイニングイベント、Sandmanプラチナ、24時間コンシェルジュ。", "ko": "호텔 업그레이드, 레이트 체크아웃, 다이닝 이벤트, Sandman 플래티넘, 24시간 컨시어지.", "zh": "酒店升级、延迟退房、餐饮活动、Sandman白金会员和24/7礼宾服务。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'REDEMPTION', '{"en": "Flexible Redemption", "es": "Canje flexible", "fr": "Échange flexible", "ja": "柔軟な交換", "ko": "유연한 교환", "zh": "灵活兑换"}', '{"en": "Redeem for cash back, travel, charitable donations, or gift cards. 1 point = 1 cent value.", "es": "Canjea por cashback, viajes, donaciones o tarjetas regalo. 1 punto = 1 centavo.", "fr": "Échangez contre remises, voyages, dons caritatifs ou cartes-cadeaux. 1 point = 1 ¢.", "ja": "キャッシュバック、旅行、寄付、ギフトカードに交換。1ポイント=1セント。", "ko": "캐시백, 여행, 기부, 기프트 카드로 교환. 1포인트 = 1센트.", "zh": "可兑换返现、旅行、慈善捐款或礼品卡。1积分=1分钱价值。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Vancity' AND name = 'enviro Visa Infinite'), 'STACKING', '{"en": "Best for BC Commuters", "es": "Ideal para commuters BC", "fr": "Idéal pour navetteurs C.-B.", "ja": "BC通勤者に最適", "ko": "BC 통근자에게 최적", "zh": "最适合BC通勤族"}', '{"en": "If you commute by transit in BC, this is one of Canada''s best cards. 5% on transit + local partner bonuses.", "es": "Si usas transporte en BC, es una de las mejores tarjetas de Canadá. 5% transporte + bonos socios locales.", "fr": "Si vous utilisez les transports en C.-B., c''est l''une des meilleures cartes au Canada. 5 % transport + bonus partenaires.", "ja": "BCで公共交通通勤なら、カナダ最高のカードの一つ。交通5% + 地元パートナーボーナス。", "ko": "BC에서 대중교통 출퇴근 시 캐나다 최고의 카드 중 하나. 교통 5% + 지역 파트너 보너스.", "zh": "如果您在BC乘公共交通通勤，这是加拿大最佳卡之一。交通5% + 本地合作商家奖励。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'AVOID', '{"en": "1% Base Rate", "es": "Tasa base 1%", "fr": "Taux de base 1 %", "ja": "基本1%還元", "ko": "기본 1% 적립", "zh": "基础1%返现"}', '{"en": "Only 1% back on non-Walmart purchases. Use a different card for higher rewards elsewhere.", "es": "Solo 1% en compras fuera de Walmart. Usa otra tarjeta para mejores recompensas en otros lugares.", "fr": "Seulement 1 % sur achats hors Walmart. Utilisez une autre carte pour plus de récompenses ailleurs.", "ja": "ウォルマート以外は1%のみ。他店では別のカードで高還元を。", "ko": "월마트 외 구매는 1%만. 다른 곳에서는 고적립 카드 사용 권장.", "zh": "非沃尔玛消费仅1%返现。在其他地方消费请使用其他高返现卡。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'AVOID', '{"en": "Walmart-Only Rewards", "es": "Recompensas solo Walmart", "fr": "Récompenses Walmart seulement", "ja": "ウォルマート専用特典", "ko": "월마트 전용 보상", "zh": "仅限沃尔玛使用"}', '{"en": "Walmart Reward Dollars can only be redeemed at Walmart. No cash back or transfer options.", "es": "Los Dólares de Recompensa solo se canjean en Walmart. Sin opción de efectivo o transferencia.", "fr": "Les Dollars Récompenses ne sont utilisables que chez Walmart. Pas de remise ou transfert.", "ja": "ウォルマートリワードドルはウォルマートでのみ使用可能。現金化・移行不可。", "ko": "월마트 리워드 달러는 월마트에서만 사용 가능. 현금화 또는 이전 불가.", "zh": "沃尔玛奖励金只能在沃尔玛使用。无法兑换现金或转移。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'BEST_USE', '{"en": "3% at Walmart", "es": "3% en Walmart", "fr": "3 % chez Walmart", "ja": "ウォルマートで3%", "ko": "월마트 3%", "zh": "沃尔玛3%返现"}', '{"en": "Earn 3% Walmart Reward Dollars at all Walmart stores and walmart.ca. Best for regular Walmart shoppers.", "es": "Gana 3% en Dólares de Recompensa en tiendas Walmart y walmart.ca. Ideal para compradores regulares.", "fr": "Gagnez 3 % en Dollars Récompenses chez Walmart et walmart.ca. Idéal pour les clients réguliers.", "ja": "全Walmart店舗とwalmart.caで3%ウォルマートリワードドル獲得。定期的な買い物客に最適。", "ko": "모든 월마트 매장과 walmart.ca에서 3% 월마트 리워드 달러 적립. 정기 쇼핑객에게 최적.", "zh": "在所有沃尔玛门店和walmart.ca获得3%沃尔玛奖励金。最适合经常购物者。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'BEST_USE', '{"en": "Grocery & Household", "es": "Comestibles y hogar", "fr": "Épicerie et maison", "ja": "食料品・日用品", "ko": "식료품 및 생활용품", "zh": "食品杂货和家居用品"}', '{"en": "Use for all grocery and household purchases at Walmart to maximize your 3% back on everyday essentials.", "es": "Úsala para todas las compras de comestibles y hogar en Walmart para maximizar el 3% en productos esenciales.", "fr": "Utilisez pour tous vos achats d''épicerie et ménagers chez Walmart pour maximiser le 3 % sur les essentiels.", "ja": "ウォルマートでの食料品・日用品購入で、日常必需品の3%還元を最大化。", "ko": "월마트에서 식료품 및 가정용품 구매 시 일상 필수품 3% 적립 극대화.", "zh": "在沃尔玛购买所有食品杂货和家居用品，最大化日常必需品3%返现。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'INSURANCE', '{"en": "Basic Protection", "es": "Protección básica", "fr": "Protection de base", "ja": "基本保護", "ko": "기본 보호", "zh": "基础保障"}', '{"en": "Standard Mastercard purchase protection and zero liability for unauthorized transactions.", "es": "Protección de compras Mastercard estándar y responsabilidad cero por transacciones no autorizadas.", "fr": "Protection achats Mastercard standard et responsabilité zéro pour transactions non autorisées.", "ja": "標準Mastercard購入保護と不正取引のゼロ責任。", "ko": "표준 Mastercard 구매 보호 및 무단 거래에 대한 제로 책임.", "zh": "标准万事达购物保护和未授权交易零责任。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'PERK', '{"en": "$0 Annual Fee", "es": "Sin cuota anual", "fr": "Sans frais annuels", "ja": "年会費無料", "ko": "연회비 무료", "zh": "免年费"}', '{"en": "No annual fee ever. Keep the card as a dedicated Walmart shopping card at zero cost.", "es": "Sin cuota anual nunca. Mantenla como tarjeta dedicada de Walmart sin costo.", "fr": "Aucuns frais annuels. Gardez la carte comme carte Walmart dédiée sans aucun coût.", "ja": "年会費永久無料。コストゼロでウォルマート専用カードとして保持可能。", "ko": "연회비 영구 무료. 비용 없이 월마트 전용 카드로 유지 가능.", "zh": "永久免年费。可零成本保留作为专用沃尔玛购物卡。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'PERK', '{"en": "$25 Welcome Bonus", "es": "Bono de $25", "fr": "Bonus de 25 $", "ja": "$25ウェルカムボーナス", "ko": "$25 웰컴 보너스", "zh": "$25欢迎奖励"}', '{"en": "Earn $25 in Walmart Reward Dollars after spending just $75 in your first 30 days. Easy to earn.", "es": "Gana $25 después de gastar solo $75 en 30 días. Fácil de obtener.", "fr": "Gagnez 25 $ après seulement 75 $ en 30 jours. Facile à obtenir.", "ja": "30日以内に$75利用で$25獲得。達成しやすい条件。", "ko": "30일 내 $75 사용 시 $25 획득. 쉽게 달성 가능.", "zh": "30天内消费$75即可获得$25沃尔玛奖励金。轻松获取。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'PERK', '{"en": "Delivery Pass Benefit", "es": "Beneficio Delivery Pass", "fr": "Avantage Delivery Pass", "ja": "デリバリーパス特典", "ko": "배송 패스 혜택", "zh": "配送通行证优惠"}', '{"en": "Access to Walmart Delivery Pass with unlimited free delivery on groceries and household essentials.", "es": "Acceso a Delivery Pass con entregas gratis ilimitadas en comestibles y esenciales del hogar.", "fr": "Accès au Delivery Pass Walmart avec livraison gratuite illimitée sur épicerie et essentiels.", "ja": "ウォルマートデリバリーパスで食料品・日用品の配送無制限無料。", "ko": "월마트 배송 패스로 식료품 및 생필품 무제한 무료 배송.", "zh": "可享用沃尔玛配送通行证，食品杂货和家居必需品无限免费配送。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'PERK', '{"en": "Mobile Wallet Ready", "es": "Compatible con billetera móvil", "fr": "Compatible portefeuille mobile", "ja": "モバイルウォレット対応", "ko": "모바일 월렛 지원", "zh": "支持移动钱包"}', '{"en": "Works with Apple Pay, Google Pay, and Mastercard Tap for convenient contactless payments.", "es": "Funciona con Apple Pay, Google Pay y Mastercard Tap para pagos sin contacto.", "fr": "Compatible Apple Pay, Google Pay et Mastercard Tap pour paiements sans contact.", "ja": "Apple Pay、Google Pay、Mastercard Tap対応で便利な非接触決済。", "ko": "Apple Pay, Google Pay, Mastercard Tap 지원으로 편리한 비접촉 결제.", "zh": "支持Apple Pay、Google Pay和Mastercard感应支付，便捷非接触式付款。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'REDEMPTION', '{"en": "Instant Redemption", "es": "Canje instantáneo", "fr": "Échange instantané", "ja": "即時交換", "ko": "즉시 교환", "zh": "即时兑换"}', '{"en": "Redeem Walmart Reward Dollars instantly at checkout in-store or online. Minimum $5 redemption.", "es": "Canjea instantáneamente en caja o en línea. Mínimo $5 para canjear.", "fr": "Échangez instantanément en caisse ou en ligne. Minimum 5 $ pour l''échange.", "ja": "店舗またはオンラインでチェックアウト時に即時交換。最低$5から。", "ko": "매장 또는 온라인 결제 시 즉시 교환. 최소 $5부터 교환 가능.", "zh": "在门店或网上结账时即时兑换沃尔玛奖励金。最低$5起兑。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Walmart' AND name = 'Rewards Mastercard'), 'STACKING', '{"en": "Best for Walmart Shoppers", "es": "Ideal para compradores Walmart", "fr": "Idéal pour clients Walmart", "ja": "ウォルマート買い物客に最適", "ko": "월마트 쇼핑객에게 최적", "zh": "最适合沃尔玛购物者"}', '{"en": "If Walmart is your main grocery store, this card is a must. Combine with Delivery Pass for maximum value.", "es": "Si Walmart es tu supermercado principal, esta tarjeta es imprescindible. Combina con Delivery Pass.", "fr": "Si Walmart est votre épicerie principale, cette carte est essentielle. Combinez avec Delivery Pass.", "ja": "ウォルマートが主要な買い物先なら必携。デリバリーパスと組み合わせて最大価値。", "ko": "월마트가 주 식료품점이라면 필수 카드. 배송 패스와 함께 사용하여 최대 가치 실현.", "zh": "如果沃尔玛是您的主要超市，此卡必备。搭配配送通行证获得最大价值。"}', NULL, 0, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'AVOID', '{"en": "$240 Annual Fee", "es": "Cuota anual $240", "fr": "Frais annuels 240 $", "ja": "年会費$240", "ko": "연회비 $240", "zh": "年费$240"}', '{"en": "$240/year ($20/month) if not waived. Need to spend $12,000+ annually to break even on the fee.", "es": "$240/año ($20/mes) si no se exonera. Necesitas gastar $12,000+ al año para cubrir la cuota.", "fr": "240 $/an (20 $/mois) si non exonéré. Dépenser 12 000 $+ par an pour rentabiliser.", "ja": "免除されない場合$240/年($20/月)。年$12,000以上利用で元が取れる。", "ko": "면제되지 않으면 연 $240 (월 $20). 연 $12,000+ 사용해야 손익분기점.", "zh": "未减免时年费$240（月费$20）。需年消费$12,000+才能回本。"}', NULL, 3, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'AVOID', '{"en": "$60K Income Required", "es": "Ingreso $60K requerido", "fr": "Revenu 60 K$ requis", "ja": "年収$6万必要", "ko": "소득 $6만 필요", "zh": "需$6万收入"}', '{"en": "Requires $60K personal income or $100K household income. Must be Canadian resident.", "es": "Requiere ingreso personal de $60K o $100K por hogar. Debe ser residente canadiense.", "fr": "Revenu personnel de 60 K$ ou 100 K$ par ménage requis. Résident canadien requis.", "ja": "個人年収$6万または世帯年収$10万必要。カナダ居住者のみ。", "ko": "개인 소득 $6만 또는 가구 소득 $10만 필요. 캐나다 거주자만 가능.", "zh": "需个人年收入$6万或家庭年收入$10万。需为加拿大居民。"}', NULL, 2, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'BEST_USE', '{"en": "2% on Everything", "es": "2% en todo", "fr": "2 % sur tout", "ja": "全て2%還元", "ko": "모든 구매 2%", "zh": "全部消费2%返现"}', '{"en": "Earn 2% unlimited cash back on all purchases. No categories to track, no caps, no expiry.", "es": "Gana 2% ilimitado en todas las compras. Sin categorías, sin límites, sin vencimiento.", "fr": "Gagnez 2 % illimité sur tous les achats. Pas de catégories, pas de plafond, jamais d''expiration.", "ja": "全ての購入で2%無制限キャッシュバック。カテゴリー追跡不要、上限なし、有効期限なし。", "ko": "모든 구매에서 2% 무제한 캐시백. 카테고리 추적 불필요, 상한 없음, 만료 없음.", "zh": "所有消费无上限2%返现。无需追踪类别，无上限，永不过期。"}', NULL, 10, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'BEST_USE', '{"en": "No FX Fees", "es": "Sin comisión de cambio", "fr": "Sans frais de change", "ja": "外貨手数料無料", "ko": "환전 수수료 없음", "zh": "无外汇手续费"}', '{"en": "No foreign transaction fees on international purchases. Still earn 2% cashback abroad.", "es": "Sin cargos por transacciones extranjeras. Aún ganas 2% en el extranjero.", "fr": "Pas de frais de transaction étrangère. Gagnez toujours 2 % à l''étranger.", "ja": "海外取引手数料なし。海外でも2%キャッシュバック獲得。", "ko": "해외 거래 수수료 없음. 해외에서도 2% 캐시백 적립.", "zh": "国际消费无外汇手续费。海外消费仍享2%返现。"}', NULL, 9, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'INSURANCE', '{"en": "Travel & Purchase Insurance", "es": "Seguro de viaje y compras", "fr": "Assurance voyage et achats", "ja": "旅行・購入保険", "ko": "여행 및 구매 보험", "zh": "旅行和购物保险"}', '{"en": "Trip cancellation, delayed/lost baggage, 90-day purchase protection, extended warranty, and more.", "es": "Cancelación de viaje, equipaje retrasado/perdido, protección de compras 90 días, garantía extendida y más.", "fr": "Annulation voyage, bagages retardés/perdus, protection achats 90 jours, garantie prolongée et plus.", "ja": "旅行キャンセル、手荷物遅延/紛失、90日購入保護、延長保証など。", "ko": "여행 취소, 수하물 지연/분실, 90일 구매 보호, 연장 보증 등.", "zh": "行程取消、行李延误/丢失、90天购物保护、延保等。"}', NULL, 1, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'PERK', '{"en": "Fee Waiver Options", "es": "Opciones de exención", "fr": "Options d''exonération", "ja": "年会費免除オプション", "ko": "연회비 면제 옵션", "zh": "年费减免选项"}', '{"en": "$240 annual fee waived with $100K+ assets on Wealthsimple or $4K+ monthly direct deposit.", "es": "Cuota de $240 exonerada con $100K+ en activos o $4K+ de depósito directo mensual.", "fr": "Frais de 240 $ exonérés avec 100 K$ d''actifs ou 4 K$/mois en dépôt direct.", "ja": "Wealthsimpleに$10万以上の資産または月$4,000以上の直接入金で$240年会費免除。", "ko": "Wealthsimple에 $10만+ 자산 또는 월 $4,000+ 직접 입금 시 $240 연회비 면제.", "zh": "在Wealthsimple拥有$10万+资产或每月$4000+直接存款可免$240年费。"}', NULL, 8, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'PERK', '{"en": "$1M Travel Medical", "es": "$1M médico de viaje", "fr": "1 M$ médical voyage", "ja": "$100万旅行医療", "ko": "$100만 여행 의료", "zh": "$100万旅行医疗"}', '{"en": "Up to $1 million emergency medical coverage for trips up to 14 days when paying with card.", "es": "Hasta $1 millón en cobertura médica de emergencia para viajes de hasta 14 días.", "fr": "Jusqu''à 1 M$ de couverture médicale d''urgence pour voyages jusqu''à 14 jours.", "ja": "カード支払いで最大14日間の旅行に最大$100万の緊急医療保険。", "ko": "카드 결제 시 최대 14일 여행에 최대 $100만 응급 의료 보장.", "zh": "使用此卡支付旅行时，最长14天旅程可获最高$100万紧急医疗保障。"}', NULL, 7, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'PERK', '{"en": "$1,000 Phone Insurance", "es": "$1,000 seguro de teléfono", "fr": "1 000 $ assurance téléphone", "ja": "$1,000携帯保険", "ko": "$1,000 휴대폰 보험", "zh": "$1,000手机保险"}', '{"en": "Up to $1,000 coverage for phone repair or replacement when you pay your phone bill with the card.", "es": "Hasta $1,000 para reparación o reemplazo del teléfono al pagar la factura con la tarjeta.", "fr": "Jusqu''à 1 000 $ pour réparation ou remplacement de téléphone en payant la facture avec la carte.", "ja": "カードで携帯料金を支払うと修理・交換に最大$1,000の保険。", "ko": "카드로 휴대폰 요금 결제 시 수리 또는 교체에 최대 $1,000 보장.", "zh": "使用此卡支付手机账单后，手机维修或更换可获最高$1,000保障。"}', NULL, 6, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'PERK', '{"en": "Visa Infinite Perks", "es": "Beneficios Visa Infinite", "fr": "Avantages Visa Infinite", "ja": "Visa Infinite特典", "ko": "Visa Infinite 혜택", "zh": "Visa无限卡特权"}', '{"en": "Access to Visa Infinite Luxury Hotel Collection (900+ hotels), 24/7 concierge, and premium experiences.", "es": "Acceso a Visa Infinite Luxury Hotel Collection (900+ hoteles), concierge 24/7 y experiencias premium.", "fr": "Accès à Visa Infinite Luxury Hotel Collection (900+ hôtels), concierge 24/7 et expériences premium.", "ja": "Visa Infiniteラグジュアリーホテルコレクション(900+ホテル)、24時間コンシェルジュ、プレミアム体験。", "ko": "Visa Infinite 럭셔리 호텔 컬렉션(900+ 호텔), 24시간 컨시어지, 프리미엄 경험.", "zh": "可享用Visa无限豪华酒店精选(900+酒店)、24/7礼宾服务和尊享体验。"}', NULL, 5, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'PERK', '{"en": "Cashback Earns Interest", "es": "Cashback gana intereses", "fr": "Remise gagne intérêts", "ja": "キャッシュバックに利息", "ko": "캐시백에 이자 적립", "zh": "返现可赚利息"}', '{"en": "Your earned cashback can earn up to 2.25% interest in Wealthsimple Cash. Money earns money.", "es": "Tu cashback puede ganar hasta 2.25% de interés en Wealthsimple Cash.", "fr": "Votre remise peut gagner jusqu''à 2,25 % d''intérêt dans Wealthsimple Cash.", "ja": "獲得したキャッシュバックはWealthsimple Cashで最大2.25%の利息を獲得。", "ko": "적립된 캐시백이 Wealthsimple Cash에서 최대 2.25% 이자를 받을 수 있음.", "zh": "赚取的返现可在Wealthsimple Cash中获得最高2.25%利息。钱生钱。"}', NULL, 4, 1;
INSERT INTO card_usage_tips (card_id, tip_type, title_json, content_json, icon, priority, is_active) SELECT (SELECT id FROM credit_cards WHERE bank = 'Wealthsimple' AND name = 'Visa Infinite'), 'STACKING', '{"en": "Best for Wealthsimple Users", "es": "Ideal para usuarios Wealthsimple", "fr": "Idéal pour utilisateurs Wealthsimple", "ja": "Wealthsimpleユーザーに最適", "ko": "Wealthsimple 사용자에게 최적", "zh": "最适合Wealthsimple用户"}', '{"en": "If you already use Wealthsimple for investing/banking, get the fee waived and enjoy 2% on everything.", "es": "Si ya usas Wealthsimple, obtén la exención y disfruta 2% en todo.", "fr": "Si vous utilisez déjà Wealthsimple, obtenez l''exonération et profitez de 2 % sur tout.", "ja": "すでにWealthsimpleを投資/銀行で使用なら、年会費免除で全て2%還元。", "ko": "이미 Wealthsimple 투자/뱅킹을 사용 중이라면 연회비 면제와 모든 2% 적립 가능.", "zh": "如果您已使用Wealthsimple投资/银行服务，可免年费并享受全部消费2%返现。"}', NULL, 0, 1;
